  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Http\Controllers\Controller;
  8: use App\Http\Requests\Api\V1\Admin\StoreLocationRequest;
  9: use App\Http\Requests\Api\V1\Admin\UpdateLocationRequest;
 10: use App\Http\Resources\Api\V1\Admin\LocationResource;
 11: use App\Models\Branch;
 12: use App\Models\Location;
 13: use Illuminate\Database\QueryException;
 14: use Illuminate\Http\JsonResponse;
 15: use Illuminate\Http\Request;
 16: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 17: use Illuminate\Http\Response;
 18: use Illuminate\Support\Facades\DB;
 19: use Illuminate\Support\Facades\Schema;
 20: 
 21: class LocationController extends Controller
 22: {
 23:     public function index(Request $request, Branch $branch): AnonymousResourceCollection
 24:     {
 25:         $validated = $request->validate([
 26:             'per_page' => ['sometimes', 'integer', 'min:1', 'max:100'],
 27:         ]);
 28: 
 29:         $locations = $branch->locations()
 30:             ->orderBy('id')
 31:             ->paginate($validated['per_page'] ?? 15)
 32:             ->withQueryString();
 33: 
 34:         return LocationResource::collection($locations);
 35:     }
 36: 
 37:     public function store(StoreLocationRequest $request, Branch $branch): JsonResponse
 38:     {
 39:         $location = $branch->locations()->create($request->validated());
 40: 
 41:         return LocationResource::make($location)->response()->setStatusCode(201);
 42:     }
 43: 
 44:     public function show(Branch $branch, Location $location): LocationResource
 45:     {
 46:         $this->ensureLocationBelongsToBranch($branch, $location);
 47: 
 48:         return LocationResource::make($location);
 49:     }
 50: 
 51:     public function update(UpdateLocationRequest $request, Branch $branch, Location $location): LocationResource
 52:     {
 53:         $this->ensureLocationBelongsToBranch($branch, $location);
 54:         $location->update($request->validated());
 55: 
 56:         return LocationResource::make($location);
 57:     }
 58: 
 59:     public function destroy(Branch $branch, Location $location): JsonResponse|Response
 60:     {
 61:         $this->ensureLocationBelongsToBranch($branch, $location);
 62:         $inventoryTables = $this->inventoryMovementTables();
 63: 
 64:         try {
 65:             $deleted = DB::transaction(function () use ($branch, $location, $inventoryTables): bool {
 66:                 $lockedLocation = Location::query()
 67:                     ->whereKey($location->getKey())
 68:                     ->lockForUpdate()
 69:                     ->firstOrFail();
 70:                 $this->ensureLocationBelongsToBranch($branch, $lockedLocation);
 71: 
 72:                 if ($this->hasInventoryMovements($lockedLocation, $inventoryTables)) {
 73:                     return false;
 74:                 }
 75: 
 76:                 $lockedLocation->delete();
 77: 
 78:                 return true;
 79:             });
 80:         } catch (QueryException $exception) {
 81:             if (! $this->isIntegrityConstraintViolation($exception)) {
 82:                 throw $exception;
 83:             }
 84: 
 85:             return $this->conflictResponse();
 86:         }
 87: 
 88:         if (! $deleted) {
 89:             return $this->conflictResponse();
 90:         }
 91: 
 92:         return response()->noContent();
 93:     }
 94: 
 95:     /**
 96:      * @return list<string>
 97:      */
 98:     private function inventoryMovementTables(): array
 99:     {
100:         $tables = [];
101: 
102:         foreach (['inventory_movements', 'stock_movements', 'inventory_transactions', 'stock_transactions'] as $table) {
103:             if (! Schema::hasTable($table) || ! Schema::hasColumn($table, 'location_id')) {
104:                 continue;
105:             }
106: 
107:             $tables[] = $table;
108:         }
109: 
110:         return $tables;
111:     }
112: 
113:     /**
114:      * @param  list<string>  $tables
115:      */
116:     private function hasInventoryMovements(Location $location, array $tables): bool
117:     {
118:         foreach ($tables as $table) {
119:             if (DB::table($table)->where('location_id', $location->getKey())->exists()) {
120:                 return true;
121:             }
122:         }
123: 
124:         return false;
125:     }
126: 
127:     private function isIntegrityConstraintViolation(QueryException $exception): bool
128:     {
129:         $sqlState = (string) ($exception->errorInfo[0] ?? $exception->getCode());
130: 
131:         return in_array($sqlState, ['23000', '23503'], true);
132:     }
133: 
134:     private function conflictResponse(): JsonResponse
135:     {
136:         return response()->json([
137:             'message' => 'لا يمكن حذف الموقع لارتباطه بحركات مخزنية.',
138:         ], 409);
139:     }
140: 
141:     private function ensureLocationBelongsToBranch(Branch $branch, Location $location): void
142:     {
143:         abort_unless($location->branch_id === $branch->getKey(), 404);
144:     }
145: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Enums\StocktakeStatus;
 8: use App\Http\Controllers\Controller;
 9: use App\Http\Requests\Admin\Stocktake\StoreStocktakeRequest;
10: use App\Http\Requests\Admin\Stocktake\UpdateStocktakeItemsRequest;
11: use App\Http\Requests\Admin\Stocktake\UpdateStocktakeRequest;
12: use App\Http\Resources\Admin\StocktakeResource;
13: use App\Models\Stocktake;
14: use App\Services\BranchAccess;
15: use App\Services\StocktakeService;
16: use Illuminate\Http\JsonResponse;
17: use Illuminate\Http\Request;
18: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
19: use Illuminate\Routing\Controllers\HasMiddleware;
20: use Illuminate\Routing\Controllers\Middleware;
21: use Illuminate\Validation\Rule;
22: 
23: class StocktakeController extends Controller implements HasMiddleware
24: {
25:     public function __construct(private readonly StocktakeService $stocktakes) {}
26: 
27:     public static function middleware(): array
28:     {
29:         return [
30:             new Middleware('can:stocktakes.view', only: ['index', 'show']),
31:             new Middleware('can:stocktakes.create', only: ['store']),
32:             new Middleware('can:stocktakes.update', only: ['update', 'updateItems']),
33:             new Middleware('can:stocktakes.delete', only: ['destroy']),
34:             new Middleware('can:stocktakes.approve', only: ['approve']),
35:         ];
36:     }
37: 
38:     public function index(Request $request): AnonymousResourceCollection
39:     {
40:         $filters = $request->validate([
41:             'branch_id' => ['nullable', 'integer', 'min:1'],
42:             'status' => ['nullable', Rule::in(array_column(StocktakeStatus::cases(), 'value'))],
43:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
44:         ]);
45: 
46:         $filters['staff_branch_id'] = app(BranchAccess::class)->restrictedBranch($request->user());
47: 
48:         return StocktakeResource::collection($this->stocktakes->paginate($filters));
49:     }
50: 
51:     public function store(StoreStocktakeRequest $request): JsonResponse
52:     {
53:         $stocktake = $this->stocktakes->create($request->validated(), $request->user()->id, $this->idempotencyKey($request));
54: 
55:         return (new StocktakeResource($stocktake))
56:             ->additional(['message' => 'تم إنشاء جلسة الجرد بنجاح'])
57:             ->response()
58:             ->setStatusCode(201);
59:     }
60: 
61:     public function show(Request $request, Stocktake $stocktake): StocktakeResource
62:     {
63:         app(BranchAccess::class)->assertBranch($request->user()->id, $stocktake->branch_id);
64: 
65:         return new StocktakeResource($this->stocktakes->find($stocktake->id));
66:     }
67: 
68:     public function update(UpdateStocktakeRequest $request, Stocktake $stocktake): StocktakeResource
69:     {
70:         return new StocktakeResource($this->stocktakes->update($stocktake, $request->validated(), $request->user()->id));
71:     }
72: 
73:     /** تحديث جزئي للعناصر: upsert للمرسلة فقط دون حذف الغائبة (M-4). */
74:     public function updateItems(UpdateStocktakeItemsRequest $request, Stocktake $stocktake): StocktakeResource
75:     {
76:         return new StocktakeResource($this->stocktakes->upsertSomeItems($stocktake, $request->validated()['items'], $request->user()->id));
77:     }
78: 
79:     public function destroy(Request $request, Stocktake $stocktake): JsonResponse
80:     {
81:         $this->stocktakes->delete($stocktake, $request->user()->id);
82: 
83:         return response()->json(['message' => 'تم حذف جلسة الجرد بنجاح']);
84:     }
85: 
86:     public function approve(Request $request, Stocktake $stocktake): StocktakeResource
87:     {
88:         $stocktake = $this->stocktakes->approve($stocktake, $request->user()->id);
89: 
90:         return (new StocktakeResource($stocktake))->additional(['message' => 'تم اعتماد الجرد وتسوية الفروق']);
91:     }
92: }

