 5: namespace App\Http\Requests\Admin\Inventory;
 6: 
 7: use App\Http\Requests\Admin\Concerns\BulkVariantExists;
 8: use Illuminate\Foundation\Http\FormRequest;
 9: use Illuminate\Validation\Rule;
10: use Illuminate\Validation\Validator;
11: 
12: class StoreAdjustmentRequest extends FormRequest
13: {
14:     use BulkVariantExists;
15: 
16:     public function authorize(): bool
17:     {
18:         return true;
19:     }
20: 
21:     /**
22:      * @return array<string, mixed>
23:      */
24:     public function rules(): array
25:     {
26:         return [
27:             'branch_id' => ['required', 'bail', 'integer', 'min:1', Rule::exists('branches', 'id')->where('is_active', true)],
28:             'location_id' => [
29:                 'nullable', 'bail', 'integer', 'min:1',
30:                 Rule::exists('locations', 'id')->where('branch_id', filter_var($this->input('branch_id'), FILTER_VALIDATE_INT) ?: 0),
31:             ],
32:             'items' => ['required', 'array', 'min:1', 'max:100'],
33:             'items.*.product_variant_id' => ['required', 'bail', 'integer', 'min:1'],
34:             'items.*.adjustment_type' => ['required', Rule::in(['increase', 'decrease', 'mark_damaged', 'write_off_damaged', 'restore_damaged'])],
35:             'items.*.quantity' => ['required', 'numeric', 'decimal:0,4', 'gt:0', 'max:99999999.9999'],
36:             'items.*.reason' => ['nullable', 'string', 'max:1000'],
37:         ];
38:     }
39: 
40:     public function withValidator(Validator $validator): void
41:     {
42:         $this->addBulkVariantExistsCheck($validator);
43:     }
44: }

