 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Http\Requests\Admin\Stocktake;
 6: 
 7: use App\Enums\StocktakeStatus;
 8: use App\Http\Requests\Admin\Concerns\BulkVariantExists;
 9: use Illuminate\Foundation\Http\FormRequest;
10: use Illuminate\Validation\Rule;
11: use Illuminate\Validation\Validator;
12: 
13: class UpdateStocktakeRequest extends FormRequest
14: {
15:     use BulkVariantExists;
16: 
17:     public function authorize(): bool
18:     {
19:         return true;
20:     }
21: 
22:     /**
23:      * @return array<string, mixed>
24:      */
25:     public function rules(): array
26:     {
27:         $branchId = filter_var($this->input('branch_id', $this->route('stocktake')?->branch_id), FILTER_VALIDATE_INT) ?: 0;
28: 
29:         return [
30:             'branch_id' => ['sometimes', 'bail', 'integer', 'min:1', Rule::exists('branches', 'id')->where('is_active', true)],
31:             'location_id' => [
32:                 'sometimes', 'nullable', 'bail', 'integer', 'min:1',
33:                 Rule::exists('locations', 'id')->where('branch_id', $branchId),
34:             ],
35:             'status' => ['sometimes', Rule::in([StocktakeStatus::InProgress->value, StocktakeStatus::Cancelled->value])],
36:             'notes' => ['sometimes', 'nullable', 'string', 'max:2000'],
37:             'items' => ['sometimes', 'array', 'max:500'],
38:             'items.*.product_variant_id' => [
39:                 'required_with:items', 'bail', 'integer', 'min:1', 'distinct',
40:             ],
41:             'items.*.counted_qty' => ['nullable', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
42:             'items.*.recount' => ['nullable', 'boolean'],
43:         ];
