10: // الاستثناء اللي بنرميه لما قاعدة من قواعد البيزنس تتكسر، وبيرجّع 422.
11: class BusinessException extends Exception
12: {
13:     public function __construct(
14:         string $message,
15:         public array $errors = [],
16:         public int $status = 422,
17:         public ?string $errorCode = null,
18:     ) {
19:         parent::__construct($message);
20:     }
21: 
22:     public function render(): JsonResponse
23:     {
24:         $payload = ['message' => $this->getMessage(), 'errors' => $this->errors];
25:         if ($this->errorCode !== null) {
26:             // رمز خطأ مميز تتصرف الواجهة على أساسه (مثل coupon_invalid)
27:             $payload['code'] = $this->errorCode;
28:         }
29: 
30:         return response()->json($payload, $this->status);
31:     }
32: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Http\Controllers\Controller;
  8: use App\Http\Requests\Api\V1\Admin\StoreBranchRequest;
  9: use App\Http\Requests\Api\V1\Admin\UpdateBranchRequest;
 10: use App\Http\Resources\Api\V1\Admin\BranchResource;
 11: use App\Models\Branch;
 12: use Illuminate\Database\QueryException;
 13: use Illuminate\Http\JsonResponse;
 14: use Illuminate\Http\Request;
 15: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 16: use Illuminate\Http\Response;
 17: use Illuminate\Support\Facades\DB;
 18: use Illuminate\Support\Facades\Schema;
 19: 
 20: class BranchController extends Controller
 21: {
 22:     public function index(Request $request): AnonymousResourceCollection
 23:     {
 24:         $validated = $request->validate([
 25:             'per_page' => ['sometimes', 'integer', 'min:1', 'max:100'],
 26:         ]);
 27: 
 28:         $branches = Branch::query()
 29:             ->withCount(['locations', 'users'])
 30:             ->orderBy('id')
 31:             ->paginate($validated['per_page'] ?? 15)
 32:             ->withQueryString();
 33: 
 34:         return BranchResource::collection($branches);
 35:     }
 36: 
 37:     public function store(StoreBranchRequest $request): JsonResponse
 38:     {
 39:         $branch = Branch::query()->create($request->validated());
 40: 
 41:         return $this->branchResource($branch)->response()->setStatusCode(201);
 42:     }
 43: 
 44:     public function show(Branch $branch): BranchResource
 45:     {
 46:         return $this->branchResource($branch);
 47:     }
 48: 
 49:     public function update(UpdateBranchRequest $request, Branch $branch): BranchResource
 50:     {
 51:         $branch->update($request->validated());
 52: 
 53:         return $this->branchResource($branch);
 54:     }
 55: 
 56:     private function branchResource(Branch $branch): BranchResource
 57:     {
 58:         return BranchResource::make($branch->loadCount(['locations', 'users']));
 59:     }
 60: 
 61:     public function destroy(Branch $branch): JsonResponse|Response
 62:     {
 63:         $inventoryTables = $this->inventoryMovementTables();
 64: 
 65:         try {
 66:             $deleted = DB::transaction(function () use ($branch, $inventoryTables): bool {
 67:                 $lockedBranch = Branch::query()
 68:                     ->whereKey($branch->getKey())
 69:                     ->lockForUpdate()
 70:                     ->firstOrFail();
 71: 
 72:                 if ($lockedBranch->users()->exists() || $this->hasInventoryMovements($lockedBranch, $inventoryTables)) {
 73:                     return false;
 74:                 }
 75: 
 76:                 $lockedBranch->delete();
 77: 
 78:                 return true;
 79:             });
 80:         } catch (QueryException $exception) {
 81:             if (! $this->isIntegrityConstraintViolation($exception)) {
 82:                 throw $exception;
 83:             }
 84: 
 85:             return $this->conflictResponse();
 86:         }
 87: 
 88:         if (! $deleted) {
 89:             return $this->conflictResponse();
 90:         }
 91: 
 92:         return response()->noContent();
 93:     }
 94: 
 95:     /**
 96:      * @return array<string, list<string>>
 97:      */
 98:     private function inventoryMovementTables(): array
 99:     {
100:         $tables = [];
101: 
102:         foreach (['inventory_movements', 'stock_movements', 'inventory_transactions', 'stock_transactions'] as $table) {
103:             if (! Schema::hasTable($table)) {
104:                 continue;
105:             }
106: 
107:             $columns = [];
108: 
109:             foreach (['branch_id', 'location_id'] as $column) {
110:                 if (Schema::hasColumn($table, $column)) {
111:                     $columns[] = $column;
112:                 }
113:             }
114: 
115:             if ($columns !== []) {
116:                 $tables[$table] = $columns;
117:             }
118:         }
119: 
120:         return $tables;
121:     }
122: 
123:     /**
124:      * @param  array<string, list<string>>  $tables
125:      */
126:     private function hasInventoryMovements(Branch $branch, array $tables): bool
127:     {
128:         foreach ($tables as $table => $columns) {
129:             if (in_array('branch_id', $columns, true) && DB::table($table)->where('branch_id', $branch->getKey())->exists()) {
130:                 return true;
131:             }
132: 
133:             if (in_array('location_id', $columns, true)) {
134:                 $locationIds = $branch->locations()->select('locations.id');
135: 
136:                 if (DB::table($table)->whereIn('location_id', $locationIds)->exists()) {
137:                     return true;
138:                 }
139:             }
140:         }
141: 
142:         return false;
143:     }
144: 
145:     private function isIntegrityConstraintViolation(QueryException $exception): bool
146:     {
147:         $sqlState = (string) ($exception->errorInfo[0] ?? $exception->getCode());
148: 
149:         return in_array($sqlState, ['23000', '23503'], true);
150:     }
151: 
152:     private function conflictResponse(): JsonResponse
153:     {
154:         return response()->json([
155:             'message' => 'لا يمكن حذف الفرع لارتباطه بموظفين أو حركات مخزنية.',
156:         ], 409);
157:     }
158: }

