36:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
37:         ]);
38: 
39:         $quotations = Quotation::query()
40:             ->with(['customer', 'items.variant.product'])
41:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
42:             ->when($filters['customer_id'] ?? null, fn ($q, $v) => $q->where('customer_id', $v))
43:             ->latest('id')
44:             ->paginate($filters['per_page'] ?? 15);
45: 
46:         return QuotationResource::collection($quotations)->response();
