 8: use App\Models\ProductVariant;
 9: use App\Notifications\LowStockAlertNotification;
10: use App\Notifications\StaffRecipients;
11: use Illuminate\Contracts\Queue\ShouldQueue;
12: use Illuminate\Support\Facades\Notification;
13: 
14: /** تنبيه مديري المشتريات (purchases.view) ومديري الفرع بانخفاض المخزون. */
15: class SendLowStockAlert implements ShouldQueue
16: {
17:     public function handle(StockLowDetected $event): void
18:     {
19:         $recipients = StaffRecipients::withAnyPermission(['purchases.view'])
20:             ->merge(StaffRecipients::branchManagers($event->branchId))
21:             ->unique('id');
22: 
23:         if ($recipients->isEmpty()) {
24:             return;
25:         }
26: 
27:         $sku = ProductVariant::query()->whereKey($event->productVariantId)->value('sku');
28: 
29:         Notification::send($recipients, new LowStockAlertNotification(
30:             $event->productVariantId,
31:             $sku !== null ? (string) $sku : null,
32:             $event->branchId,
33:             $event->available,
34:             $event->reorderLevel,
35:         ));
36:     }
37: }

