 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Models;
 6: 
 7: use Illuminate\Database\Eloquent\Builder;
 8: use Illuminate\Database\Eloquent\Model;
 9: use Illuminate\Database\Eloquent\Relations\BelongsTo;
10: 
11: /**
12:  * رصيد مخزون حالي لمتغير في فرع/موقع. ممنوع التعديل المباشر:
13:  * أي تغيير بيتم حصرًا عن طريق InventoryService::recordMovement (قاعدة المرحلة 3 الصارمة).
14:  */
15: class StockLevel extends Model
16: {
17:     protected $fillable = [
18:         'product_variant_id', 'branch_id', 'location_id',
19:         'on_hand', 'reserved', 'damaged', 'in_transit', 'reorder_level',
20:     ];
21: 
22:     protected $casts = [
23:         'on_hand' => 'decimal:4',
24:         'reserved' => 'decimal:4',
25:         'damaged' => 'decimal:4',
26:         'in_transit' => 'decimal:4',
27:         'reorder_level' => 'decimal:4',
28:         'available' => 'decimal:4',
29:     ];
30: 
31:     /** المتاح للبيع = الفعلي − المحجوز − التالف (نفس معادلة العمود المولّد في القاعدة). */
32:     public function getAvailableAttribute(): float
33:     {
34:         return round((float) $this->on_hand - (float) $this->reserved - (float) $this->damaged, 4);
35:     }
36: 
37:     /**
38:      * نطاق للأرصدة غير الصفرية في أي وعاء مخزني (فعلي، محجوز، تالف، قيد النقل).
39:      *
40:      * @param  Builder<StockLevel>  $query
41:      * @return Builder<StockLevel>
42:      */
43:     public function scopeHasNonZeroBalance(Builder $query): Builder
44:     {
45:         return $query->where(fn (Builder $q) => $q
46:             ->where('on_hand', '<>', 0)
47:             ->orWhere('reserved', '<>', 0)
48:             ->orWhere('damaged', '<>', 0)
49:             ->orWhere('in_transit', '<>', 0));
50:     }
51: 
52:     public function variant(): BelongsTo
53:     {
54:         return $this->belongsTo(ProductVariant::class, 'product_variant_id')->withTrashed();
55:     }
56: 
57:     public function branch(): BelongsTo
58:     {
59:         return $this->belongsTo(Branch::class);
60:     }
61: 
62:     public function location(): BelongsTo
63:     {
64:         return $this->belongsTo(Location::class);
65:     }
66: }

