 8: use Carbon\Carbon;
 9: use Illuminate\Database\Eloquent\Model;
10: use Illuminate\Database\Eloquent\Relations\BelongsTo;
11: use Illuminate\Database\Eloquent\Relations\HasMany;
12: 
13: class StockTransfer extends Model
14: {
15:     protected $attributes = ['version' => 1];
16: 
17:     protected static function booted(): void
18:     {
19:         static::saving(function (self $transfer): void {
20:             if (! $transfer->exists) {
21:                 return;
22:             }
23:             $transfer->version = (int) $transfer->getRawOriginal('version') + 1;
24:             $previous = Carbon::parse($transfer->getRawOriginal('updated_at'));
25:             $current = now()->startOfSecond();
26:             $transfer->updated_at = $current->greaterThan($previous) ? $current : $previous->addSecond();
27:         });
28:     }
29: 
30:     protected $fillable = [
31:         'transfer_number', 'from_branch_id', 'to_branch_id', 'status',
32:         'created_by', 'approved_by', 'shipped_at', 'received_at', 'notes',
33:     ];
