 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services\Concerns;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Models\InventoryIdempotencyKey;
 9: use App\Services\BranchAccess;
10: use App\Services\IdempotencyFingerprint;
11: use Illuminate\Database\Eloquent\Model;
12: use Illuminate\Database\UniqueConstraintViolationException;
13: use Illuminate\Support\Facades\DB;
14: 
15: /**
16:  * إنشاء بمفتاح عدم تكرار لنهايات الإنشاء (تحويل/جرد): إعادة المحاولة بعد
17:  * timeout بنفس المفتاح تعيد النموذج المنشأ بدل نسخة مكررة، ونفس المفتاح
18:  * بحمولة مختلفة يُرفض 409. المفتاح يُدرج في نفس معاملة الإنشاء، ففشل
19:  * الإنشاء يلغيه معه (L-7 — نفس نمط مفتاح التسويات).
20:  */
21: trait HandlesIdempotentCreation
22: {
23:     /**
24:      * @param  list<string>  $relations
25:      * @param  callable(): Model  $creator
26:      */
27:     private function createIdempotently(string $context, array $payload, int $userId, ?string $idempotencyKey, string $modelClass, array $relations, callable $creator): Model
28:     {
29:         if ($idempotencyKey === null) {
30:             return $creator();
31:         }
32: 
33:         $requestHash = IdempotencyFingerprint::hash(['__context' => $context, 'payload' => $payload]);
34: 
35:         try {
36:             return DB::transaction(function () use ($userId, $idempotencyKey, $requestHash, $creator): Model {
37:                 $record = InventoryIdempotencyKey::query()->create([
38:                     'user_id' => $userId,
39:                     'key' => $idempotencyKey,
40:                     'request_hash' => $requestHash,
41:                 ]);
42: 
43:                 $model = $creator();
44: 
45:                 $record->update(['response' => [$model->id], 'status_code' => 201]);
46: 
47:                 return $model;
48:             });
49:         } catch (UniqueConstraintViolationException $e) {
50:             if (! str_contains($e->getMessage(), 'inventory_idempotency_keys_user_id_key_unique')) {
51:                 throw $e;
52:             }
53: 
54:             $record = InventoryIdempotencyKey::query()
55:                 ->where('user_id', $userId)->where('key', $idempotencyKey)->first();
56: 
57:             if ($record === null || ! hash_equals($record->request_hash, $requestHash)) {
58:                 throw new BusinessException('مفتاح عدم التكرار هذا مستخدم مسبقًا مع بيانات مختلفة.', [], 409);
59:             }
60: 
61:             $model = $modelClass::query()->with($relations)->findOrFail((int) ($record->response[0] ?? 0));
62:             app(BranchAccess::class)->assertBranch($userId, (int) ($model->getAttribute('branch_id') ?? $model->getAttribute('from_branch_id')));
63: 
64:             return $model;
65:         }
66:     }
67: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services;
 6: 
 7: use App\Enums\StaffRole;
 8: use App\Models\User;
 9: use Illuminate\Auth\Access\AuthorizationException;
10: 
11: /**
12:  * نطاق الفروع للموظفين — Fail-Closed:
13:  * الوصول لكل الفروع امتياز صريح (Super Admin أو صلاحية inventory.all_branches)،
14:  * والموظف المرتبط بفرع محصور فيه، ومن لا فرع له ولا امتياز يُرفض بدل أن يرى كل شيء.
15:  */
16: class BranchAccess
17: {
18:     /** @var array<int, User> ذاكرة لكل طلب حتى لا يُعاد تحميل المستخدم مع كل فحص. */
19:     private array $usersById = [];
20: 
21:     public function restrictedBranch(?User $user): ?int
22:     {
23:         if ($user === null) {
24:             throw new AuthorizationException;
25:         }
26: 
27:         if ($user->hasRole(StaffRole::SuperAdmin->value, 'staff') || $user->can('inventory.all_branches')) {
28:             return null;
29:         }
30: 
31:         if ($user->branch_id !== null) {
32:             return (int) $user->branch_id;
33:         }
34: 
35:         throw new AuthorizationException('حسابك غير مرتبط بأي فرع ولا تملك صلاحية الوصول لكل الفروع (inventory.all_branches).');
36:     }
37: 
38:     public function assertBranch(int $userId, int ...$branchIds): void
39:     {
40:         $branchId = $this->restrictedBranch($this->usersById[$userId] ??= User::findOrFail($userId));
41:         if ($branchId !== null && ! in_array($branchId, $branchIds, true)) {
42:             throw new AuthorizationException('لا تملك صلاحية الوصول إلى هذا الفرع.');
43:         }
44:     }
45: 
46:     public function assertCentralAccess(?User $user): void
47:     {
48:         if ($this->restrictedBranch($user) !== null) {
49:             throw new AuthorizationException('تعديل مجموعات العملاء والأسعار العامة يتطلب صلاحية الوصول لكل الفروع.');
50:         }
51:     }
52: }

 1: <?php
 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use Illuminate\Database\Eloquent\Model;
 9: use Illuminate\Support\Facades\DB;
10: 
11: class OperationIdempotencyService
12: {
13:     public function run(string $operation, Model $actor, ?string $key, array $payload, callable $execute): Model
14:     {
15:         if ($key === null || ! preg_match('/\A[A-Za-z0-9._:-]{1,128}\z/', $key)) {
16:             throw new BusinessException('ترويسة Idempotency-Key مطلوبة (حتى 128 حرفًا إنجليزيًا أو رقمًا).');
17:         }
18:         $scope = ['operation' => $operation, 'actor_type' => $actor->getMorphClass(), 'actor_id' => $actor->getKey(), 'key' => $key];
19:         $hash = IdempotencyFingerprint::hash($payload);
20: 
21:         return DB::transaction(function () use ($scope, $hash, $execute): Model {
22:             $inserted = DB::table('operation_idempotency_keys')->insertOrIgnore([
23:                 ...$scope, 'request_hash' => $hash, 'created_at' => now(),
24:             ]);
25:             $record = DB::table('operation_idempotency_keys')->where($scope)->lockForUpdate()->first();
26:             if (! $inserted) {
27:                 if (! hash_equals($record->request_hash, $hash)) {
28:                     throw new BusinessException('مفتاح عدم التكرار مستخدم مع بيانات مختلفة.', [], 409);
29:                 }
30:                 $result = $record->result_type::query()->find($record->result_id);
31:                 if ($result === null) {
32:                     throw new BusinessException('العملية سبق تنفيذها ثم أزيل مستندها؛ استخدم عملية جديدة.', [], 409);
33:                 }
34: 
35:                 return $result;
36:             }
37:             $result = $execute();
38:             DB::table('operation_idempotency_keys')->where($scope)->update([
39:                 'result_type' => $result::class, 'result_id' => $result->getKey(),
40:             ]);
41: 
42:             return $result;
43:         }, 3);
44:     }
45: }

