 29: 
 30: /**
 31:  * محرك نقطة البيع — كل عملية POS تمر من هنا.
 32:  *
 33:  * القاعدة الذهبية: الكاشير لا يُنفذ أي عملية بلا وردية مفتوحة في فرعه.
 34:  * البيع يخصم من on_hand فوراً (لا حجز مؤقت كالأونلاين).
 35:  */
 36: class PosService
 37: {
 38:     public function __construct(
 39:         private readonly InventoryService $inventory,
 40:         private readonly PricingService $pricing,
 41:         private readonly TreasuryService $treasury,
 42:         private readonly SettingService $settings,
 43:     ) {}
 44: 
 45:     // ===================================================================
 46:     //  الورديات
 47:     // ===================================================================
 48: 
 49:     /**
 50:      * فتح وردية جديدة للكاشير.
 51:      */
 52:     public function openShift(User $user, int $branchId, int $treasuryId, float $openingCash): PosShift
 53:     {
 54:         return DB::transaction(function () use ($user, $branchId, $treasuryId, $openingCash): PosShift {
 55:             // التحقق من عدم وجود وردية مفتوحة لنفس الكاشير
 56:             $existingUserShift = PosShift::query()
 57:                 ->where('user_id', $user->id)
 58:                 ->where('status', PosShiftStatus::Open)
 59:                 ->lockForUpdate()
 60:                 ->exists();
 61: 
 62:             if ($existingUserShift) {
 63:                 throw new BusinessException('لديك وردية مفتوحة بالفعل. أغلقها أولًا قبل فتح وردية جديدة.');
 64:             }
 65: 
 66:             // التحقق من عدم وجود وردية مفتوحة على نفس الدرج
 67:             $existingDrawerShift = PosShift::query()
 68:                 ->where('treasury_id', $treasuryId)
 69:                 ->where('status', PosShiftStatus::Open)
 70:                 ->lockForUpdate()
 71:                 ->exists();
 72: 
 73:             if ($existingDrawerShift) {
 74:                 throw new BusinessException('درج النقدية المحدد مفتوح على وردية أخرى.');
 75:             }
 76: 
 77:             // التحقق أن الخزينة تتبع الفرع وهي من نوع درج
 78:             $treasury = Treasury::query()
 79:                 ->where('id', $treasuryId)
 80:                 ->where('branch_id', $branchId)
 81:                 ->where('type', 'pos_drawer')
 82:                 ->where('is_active', true)
 83:                 ->firstOrFail();
 84: 
 85:             $shiftNumber = $this->settings->generateNextNumber('shift');
 86: 
 87:             $shift = PosShift::create([
 88:                 'shift_number'          => $shiftNumber,
 89:                 'user_id'               => $user->id,
 90:                 'branch_id'             => $branchId,
 91:                 'treasury_id'           => $treasuryId,
 92:                 'status'                => PosShiftStatus::Open,
 93:                 'opened_at'             => now(),
 94:                 'opening_cash'          => $openingCash,
 95:                 'cash_sales_total'      => 0,
 96:                 'card_sales_total'      => 0,
 97:                 'cash_returns_total'    => 0,
 98:                 'cash_expenses_total'   => 0,
 99:                 'expected_closing_cash' => $openingCash,
100:             ]);
101: 
102:             // تسجيل رصيد الفتح في دفتر الخزينة
103:             $this->treasury->record([
104:                 'treasury_id'    => $treasury->id,
105:                 'shift_id'       => $shift->id,
106:                 'type'           => TreasuryTransactionType::OpeningBalance,
107:                 'amount'         => $openingCash,
108:                 'reference_type' => PosShift::class,
109:                 'reference_id'   => $shift->id,
110:                 'created_by'     => $user->id,
111:                 'notes'          => "رصيد فتح وردية #{$shiftNumber}",
112:             ]);
113: 
114:             return $shift;
115:         });
116:     }
117: 
118:     /**
119:      * إغلاق الوردية بعد عدّ الكاشير للنقدية.
120:      *
121:      * expected_closing_cash = opening_cash + cash_sales - cash_returns - cash_expenses
122:      * cash_difference = actual - expected
123:      */
124:     public function closeShift(PosShift $shift, float $actualCash, ?string $notes): PosShift
125:     {
126:         if ($shift->status !== PosShiftStatus::Open) {
127:             throw new BusinessException('يمكن إغلاق الورديات المفتوحة فقط.');
128:         }
129: 
130:         return DB::transaction(function () use ($shift, $actualCash, $notes): PosShift {
131:             // إعادة حساب مجاميع الوردية من بيانات الطلبات الفعلية
132:             $salesStats = Order::query()
133:                 ->where('pos_shift_id', $shift->id)
134:                 ->where('status', OrderStatus::Delivered)
135:                 ->selectRaw('
136:                     COALESCE(SUM(cash_amount), 0) AS cash_sales,
137:                     COALESCE(SUM(card_amount), 0) AS card_sales
138:                 ')
139:                 ->first();
140: 
141:             $cashSales = (float) ($salesStats?->cash_sales ?? 0);
142:             $cardSales = (float) ($salesStats?->card_sales ?? 0);
143: 
144:             $cashReturns = (float) Order::query()
145:                 ->where('pos_shift_id', $shift->id)
146:                 ->where('status', OrderStatus::Returned)
147:                 ->sum('cash_amount');
148: 
149:             $cashExpenses = (float) Expense::query()
150:                 ->where('shift_id', $shift->id)
151:                 ->sum('amount');
152: 
153:             $expectedClosingCash = (float) $shift->opening_cash
154:                 + $cashSales
155:                 - $cashReturns
156:                 - $cashExpenses;
157: 
158:             $cashDifference = $actualCash - $expectedClosingCash;
159: 
160:             $shift->update([
161:                 'status'                => PosShiftStatus::ClosedPendingApproval,
162:                 'closed_at'             => now(),
163:                 'cash_sales_total'      => $cashSales,
164:                 'card_sales_total'      => $cardSales,
165:                 'cash_returns_total'    => $cashReturns,
166:                 'cash_expenses_total'   => $cashExpenses,
167:                 'expected_closing_cash' => $expectedClosingCash,
168:                 'actual_closing_cash'   => $actualCash,
169:                 'cash_difference'       => $cashDifference,
170:                 'notes'                 => $notes,
171:             ]);
172: 
173:             return $shift->fresh();
174:         });
175:     }
176: 
177:     /**
178:      * الاعتماد الإداري للوردية المغلقة وترحيل النقدية للخزنة الرئيسية.
179:      */
180:     public function approveShift(PosShift $shift, User $approver): PosShift
181:     {
182:         if ($shift->status !== PosShiftStatus::ClosedPendingApproval) {
183:             throw new BusinessException('يمكن اعتماد الورديات المغلقة المنتظرة للاعتماد فقط.');
184:         }
185: 
186:         return DB::transaction(function () use ($shift, $approver): PosShift {
187:             $shift->update([
188:                 'status'      => PosShiftStatus::Approved,
189:                 'approved_at' => now(),
190:                 'approved_by' => $approver->id,
191:             ]);
192: 
193:             // ترحيل النقدية من الدرج إلى الخزنة الرئيسية
194:             $this->treasury->settleShiftToMainSafe($shift, $approver->id);
195: 
196:             return $shift->fresh();
197:         });
198:     }
199: 
200:     // ===================================================================
201:     //  البيع
202:     // ===================================================================
203: 
204:     /**
205:      * إنشاء فاتورة بيع POS مع الخصم الفوري من المخزن.
206:      *
207:      * @param  array{
208:      *     items: array<array{product_variant_id: int, qty: int, unit_price?: float|null, discount_amount?: float}>,
209:      *     customer_id?: int|null,
210:      *     payment_method?: string,
211:      *     cash_amount?: float,
212:      *     card_amount?: float,
213:      *     notes?: string|null,
214:      *     override_price?: bool,
215:      * }  $payload
216:      */
217:     public function createSale(PosShift $shift, array $payload): Order
218:     {
219:         if ($shift->status !== PosShiftStatus::Open) {
220:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن إجراء أي بيع.');
221:         }
222: 
223:         return DB::transaction(function () use ($shift, $payload): Order {
224:             $customer    = isset($payload['customer_id'])
225:                 ? Customer::find($payload['customer_id'])
226:                 : null;
227: 
228:             $overridePrice = (bool) ($payload['override_price'] ?? false);
229:             $items         = $this->resolveItems($shift, $payload['items'], $customer, $overridePrice);
230: 
231:             $subtotal      = $items->sum('line_total');
232:             $discountTotal = $items->sum('discount_amount');
233:             $grandTotal    = $subtotal - $discountTotal;
234: 
235:             // التحقق من الدفع المختلط
236:             $cashAmount = (float) ($payload['cash_amount'] ?? $grandTotal);
237:             $cardAmount = (float) ($payload['card_amount'] ?? 0);
238: 
239:             if (abs(($cashAmount + $cardAmount) - $grandTotal) > 0.01) {
240:                 throw new BusinessException('مجموع المبالغ (نقدي + بطاقة) لا يساوي إجمالي الفاتورة.');
241:             }
242: 
243:             // توليد رقم الطلب بنفس آلية الـ order_next_number
244:             $orderNumber = $this->settings->generateNextNumber('order');
245: 
246:             // إنشاء الطلب بحالة delivered مباشرة (POS = تسليم فوري)
247:             $order = Order::create([
248:                 'order_number'        => $orderNumber,
249:                 'channel'             => 'pos',
250:                 'customer_id'         => $customer?->id,
251:                 'allocated_branch_id' => $shift->branch_id,
252:                 'pos_shift_id'        => $shift->id,
253:                 'status'              => OrderStatus::Delivered,
254:                 'payment_method'      => $payload['payment_method'] ?? 'mixed',
255:                 'payment_status'      => 'paid',
256:                 'subtotal'            => $subtotal,
257:                 'discount_amount'     => $discountTotal,
258:                 'shipping_cost'       => 0,
259:                 'tax_amount'          => 0,
260:                 'grand_total'         => $grandTotal,
261:                 'cash_amount'         => $cashAmount,
262:                 'card_amount'         => $cardAmount,
263:             ]);
264: 
265:             // إنشاء عناصر الطلب وخصم المخزون فوراً
266:             foreach ($items as $item) {
267:                 OrderItem::create([
268:                     'order_id'               => $order->id,
269:                     'product_variant_id'     => $item['product_variant_id'],
270:                     'product_name_snapshot'  => $item['product_name_snapshot'],
271:                     'sku_snapshot'           => $item['sku_snapshot'],
272:                     'allocated_branch_id'    => $shift->branch_id,
273:                     'qty'                    => $item['qty'],
274:                     'unit_price'             => $item['unit_price'],
275:                     'discount_amount'        => $item['discount_amount'],
276:                     'line_total'             => $item['line_total'],
277:                 ]);
278: 
279:                 // خصم فوري من on_hand
280:                 $this->inventory->recordMovement([
281:                     'product_variant_id' => $item['product_variant_id'],
282:                     'branch_id'          => $shift->branch_id,
283:                     'type'               => StockMovementType::Sale,
284:                     'affected_bucket'    => StockBucket::OnHand,
285:                     'quantity'           => -$item['qty'],
286:                     'reference_type'     => Order::class,
287:                     'reference_id'       => $order->id,
288:                     'created_by'         => $shift->user_id,
289:                     'notes'              => "بيع POS #{$orderNumber}",
290:                 ]);
291:             }
292: 
293:             // تسجيل تاريخ الحالة
294:             OrderStatusHistory::create([
295:                 'order_id'        => $order->id,
296:                 'from_status'     => null,
297:                 'to_status'       => OrderStatus::Delivered,
298:                 'changed_by_type' => User::class,
299:                 'changed_by_id'   => $shift->user_id,
300:                 'notes'           => 'بيع POS مباشر',
301:             ]);
302: 
303:             // تسجيل المقبوضة النقدية في الخزينة
304:             if ($cashAmount > 0) {
305:                 $this->treasury->record([
306:                     'treasury_id'    => $shift->treasury_id,
307:                     'shift_id'       => $shift->id,
308:                     'type'           => TreasuryTransactionType::PosSale,
309:                     'amount'         => $cashAmount,
310:                     'reference_type' => Order::class,
311:                     'reference_id'   => $order->id,
312:                     'created_by'     => $shift->user_id,
313:                     'notes'          => "مبيعات نقدية POS #{$orderNumber}",
314:                 ]);
315:             }
316: 
317:             return $order->load(['items.variant', 'customer']);
318:         });
319:     }
320: 
321:     /**
322:      * مرتجع كلي أو جزئي من فاتورة POS.
323:      * يُعيد البضاعة إلى on_hand ويرد النقدية من الدرج إن كانت مدفوعة نقداً.
324:      *
325:      * @param  array<array{product_variant_id: int, qty: int, return_to?: string}>  $returnedItems
326:      * @param  array<array{product_variant_id: int, qty: int}>  $exchangeItems (للاستبدال)
327:      */
328:     public function processReturn(
329:         PosShift $shift,
330:         Order $originalOrder,
331:         array $returnedItems,
332:         array $exchangeItems = []
333:     ): array {
334:         if ($shift->status !== PosShiftStatus::Open) {
335:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن إجراء أي مرتجع.');
336:         }
337: 
338:         if ($originalOrder->channel !== 'pos') {
339:             throw new BusinessException('يمكن مرتجع طلبات POS فقط من شاشة الـ POS.');
340:         }
341: 
342:         return DB::transaction(function () use ($shift, $originalOrder, $returnedItems, $exchangeItems): array {
343:             $returnValue   = 0.0;
344:             $returnOrderId = null;
345: 
346:             // ===== معالجة الأصناف المرتجعة =====
347:             if (! empty($returnedItems)) {
348:                 foreach ($returnedItems as $ret) {
349:                     $originalItem = $originalOrder->items
350:                         ->firstWhere('product_variant_id', $ret['product_variant_id']);
351: 
352:                     if ($originalItem === null) {
353:                         throw new BusinessException("الصنف {$ret['product_variant_id']} غير موجود في الطلب الأصلي.");
354:                     }
355: 
356:                     if ($ret['qty'] > $originalItem->qty) {
357:                         throw new BusinessException("كمية المرتجع ({$ret['qty']}) أكبر من الكمية المباعة ({$originalItem->qty}).");
358:                     }
359: 
360:                     $returnValue += (float) $originalItem->unit_price * $ret['qty'];
361:                     $bucket = ($ret['return_to'] ?? 'on_hand') === 'damaged'
362:                         ? StockBucket::Damaged
363:                         : StockBucket::OnHand;
364: 
365:                     // إعادة الكمية للمخزون
366:                     $this->inventory->recordMovement([
367:                         'product_variant_id' => $ret['product_variant_id'],
368:                         'branch_id'          => $shift->branch_id,
369:                         'type'               => StockMovementType::SaleReturn,
370:                         'affected_bucket'    => $bucket,
371:                         'quantity'           => $ret['qty'],
372:                         'reference_type'     => Order::class,
373:                         'reference_id'       => $originalOrder->id,
374:                         'created_by'         => $shift->user_id,
375:                         'notes'              => "مرتجع POS من #{$originalOrder->order_number}",
376:                     ]);
377:                 }
378: 
379:                 // إنشاء طلب مرتجع
380:                 $returnOrderNumber = $this->settings->generateNextNumber('order');
381:                 $returnOrder       = Order::create([
382:                     'order_number'        => $returnOrderNumber,
383:                     'channel'             => 'pos',
384:                     'customer_id'         => $originalOrder->customer_id,
385:                     'allocated_branch_id' => $shift->branch_id,
386:                     'pos_shift_id'        => $shift->id,
387:                     'status'              => OrderStatus::Returned,
388:                     'payment_method'      => $originalOrder->payment_method,
389:                     'payment_status'      => 'refunded',
390:                     'subtotal'            => $returnValue,
391:                     'discount_amount'     => 0,
392:                     'shipping_cost'       => 0,
393:                     'tax_amount'          => 0,
394:                     'grand_total'         => $returnValue,
395:                     'cash_amount'         => $returnValue, // يُرد نقدًا من الدرج
396:                     'card_amount'         => 0,
397:                 ]);
398: 
399:                 foreach ($returnedItems as $ret) {
400:                     $originalItem = $originalOrder->items->firstWhere('product_variant_id', $ret['product_variant_id']);
401:                     OrderItem::create([
402:                         'order_id'              => $returnOrder->id,
403:                         'product_variant_id'    => $ret['product_variant_id'],
404:                         'product_name_snapshot' => $originalItem->product_name_snapshot,
405:                         'sku_snapshot'          => $originalItem->sku_snapshot,
406:                         'allocated_branch_id'   => $shift->branch_id,
407:                         'qty'                   => $ret['qty'],
408:                         'unit_price'            => $originalItem->unit_price,
409:                         'discount_amount'       => 0,
410:                         'line_total'            => (float) $originalItem->unit_price * $ret['qty'],
411:                     ]);
412:                 }
413: 
414:                 OrderStatusHistory::create([
415:                     'order_id'        => $returnOrder->id,
416:                     'from_status'     => null,
417:                     'to_status'       => OrderStatus::Returned,
418:                     'changed_by_type' => User::class,
419:                     'changed_by_id'   => $shift->user_id,
420:                     'notes'           => "مرتجع من #{$originalOrder->order_number}",
421:                 ]);
422: 
423:                 // رد النقدية للعميل من الدرج
424:                 $this->treasury->record([
425:                     'treasury_id'    => $shift->treasury_id,
426:                     'shift_id'       => $shift->id,
427:                     'type'           => TreasuryTransactionType::PosReturn,
428:                     'amount'         => -$returnValue,
429:                     'reference_type' => Order::class,
430:                     'reference_id'   => $returnOrder->id,
431:                     'created_by'     => $shift->user_id,
432:                     'notes'          => "رد مرتجع #{$returnOrderNumber}",
433:                 ]);
434: 
435:                 $returnOrderId = $returnOrder->id;
436:             }
437: 
438:             // ===== معالجة الاستبدال =====
439:             $exchangeOrderId = null;
440:             if (! empty($exchangeItems)) {
441:                 $exchangeOrder = $this->createSale($shift, [
442:                     'items'       => $exchangeItems,
443:                     'customer_id' => $originalOrder->customer_id,
444:                     'cash_amount' => max(0, 0 - $returnValue), // صافي الفرق
445:                     'card_amount' => 0,
446:                 ]);
447:                 $exchangeOrderId = $exchangeOrder->id;
448:             }
449: 
450:             return [
451:                 'return_order_id'   => $returnOrderId,
452:                 'exchange_order_id' => $exchangeOrderId,
453:                 'refund_amount'     => $returnValue,
454:             ];
455:         });
456:     }
