462:     public function holdSale(PosShift $shift, array $payload): PosHeldSale
463:     {
464:         return PosHeldSale::create([
465:             'hold_reference' => 'HOLD-'.strtoupper(Str::random(8)),
466:             'branch_id'      => $shift->branch_id,
467:             'user_id'        => $shift->user_id,
468:             'customer_id'    => $payload['customer_id'] ?? null,
469:             'items_payload'  => $payload['items'],
470:             'notes'          => $payload['notes'] ?? null,
471:             'created_at'     => now(),
472:         ]);
473:     }
474: 
475:     // ===================================================================
476:     //  البحث السريع عن المنتجات
477:     // ===================================================================
478: 
479:     /**
480:      * بحث فائق السرعة بالباركود أو SKU أو جزء من الاسم.
481:      * يرجع المتغير مع رصيده في الفرع الحالي فقط وسعره.
482:      *
483:      * @return array<int, array<string, mixed>>
484:      */
485:     public function lookupProducts(string $query, int $branchId, ?Customer $customer = null): array
486:     {
487:         $variants = ProductVariant::query()
488:             ->with(['product', 'media'])
489:             ->whereHas('product', fn ($q) => $q->where('is_active', true)->whereNotNull('published_at'))
490:             ->where('is_active', true)
491:             ->where(function ($q) use ($query): void {
492:                 $q->where('barcode', $query)
493:                     ->orWhere('sku', $query)
494:                     ->orWhereHas('product', fn ($pq) => $pq->whereRaw('LOWER(name_ar) LIKE ? OR LOWER(name_en) LIKE ?', ['%'.mb_strtolower($query).'%', '%'.mb_strtolower($query).'%']));
495:             })
496:             ->limit(20)
497:             ->get();
498: 
499:         $result = [];
500:         foreach ($variants as $variant) {
501:             $stock = StockLevel::query()
502:                 ->where('product_variant_id', $variant->id)
503:                 ->where('branch_id', $branchId)
504:                 ->whereNull('location_id')
505:                 ->first();
506: 
507:             try {
508:                 $priceData = $this->pricing->resolve($variant, $customer, 1, $branchId);
509:             } catch (\Throwable) {
510:                 $priceData = ['unit_price' => null, 'source' => 'unpriced', 'price_list_id' => null];
511:             }
512: 
513:             $result[] = [
514:                 'id'                => $variant->id,
515:                 'sku'               => $variant->sku,
516:                 'barcode'           => $variant->barcode,
517:                 'product_name'      => $variant->product->name_ar ?? $variant->product->name_en,
518:                 'variant_name'      => $variant->color_name_ar ?? $variant->color_name_en,
519:                 'on_hand'           => (float) ($stock?->on_hand ?? 0),
520:                 'available'         => (float) ($stock?->available ?? 0),
521:                 'unit_price'        => $priceData['unit_price'],
522:                 'price_source'      => $priceData['source'],
523:                 'price_list_id'     => $priceData['price_list_id'],
524:             ];
525:         }
526: 
527:         return $result;
528:     }
529: 
530:     // ===================================================================
531:     //  المساعدات الداخلية
532:     // ===================================================================
533: 
534:     /**
535:      * تجهيز عناصر الفاتورة مع حل الأسعار.
536:      *
537:      * @param  array<array{product_variant_id: int, qty: int, unit_price?: float|null, discount_amount?: float}>  $rawItems
538:      * @return Collection<int, array<string, mixed>>
539:      */
540:     private function resolveItems(
541:         PosShift $shift,
542:         array $rawItems,
543:         ?Customer $customer,
544:         bool $overridePrice
545:     ): Collection {
546:         return collect($rawItems)->map(function (array $item) use ($shift, $customer, $overridePrice): array {
547:             /** @var ProductVariant $variant */
548:             $variant = ProductVariant::query()
549:                 ->where('id', $item['product_variant_id'])
550:                 ->where('is_active', true)
551:                 ->firstOrFail();
552: 
553:             // التحقق من المخزون المتاح في الفرع
554:             $stock = StockLevel::query()
555:                 ->where('product_variant_id', $variant->id)
556:                 ->where('branch_id', $shift->branch_id)
557:                 ->whereNull('location_id')
558:                 ->first();
559: 
560:             $available = (float) ($stock?->available ?? 0);
561: 
562:             if ($available < $item['qty']) {
563:                 throw new BusinessException(
564:                     "الكمية المتاحة للصنف [{$variant->sku}] في الفرع هي {$available} فقط.",
565:                     status: 422,
566:                 );
567:             }
568: 
569:             // السعر: يدوي (بشرط الصلاحية) أو محسوب
570:             if ($overridePrice && isset($item['unit_price'])) {
571:                 $unitPrice = (float) $item['unit_price'];
572:             } else {
573:                 $priceData = $this->pricing->resolve($variant, $customer, (float) $item['qty'], $shift->branch_id);
574:                 $unitPrice = (float) $priceData['unit_price'];
575:             }
576: 
577:             $discount  = (float) ($item['discount_amount'] ?? 0);
578:             $lineTotal = round($unitPrice * $item['qty'] - $discount, 2);
579: 
580:             if ($lineTotal < 0) {
581:                 throw new BusinessException("إجمالي السطر للصنف [{$variant->sku}] لا يمكن أن يكون سالبًا.");
582:             }
583: 
584:             return [
585:                 'product_variant_id'    => $variant->id,
586:                 'product_name_snapshot' => $variant->product->name_ar ?? $variant->product->name_en ?? 'POS Item',
587:                 'sku_snapshot'          => $variant->sku,
588:                 'qty'                   => $item['qty'],
589:                 'unit_price'            => $unitPrice,
590:                 'discount_amount'       => $discount,
591:                 'line_total'            => $lineTotal,
592:             ];
593:         });
594:     }
595: 
596:     /**
597:      * تسجيل مصروف من درج الوردية الحالية.
598:      */
599:     public function recordExpense(PosShift $shift, array $data, int $userId): Expense
600:     {
601:         if ($shift->status !== PosShiftStatus::Open) {
602:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن تسجيل مصاريف.');
603:         }
604: 
605:         return DB::transaction(function () use ($shift, $data, $userId): Expense {
606:             $expenseNumber = $this->settings->generateNextNumber('expense');
607: 
608:             $expense = Expense::create([
609:                 'expense_number' => $expenseNumber,
610:                 'branch_id'      => $shift->branch_id,
611:                 'treasury_id'    => $shift->treasury_id,
612:                 'shift_id'       => $shift->id,
613:                 'category'       => $data['category'],
614:                 'amount'         => $data['amount'],
615:                 'expense_date'   => $data['expense_date'] ?? today(),
616:                 'attachment_path'=> $data['attachment_path'] ?? null,
617:                 'notes'          => $data['notes'] ?? null,
618:                 'created_by'     => $userId,
619:             ]);
620: 
621:             // خصم من الخزينة
622:             $this->treasury->record([
623:                 'treasury_id'    => $shift->treasury_id,
624:                 'shift_id'       => $shift->id,
625:                 'type'           => TreasuryTransactionType::Expense,
626:                 'amount'         => -(float) $data['amount'],
627:                 'reference_type' => Expense::class,
628:                 'reference_id'   => $expense->id,
629:                 'created_by'     => $userId,
630:                 'notes'          => "مصروف: {$data['category']} #{$expenseNumber}",
631:             ]);
632: 
633:             return $expense;
634:         });
635:     }
636: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Enums\StocktakeStatus;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Location;
 12: use App\Models\StockMovement;
 13: use App\Models\Stocktake;
 14: use App\Services\Concerns\HandlesIdempotentCreation;
 15: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
 16: use Illuminate\Support\Collection;
 17: use Illuminate\Support\Facades\DB;
 18: 
 19: /**
 20:  * جلسات الجرد الفعلي. لقطة system_qty بتتاخد من stock_levels وقت إنشاء العنصر،
 21:  * والاعتماد بيحوّل الفروق لحركات دفتر (فائض/عجز) عبر InventoryService فقط،
 22:  * وبعد الاعتماد الجلسة بتتقفل نهائيًا.
 23:  */
 24: class StocktakeService
 25: {
 26:     use HandlesIdempotentCreation;
 27: 
 28:     public function __construct(
 29:         private readonly InventoryService $inventory,
 30:         private readonly SettingService $settings,
 31:     ) {}
 32: 
 33:     public function paginate(array $filters): LengthAwarePaginator
 34:     {
 35:         return Stocktake::query()
 36:             ->when($filters['staff_branch_id'] ?? null, fn ($q, $branch) => $q->where('branch_id', $branch))
 37:             ->with(['branch', 'location', 'creator'])
 38:             ->withCount('items')
 39:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 40:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 41:             ->orderByDesc('id')
 42:             ->paginate($filters['per_page'] ?? 15);
 43:     }
 44: 
 45:     public function find(int $id): Stocktake
 46:     {
 47:         return Stocktake::query()
 48:             ->with(['items.variant', 'branch', 'location', 'creator', 'approver'])
 49:             ->findOrFail($id);
 50:     }
 51: 
 52:     public function create(array $data, int $userId, ?string $idempotencyKey = null): Stocktake
 53:     {
 54:         app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
 55: 
 56:         /** @var Stocktake */
 57:         return $this->createIdempotently(
 58:             'stocktake_store',
 59:             $data,
 60:             $userId,
 61:             $idempotencyKey,
 62:             Stocktake::class,
 63:             ['items.variant', 'branch', 'location', 'creator'],
 64:             fn (): Stocktake => $this->doCreate($data, $userId),
 65:         );
 66:     }
 67: 
 68:     private function doCreate(array $data, int $userId): Stocktake
 69:     {
 70:         return DB::transaction(function () use ($data, $userId): Stocktake {
 71:             app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
 72:             $stocktake = Stocktake::query()->create([
 73:                 'stocktake_number' => $this->settings->generateNextNumber('stocktake'),
 74:                 'branch_id' => $data['branch_id'],
 75:                 'location_id' => $data['location_id'] ?? null,
 76:                 'status' => StocktakeStatus::Draft,
 77:                 'created_by' => $userId,
 78:                 'notes' => $data['notes'] ?? null,
 79:             ]);
 80: 
 81:             $this->syncItems($stocktake, $data['items'] ?? []);
 82: 
 83:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
 84:         });
 85:     }
 86: 
 87:     public function update(Stocktake $stocktake, array $data, int $userId): Stocktake
 88:     {
 89:         return DB::transaction(function () use ($stocktake, $data, $userId): Stocktake {
 90:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
 91:             $this->assertEditable($stocktake);
 92:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
 93:             app(BranchAccess::class)->assertBranch($userId, (int) ($data['branch_id'] ?? $stocktake->branch_id));
 94: 
 95:             $branchId = $data['branch_id'] ?? $stocktake->branch_id;
 96:             $locationId = array_key_exists('location_id', $data) ? $data['location_id'] : $stocktake->location_id;
 97:             if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $branchId)->exists()) {
 98:                 throw new BusinessException('موقع الجرد لا يتبع الفرع المحدد.');
 99:             }
100:             $scopeChanged = (int) $branchId !== $stocktake->branch_id || ($locationId === null ? null : (int) $locationId) !== $stocktake->location_id;
101:             if ($scopeChanged
102:                 && ! array_key_exists('items', $data) && $stocktake->items()->exists()) {
103:                 throw new BusinessException('تغيير نطاق الجرد يتطلب إعادة إرسال العناصر والعد الفعلي.');
104:             }
105: 
106:             if (isset($data['status'])) {
107:                 $target = StocktakeStatus::from($data['status']);
108:                 $allowed = match ($stocktake->status) {
109:                     StocktakeStatus::Draft => [StocktakeStatus::InProgress, StocktakeStatus::Cancelled],
110:                     StocktakeStatus::InProgress => [StocktakeStatus::Cancelled],
111:                     default => [],
112:                 };
113: 
114:                 if (! in_array($target, $allowed, true)) {
115:                     throw new BusinessException("لا يمكن نقل الجرد من حالة {$stocktake->status->value} إلى {$target->value}.");
116:                 }
117: 
118:                 $stocktake->status = $target;
119:             }
120: 
121:             $stocktake->fill([
122:                 'branch_id' => $data['branch_id'] ?? $stocktake->branch_id,
123:                 'location_id' => array_key_exists('location_id', $data) ? $data['location_id'] : $stocktake->location_id,
124:                 'notes' => array_key_exists('notes', $data) ? $data['notes'] : $stocktake->notes,
125:             ])->save();
126: 
127:             if (isset($data['items'])) {
128:                 if ($scopeChanged) {
129:                     $data['items'] = array_map(fn ($item) => [...$item, 'recount' => true], $data['items']);
130:                 }
131:                 $this->upsertItems($stocktake, $data['items']);
132:             }
133: 
134:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
135:         });
136:     }
137: 
138:     /**
139:      * الاعتماد: تحويل كل فارق غير صفري لحركة دفتر (stocktake_gain/stocktake_loss)
140:      * على on_hand في نطاق الجلسة (فرعها وموقعها)، ثم قفل الجلسة.
141:      */
142:     public function approve(Stocktake $stocktake, int $userId): Stocktake
143:     {
144:         return DB::transaction(function () use ($stocktake, $userId): Stocktake {
145:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
146:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
147:             $stocktake->load('items.variant');
148: 
149:             if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::InProgress], true)) {
150:                 throw new BusinessException('لا يمكن اعتماد جرد بحالة '.$stocktake->status->value.'.');
151:             }
152: 
153:             $uncounted = $stocktake->items->filter(fn ($item) => $item->counted_qty === null);
154: 
155:             if ($stocktake->items->isEmpty()) {
156:                 throw new BusinessException('لا يمكن اعتماد جرد بلا عناصر.');
157:             }
158: 
159:             if ($uncounted->isNotEmpty()) {
160:                 throw new BusinessException('لا يمكن الاعتماد: توجد عناصر لم تُعدّ بعد.');
161:             }
162: 
163:             $levels = $this->inventory->lockLevels($stocktake->items->map(fn ($item) => [
164:                 'product_variant_id' => $item->product_variant_id,
165:                 'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
166:             ])->all());
167: 
168:             // سياسة اللقطة القديمة قابلة للضبط (inventory.stocktake_stale_policy):
169:             // - reject (الافتراضي): أي حركة بعد العد ترفض الاعتماد وتعيد قائمة
170:             //   إعادة العد. يمنع أيضًا تطبيق نفس الفرق مرتين عند تداخل جلستين.
171:             // - apply_difference: تطبيق الفرق (counted − system_qty) على الرصيد
172:             //   الحالي يحفظ الحركات البينية حسابيًا (النهائي = المعدود + صافيها)
173:             //   فلا تُحبس جلسات الفروع النشطة. تسوية جرد أخرى بعد اللقطة تُرفض
174:             //   في الوضعين حتى لا يُطبّق نفس الفرق مرتين.
175:             // ولا تُحدَّث اللقطة بإعادة الحفظ في أي سياسة، بل بتغيير العدد أو recount.
176:             $rejectStale = config('inventory.stocktake_stale_policy', 'reject') !== 'apply_difference';
177:             $staleItemIds = [];
178:             $staleVariantIds = [];
179:             $latestMovements = StockMovement::query()->where('branch_id', $stocktake->branch_id)
180:                 ->where('location_id', $stocktake->location_id)->where('affected_bucket', StockBucket::OnHand->value)
181:                 ->whereIn('product_variant_id', $stocktake->items->pluck('product_variant_id'))
182:                 ->when(! $rejectStale, fn ($q) => $q->whereIn('type', [StockMovementType::StocktakeGain->value, StockMovementType::StocktakeLoss->value]))
183:                 ->selectRaw('product_variant_id, MAX(id) AS last_id')->groupBy('product_variant_id')
184:                 ->pluck('last_id', 'product_variant_id');
185:             foreach ($stocktake->items as $item) {
186:                 $key = $this->inventory->levelKey([
187:                     'product_variant_id' => $item->product_variant_id,
188:                     'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
189:                 ]);
190:                 if ((int) ($latestMovements[$item->product_variant_id] ?? 0) > (int) $item->snapshot_movement_id
191:                     || ($rejectStale && (int) round((float) $levels[$key]->on_hand * 10000) !== (int) round((float) $item->system_qty * 10000))) {
192:                     $staleItemIds[] = $item->id;
193:                     $staleVariantIds[] = $item->product_variant_id;
194:                 }
195:                 $finalQty = (float) $levels[$key]->on_hand + (float) $item->difference;
196:                 if ((int) round($finalQty * 10000) < (int) round((float) $levels[$key]->reserved * 10000) + (int) round((float) $levels[$key]->damaged * 10000)) {
197:                     throw new BusinessException('العد الفعلي أقل من المحجوز والتالف؛ راجع الحجوزات وسوِّ التالف قبل إعادة العد والاعتماد.');
198:                 }
199:             }
200: 
201:             if ($staleItemIds !== []) {
202:                 throw new BusinessException(
203:                     'توجد أصناف تغيّر رصيدها بعد عدّها وتحتاج إعادة عد قبل الاعتماد.',
204:                     ['recount_item_ids' => $staleItemIds, 'recount_variant_ids' => $staleVariantIds],
205:                 );
206:             }
207: 
208:             foreach ($stocktake->items as $item) {
209:                 $difference = (float) $item->difference;
210: 
211:                 if ($difference === 0.0) {
212:                     continue;
213:                 }
214: 
215:                 $key = $this->inventory->levelKey([
216:                     'product_variant_id' => $item->product_variant_id,
217:                     'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
218:                 ]);
219: 
220:                 $this->inventory->recordMovement([
221:                     'product_variant_id' => $item->product_variant_id,
222:                     'branch_id' => $stocktake->branch_id,
223:                     'location_id' => $stocktake->location_id,
224:                     'type' => $difference > 0 ? StockMovementType::StocktakeGain : StockMovementType::StocktakeLoss,
225:                     'affected_bucket' => StockBucket::OnHand,
226:                     'quantity' => $difference,
227:                     'unit_cost' => $item->variant?->cost_price,
228:                     'reference_type' => Stocktake::class,
229:                     'reference_id' => $stocktake->id,
230:                     'created_by' => $userId,
231:                     'notes' => 'تسوية جرد '.$stocktake->stocktake_number,
232:                 ], $levels[$key] ?? null);
233:             }
234: 
235:             $stocktake->update([
236:                 'status' => StocktakeStatus::Approved,
237:                 'approved_by' => $userId,
238:                 'approved_at' => now(),
239:             ]);
240: 
241:             return $stocktake->load(['items.variant', 'branch', 'location']);
242:         });
243:     }
244: 
245:     public function delete(Stocktake $stocktake, int $userId): void
246:     {
247:         DB::transaction(function () use ($stocktake, $userId): void {
248:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
249:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
250: 
251:             if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::Cancelled], true)) {
252:                 throw new BusinessException('لا يمكن حذف جرد إلا في حالة المسودة أو الملغي.');
253:             }
254: 
255:             $stocktake->delete();
256:         });
257:     }
258: 
259:     private function assertEditable(Stocktake $stocktake): void
260:     {
261:         if (in_array($stocktake->status, [StocktakeStatus::Approved, StocktakeStatus::Cancelled], true)) {
262:             throw new BusinessException('هذا الجرد مقفل ولا يقبل أي تعديل.');
263:         }
264:     }
265: 
266:     /**
267:      * تسجيل العناصر مع لقطة system_qty من الرصيد الحالي في نطاق الجلسة.
268:      *
269:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null}>  $items
270:      */
271:     private function syncItems(Stocktake $stocktake, array $items): void
272:     {
273:         $levels = $this->snapshotLevels($stocktake, $items);
274:         $snapshotMovementId = (int) StockMovement::query()->max('id');
275:         foreach ($items as $item) {
276:             $level = $levels->get($item['product_variant_id']);
277: 
278:             $stocktake->items()->create([
279:                 'product_variant_id' => $item['product_variant_id'],
280:                 'system_qty' => $level ? (float) $level->on_hand : 0,
281:                 'snapshot_movement_id' => $snapshotMovementId,
282:                 'counted_qty' => $item['counted_qty'] ?? null,
283:             ]);
284:         }
285:     }
286: 
287:     /**
288:      * تحديث جزئي لعناصر جرد قائم (M-4): upsert للعناصر المرسلة فقط دون حذف
289:      * الغائبين — تسجيل عدّ صنف واحد لا يتطلب إعادة إرسال قائمة الجلسة كاملة،
290:      * والجلسات الأكبر من حد الحمولة (500) تُبنى عبر دفعات متتالية هنا.
291:      *
292:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null, recount?: bool|null}>  $items
293:      */
294:     public function upsertSomeItems(Stocktake $stocktake, array $items, int $userId): Stocktake
295:     {
296:         return DB::transaction(function () use ($stocktake, $items, $userId): Stocktake {
297:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
298:             $this->assertEditable($stocktake);
299:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
300: 
301:             $this->upsertItems($stocktake, $items, deleteAbsent: false);
302:             $stocktake->touch();
303: 
304:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
305:         });
306:     }
307: 
308:     /**
309:      * تحديث عناصر جرد قائم بدون كسر ربط اللقطة بلحظة العد:
310:      * - عنصر جديد يُنشأ بلقطة الآن.
311:      * - لقطة عنصر قائم لا تتجدد إلا إذا سُجّل counted_qty أو تغيّر، أو أُرسل recount=true.
312:      * - إعادة حفظ بنفس الأعداد (الواجهة ترسل المصفوفة كاملة) لا تلمس اللقطات.
313:      * - عنصر غائب من الحمولة يُحذف من الجرد (في الاستبدال الكامل فقط).
314:      *
315:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null, recount?: bool|null}>  $items
316:      */
317:     private function upsertItems(Stocktake $stocktake, array $items, bool $deleteAbsent = true): void
318:     {
319:         $existing = $stocktake->items()->get()->keyBy('product_variant_id');
320:         $levels = $this->snapshotLevels($stocktake, $items);
321:         $snapshotMovementId = (int) StockMovement::query()->max('id');
322: 
323:         $keepIds = [];
324:         foreach ($items as $item) {
325:             $variantId = (int) $item['product_variant_id'];
326:             $currentOnHand = $levels->get($variantId) ? (float) $levels->get($variantId)->on_hand : 0.0;
327:             $row = $existing->get($variantId);
328: 
329:             if ($row === null) {
330:                 $created = $stocktake->items()->create([
331:                     'product_variant_id' => $variantId,
332:                     'system_qty' => $currentOnHand,
333:                     'snapshot_movement_id' => $snapshotMovementId,
334:                     'counted_qty' => $item['counted_qty'] ?? null,
335:                 ]);
336:                 $keepIds[] = $created->id;
337: 
338:                 continue;
339:             }
340: 
341:             $keepIds[] = $row->id;
342:             $updates = [];
343: 
344:             if (array_key_exists('counted_qty', $item)) {
345:                 $updates['counted_qty'] = $item['counted_qty'];
346: 
347:                 $countChanged = $item['counted_qty'] !== null
348:                     && ($row->counted_qty === null || (float) $item['counted_qty'] !== (float) $row->counted_qty);
349: 
350:                 if ($countChanged || ! empty($item['recount'])) {
351:                     $updates['system_qty'] = $currentOnHand;
352:                     $updates['snapshot_movement_id'] = $snapshotMovementId;
353:                 }
354:             } elseif (! empty($item['recount'])) {
355:                 $updates['system_qty'] = $currentOnHand;
356:                 $updates['snapshot_movement_id'] = $snapshotMovementId;
357:             }
358: 
359:             if ($updates !== []) {
360:                 $row->update($updates);
361:             }
362:         }
363: 
364:         if ($deleteAbsent) {
365:             $stocktake->items()->whereNotIn('id', $keepIds)->delete();
366:         }
367:     }
368: 
369:     private function snapshotLevels(Stocktake $stocktake, array $items): Collection
370:     {
371:         return $this->inventory->lockLevels(array_map(fn ($item) => [
372:             'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
373:             'product_variant_id' => $item['product_variant_id'],
374:         ], $items))->keyBy('product_variant_id');
375:     }
376: }

