  82:           <Field label="البريد الإلكتروني" error={err.email}><input dir="ltr" className={`inp mono text-left ${err.email ? 'err' : ''}`} value={f.email} onChange={e => set('email', e.target.value)} placeholder="branch@company.com" /></Field>
