 127:       if (f.id) {
 128:         const cur = list.find(b => b.id === f.id) || {};
 129:         const next = payload(f);
 130:         const diff = {};
 131:         ['name', 'code', 'type', 'is_active', 'phone', 'email', 'address', 'city'].forEach(k => {
 132:           if ((next[k] ?? null) !== (cur[k] ?? null)) diff[k] = next[k] ?? null;
 133:         });
 134:         // PUT sends only changed fields, so an untouched unique code never re-triggers 422.
 135:         if (Object.keys(diff).length) await branchesApi.update(f.id, diff);
 136:       } else {
 137:         await branchesApi.create(payload(f));
 138:       }
 139:     } catch (e) {
 140:       const ne = normalizeError(e);
 141:       return { fields: ne.fields, message: ne.message };
 142:     }
 143:     setForm({ open: false, initial: null });
 144:     reloadBranches();
 145:     toast(f.id ? 'تم حفظ التعديلات' : 'تمت إضافة ' + (f.type === 'warehouse' ? 'المخزن' : 'الفرع'));
 146:     return null;
 147:   };
 148:   const doDelete = async () => {
 149:     setDelBusy(true); setDelErr(null);
 150:     try {
 151:       await branchesApi.remove(del.id);
 152:       setDel(null); reloadBranches(); toast('تم الحذف');
 153:     } catch (e) {
 154:       setDelErr(normalizeError(e).message);
 155:     } finally { setDelBusy(false); }
 156:   };
 157:   const disableInstead = async () => {
 158:     setDelBusy(true);
 159:     try {
 160:       await branchesApi.update(del.id, { is_active: false });
 161:       setDel(null); setDelErr(null); reloadBranches(); toast('تم تعطيل «' + del.name + '» بدلًا من الحذف');
 162:     } catch (e) {
 163:       setDelErr(normalizeError(e).message);
 164:     } finally { setDelBusy(false); }
 165:   };
 166: 
 167:   const counts = { all: list.length, branch: list.filter(b => b.type === 'branch').length, warehouse: list.filter(b => b.type === 'warehouse').length };
 168: 
 169:   return (
 170:     <section className="space-y-5">
 171:       <PageHead title="الفروع والمخازن" sub="سجل نقاط البيع والمخازن ومواقع التخزين التابعة لكل منها."
 172:         actions={canAdd && <button className="btn btn-dark" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={14} w={2.2} /> إضافة فرع / مخزن</button>} />
 173: 
 174:       <Card>
 175:         <CardHead title="القائمة" meta={phase === 'ready' ? `${rows.length} من ${list.length} · ${list.filter(b => b.is_active).length} نشط` : null}
 176:           right={<>
 177:             <div className="seg">
 178:               {[['all', 'الكل'], ['branch', 'فروع'], ['warehouse', 'مخازن']].map(([k, l]) => (
 179:                 <button key={k} className={type === k ? 'on' : ''} onClick={() => setType(k)}>{l} <span className="num c-muted mr-1">{counts[k]}</span></button>
 180:               ))}
 181:             </div>
 182:             <SearchPill value={q} onChange={setQ} placeholder="الاسم، الكود، المدينة" />
 183:           </>} />
 184:         <Phase phase={phase} cols={8} error={error} onRetry={reloadBranches}
 185:           empty={<EmptyState icon="store" title="لا توجد فروع أو مخازن بعد" sub="ابدأ بإضافة المخزن الرئيسي، ثم أضف مواقع التخزين بداخله."
 186:             action={canAdd && <button className="btn btn-dark btn-sm" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={13} /> إضافة أول فرع</button>} />}>
 187:           {rows.length === 0 ? <EmptyState icon="search" title="لا توجد نتائج" sub="جرّب كلمة بحث أخرى أو غيّر نوع الفلتر." /> : (
 188:             <div className="overflow-x-auto">
 189:               <table className="vt">
 190:                 <thead><tr>
 191:                   <th>الاسم</th><th>الكود</th><th>النوع</th><th>المدينة</th><th>الهاتف</th><th>الحالة</th><th>مواقع التخزين</th><th>الموظفون</th><th></th>
 192:                 </tr></thead>
 193:                 <tbody>
 194:                   {rows.map(b => (
 195:                     <tr key={b.id}>
 196:                       <td>
 197:                         <div className="flex items-center gap-2.5">
 198:                           <span className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${b.type === 'warehouse' ? '' : 'v-icon-well'}`} style={b.type === 'warehouse' ? { background: 'var(--accent-orange-light)', color: 'var(--accent-orange)' } : {}}>
 199:                             <Icon n={b.type === 'warehouse' ? 'warehouse' : 'store'} s={14} />
 200:                           </span>
 201:                           <div><div className="font-semibold c-primary">{b.name}</div><div className="text-[11px] c-muted mono">{b.email || '—'}</div></div>
 202:                         </div>
 203:                       </td>
 204:                       <td><Sku>{b.code}</Sku></td>
 205:                       <td><TypeBadge type={b.type} /></td>
 206:                       <td className="c-secondary">{b.city || '—'}</td>
 207:                       <td className="num c-secondary" dir="ltr">{b.phone || '—'}</td>
 208:                       <td><ActiveBadge on={b.is_active} /></td>
 209:                       <td>
 210:                         <button onClick={() => go('locations', { branchId: b.id })} className="flex items-center gap-2 group">
 211:                           <span className="num font-semibold c-primary">{b.locations_count ?? '—'}</span>
 212:                           <span className="text-[11.5px] c-orange font-semibold opacity-0 group-hover:opacity-100 transition">فتح ←</span>
 213:                         </button>
 214:                       </td>
 215:                       <td className="num c-secondary">{b.employees_count ?? '—'}</td>
 216:                       <td>
 217:                         <div className="flex items-center gap-0.5 justify-end">
 218:                           <button className="icon-btn" title="مواقع التخزين" onClick={() => go('locations', { branchId: b.id })}><Icon n="pin" s={15} /></button>
 219:                           {canEdit && <button className="icon-btn" title="تعديل" onClick={() => setForm({ open: true, initial: b })}><Icon n="edit" s={15} /></button>}
 220:                           {canDelete && <button className="icon-btn hover:!text-[var(--badge-red-text)]" title="حذف" onClick={() => { setDel(b); setDelErr(null); }}><Icon n="trash" s={15} /></button>}
 221:                         </div>
 222:                       </td>
 223:                     </tr>
 224:                   ))}
 225:                 </tbody>
 226:               </table>
 227:             </div>
 228:           )}
 229:         </Phase>
 230:       </Card>
 231: 
 232:       <BranchForm open={form.open} initial={form.initial} onClose={() => setForm({ open: false, initial: null })} onSave={save} />
 233:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} onConfirm={doDelete} danger busy={delBusy} error={delErr}
 234:         title={`حذف ${del?.type === 'warehouse' ? 'المخزن' : 'الفرع'}؟`} confirmLabel="حذف نهائي"
 235:         body={<>سيتم حذف <b className="c-primary">{del?.name}</b> (<span className="mono">{del?.code}</span>). لا يمكن التراجع عن هذا الإجراء، وسيرفض الخادم الحذف إذا كانت هناك مواقع تخزين أو أرصدة أو حركات مرتبطة.
 236:           {delErr && canEdit && <div className="mt-3"><button type="button" className="btn btn-soft btn-sm" disabled={delBusy} onClick={disableInstead}>تعطيل بدلًا من الحذف</button></div>}</>} />
 237:     </section>
 238:   );
 239: }
