1022: // Product-level then variant-level filter (product narrows the variant list)
1023: 
1024: // ---------------- 3. Stock balances ----------------
1025: function StockScreen({ go, params }) {
1026:   const { toast, can, branchesQuery, variantCache } = useInv();
1027:   const [page, setPage] = useState(1);
1028:   const restriction = useRestrictedBranch();
1029:   const allowed = canAny(can, 'inventory.view');
1030: 
1031:   const f = {
1032:     branchId: params.branchId ? Number(params.branchId) : null,
1033:     locationId: params.locationId ? Number(params.locationId) : null,
1034:     variantId: params.variantId ? Number(params.variantId) : null,
1035:     low: params.low === '1',
1036:   };
1037:   // A restricted user is pinned to their branch (the backend scopes them anyway).
1038:   const effBranch = restriction.locked ? restriction.branchId : f.branchId;
1039:   const set = p => {
1040:     const n = { branchId: f.branchId, locationId: f.locationId, variantId: f.variantId, low: f.low ? '1' : undefined, ...p };
1041:     if (n.branchId !== f.branchId) n.locationId = undefined;
1042:     if (!n.low) delete n.low;
1043:     go('stock', n);
1044:   };
1045: 
1046:   const locsQuery = useBranchesWithLocations(effBranch);
1047:   const query = useApi(signal => stockApi.levels({
1048:     branch_id: effBranch || undefined, location_id: f.locationId || undefined,
1049:     product_variant_id: f.variantId || undefined, low_stock: f.low || undefined,
1050:     per_page: 15, page,
1051:   }, signal).then(res => { cacheVariantNames(variantCache, (res.data || []).map(r => r.variant)); return res; }),
1052:   [effBranch || 0, f.locationId || 0, f.variantId || 0, f.low, page]);
1053: 
1054:   if (!allowed) return <NoPerm title="أرصدة المخزون" perm="inventory.view" go={go} />;
1055: 
1056:   const rows = query.data?.data || [];
1057:   const meta = query.data?.meta;
1058:   const { phase, error } = apiPhase(query, rows.length === 0);
1059:   const onRetry = () => query.reload();
1060:   const shared = branchesQuery.data || [];
1061:   const branchOptions = (restriction.locked ? shared.filter(b => b.id === restriction.branchId) : shared.filter(b => b.is_active))
1062:     .map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1063:   const locOptions = (locsQuery.data || []).filter(l => l.is_active).map(l => ({ value: l.id, label: `${l.name} (${l.code})` }));
1064:   const active = (effBranch ? 1 : 0) + (f.locationId ? 1 : 0) + (f.variantId ? 1 : 0) + (f.low ? 1 : 0);
1065:   const sum = k => rows.reduce((a, s) => a + Number(s[k] || 0), 0);
1066:   const canAdjust = canAny(can, 'inventory.adjust');
1067: 
1068:   return (
1069:     <section className="space-y-5">
1070:       <PageHead title="أرصدة المخزون" sub="الكميات الحالية لكل SKU في كل فرع وموقع. لتغيير أي كمية استخدم عملية مخزنية."
1071:         actions={canAdjust && <button className="btn btn-dark" onClick={() => go('adjust')}><Icon n="sliders" s={14} /> تسوية جديدة</button>} />
1072: 
1073:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
1074:         <KPI hot label="المتاح" icon="box" value={phase === 'ready' ? formatQty(sum('available')) : '—'} sub={`${rows.length} سطر رصيد · في الصفحة الحالية`} />
1075:         <KPI label="المحجوز" icon="lock" value={phase === 'ready' ? formatQty(sum('reserved')) : '—'} sub="لطلبات مفتوحة" />
1076:         <KPI label="قيد النقل" icon="truck" value={phase === 'ready' ? formatQty(sum('in_transit')) : '—'} sub="في تحويلات مشحونة" />
1077:         <button onClick={() => set({ low: f.low ? undefined : '1' })} className="text-right">
1078:           <KPI label="تحت حد إعادة الطلب" icon="alert" value={phase === 'ready' ? rows.filter(r => r.is_low_stock).length : '—'} sub={f.low ? 'الفلتر مفعّل · اضغط للإلغاء' : 'اضغط لعرضها فقط'} />
1079:         </button>
1080:       </div>
1081: 
1082:       <Card stagger={3}>
1083:         <CardHead title="الأرصدة" meta={phase === 'ready' ? `${rows.length} سطر` : null}
1084:           right={<span className="text-[11.5px] c-muted flex items-center gap-1.5"><Icon n="eye" s={13} /> للعرض فقط</span>} />
1085:         <FilterBar active={active} onReset={() => go('stock', {})}>
1086:           <FItem label="الفرع"><Sel small value={effBranch} onChange={v => set({ branchId: v || undefined })} placeholder="كل الفروع" disabled={restriction.locked} options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1087:           <FItem label="الموقع" w="w-40"><Sel small value={f.locationId} onChange={v => set({ locationId: v || undefined })} placeholder={effBranch ? 'كل المواقع' : 'اختر فرعًا أولًا'} disabled={!effBranch} options={locOptions} className="!bg-[var(--bg-card)]" /></FItem>
1088:           <FItem label="الصنف / SKU" w="w-64"><VariantPicker small value={f.variantId} onChange={v => set({ variantId: v || undefined })} placeholder="كل الأصناف" allowClear /></FItem>
1089:           <label className="flex items-center gap-2.5 px-3 py-2 rounded-full cursor-pointer mb-0.5" style={{ background: f.low ? 'var(--accent-orange-light)' : 'var(--bg-card)' }}>
1090:             <Toggle on={f.low} onChange={v => set({ low: v ? '1' : undefined })} />
1091:             <span className="text-[12px] font-medium c-primary">المخزون المنخفض فقط</span>
1092:           </label>
1093:         </FilterBar>
1094:         <Phase phase={phase} cols={10} rows={7} error={error} onRetry={onRetry}
1095:           empty={<EmptyState icon="box" title="لا توجد أرصدة مسجّلة بعد" sub="سجّل الكميات الافتتاحية عن طريق تسوية زيادة مع سبب واضح مثل «رصيد افتتاحي»."
1096:             action={canAdjust && <button className="btn btn-dark btn-sm" onClick={() => go('adjust')}><Icon n="plus" s={13} /> إدخال رصيد افتتاحي</button>} />}>
1097:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد أرصدة تطابق الفلاتر" sub="غيّر الفلاتر أو امسحها لعرض كل الأرصدة." /> : (
1098:             <div className="overflow-x-auto -mx-1 px-1">
1099:               <table className="vt">
1100:                 <thead><tr>
1101:                   <th>المنتج</th><th>SKU</th><th>الفرع</th><th>الموقع</th>
1102:                   <th className="t-num">الموجود</th><th className="t-num">المحجوز</th><th className="t-num">التالف</th><th className="t-num">قيد النقل</th><th className="t-num">المتاح</th><th className="t-num">حد الطلب</th><th>آخر تحديث</th><th></th>
1103:                 </tr></thead>
1104:                 <tbody>
1105:                   {rows.map(s => {
1106:                     const low = !!s.is_low_stock;
1107:                     const pct = Math.min(100, Number(s.reorder_level) ? Number(s.available) / (Number(s.reorder_level) * 2) * 100 : 100);
1108:                     const v = s.variant || variantCache.get(Number(s.product_variant_id)) || {};
1109:                     return (
1110:                       <tr key={s.id}>
1111:                         <td><div className="min-w-0"><div className="font-medium c-primary truncate">{pickName({ product_name_ar: v.product_name_ar, product_name_en: v.product_name_en, sku: v.sku || s.product_variant_id })}</div></div></td>
1112:                         <td><Sku>{v.sku || `#${s.product_variant_id}`}</Sku></td>
1113:                         <td className="c-secondary">{s.branch?.name || '—'}</td>
1114:                         <td>{s.location ? <span className="text-[11.5px] c-secondary">{s.location.name}</span> : <span className="text-[11.5px] c-muted">بدون موقع</span>}</td>
1115:                         <td className="t-num num font-semibold c-primary">{formatQty(s.on_hand)}</td>
1116:                         <td className="t-num num c-secondary">{formatQty(s.reserved)}</td>
1117:                         <td className="t-num num" style={{ color: Number(s.damaged) ? 'var(--badge-red-text)' : 'var(--text-muted)' }}>{formatQty(s.damaged)}</td>
1118:                         <td className="t-num num" style={{ color: Number(s.in_transit) ? 'var(--badge-blue-text)' : 'var(--text-muted)' }}>{formatQty(s.in_transit)}</td>
1119:                         <td className="t-num">
1120:                           <div className="flex flex-col items-end gap-1">
1121:                             <span className="flex items-center gap-1.5"><span className={`num font-bold ${low ? '' : 'c-primary'}`} style={low ? { color: 'var(--accent-orange)' } : {}}>{formatQty(s.available)}</span>{low && <Badge cls="b-amber" dot>منخفض</Badge>}</span>
1122:                             <span className="w-16 h-1 rounded-full hatched overflow-hidden flex justify-end" style={{ direction: 'ltr' }}>
1123:                               <span className="block h-full rounded-full" style={{ width: pct + '%', background: low ? 'var(--accent-orange)' : 'var(--text-primary)' }} />
1124:                             </span>
1125:                           </div>
1126:                         </td>
1127:                         <td className="t-num num c-muted">{formatQty(s.reorder_level)}</td>
1128:                         <td className="num text-[11.5px] c-muted">{formatDate(s.updated_at)}</td>
1129:                         <td>
1130:                           <div className="flex items-center gap-0.5 justify-end">
1131:                             <button className="icon-btn" title="حركات الصنف" onClick={() => go('moves', { variantId: s.product_variant_id, branchId: s.branch?.id, locationId: s.location?.id })}><Icon n="history" s={15} /></button>
1132:                             {canAdjust && <button className="icon-btn" title="تسوية" onClick={() => go('adjust', { branchId: s.branch?.id, locId: s.location?.id, variantId: s.product_variant_id })}><Icon n="sliders" s={15} /></button>}
1133:                           </div>
1134:                         </td>
1135:                       </tr>
1136:                     );
1137:                   })}
1138:                 </tbody>
1139:               </table>
1140:             </div>
1141:           )}
1142:         </Phase>
1143:         {meta && (meta.last_page > 1) && (
1144:           <div className="flex items-center justify-between mt-4">
1145:             <button className="btn btn-soft btn-sm" disabled={page <= 1} onClick={() => setPage(p => Math.max(1, p - 1))}>السابق</button>
1146:             <span className="text-[12px] c-muted num">صفحة {page} من {meta.last_page}</span>
1147:             <button className="btn btn-soft btn-sm" disabled={page >= meta.last_page} onClick={() => setPage(p => p + 1)}>التالي</button>
1148:           </div>
1149:         )}
1150:       </Card>
1151:     </section>
1152:   );
1153: }
1154: // NOTE: "المتاح" KPI is page-scoped on purpose — GET inventory returns one page
1155: // and there is no summary endpoint, so a global total cannot be shown honestly.
1156: 
1157: // ---------------- 4. Adjustment ----------------
1158: const ADJ_MAX = 100;
1159: let __adjLineId = 1;
1160: const newAdjLine = (p = {}) => ({ key: __adjLineId++, variantId: null, type: 'increase', qty: '', reason: '', ...p });
1161: 
1162: const ADJ_API_TYPES = {
1163:   increase:         { label: 'زيادة',              cls: 'b-green' },
1164:   decrease:         { label: 'نقصان',              cls: 'b-red'   },
1165:   mark_damaged:     { label: 'تسجيل تالف',         cls: 'b-amber' },
1166:   write_off_damaged:{ label: 'إعدام تالف',         cls: 'b-red'   },
1167:   restore_damaged:  { label: 'استرجاع من التالف',  cls: 'b-blue'  },
1168: };
1169: 
1170: function AdjustScreen({ go, params }) {
1171:   const { toast, can, branchesQuery, variantCache } = useInv();
1172:   const { keyFor, reset } = useIdempotencyKey();
1173:   const [branchId, setBranchId] = useState(params.branchId ? Number(params.branchId) : null);
1174:   const [locId, setLocId] = useState(params.locId ? Number(params.locId) : (params.locationId ? Number(params.locationId) : null));
1175:   const [lines, setLines] = useState(() => [newAdjLine(params.variantId ? { variantId: Number(params.variantId) } : {})]);
1176:   const [tried, setTried] = useState(false);
1177:   const [confirm, setConfirm] = useState(false);
1178:   const [busy, setBusy] = useState(false);
1179:   const [srvErr, setSrvErr] = useState(null);
1180:   const [rowErrs, setRowErrs] = useState({});
1181:   const [opening, setOpening] = useState(false);
1182:   const allowed = can('inventory.adjust');
1183:   const restriction = useRestrictedBranch();
1184:   const effBranch = restriction.locked ? restriction.branchId : branchId;
1185: 
1186:   const locsQuery = useBranchesWithLocations(effBranch);
1187: 
1188:   if (!allowed) return <NoPerm title="تسوية المخزون" perm="inventory.adjust" go={go} />;
1189: 
1190:   const upd = (key, p) => { setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l)); setRowErrs({}); };
1191:   const lineErr = l => {
1192:     const e = {};
1193:     if (!l.variantId) e.variantId = true;
1194:     const qv = toLatinDigits(l.qty);
1195:     if (!qv || !QTY_RE.test(qv) || !(Number(qv) > 0) || Number(qv) > QTY_MAX) e.qty = 'كمية موجبة حتى 4 منازل عشرية';
1196:     if (!l.reason.trim()) e.reason = true;
1197:     else if (l.reason.trim().length > 1000) e.reason = true;
1198:     return e;
1199:   };
1200:   const clientErrs = lines.map(lineErr);
1201:   const valid = effBranch && clientErrs.every(e => !Object.keys(e).length);
1202:   const dupes = lines.filter((l, i) => l.variantId && lines.findIndex(x => x.variantId === l.variantId && x.type === l.type) !== i).length;
1203: 
1204:   const applyOpening = on => {
1205:     setOpening(on);
1206:     setLines(ls => ls.map(l => on ? { ...l, type: 'increase', reason: l.reason || 'رصيد افتتاحي' } : l));
1207:   };
1208: 
1209:   const execute = async () => {
1210:     if (busy) return; // double-click guard: one movement per key
1211:     setBusy(true); setSrvErr(null); setRowErrs({});
1212:     const payload = {
1213:       branch_id: effBranch,
1214:       ...(locId ? { location_id: locId } : {}),
1215:       items: lines.map(l => ({ product_variant_id: l.variantId, adjustment_type: l.type, quantity: Number(toLatinDigits(l.qty)), reason: l.reason.trim() || null })),
1216:     };
1217:     try {
1218:       const res = await adjustmentsApi.create(payload, keyFor(payload));
1219:       reset(); // new key only after success
1220:       setConfirm(false); setLines([newAdjLine()]); setTried(false);
1221:       toast(res.message || `تم تنفيذ التسوية · ${lines.length} بند`);
1222:       go('moves', { branchId: effBranch });
1223:     } catch (e) {
1224:       const ne = normalizeError(e);
1225:       setRowErrs({ ...ne.fields, ...groupItemsErrors(ne.fields) });
1226:       // Server messages are Arabic — shown verbatim. 409 busy-lock keeps the
1227:       // dialog open so retry reuses the SAME key (no duplicate movement).
1228:       setSrvErr(ne.message);
1229:       setBusy(false);
1230:     }
1231:   };
1232: 
1233:   const totals = Object.keys(ADJ_API_TYPES).map(k => ({ k, n: lines.filter(l => l.type === k && l.variantId).length })).filter(x => x.n);
1234:   const shared = branchesQuery.data || [];
1235:   const branchOptions = (restriction.locked ? shared.filter(b => b.id === restriction.branchId) : shared.filter(b => b.is_active))
1236:     .map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1237:   const locOptions = (locsQuery.data || []).filter(l => l.is_active).map(l => ({ value: l.id, label: `${l.name} (${l.code})` }));
1238:   const brName = shared.find(b => b.id === effBranch)?.name || '';
1239:   const locCode = (locsQuery.data || []).find(l => l.id === locId)?.code || '';
1240: 
1241:   return (
1242:     <section className="space-y-5">
1243:       <PageHead title="تسوية المخزون" back={{ label: 'أرصدة المخزون', onClick: () => go('stock') }}
1244:         sub="زيادة أو خصم كميات، أو نقلها من وإلى التالف. التسوية تُنفَّذ كعملية واحدة وتنعكس فورًا على الأرصدة والحركات." />
1245: 
1246:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
1247:         <div className="lg:col-span-9 space-y-5">
1248:           <Card stagger={2}>
1249:             <CardHead title="بيانات العملية" />
1250:             <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
1251:               <Field label="الفرع / المخزن" req error={tried && !effBranch ? 'اختر الفرع' : rowErrs.branch_id}>
1252:                 <Sel value={effBranch} onChange={v => { if (!restriction.locked) { setBranchId(v || null); setLocId(null); } }} placeholder="اختر…" disabled={restriction.locked} options={branchOptions} className={tried && !effBranch ? 'err' : ''} />
1253:               </Field>
1254:               <Field label="موقع التخزين" hint="اختياري — يطبَّق على كل البنود" error={rowErrs.location_id}>
1255:                 <Sel value={locId} onChange={v => setLocId(v || null)} placeholder={effBranch ? 'بدون موقع محدد' : 'اختر الفرع أولًا'} disabled={!effBranch} options={locOptions} />
1256:               </Field>
1257:               <div>
1258:                 <span className="field-label">إدخال رصيد افتتاحي</span>
1259:                 <label className="v-subcard px-3.5 py-2 flex items-center justify-between cursor-pointer" style={{ borderRadius: 12 }}>
1260:                   <span className="text-[12px] c-secondary">كل البنود = زيادة</span>
1261:                   <Toggle on={opening} onChange={applyOpening} />
1262:                 </label>
1263:               </div>
1264:             </div>
1265:             {opening && <div className="mt-4"><InlineAlert kind="blue" icon="info" title="رصيد افتتاحي">تُسجَّل الكميات الافتتاحية حاليًا كتسوية زيادة. اكتب سببًا واضحًا لكل بند حتى يسهل تتبّعها في سجل الحركات.</InlineAlert></div>}
1266:           </Card>
1267: 
1268:           <Card stagger={3}>
1269:             <CardHead title="البنود" meta={<span className="num">{lines.length} / {ADJ_MAX}</span>}
1270:               right={<button className="btn btn-soft btn-sm" disabled={lines.length >= ADJ_MAX} onClick={() => setLines(ls => [...ls, newAdjLine(opening ? { reason: 'رصيد افتتاحي' } : {})])}><Icon n="plus" s={13} /> إضافة بند</button>} />
1271:             {dupes > 0 && <div className="mb-3"><InlineAlert kind="amber" title="بنود مكررة">يوجد {dupes} بند مكرر بنفس SKU ونفس نوع التسوية — سيتم دمجها عند التنفيذ.</InlineAlert></div>}
1272:             <div className="overflow-x-auto">
1273:               <table className="vt">
1274:                 <thead><tr><th className="w-8">#</th><th style={{ minWidth: 280 }}>المنتج / المتغير</th><th style={{ minWidth: 170 }}>نوع التسوية</th><th style={{ minWidth: 120 }}>الكمية</th><th style={{ minWidth: 200 }}>السبب</th><th></th></tr></thead>
1275:                 <tbody>
1276:                   {lines.map((l, i) => {
1277:                     const e = { ...(tried ? clientErrs[i] : {}), ...(rowErrs[i] || {}) };
1278:                     return (
1279:                       <tr key={l.key} className="align-top">
1280:                         <td className="num c-muted pt-4">{i + 1}</td>
1281:                         <td>
1282:                           <div className={e.variantId ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v })} /></div>
1283:                           {e.product_variant_id && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.product_variant_id}</div>}
1284:                         </td>
1285:                         <td><Sel small value={l.type} onChange={v => upd(l.key, { type: v || 'increase' })} options={Object.entries(ADJ_API_TYPES).map(([k, t]) => ({ value: k, label: t.label }))} /></td>
1286:                         <td>
1287:                           <NumInput small value={l.qty} onChange={v => upd(l.key, { qty: v })} err={e.qty || e.quantity} placeholder="0.0000" />
1288:                           {(e.qty || e.quantity) && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.qty || e.quantity}</div>}
1289:                         </td>
1290:                         <td><input maxLength={1000} className={`inp inp-sm ${e.reason ? 'err' : ''}`} value={l.reason} onChange={ev => upd(l.key, { reason: ev.target.value })} placeholder="مثال: كسر أثناء التفريغ" />
1291:                           {e.reason && typeof e.reason === 'string' && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.reason}</div>}</td>
1292:                         <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1293:                       </tr>
1294:                     );
1295:                   })}
1296:                 </tbody>
1297:               </table>
1298:             </div>
1299:             <div className="mt-3 text-[11px] c-muted flex items-center gap-1.5"><Icon n="info" s={12} /> الكميات موجبة دائمًا وتقبل حتى 4 منازل عشرية. اتجاه الحركة يحدده نوع التسوية.</div>
1300:           </Card>
1301:         </div>
1302: 
1303:         <div className="lg:col-span-3 lg:sticky lg:top-5">
1304:           <Card stagger={4}>
1305:             <h3 className="font-display text-[15px] font-semibold c-primary mb-3">ملخص</h3>
1306:             <div className="space-y-2 text-[12.5px]">
1307:               <div className="flex justify-between"><span className="c-secondary">الفرع</span><span className="font-medium c-primary">{brName || '—'}</span></div>
1308:               <div className="flex justify-between"><span className="c-secondary">الموقع</span><span className="mono c-primary" dir="ltr">{locCode || '—'}</span></div>
1309:               <div className="flex justify-between"><span className="c-secondary">عدد البنود</span><span className="num font-semibold c-primary">{lines.length}</span></div>
1310:             </div>
1311:             <div className="h-px my-4" style={{ background: 'var(--divider-color)' }} />
1312:             <div className="space-y-1.5">
1313:               {totals.length === 0 && <div className="text-[11.5px] c-muted">لم يتم اختيار أصناف بعد</div>}
1314:               {totals.map(t => <div key={t.k} className="flex items-center justify-between"><Badge cls={ADJ_API_TYPES[t.k].cls}>{ADJ_API_TYPES[t.k].label}</Badge><span className="num text-[12px] c-primary font-semibold">{t.n}</span></div>)}
1315:             </div>
1316:             <div className="mt-5 space-y-2">
1317:               <button className="btn btn-orange w-full" onClick={() => { setTried(true); if (valid) { setSrvErr(null); setRowErrs({}); setConfirm(true); } }}>
1318:                 <Icon n="check" s={14} w={2.2} /> تنفيذ التسوية
1319:               </button>
1320:               <button className="btn btn-soft w-full" onClick={() => go('stock')}>إلغاء</button>
1321:             </div>
1322:             {tried && !valid && <div className="text-[11px] mt-3" style={{ color: 'var(--badge-red-text)' }}>أكمل الحقول المطلوبة المظللة بالأحمر.</div>}
