1336:                   <span className="num font-semibold c-primary">{formatQty(toLatinDigits(l.qty))}</span>
1337:                 </div>
1338:                 {(rowErrs[fi]?.quantity || rowErrs[fi]?.product_variant_id) && <div className="text-[11px] mt-1 text-right" style={{ color: 'var(--badge-red-text)' }}>{rowErrs[fi]?.quantity || rowErrs[fi]?.product_variant_id}</div>}
1339:               </div>
