1469: function TransfersScreen({ go }) {
1470:   const { can, branchesQuery } = useInv();
1471:   const [st, setSt] = useState('all');
1472:   const [q, setQ] = useState('');
1473:   const [fromF, setFromF] = useState(null);
1474:   const [toF, setToF] = useState(null);
1475:   const allowed = canAny(can, 'transfers.view', 'transfers.manage');
1476: 
1477:   // Small cardinality like branches: fetch all pages once (per_page=100) so the
1478:   // KPIs are exact and status/branch/search filters run client-side.
1479:   const query = useApi(signal => (async () => {
1480:     const all = []; let page = 1; let last = 1;
1481:     do {
1482:       const res = await transfersApi.list({ per_page: 100, page, from_branch_id: fromF || undefined, to_branch_id: toF || undefined, status: st === 'all' ? undefined : st }, signal);
1483:       all.push(...(res.data || [])); last = res.meta?.last_page || 1; page += 1;
1484:     } while (page <= last);
1485:     return all;
1486:   })(), [fromF, toF, st]);
1487: 
1488:   if (!allowed) return <NoPerm title="التحويلات المخزنية" perm="transfers.view" go={go} />;
1489: 
1490:   const list = query.data || [];
1491:   const { phase, error } = apiPhase(query, list.length === 0);
1492:   const onRetry = () => query.reload();
1493:   const ql = q.trim().toLowerCase();
1494:   const rows = list.filter(t => (st === 'all' || t.status === st)
1495:     && (!fromF || t.from_branch?.id === fromF) && (!toF || t.to_branch?.id === toF)
1496:     && (!ql || (t.transfer_number || '').toLowerCase().includes(ql)));
1497:   const cnt = k => list.filter(t => t.status === k).length;
1498:   const active = (fromF ? 1 : 0) + (toF ? 1 : 0) + (ql ? 1 : 0) + (st !== 'all' ? 1 : 0);
1499:   const shared = branchesQuery.data || [];
1500:   const branchOptions = shared.filter(b => b.is_active).map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1501:   const canCreate = canAny(can, 'transfers.create', 'transfers.manage');
1502: 
1503:   return (
1504:     <section className="space-y-5">
1505:       <PageHead title="التحويلات المخزنية" sub="نقل البضاعة بين فرعين أو مخزنين عبر مراحل: مسودة ← اعتماد ← شحن ← استلام."
1506:         actions={canCreate && <button className="btn btn-dark" onClick={() => go('transfer-edit', {})}><Icon n="plus" s={14} w={2.2} /> تحويل جديد</button>} />
1507: 
1508:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
1509:         <KPI label="مسودات" icon="edit" value={phase === 'ready' ? cnt('draft') : '—'} sub="بانتظار الاعتماد" />
1510:         <KPI label="معتمدة" icon="check" value={phase === 'ready' ? cnt('approved') : '—'} sub="جاهزة للشحن" />
1511:         <KPI hot label="في الطريق" icon="truck" value={phase === 'ready' ? cnt('shipped') : '—'} sub="بانتظار الاستلام" />
1512:         <KPI label="مستلمة" icon="inbox" value={phase === 'ready' ? cnt('received') : '—'} sub="تحويلات مستلمة" />
1513:       </div>
1514: 
1515:       <Card stagger={3}>
1516:         <CardHead title="القائمة" right={<>
1517:           <div className="seg">
1518:             <button className={st === 'all' ? 'on' : ''} onClick={() => setSt('all')}>الكل</button>
1519:             {Object.entries(TRANSFER_STATUS).map(([k, t]) => <button key={k} className={st === k ? 'on' : ''} onClick={() => setSt(k)}>{t}</button>)}
1520:           </div>
1521:           <SearchPill value={q} onChange={setQ} placeholder="رقم التحويل" w="w-32" />
1522:         </>} />
1523:         <FilterBar active={active} onReset={() => { setFromF(null); setToF(null); setQ(''); setSt('all'); }}>
1524:           <FItem label="من فرع"><Sel small value={fromF} onChange={v => setFromF(v || null)} placeholder="كل الفروع" options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1525:           <FItem label="إلى فرع"><Sel small value={toF} onChange={v => setToF(v || null)} placeholder="كل الفروع" options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1526:         </FilterBar>
1527:         <Phase phase={phase} cols={6} error={error} onRetry={onRetry}
1528:           empty={<EmptyState icon="swap" title="لا توجد تحويلات" sub="أنشئ أول تحويل لنقل الكميات من المخزن الرئيسي إلى الفروع."
1529:             action={canCreate && <button className="btn btn-dark btn-sm" onClick={() => go('transfer-edit', {})}><Icon n="plus" s={13} /> تحويل جديد</button>} />}>
1530:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد تحويلات بهذه الحالة" /> : (
1531:             <table className="vt">
1532:               <thead><tr><th>رقم التحويل</th><th>المصدر ← الوجهة</th><th>التقدّم</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead>
1533:               <tbody>
1534:                 {rows.map(t => {
1535:                   const idx = TR_FLOW.indexOf(t.status);
1536:                   return (
1537:                     <tr key={t.id} className="cursor-pointer" onClick={() => go('transfer', { id: t.id })}>
1538:                       <td><span className="mono text-[12px] font-semibold c-primary" dir="ltr">{t.transfer_number}</span></td>
1539:                       <td>
1540:                         <div className="flex items-center gap-2">
1541:                           <span className="font-medium c-primary">{t.from_branch?.name || '—'}</span>
1542:                           <Icon n="arrowL" s={14} className="c-orange" />
1543:                           <span className="font-medium c-primary">{t.to_branch?.name || '—'}</span>
1544:                         </div>
1545:                       </td>
1546:                       <td>
1547:                         <div className="flex items-center gap-1 w-28">
1548:                           {TR_FLOW.slice(1).map((s, i) => <span key={s} className="h-1.5 flex-1 rounded-full" style={{ background: t.status === 'cancelled' ? 'var(--badge-red-bg)' : i < idx ? 'var(--accent-orange)' : 'var(--badge-gray-bg)' }} />)}
1549:                         </div>
1550:                       </td>
1551:                       <td><TrStatus s={t.status} /></td>
1552:                       <td className="num text-[11.5px] c-secondary">{formatDate(t.created_at)}</td>
1553:                       <td><Icon n="chevL" s={15} className="c-muted" /></td>
1554:                     </tr>
1555:                   );
1556:                 })}
1557:               </tbody>
1558:             </table>
1559:           )}
1560:         </Phase>
1561:       </Card>
1562:     </section>
1563:   );
1564: }
1565: // NOTE: the transfer list resource omits line items (TransferService::paginate
1566: // loads fromBranch/toBranch/creator only), so the old "items count" column was
1567: // dropped — the contract is the source of truth, not the mock.
1568: 
1569: function TransferEdit({ go, params }) {
1570:   const { toast, can, branchesQuery, variantCache } = useInv();
1571:   const restriction = useRestrictedBranch();
1572:   const { keyFor, reset } = useIdempotencyKey();
1573:   const editId = params.id ? Number(params.id) : null;
1574:   const [from, setFrom] = useState(restriction.locked ? restriction.branchId : null);
1575:   const [to, setTo] = useState(null);
1576:   const [note, setNote] = useState('');
1577:   const [lines, setLines] = useState(() => [newTrLine()]);
1578:   const [tried, setTried] = useState(false);
1579:   const [busy, setBusy] = useState(false);
1580:   const [srvErr, setSrvErr] = useState(null);
1581:   const [rowErrs, setRowErrs] = useState({});
1582:   const [loaded, setLoaded] = useState(!editId);
1583:   const allowed = editId ? canAny(can, 'transfers.update', 'transfers.manage') : canAny(can, 'transfers.create', 'transfers.manage');
1584: 
1585:   const showQuery = useApi(signal => (editId ? transfersApi.show(editId, signal) : Promise.resolve(null)), [editId || 0]);
1586:   useEffect(() => {
1587:     const t = showQuery.data;
1588:     if (editId && t && !loaded) {
1589:       setFrom(t.from_branch?.id ?? null); setTo(t.to_branch?.id ?? null); setNote(t.notes || '');
1590:       setLines((t.items || []).map(it => newTrLine({ variantId: it.product_variant_id, fromLoc: it.from_location?.id ?? null, toLoc: it.to_location?.id ?? null, req: it.requested_qty != null ? String(it.requested_qty) : '' })));
1591:       cacheVariantNames(variantCache, (t.items || []).map(it => ({ id: it.product_variant_id, sku: it.sku })));
1592:       setLoaded(true);
1593:     }
1594:   }, [showQuery.data]);
1595:   const fromLocsQuery = useBranchesWithLocations(from);
1596:   const toLocsQuery = useBranchesWithLocations(to);
1597: 
1598:   if (!allowed) return <NoPerm title={editId ? 'تعديل التحويل' : 'تحويل جديد'} perm={editId ? 'transfers.update' : 'transfers.create'} go={go} />;
1599: 
1600:   const t = showQuery.data;
1601:   const same = from && to && from === to;
1602:   const upd = (key, p) => { setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l)); setRowErrs({}); };
1603:   const lineBad = l => {
1604:     if (!l.variantId) return true;
1605:     const qv = toLatinDigits(l.req);
1606:     return !QTY_RE.test(qv) || !(Number(qv) > 0) || Number(qv) > QTY_MAX;
1607:   };
1608:   const valid = from && to && !same && lines.length && lines.length <= 100 && lines.every(l => !lineBad(l));
1609: 
1610:   const save = async () => {
1611:     setTried(true); if (!valid || busy || (editId && (!t || t.status !== 'draft'))) return;
1612:     setBusy(true); setSrvErr(null); setRowErrs({});
1613:     const payload = {
1614:       from_branch_id: from, to_branch_id: to, notes: note.trim() || null,
1615:       items: lines.map(l => ({
1616:         product_variant_id: l.variantId,
