1736:     receive: { col: 'received_qty', srcCol: 'shipped_qty', label: 'استلام', perm: 'transfers.receive', hint: 'أدخل الكمية المستلمة فعليًا في الوجهة. أي فرق يُسجَّل كعجز تحويل.' },
1737:   };
1738:   const startStage = s => { const m = stageMeta[s]; setStageErrors({}); setErr(null); setStage(s); setQtys(Object.fromEntries((t.items || []).map((l, i) => [i, String(l[m.srcCol] ?? '')]))); };
1739:   const idx = t ? TR_FLOW.indexOf(t.status) : -1;
