1795:     if (canSend && ['draft', 'approved'].includes(t.status) && canAny(can, 'transfers.update', 'transfers.manage')) actions.unshift(<button key="c" className="btn btn-danger" onClick={() => { setErr(null); setConfirm('cancel'); }}>إلغاء التحويل</button>);
1796:     if (canSend && t.status === 'draft' && canAny(can, 'transfers.delete', 'transfers.manage')) actions.push(<button key="d" className="btn btn-soft hover:!text-[var(--badge-red-text)]" disabled={delBusy} onClick={() => { setErr(null); setConfirm('delete'); }}><Icon n="trash" s={14} /> حذف</button>);
