1894:                     <div className="h-1.5 rounded-full hatched overflow-hidden"><div className="h-full rounded-full bar-hatched-orange" style={{ width: (req ? total / req * 100 : 0) + '%' }} /></div>
1895:                   </div>
1896:                 );
1897:               })}
1898:             </div>
1899:           </Card>
