1903:       <ConfirmDialog open={confirm === 'stage'} onClose={() => setConfirm(null)} onConfirm={commit} busy={busy} error={err}
1904:         title={stage ? `تأكيد ${stageMeta[stage].label} ${t?.transfer_number || ''}` : ''} confirmLabel="تأكيد"
1905:         body={<div className="space-y-2">
