1907:           {shortage > 0 && <InlineAlert kind="amber" title="يوجد عجز في الاستلام">الفرق بين المشحون والمستلم {formatQty(shortage)} — سيُسجَّل كعجز تحويل.</InlineAlert>}
1908:         </div>} />
1909:       <ConfirmDialog open={confirm === 'cancel'} onClose={() => setConfirm(null)} onConfirm={cancel} busy={busy} error={err} danger title="إلغاء التحويل؟" confirmLabel="إلغاء التحويل"
1910:         body={<>سيتم إلغاء <span className="mono c-primary" dir="ltr">{t?.transfer_number}</span> نهائيًا ولن يمكن إعادة تفعيله.</>} />
1911:       <ConfirmDialog open={confirm === 'delete'} onClose={() => setConfirm(null)} onConfirm={doDelete} busy={delBusy} error={err} danger title="حذف مسودة التحويل؟" confirmLabel="حذف نهائي"
1912:         body={<>سيتم حذف <span className="mono c-primary" dir="ltr">{t?.transfer_number}</span> نهائيًا. الحذف مسموح للمسودة فقط.</>} />
1913:     </section>
