2176: // ---------- Modal ----------
2177: function Modal({ open, onClose, title, sub, children, footer, width = 'max-w-lg' }) {
2178:   useEffect(() => {
2179:     if (!open) return;
2180:     const h = e => e.key === 'Escape' && onClose && onClose();
2181:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
2182:   }, [open]);
2183:   if (!open) return null;
2184:   return (
2185:     <div className="fixed inset-0 z-50 flex items-center justify-center p-4 fade-in" style={{ background: 'rgba(0,0,0,.4)', backdropFilter: 'blur(4px)' }} onMouseDown={e => e.target === e.currentTarget && onClose && onClose()}>
2186:       <div className={`v-card ${width} w-full shadow-2xl modal-in flex flex-col max-h-[92vh]`}>
2187:         <div className="flex items-start justify-between gap-4 p-6 pb-4">
2188:           <div>
2189:             <h3 className="font-display text-[18px] font-semibold c-primary">{title}</h3>
2190:             {sub && <p className="text-[12px] c-secondary mt-0.5">{sub}</p>}
2191:           </div>
2192:           <button onClick={onClose} className="w-8 h-8 rounded-full v-subcard flex items-center justify-center c-secondary shrink-0"><Icon n="x" s={14} /></button>
2193:         </div>
2194:         <div className="px-6 pb-2 overflow-y-auto flex-1">{children}</div>
2195:         {footer && <div className="p-6 pt-4 flex items-center justify-start gap-2.5 flex-row-reverse">{footer}</div>}
2196:       </div>
2197:     </div>
2198:   );
2199: }
