2333: const SCREENS = { branches:BranchesScreen,locations:LocationsScreen,stock:StockScreen,adjust:AdjustScreen,moves:MovesScreen,transfers:TransfersScreen,transfer:TransferDetail,'transfer-edit':TransferEdit,counts:CountsScreen,count:CountDetail,production:ProductionScreen };
2334: function readInventoryRoute() {
2335:  const [path,query='']=location.hash.slice(1).split('?');
2336:  const route=path?.split('/')[2] || 'stock';
2337:  return { route:SCREENS[route]?route:'stock', params:Object.fromEntries(new URLSearchParams(query)) };
2338: }
2339: export function InventoryReference({can,isDark}) {
2340:  const [nav,setNav]=useState(readInventoryRoute);
2341:  const [toastMsg,setToastMsg]=useState(null), [reloadKey,setReloadKey]=useState(0);
2342:  const variantCache = useRef(new Map());
2343:  const locationCache = useRef(new Map());
2344:  const dirtyNavigation = useRef(false);
2345:  const lastHash = useRef(location.hash);
2346:  const [branchesTick, setBranchesTick] = useState(0);
2347:  // Context-level cache of all branches with their counts; both branch screens and every dropdown share it (Phase 2.4).
2348:  const branchesQuery = useApi(signal => fetchAllBranches(signal), [branchesTick]);
2349:  const reloadBranches = () => { locationCache.current.clear(); setBranchesTick(t => t + 1); };
2350:  const timer=useRef();
2351:  useEffect(()=>{
2352:    const markDirty = e => { dirtyNavigation.current = Boolean(e.detail); };
2353:    const changed=()=>{
2354:      if (location.hash === lastHash.current) return;
2355:      if (dirtyNavigation.current && !window.confirm('تغييرات غير محفوظة. هل تريد مغادرة الجرد وفقدها؟')) {
2356:        history.replaceState(null, '', lastHash.current); return;
2357:      }
2358:      dirtyNavigation.current = false; lastHash.current = location.hash; setNav(readInventoryRoute());
2359:    };
2360:    window.addEventListener('inventory:dirty',markDirty); window.addEventListener('hashchange',changed);
2361:    return()=>{window.removeEventListener('inventory:dirty',markDirty);window.removeEventListener('hashchange',changed);clearTimeout(timer.current);};
2362:  },[]);
2363:  const go=(route,params={})=>{const qs=new URLSearchParams(Object.entries(params).filter(([,value])=>value!=null)).toString();location.hash='/inventory/'+route+(qs?'?'+qs:'');};
2364:  const toast=text=>{setToastMsg({text});clearTimeout(timer.current);timer.current=setTimeout(()=>setToastMsg(null),2400);};
2365:  const Screen=SCREENS[nav.route];
2366:  return <InvCtx.Provider value={{toast,can,go,reloadKey,reload:()=>setReloadKey(k=>k+1),variantCache:variantCache.current,locationCache:locationCache.current,branchesQuery,reloadBranches}}>
2367:   <div className={'inventory-surface '+(isDark?'theme-dark':'theme-light')} dir="rtl" lang="ar">
2368:    <nav aria-label="شاشات المخزون" className="flex gap-2 overflow-x-auto pb-2 mb-5">
2369:     {INV_NAV.map(item=><button key={item.id} type="button" onClick={()=>go(item.id)} className={'btn shrink-0 '+(item.match.includes(nav.route)?'btn-dark':'btn-soft')}><Icon n={item.icon} s={15}/>{item.label}</button>)}
2370:    </nav>
2371:    <main data-inventory-screen={nav.route}><Screen key={nav.route+JSON.stringify(nav.params)} go={go} params={nav.params}/></main>
2372:    <Toast toast={toastMsg}/>
2373:   </div>
2374:  </InvCtx.Provider>;
2375: }

