 1: // Shared inventory contract — mirrors backend Resources 1:1.
 2: // Numbers arrive as strings with 4 decimals ("10.0000"): always Number() before
 3: // math, and formatQty() before display. See Branch/Location/StockLevel/
 4: // StockMovement/Stocktake/StockTransfer Resources + Transfer/Stocktake services.
 5: export type BranchType = 'branch' | 'warehouse';
 6: export type LocationType = 'shelf' | 'zone' | 'bin' | 'damaged' | 'receiving';
 7: export type TransferStatus = 'draft' | 'approved' | 'shipped' | 'received' | 'cancelled';
 8: export type StocktakeStatus = 'draft' | 'in_progress' | 'approved' | 'cancelled';
 9: export type AdjustmentType = 'increase' | 'decrease' | 'mark_damaged' | 'write_off_damaged' | 'restore_damaged';
10: export type StockMovementType =
11:   | 'production_receipt' | 'purchase_receipt' | 'sale' | 'sale_return'
12:   | 'adjustment_in' | 'adjustment_out' | 'damage' | 'damage_release' | 'damage_write_off'
13:   | 'transfer_out' | 'transfer_in' | 'transfer_in_transit' | 'transfer_transit_release' | 'transfer_shortage'
14:   | 'stocktake_gain' | 'stocktake_loss' | 'reserve' | 'release_reserve';
15: 
16: export interface Branch {
17:   id: number; name: string; code: string; type: BranchType;
18:   phone: string | null; email: string | null; address: string | null;
19:   city: string | null; city_id: number | null; is_active: boolean;
20:   locations_count?: number; employees_count?: number;
21:   created_at: string; updated_at: string;
22: }
23: export interface Location {
24:   id: number; branch_id: number; name: string; code: string;
25:   type: LocationType; is_active: boolean; created_at: string; updated_at: string;
26: }
27: export interface StockLevel {
28:   id: number; product_variant_id: number;
29:   variant?: { id: number; sku: string; barcode: string | null; product_id: number;
30:               product_name_ar?: string; product_name_en?: string | null };
31:   branch?: { id: number; name: string };
32:   location?: { id: number; name: string; code: string } | null;
33:   on_hand: string; reserved: string; damaged: string; in_transit: string;
34:   available: string; reorder_level: string; is_low_stock: boolean; updated_at: string;
35: }
36: export interface StockMovement {
37:   id: number; reference_number: string; product_variant_id: number;
38:   variant?: { id: number; sku: string; product_id: number };
39:   branch?: { id: number; name: string };
40:   location?: { id: number; name: string } | null;
41:   type: StockMovementType; affected_bucket: 'on_hand' | 'reserved' | 'damaged' | 'in_transit';
42:   quantity: string; balance_before: string; balance_after: string;
43:   unit_cost?: string; // only with inventory.view_cost — backend omits it otherwise
44:   reference_type: string | null; reference_id: number | null;
45:   created_by: number | null; creator_name?: string | null; notes: string | null; created_at: string;
46: }
47: export interface StockTransferItem {
48:   id: number; product_variant_id: number; sku: string | null;
49:   from_location: { id: number; name: string } | null;
50:   to_location: { id: number; name: string } | null;
51:   requested_qty: string; approved_qty: string | null; shipped_qty: string | null; received_qty: string | null;
52: }
53: export interface StockTransfer {
54:   id: number; version: number; transfer_number: string;
55:   from_branch?: { id: number; name: string }; to_branch?: { id: number; name: string };
56:   status: TransferStatus; created_by: number; creator_name?: string;
57:   approved_by: number | null; shipped_at: string | null; received_at: string | null;
58:   notes: string | null; items?: StockTransferItem[]; created_at: string; updated_at: string;
59: }
60: export interface StocktakeItem {
61:   id: number; product_variant_id: number; sku: string | null;
62:   system_qty: string; counted_qty: string | null; difference: string | null;
63: }
64: export interface Stocktake {
65:   id: number; stocktake_number: string;
66:   branch?: { id: number; name: string }; location?: { id: number; name: string } | null;
67:   status: StocktakeStatus; items_count?: number; created_by: number; creator_name?: string;
68:   approved_by: number | null; approved_at: string | null; notes: string | null;
69:   items?: StocktakeItem[]; created_at: string; updated_at: string;
70: }
71: export interface CursorPaginated<T> {
72:   data: T[];
73:   meta: { path: string; per_page: number; next_cursor: string | null; prev_cursor: string | null };
74:   links: { first: null; last: null; prev: string | null; next: string | null };
75: }
76: 
77: // ProductionReceipt store/show returns the MODEL itself, not a Resource:
78: // { id, batch_number, branch_id, location_id, created_by, notes, items[], created_at }.
79: export interface ProductionReceiptItem {
80:   product_variant_id: number; quantity: number; unit_cost?: number | string;
81: }
82: export interface ProductionReceipt {
83:   id: number; batch_number: string; branch_id: number; location_id: number | null;
84:   created_by: number; notes: string | null; items: ProductionReceiptItem[];
85:   created_at: string; updated_at?: string;
86: }
87: export interface ProductionOptions {
88:   branches: { id: number; name: string; locations: { id: number; name: string }[] }[];
89:   variants: { id: number; label: string }[];
90: }
91: // Raw Laravel paginator (NOT under meta): { data, current_page, last_page, ... }.
92: export interface RawPaginated<T> {
93:   data: T[]; current_page: number; last_page: number; per_page: number; total: number;
94: }

 1: // Local development services share the machine serving the page, including on LAN devices.
 2: export function resolveServiceUrl(configured: string): string {
 3:   if (typeof window === 'undefined') return configured;
 4:   const hostname = window.location.hostname;
 5:   const parts = hostname?.split('.').map(Number);
 6:   const privateIpv4 = parts?.length === 4 && parts.every(part => Number.isInteger(part) && part >= 0 && part <= 255)
 7:     && (parts[0] === 10 || (parts[0] === 192 && parts[1] === 168) || (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31));
 8:   if (!privateIpv4) return configured;
 9:   try {
10:     const url = new URL(configured);
11:     if (!['localhost', '127.0.0.1', '[::1]'].includes(url.hostname)) return configured;
12:     url.hostname = hostname;
13:     return url.href.replace(/\/$/, '');
14:   } catch {
15:     return configured;
16:   }
17: }

