 3: 
 4: export interface Column<T> {
 5:   header: string;
 6:   accessorKey?: keyof T;
 7:   cell?: (row: T) => React.ReactNode;
 8:   className?: string;
 9: }
10: 
11: export interface DataTableProps<T> {
12:   columns: Column<T>[];
13:   data: T[];
14:   isLoading?: boolean;
15:   emptyMessage?: string;
16:   className?: string;
17: }
18: 
19: export function DataTable<T extends Record<string, any>>({
20:   columns,
21:   data,
22:   isLoading = false,
23:   emptyMessage = 'لا توجد بيانات متاحة',
24:   className,
25: }: DataTableProps<T>) {
26:   return (
27:     <div className={cn('w-full overflow-x-auto rounded-xl border border-zinc-200 bg-white', className)} dir="rtl">
28:       <table className="w-full text-right text-sm">
29:         <thead className="bg-zinc-50 border-b border-zinc-200 text-xs font-semibold text-zinc-600 uppercase">
30:           <tr>
31:             {columns.map((col, index) => (
32:               <th key={index} className={cn('px-4 py-3.5', col.className)}>
33:                 {col.header}
34:               </th>
35:             ))}
36:           </tr>
37:         </thead>
38:         <tbody className="divide-y divide-zinc-200">
39:           {isLoading ? (
40:             <tr>
41:               <td colSpan={columns.length} className="py-12 text-center text-zinc-500">
42:                 <div className="flex items-center justify-center gap-2">
43:                   <div className="h-4 w-4 animate-spin rounded-full border-2 border-brand-500 border-t-transparent" />
44:                   <span>جاري التحميل...</span>
45:                 </div>
46:               </td>
47:             </tr>
48:           ) : data.length === 0 ? (
49:             <tr>
50:               <td colSpan={columns.length} className="py-12 text-center text-zinc-500">
51:                 {emptyMessage}
52:               </td>
53:             </tr>
54:           ) : (
55:             data.map((row, rowIndex) => (
56:               <tr key={rowIndex} className="hover:bg-zinc-50/70 transition-colors">
57:                 {columns.map((col, colIndex) => (
58:                   <td key={colIndex} className={cn('px-4 py-3 text-zinc-700', col.className)}>
59:                     {col.cell ? col.cell(row) : col.accessorKey ? String(row[col.accessorKey] ?? '-') : null}
60:                   </td>
61:                 ))}
62:               </tr>
63:             ))
64:           )}
65:         </tbody>
66:       </table>
67:     </div>
68:   );
69: }

 1: 'use client';
