 3: import React, { useEffect } from 'react';
 4: import { X } from 'lucide-react';
 5: import { cn } from '../lib/utils';
 6: 
 7: export interface ModalProps {
 8:   isOpen: boolean;
 9:   onClose: () => void;
10:   title?: React.ReactNode;
11:   children: React.ReactNode;
12:   footer?: React.ReactNode;
13:   className?: string;
14:   size?: 'sm' | 'md' | 'lg' | 'xl';
15: }
16: 
17: export function Modal({
18:   isOpen,
19:   onClose,
20:   title,
21:   children,
22:   footer,
23:   className,
24:   size = 'md',
25: }: ModalProps) {
26:   useEffect(() => {
27:     const handleKeyDown = (e: KeyboardEvent) => {
28:       if (e.key === 'Escape' && isOpen) {
29:         onClose();
30:       }
31:     };
32:     window.addEventListener('keydown', handleKeyDown);
33:     return () => window.removeEventListener('keydown', handleKeyDown);
34:   }, [isOpen, onClose]);
35: 
36:   if (!isOpen) return null;
37: 
38:   const sizeClasses = {
39:     sm: 'max-w-md',
40:     md: 'max-w-lg',
41:     lg: 'max-w-2xl',
42:     xl: 'max-w-4xl',
43:   };
44: 
45:   return (
46:     <div className="fixed inset-0 z-50 flex items-center justify-center p-4" dir="rtl">
47:       <div className="fixed inset-0 bg-black/50 backdrop-blur-sm transition-opacity" onClick={onClose} />
48:       <div
49:         className={cn(
50:           'relative w-full rounded-2xl bg-white shadow-xl transition-all z-10 overflow-hidden flex flex-col max-h-[90vh]',
51:           sizeClasses[size],
52:           className
53:         )}
54:       >
55:         {title && (
56:           <div className="flex items-center justify-between border-b border-zinc-100 px-6 py-4">
57:             <h3 className="text-lg font-semibold text-zinc-900">{title}</h3>
58:             <button
59:               onClick={onClose}
60:               className="rounded-lg p-1 text-zinc-400 hover:bg-zinc-100 hover:text-zinc-600 transition-colors"
61:             >
62:               <X className="h-5 w-5" />
63:             </button>
64:           </div>
65:         )}
66:         <div className="p-6 overflow-y-auto flex-1">{children}</div>
67:         {footer && (
68:           <div className="flex items-center justify-end gap-3 border-t border-zinc-100 bg-zinc-50/50 px-6 py-4">
69:             {footer}
70:           </div>
71:         )}
72:       </div>
73:     </div>
74:   );
75: }

