18: use Illuminate\Routing\Controllers\HasMiddleware;
19: use Illuminate\Routing\Controllers\Middleware;
20: 
21: /**
22:  * طلبات الشراء الداخلية: إنشاء فروع لنواقصها واعتماد إدارة المشتريات،
23:  * ثم التحويل لأمر شراء من متحكم أوامر الشراء. الدورة في ProcurementService.
24:  */
25: class PurchaseRequestController extends Controller implements HasMiddleware
26: {
27:     public static function middleware(): array
28:     {
29:         return [
30:             new Middleware('can:purchases.view', only: ['index', 'show']),
31:             new Middleware('can:purchases.create', only: ['store']),
32:             new Middleware('can:purchases.update', only: ['update', 'submit']),
33:             new Middleware('can:purchase_requests.approve', only: ['approve', 'reject']),
34:             new Middleware('can:purchases.delete', only: ['destroy']),
35:         ];
36:     }
37: 
38:     public function __construct(protected ProcurementService $procurement) {}
39: 
40:     public function index(Request $request): AnonymousResourceCollection
41:     {
42:         $requests = PurchaseRequest::query()
43:             ->with(['branch:id,name', 'items.variant'])
44:             ->when($request->query('status'), fn ($q, $status) => $q->where('status', $status))
45:             ->when($request->query('branch_id'), fn ($q, $branchId) => $q->where('branch_id', (int) $branchId))
46:             ->latest('id')
47:             ->paginate(20);
48: 
49:         return PurchaseRequestResource::collection($requests);
50:     }
51: 
52:     public function store(PurchaseRequestRequest $request): JsonResponse
53:     {
54:         /** @var User $admin */
55:         $admin = $request->user();
56:         $pr = $this->procurement->createPurchaseRequest($request->validated(), $admin);
57:         $pr->load(['branch:id,name', 'items.variant']);
58: 
59:         return PurchaseRequestResource::make($pr)->response()->setStatusCode(201);
60:     }
61: 
62:     public function show(PurchaseRequest $purchaseRequest): PurchaseRequestResource
63:     {
64:         return PurchaseRequestResource::make($purchaseRequest->load(['branch:id,name', 'items.variant']));
65:     }
66: 
67:     public function update(PurchaseRequestRequest $request, PurchaseRequest $purchaseRequest): PurchaseRequestResource
68:     {
69:         $pr = $this->procurement->updatePurchaseRequest($purchaseRequest, $request->validated());
70:         $pr->load(['branch:id,name', 'items.variant']);
71: 
72:         return PurchaseRequestResource::make($pr);
73:     }
74: 
75:     public function destroy(PurchaseRequest $purchaseRequest): JsonResponse
76:     {
77:         if ($purchaseRequest->status !== PurchaseRequestStatus::Draft) {
78:             throw new BusinessException('لا يمكن حذف طلب شراء إلا وهو مسودة.');
79:         }
80:         $purchaseRequest->delete();
81: 
82:         return response()->json(['message' => 'تم حذف طلب الشراء.']);
83:     }
84: 
85:     public function submit(PurchaseRequest $purchaseRequest): PurchaseRequestResource
86:     {
87:         return PurchaseRequestResource::make($this->procurement->submitPurchaseRequest($purchaseRequest));
88:     }
89: 
90:     public function approve(PurchaseRequest $purchaseRequest): PurchaseRequestResource
91:     {
92:         return PurchaseRequestResource::make($this->procurement->approvePurchaseRequest($purchaseRequest));
93:     }
94: 
95:     public function reject(PurchaseRequest $purchaseRequest): PurchaseRequestResource
96:     {
97:         return PurchaseRequestResource::make($this->procurement->rejectPurchaseRequest($purchaseRequest));
98:     }
99: }

