 22: use Illuminate\Routing\Controllers\HasMiddleware;
 23: use Illuminate\Routing\Controllers\Middleware;
 24: 
 25: /**
 26:  * إدارة المرتجعات (المرحلة 9): عرض وإنشاء يدوي + دورة الاعتماد
 27:  * والاستلام والرد المالي — كل المنطق والآثار في ReturnService.
 28:  */
 29: class ReturnController extends Controller implements HasMiddleware
 30: {
 31:     public static function middleware(): array
 32:     {
 33:         return [
 34:             new Middleware('can:returns.view', only: ['index', 'show']),
 35:             new Middleware('can:returns.create', only: ['store']),
 36:             new Middleware('can:returns.update', only: ['update']),
 37:             new Middleware('can:returns.approve', only: ['approve']),
 38:             new Middleware('can:returns.receive', only: ['receive']),
 39:             new Middleware('can:returns.refund', only: ['refund']),
 40:             new Middleware('can:returns.delete', only: ['destroy']),
 41:         ];
 42:     }
 43: 
 44:     public function __construct(protected ReturnService $returns) {}
 45: 
 46:     public function index(Request $request): AnonymousResourceCollection
 47:     {
 48:         $search = trim((string) $request->query('search', ''));
 49:         $returns = ReturnRequest::query()
 50:             ->with(['order:id,order_number', 'customer:id,name', 'items.orderItem'])
 51:             ->when($request->query('status'), fn ($q, $status) => $q->where('status', $status))
 52:             ->when($request->query('order_id'), fn ($q, $orderId) => $q->where('order_id', (int) $orderId))
 53:             ->when($request->query('customer_id'), fn ($q, $customerId) => $q->where('customer_id', (int) $customerId))
 54:             ->when($search !== '', fn ($q) => $q->where(function ($w) use ($search): void {
 55:                 $pattern = SearchTerm::pattern($search);
 56:                 $w->where('return_number', 'ilike', $pattern)
 57:                     ->orWhereHas('order', fn ($o) => $o->where('order_number', 'ilike', $pattern));
 58:             }))
 59:             ->latest('id')
 60:             ->paginate(20);
 61: 
 62:         return ReturnRequestResource::collection($returns);
 63:     }
 64: 
 65:     public function store(StoreReturnRequest $request): JsonResponse
 66:     {
 67:         $order = Order::query()->findOrFail((int) $request->validated('order_id'));
 68:         $return = $this->returns->createReturnRequest($order, $request->validated());
 69:         $return->load(['items.orderItem', 'order', 'customer']);
 70: 
 71:         return ReturnRequestResource::make($return)->response()->setStatusCode(201);
 72:     }
 73: 
 74:     public function show(ReturnRequest $returnRequest): ReturnRequestResource
 75:     {
 76:         $returnRequest->load(['items.orderItem', 'order', 'customer', 'branch']);
 77: 
 78:         return ReturnRequestResource::make($returnRequest);
 79:     }
 80: 
 81:     public function update(UpdateReturnRequest $request, ReturnRequest $returnRequest): ReturnRequestResource
 82:     {
 83:         /** @var User $admin */
 84:         $admin = $request->user();
 85:         $return = $this->returns->updateDetails($returnRequest, $admin, $request->validated());
 86:         $return->load(['items.orderItem', 'order', 'customer']);
 87: 
 88:         return ReturnRequestResource::make($return);
 89:     }
 90: 
 91:     public function destroy(ReturnRequest $returnRequest): JsonResponse
 92:     {
 93:         $this->returns->delete($returnRequest);
 94: 
 95:         return response()->json(['message' => 'تم حذف طلب المرتجع']);
 96:     }
 97: 
 98:     public function approve(ApproveReturnRequest $request, ReturnRequest $returnRequest): ReturnRequestResource
 99:     {
100:         /** @var User $admin */
101:         $admin = $request->user();
102:         $return = $this->returns->approve($returnRequest, $admin, $request->validated());
103:         $return->load(['items.orderItem', 'order', 'customer']);
104: 
105:         return ReturnRequestResource::make($return);
106:     }
107: 
108:     public function receive(ReceiveReturnRequest $request, ReturnRequest $returnRequest): ReturnRequestResource
109:     {
110:         /** @var User $admin */
111:         $admin = $request->user();
112:         $return = $this->returns->receive($returnRequest, $admin, $request->validated());
113:         $return->load(['items.orderItem', 'order', 'customer']);
114: 
115:         return ReturnRequestResource::make($return);
116:     }
117: 
118:     public function refund(RefundReturnRequest $request, ReturnRequest $returnRequest): ReturnRequestResource
119:     {
120:         /** @var User $admin */
121:         $admin = $request->user();
122:         $return = $this->returns->refund($returnRequest, $admin, $request->validated());
123:         $return->load(['items.orderItem', 'order', 'customer']);
124: 
125:         return ReturnRequestResource::make($return);
126:     }
127: }

