17: 
18: /**
19:  * فواتير الموردين: تسجيل مسودة ثم اعتماد (post) يثبت الاستحقاق
20:  * في رصيد المورد — الآثار المالية كلها في SupplierFinanceService.
21:  */
22: class SupplierInvoiceController extends Controller implements HasMiddleware
23: {
24:     public static function middleware(): array
25:     {
26:         return [
27:             new Middleware('can:purchases.view', only: ['index', 'show']),
28:             new Middleware('can:purchases.create', only: ['store']),
29:             new Middleware('can:purchases.update', only: ['update']),
30:             new Middleware('can:supplier_invoices.post', only: ['post']),
31:             new Middleware('can:supplier_invoices.cancel', only: ['cancel']),
32:             new Middleware('can:purchases.delete', only: ['destroy']),
33:         ];
34:     }
35: 
36:     public function __construct(protected SupplierFinanceService $finance) {}
37: 
38:     public function index(Request $request): AnonymousResourceCollection
39:     {
40:         $invoices = SupplierInvoice::query()
41:             ->with(['supplier:id,code,name', 'purchaseOrder:id,po_number'])
42:             ->when($request->query('status'), fn ($q, $status) => $q->where('status', $status))
43:             ->when($request->query('supplier_id'), fn ($q, $id) => $q->where('supplier_id', (int) $id))
44:             ->when($request->query('purchase_order_id'), fn ($q, $id) => $q->where('purchase_order_id', (int) $id))
45:             ->latest('id')
46:             ->paginate(20);
47: 
48:         return SupplierInvoiceResource::collection($invoices);
49:     }
50: 
51:     public function store(SupplierInvoiceRequest $request): JsonResponse
52:     {
53:         $data = $request->safe()->except('attachment');
54:         $invoice = $this->finance->createInvoice($data, $request->file('attachment'));
55:         $invoice->load(['supplier:id,code,name', 'purchaseOrder:id,po_number']);
56: 
57:         return SupplierInvoiceResource::make($invoice)->response()->setStatusCode(201);
58:     }
59: 
60:     public function show(SupplierInvoice $supplierInvoice): SupplierInvoiceResource
61:     {
62:         return SupplierInvoiceResource::make($supplierInvoice->load(['supplier:id,code,name', 'purchaseOrder:id,po_number']));
63:     }
64: 
65:     public function update(SupplierInvoiceRequest $request, SupplierInvoice $supplierInvoice): SupplierInvoiceResource
66:     {
67:         $data = $request->safe()->except('attachment');
68:         $invoice = $this->finance->updateInvoice($supplierInvoice, $data, $request->file('attachment'));
69:         $invoice->load(['supplier:id,code,name', 'purchaseOrder:id,po_number']);
70: 
71:         return SupplierInvoiceResource::make($invoice);
72:     }
73: 
74:     public function post(SupplierInvoice $supplierInvoice): SupplierInvoiceResource
75:     {
76:         return SupplierInvoiceResource::make($this->finance->postInvoice($supplierInvoice));
77:     }
78: 
79:     public function cancel(SupplierInvoice $supplierInvoice): SupplierInvoiceResource
80:     {
81:         return SupplierInvoiceResource::make($this->finance->cancelInvoice($supplierInvoice));
82:     }
83: 
84:     public function destroy(SupplierInvoice $supplierInvoice): JsonResponse
85:     {
86:         $this->finance->deleteInvoice($supplierInvoice);
87: 
88:         return response()->json(['message' => 'تم حذف فاتورة المورد.']);
89:     }
90: }

