 24: 
 25: class TransferController extends Controller implements HasMiddleware
 26: {
 27:     public function __construct(private readonly TransferService $transfers) {}
 28: 
 29:     public static function middleware(): array
 30:     {
 31:         return [
 32:             new Middleware('can:transfers.view', only: ['index', 'show']),
 33:             new Middleware('can:transfers.create', only: ['store']),
 34:             new Middleware('can:transfers.update', only: ['update']),
 35:             new Middleware('can:transfers.delete', only: ['destroy']),
 36:             new Middleware('can:transfers.approve', only: ['approve']),
 37:             new Middleware('can:transfers.ship', only: ['ship']),
 38:             new Middleware('can:transfers.receive', only: ['receive']),
 39:             new Middleware('can:transfers.update', only: ['cancel']),
 40:         ];
 41:     }
 42: 
 43:     public function index(Request $request): AnonymousResourceCollection
 44:     {
 45:         $filters = $request->validate([
 46:             'from_branch_id' => ['nullable', 'integer', 'min:1'],
 47:             'to_branch_id' => ['nullable', 'integer', 'min:1'],
 48:             'status' => ['nullable', Rule::in(array_column(TransferStatus::cases(), 'value'))],
 49:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 50:         ]);
 51: 
 52:         $filters['staff_branch_id'] = app(BranchAccess::class)->restrictedBranch($request->user());
 53: 
 54:         return StockTransferResource::collection($this->transfers->paginate($filters));
 55:     }
 56: 
 57:     public function store(StoreTransferRequest $request): JsonResponse
 58:     {
 59:         $transfer = $this->transfers->create($request->validated(), $request->user()->id, $this->idempotencyKey($request));
 60: 
 61:         return (new StockTransferResource($transfer))
 62:             ->additional(['message' => 'تم إنشاء التحويل بنجاح'])
 63:             ->response()
 64:             ->setStatusCode(201);
 65:     }
 66: 
 67:     public function show(Request $request, StockTransfer $transfer): StockTransferResource
 68:     {
 69:         app(BranchAccess::class)->assertBranch($request->user()->id, $transfer->from_branch_id, $transfer->to_branch_id);
 70: 
 71:         return new StockTransferResource($this->transfers->find($transfer->id));
 72:     }
 73: 
 74:     public function update(UpdateTransferRequest $request, StockTransfer $transfer): StockTransferResource
 75:     {
 76:         return new StockTransferResource($this->transfers->update($transfer, $request->validated(), $request->user()->id));
 77:     }
 78: 
 79:     public function destroy(Request $request, StockTransfer $transfer): JsonResponse
 80:     {
 81:         $this->transfers->delete($transfer, $request->user()->id);
 82: 
 83:         return response()->json(['message' => 'تم حذف التحويل بنجاح']);
 84:     }
 85: 
 86:     public function approve(ApproveTransferRequest $request, StockTransfer $transfer): StockTransferResource
 87:     {
 88:         $transfer = $this->transfers->approve(
 89:             $transfer,
 90:             $request->quantitiesByItemId(),
 91:             (int) $request->user()->id,
 92:             $request->expectedUpdatedAt(),
 93:             $request->expectedVersion(),
 94:         );
 95: 
 96:         return (new StockTransferResource($transfer))->additional(['message' => 'تم اعتماد التحويل وحجز الكميات']);
 97:     }
 98: 
 99:     public function ship(ShipTransferRequest $request, StockTransfer $transfer): StockTransferResource
100:     {
101:         $transfer = $this->transfers->ship(
102:             $transfer,
103:             $request->quantitiesByItemId(),
104:             (int) $request->user()->id,
105:             $request->expectedUpdatedAt(),
106:             $request->expectedVersion(),
107:         );
108: 
109:         return (new StockTransferResource($transfer))->additional(['message' => 'تم شحن التحويل بنجاح']);
110:     }
111: 
112:     public function receive(ReceiveTransferRequest $request, StockTransfer $transfer): StockTransferResource
113:     {
114:         $transfer = $this->transfers->receive(
115:             $transfer,
116:             $request->quantitiesByItemId(),
117:             (int) $request->user()->id,
118:             $request->expectedUpdatedAt(),
119:             $request->expectedVersion(),
120:         );
121: 
122:         return (new StockTransferResource($transfer))->additional(['message' => 'تم استلام التحويل بنجاح']);
123:     }
124: 
125:     public function cancel(Request $request, StockTransfer $transfer): StockTransferResource
126:     {
127:         $transfer = $this->transfers->cancel($transfer, $request->user()->id);
