  8: use App\Http\Controllers\Controller;
  9: use App\Models\Treasury;
 10: use Illuminate\Http\JsonResponse;
 11: use Illuminate\Http\Request;
 12: use Illuminate\Routing\Controllers\HasMiddleware;
 13: use Illuminate\Routing\Controllers\Middleware;
 14: use Illuminate\Validation\Rule;
 15: 
 16: class TreasuryController extends Controller implements HasMiddleware
 17: {
 18:     public static function middleware(): array
 19:     {
 20:         return [
 21:             new Middleware('can:treasuries.view', only: ['index', 'show']),
 22:             new Middleware('can:treasuries.create', only: ['store']),
 23:             new Middleware('can:treasuries.update', only: ['update']),
 24:             new Middleware('can:treasuries.delete', only: ['destroy']),
 25:         ];
 26:     }
 27: 
 28:     public function index(Request $request): JsonResponse
 29:     {
 30:         $filters = $request->validate([
 31:             'branch_id' => ['nullable', 'integer', 'min:1'],
 32:             'type' => ['nullable', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 33:             'is_active' => ['nullable', 'boolean'],
 34:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 35:         ]);
 36: 
 37:         $treasuries = Treasury::query()
 38:             ->with('branch')
 39:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 40:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 41:             ->when(isset($filters['is_active']), fn ($q) => $q->where('is_active', $filters['is_active']))
 42:             ->orderBy('branch_id')
 43:             ->orderBy('id')
 44:             ->paginate($filters['per_page'] ?? 15);
 45: 
 46:         return response()->json($treasuries);
 47:     }
 48: 
 49:     public function store(Request $request): JsonResponse
 50:     {
 51:         $data = $request->validate([
 52:             'name' => ['required', 'string', 'max:191'],
 53:             'code' => ['required', 'string', 'max:50', 'unique:treasuries,code'],
 54:             'branch_id' => ['nullable', 'integer', 'min:1', 'exists:branches,id'],
 55:             'type' => ['required', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 56:             'is_active' => ['nullable', 'boolean'],
 57:         ]);
 58: 
 59:         $treasury = Treasury::create($data + ['current_balance' => 0]);
 60: 
 61:         return response()->json([
 62:             'message' => 'تم إنشاء الخزينة بنجاح.',
 63:             'data' => $this->treasuryData($treasury),
 64:         ], 201);
 65:     }
 66: 
 67:     public function show(Treasury $treasury): JsonResponse
 68:     {
 69:         return response()->json(['data' => $this->treasuryData($treasury)]);
 70:     }
 71: 
 72:     public function update(Request $request, Treasury $treasury): JsonResponse
 73:     {
 74:         $data = $request->validate([
 75:             'name' => ['sometimes', 'string', 'max:191'],
 76:             'code' => ['sometimes', 'string', 'max:50', Rule::unique('treasuries', 'code')->ignore($treasury->id)],
 77:             'branch_id' => ['nullable', 'integer', 'min:1', 'exists:branches,id'],
 78:             'type' => ['sometimes', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 79:             'is_active' => ['nullable', 'boolean'],
 80:         ]);
 81: 
 82:         $treasury->update($data);
 83: 
 84:         return response()->json([
 85:             'message' => 'تم تحديث الخزينة بنجاح.',
 86:             'data' => $this->treasuryData($treasury),
 87:         ]);
 88:     }
 89: 
 90:     public function destroy(Treasury $treasury): JsonResponse
 91:     {
 92:         if ((float) $treasury->current_balance !== 0.0) {
 93:             return response()->json(['message' => 'لا يمكن حذف خزينة برصيد غير صفري.'], 422);
 94:         }
 95: 
 96:         $treasury->delete();
 97: 
 98:         return response()->json(['message' => 'تم حذف الخزينة.']);
 99:     }
100: 
101:     private function treasuryData(Treasury $treasury): Treasury
102:     {
103:         return $treasury->loadMissing('branch');
104:     }
105: }

