16: 
17: class TreasuryTransferController extends Controller implements HasMiddleware
18: {
19:     public static function middleware(): array
20:     {
21:         return [
22:             new Middleware('can:treasury_transfers.view', only: ['index', 'show']),
23:             new Middleware('can:treasury_transfers.create', only: ['store']),
24:             new Middleware('can:treasury_transfers.approve', only: ['approve', 'reject']),
25:         ];
26:     }
27: 
28:     public function __construct(private readonly TreasuryService $treasury) {}
29: 
30:     public function index(Request $request): JsonResponse
31:     {
32:         $filters = $request->validate([
33:             'from_treasury_id' => ['nullable', 'integer', 'min:1'],
34:             'to_treasury_id' => ['nullable', 'integer', 'min:1'],
35:             'status' => ['nullable', Rule::in(array_column(TreasuryTransferStatus::cases(), 'value'))],
36:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
37:         ]);
38: 
39:         $transfers = TreasuryTransfer::query()
40:             ->with(['fromTreasury', 'toTreasury', 'creator', 'approver'])
41:             ->when($filters['from_treasury_id'] ?? null, fn ($q, $v) => $q->where('from_treasury_id', $v))
42:             ->when($filters['to_treasury_id'] ?? null, fn ($q, $v) => $q->where('to_treasury_id', $v))
43:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
44:             ->orderByDesc('id')
45:             ->paginate($filters['per_page'] ?? 15);
46: 
47:         return response()->json($transfers);
48:     }
49: 
50:     public function store(Request $request): JsonResponse
51:     {
52:         $data = $request->validate([
53:             'from_treasury_id' => ['required', 'integer', 'min:1', 'exists:treasuries,id'],
54:             'to_treasury_id' => ['required', 'integer', 'min:1', 'exists:treasuries,id', 'different:from_treasury_id'],
55:             'amount' => ['required', 'numeric', 'min:0.01', 'max:99999999'],
56:             'notes' => ['nullable', 'string', 'max:500'],
57:         ]);
58: 
59:         $transfer = $this->treasury->createTransfer($data, (int) $request->user()->id);
60: 
61:         return response()->json([
62:             'message' => 'تم إنشاء طلب التحويل بنجاح وهو في انتظار الاعتماد.',
63:             'data' => $transfer->load(['fromTreasury', 'toTreasury', 'creator']),
64:         ], 201);
65:     }
66: 
67:     public function show(TreasuryTransfer $treasuryTransfer): JsonResponse
68:     {
69:         return response()->json([
70:             'data' => $treasuryTransfer->load(['fromTreasury', 'toTreasury', 'creator', 'approver']),
71:         ]);
72:     }
73: 
74:     /**
75:      * POST /admin/treasury-transfers/{id}/approve
76:      */
77:     public function approve(Request $request, TreasuryTransfer $treasuryTransfer): JsonResponse
78:     {
79:         $transfer = $this->treasury->approveTransfer($treasuryTransfer, (int) $request->user()->id);
80: 
81:         return response()->json([
82:             'message' => 'تم اعتماد تحويل الخزينة وتم تحديث أرصدة الخزائن.',
83:             'data' => $transfer->load(['fromTreasury', 'toTreasury', 'approver']),
84:         ]);
85:     }
86: 
87:     /**
88:      * POST /admin/treasury-transfers/{id}/reject
89:      */
