22:         'requested_qty',
23:         'approved_qty',
24:         'received_good_qty',
25:         'received_damaged_qty',
26:         'unit_refund_price',
27:         'refund_amount',
28:         'item_reason',
29:         'attachments',
30:     ];
31: 
32:     protected function casts(): array
33:     {
34:         return [
35:             'requested_qty' => 'decimal:4',
36:             'approved_qty' => 'decimal:4',
37:             'received_good_qty' => 'decimal:4',
38:             'received_damaged_qty' => 'decimal:4',
39:             'unit_refund_price' => 'decimal:4',
40:             'refund_amount' => 'decimal:2',
41:             'attachments' => 'array',
42:         ];
43:     }
44: 
45:     /** @return BelongsTo<ReturnRequest, $this> */
46:     public function returnRequest(): BelongsTo
47:     {
48:         return $this->belongsTo(ReturnRequest::class);
49:     }
50: 
51:     /** @return BelongsTo<OrderItem, $this> */
52:     public function orderItem(): BelongsTo
53:     {
54:         return $this->belongsTo(OrderItem::class);
55:     }
56: 
57:     /** @return BelongsTo<ProductVariant, $this> */
