  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\TreasuryTransactionType;
  8: use App\Enums\TreasuryTransferStatus;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\PosShift;
 11: use App\Models\Treasury;
 12: use App\Models\TreasuryTransaction;
 13: use App\Models\TreasuryTransfer;
 14: use Illuminate\Support\Facades\DB;
 15: 
 16: /**
 17:  * خدمة الخزائن — المدخل الوحيد لأي حركة مالية في الخزائن.
 18:  * قاعدة صارمة: ممنوع تعديل current_balance مباشرة من أي مكان آخر.
 19:  * كل قبض أو صرف يمر من هنا: يسجل حركة في treasury_transactions أولًا،
 20:  * ثم يحدث الرصيد — داخل نفس الـ transaction ومع قفل الصف.
 21:  */
 22: class TreasuryService
 23: {
 24:     public function __construct(private readonly SettingService $settings) {}
 25: 
 26:     /**
 27:      * تسجيل حركة مالية في خزينة مع قفل الصف وتحديث الرصيد.
 28:      *
 29:      * @param  array{
 30:      *     treasury_id: int,
 31:      *     shift_id?: int|null,
 32:      *     type: TreasuryTransactionType,
 33:      *     amount: float|string,
 34:      *     reference_type?: string|null,
 35:      *     reference_id?: int|null,
 36:      *     created_by: int,
 37:      *     notes?: string|null,
 38:      * }  $data
 39:      */
 40:     public function record(array $data): TreasuryTransaction
 41:     {
 42:         return DB::transaction(function () use ($data): TreasuryTransaction {
 43:             /** @var Treasury $treasury */
 44:             $treasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
 45: 
 46:             if (! $treasury->is_active) {
 47:                 throw new BusinessException('الخزينة غير نشطة.');
 48:             }
 49: 
 50:             $amount = (float) $data['amount'];
 51:             $balanceAfter = (float) $treasury->current_balance + $amount;
 52: 
 53:             // منع الرصيد السالب على أدراج نقطة البيع والخزائن الرئيسية
 54:             if ($balanceAfter < 0 && in_array($treasury->type->value, ['main_safe', 'pos_drawer'], true)) {
 55:                 throw new BusinessException('رصيد الخزينة غير كافٍ لإتمام العملية.');
 56:             }
 57: 
 58:             $transaction = TreasuryTransaction::create([
 59:                 'treasury_id' => $treasury->id,
 60:                 'shift_id' => $data['shift_id'] ?? null,
 61:                 'type' => $data['type'],
 62:                 'amount' => $amount,
 63:                 'balance_after' => $balanceAfter,
 64:                 'reference_type' => $data['reference_type'] ?? null,
 65:                 'reference_id' => $data['reference_id'] ?? null,
 66:                 'created_by' => $data['created_by'],
 67:                 'notes' => $data['notes'] ?? null,
 68:                 'created_at' => now(),
 69:             ]);
 70: 
 71:             $treasury->current_balance = $balanceAfter;
 72:             $treasury->save();
 73: 
 74:             return $transaction;
 75:         });
 76:     }
 77: 
 78:     /**
 79:      * تحويل مبلغ من خزينة إلى خزينة أخرى بعد الاعتماد.
 80:      */
 81:     public function approveTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
 82:     {
 83:         if ($transfer->status !== TreasuryTransferStatus::Pending) {
 84:             throw new BusinessException('يمكن اعتماد التحويلات المعلقة فقط.');
 85:         }
 86: 
 87:         return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
 88:             // خصم من المصدر
 89:             $this->record([
 90:                 'treasury_id' => $transfer->from_treasury_id,
 91:                 'type' => TreasuryTransactionType::TransferOut,
 92:                 'amount' => -abs((float) $transfer->amount),
 93:                 'reference_type' => TreasuryTransfer::class,
 94:                 'reference_id' => $transfer->id,
 95:                 'created_by' => $approverId,
 96:                 'notes' => "تحويل #{$transfer->transfer_number} صادر",
 97:             ]);
 98: 
 99:             // إضافة إلى الوجهة
100:             $this->record([
101:                 'treasury_id' => $transfer->to_treasury_id,
102:                 'type' => TreasuryTransactionType::TransferIn,
103:                 'amount' => abs((float) $transfer->amount),
104:                 'reference_type' => TreasuryTransfer::class,
105:                 'reference_id' => $transfer->id,
106:                 'created_by' => $approverId,
107:                 'notes' => "تحويل #{$transfer->transfer_number} وارد",
108:             ]);
109: 
110:             $transfer->update([
111:                 'status' => TreasuryTransferStatus::Approved,
112:                 'approved_by' => $approverId,
113:             ]);
114: 
115:             return $transfer->fresh();
116:         });
117:     }
118: 
119:     /**
120:      * ترحيل نقدية الوردية المعتمدة إلى الخزنة الرئيسية للفرع.
121:      */
122:     public function settleShiftToMainSafe(PosShift $shift, int $approverId): void
123:     {
124:         DB::transaction(function () use ($shift, $approverId): void {
125:             // الخزنة الرئيسية للفرع
126:             $mainSafe = Treasury::query()
127:                 ->where('branch_id', $shift->branch_id)
128:                 ->where('type', 'main_safe')
129:                 ->where('is_active', true)
130:                 ->first();
131: 
132:             if ($mainSafe === null) {
133:                 // لا خزنة رئيسية — لا ترحيل
134:                 return;
135:             }
136: 
137:             // الرصيد الفعلي الحالي في الدرج
138:             $drawer = Treasury::query()->lockForUpdate()->findOrFail($shift->treasury_id);
139:             $drawerBalance = (float) $drawer->current_balance;
140: 
141:             // المبلغ المطلوب ترحيله هو المبلغ الفعلي المعدود، ولكن لا يتجاوز رصيد الدرج المتاح
142:             $requestedAmount = (float) ($shift->actual_closing_cash ?? $shift->expected_closing_cash);
143:             $amount = min($drawerBalance, $requestedAmount);
144: 
145:             if ($amount <= 0) {
146:                 return;
147:             }
148: 
149:             // خصم من درج الكاشير
150:             $this->record([
151:                 'treasury_id' => $shift->treasury_id,
152:                 'type' => TreasuryTransactionType::TransferOut,
153:                 'amount' => -$amount,
154:                 'reference_type' => PosShift::class,
155:                 'reference_id' => $shift->id,
156:                 'created_by' => $approverId,
157:                 'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
158:             ]);
159: 
160:             // إضافة للخزنة الرئيسية
161:             $this->record([
162:                 'treasury_id' => $mainSafe->id,
163:                 'type' => TreasuryTransactionType::TransferIn,
164:                 'amount' => $amount,
165:                 'reference_type' => PosShift::class,
166:                 'reference_id' => $shift->id,
167:                 'created_by' => $approverId,
168:                 'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
169:             ]);
170:         });
171:     }
172: 
173:     /**
174:      * إنشاء تحويل خزينة جديد (معلق حتى الاعتماد).
175:      */
176:     public function createTransfer(array $data, int $userId): TreasuryTransfer
177:     {
178:         if ($data['from_treasury_id'] === $data['to_treasury_id']) {
179:             throw new BusinessException('لا يمكن التحويل من خزينة إلى نفسها.');
180:         }
181: 
182:         $number = $this->settings->generateNextNumber('treasury_transfer');
183: 
184:         return TreasuryTransfer::create([
185:             'transfer_number' => $number,
186:             'from_treasury_id' => $data['from_treasury_id'],
187:             'to_treasury_id' => $data['to_treasury_id'],
188:             'amount' => $data['amount'],
189:             'status' => TreasuryTransferStatus::Pending,
190:             'created_by' => $userId,
191:             'notes' => $data['notes'] ?? null,
192:         ]);
193:     }
194: 
195:     /**
196:      * رفض تحويل خزينة.
197:      */
198:     public function rejectTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
199:     {
200:         if ($transfer->status !== TreasuryTransferStatus::Pending) {
201:             throw new BusinessException('يمكن رفض التحويلات المعلقة فقط.');
202:         }
203: 
204:         $transfer->update([
205:             'status' => TreasuryTransferStatus::Rejected,
206:             'approved_by' => $approverId,
207:         ]);
208: 
209:         return $transfer->fresh();
210:     }
211: }

