 5: namespace App\Services;
 6: 
 7: /**
 8:  * بصمة حمولات عدم التكرار: ترتيب حتمي لمفاتيح المصفوفات وتطبيع للأرقام،
 9:  * بحيث تنتج الاختلافات الشكلية في تسلسل العميل ("5" مقابل 5 مقابل 5.0)
10:  * نفس البصمة، فلا تتحول إعادة إرسال مطابقة إلى 409 زائف (L-2).
11:  */
12: final class IdempotencyFingerprint
13: {
14:     public static function hash(array $payload): string
15:     {
16:         return hash('sha256', json_encode(self::canonicalize($payload), JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION));
17:     }
18: 
19:     private static function canonicalize(mixed $value, ?string $field = null): mixed
20:     {
21:         if (is_numeric($value) && in_array($field, [
22:             'amount', 'subtotal', 'tax_amount', 'unit_cost', 'unit_price', 'line_total',
23:             'grand_total', 'discount_amount', 'total', 'total_amount', 'paid_amount',
24:             'expected_total',
25:         ], true)) {
26:             return (int) round(((float) $value) * 100);
27:         }
28: 
29:         if (is_string($value) && is_numeric($value)
30:             && ($field === 'id' || str_ends_with($field ?? '', '_id')
31:                 || in_array($field, ['qty', 'amount', 'received_good_qty', 'received_damaged_qty', 'quantity', 'requested_qty', 'counted_qty', 'approved_qty', 'shipped_qty', 'received_qty'], true))) {
32:             $value = $value + 0;
33:         }
34: 
35:         if (is_float($value) && floor($value) === $value && abs($value) <= 9007199254740991) {
36:             return (int) $value;
37:         }
38: 
39:         if (! is_array($value)) {
40:             return $value;
41:         }
42: 
43:         $isList = array_is_list($value);
44:         $mapped = [];
45:         foreach ($value as $key => $item) {
46:             $mapped[$key] = self::canonicalize($item, is_string($key) ? $key : null);
47:         }
48: 
49:         if ($isList && $mapped !== [] && self::isItemList($mapped)) {
50:             usort($mapped, self::itemSort(...));
51:         }
52: 
53:         if (! $isList) {
54:             ksort($mapped);
55:         }
56: 
57:         return $mapped;
58:     }
59: 
60:     /** @param list<mixed> $items */
61:     private static function isItemList(array $items): bool
62:     {
63:         foreach ($items as $item) {
64:             if (! is_array($item) || (! isset($item['id']) && ! isset($item['order_item_id']) && ! isset($item['purchase_order_item_id']) && ! isset($item['product_variant_id']))) {
65:                 return false;
66:             }
67:         }
68: 
69:         return true;
70:     }
71: 
72:     /** @param array<string, mixed> $left */
73:     private static function itemSort(array $left, array $right): int
74:     {
75:         foreach (['order_item_id', 'purchase_order_item_id', 'id', 'product_variant_id'] as $key) {
76:             if (isset($left[$key], $right[$key])) {
77:                 return $left[$key] <=> $right[$key];
78:             }
79:         }
80: 
81:         return 0;
82:     }
83: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Branch;
 11: use App\Models\ProductionReceipt;
 12: use App\Models\ProductVariant;
 13: use App\Models\StockLevel;
 14: use Illuminate\Database\UniqueConstraintViolationException;
 15: use Illuminate\Support\Facades\DB;
 16: 
 17: class ProductionReceiptService
 18: {
 19:     public function __construct(private readonly InventoryService $inventory) {}
 20: 
 21:     public function receive(array $data, int $userId, string $key): ProductionReceipt
 22:     {
 23:         app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
 24:         $hash = IdempotencyFingerprint::hash($data);
 25:         $existing = ProductionReceipt::where('created_by', $userId)->where('idempotency_key', $key)->first();
 26:         if ($existing) {
 27:             return $this->replay($existing, $hash);
 28:         }
 29: 
 30:         try {
 31:             return DB::transaction(function () use ($data, $userId, $key, $hash): ProductionReceipt {
 32:                 DB::statement("SET LOCAL lock_timeout = '5s'");
 33:                 $branch = Branch::whereKey($data['branch_id'])->sharedLock()->firstOrFail();
 34:                 if (! $branch->is_active) {
 35:                     throw new BusinessException('الفرع غير نشط.');
 36:                 }
 37:                 $variants = ProductVariant::whereIn('id', array_column($data['items'], 'product_variant_id'))
 38:                     ->with('product:id,name_ar')->orderBy('id')->lockForUpdate()->get()->keyBy('id');
 39: 
 40:                 $sortedItems = collect($data['items'])->sortBy('product_variant_id')->values()->all();
 41:                 $itemsWithLabels = [];
 42: 
 43:                 foreach ($sortedItems as $item) {
 44:                     $variant = $variants->get($item['product_variant_id']);
 45:                     if (! $variant || ! $variant->is_active || ! $variant->product) {
 46:                         throw new BusinessException('أحد أصناف الإنتاج غير متاح.');
 47:                     }
 48:                     $itemsWithLabels[] = [
 49:                         ...$item,
 50:                         'label' => $variant->product->name_ar.' / '.$variant->sku,
 51:                     ];
 52:                 }
 53: 
 54:                 $receipt = ProductionReceipt::create([
 55:                     ...$data, 'items' => $itemsWithLabels, 'created_by' => $userId, 'idempotency_key' => $key, 'request_hash' => $hash,
 56:                 ]);
 57: 
 58:                 foreach ($sortedItems as $item) {
 59:                     $variant = $variants->get($item['product_variant_id']);
 60:                     $quantity = (int) $item['quantity'];
 61:                     $unitCost = bcadd((string) $item['unit_cost'], '0', 4);
 62:                     // H4: bcmath weighted average — float loses precision once
 63:                     // on_hand * cost crosses 2^53, silently biasing landed cost.
 64:                     // F12: lock this variant's stock_levels rows before summing so
 65:                     // the average is computed on a frozen balance even if a
 66:                     // concurrent movement path ever skips the variant lock.
 67:                     $lockedLevelIds = StockLevel::where('product_variant_id', $variant->id)->orderBy('id')->lockForUpdate()->pluck('id');
 68:                     $onHandStr = (string) StockLevel::whereIn('id', $lockedLevelIds)->sum('on_hand');
 69:                     $onHandStr = bccomp($onHandStr, '0', 4) < 0 ? '0' : $onHandStr;
 70:                     $costStr = (string) $variant->cost_price;
 71:                     $unitStr = $unitCost;
 72:                     $total = bcadd(bcmul($onHandStr, $costStr, 8), bcmul((string) $quantity, $unitStr, 8), 8);
 73:                     $average = bcadd(bcdiv($total, bcadd($onHandStr, (string) $quantity, 4), 5), '0.00005', 4);
 74:                     $variant->update(['cost_price' => $average, 'last_cost_price' => $unitCost]);
 75:                     $this->inventory->recordMovement([
 76:                         'product_variant_id' => $variant->id,
 77:                         'branch_id' => (int) $data['branch_id'],
 78:                         'location_id' => $data['location_id'] ?? null,
 79:                         'type' => StockMovementType::ProductionReceipt,
 80:                         'affected_bucket' => StockBucket::OnHand,
 81:                         'quantity' => $quantity, 'unit_cost' => $unitCost,
 82:                         'reference_type' => ProductionReceipt::class, 'reference_id' => $receipt->id,
 83:                         'created_by' => $userId, 'notes' => $data['notes'] ?? null,
 84:                     ]);
 85:                 }
 86: 
 87:                 return $receipt;
 88:             }, 3);
 89:         } catch (UniqueConstraintViolationException $exception) {
 90:             $existing = ProductionReceipt::where('created_by', $userId)->where('idempotency_key', $key)->first();
 91:             if ($existing) {
 92:                 return $this->replay($existing, $hash);
 93:             }
 94:             if (ProductionReceipt::whereRaw('LOWER(batch_number) = ?', [mb_strtolower($data['batch_number'])])->exists()) {
 95:                 throw new BusinessException('رقم دفعة الإنتاج مسجل بالفعل؛ راجع سجل الاستلام.', [], 409);
 96:             }
 97:             throw $exception;
 98:         }
 99:     }
100: 
101:     private function replay(ProductionReceipt $receipt, string $hash): ProductionReceipt
102:     {
103:         if (! hash_equals($receipt->request_hash, $hash)) {
104:             throw new BusinessException('مفتاح الطلب مستخدم مع بيانات مختلفة.', [], 409);
105:         }
106: 
107:         return $receipt;
108:     }
109: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Enums\QuotationStatus;
  9: use App\Events\OrderCreated;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Customer;
 12: use App\Models\Order;
 13: use App\Models\OrderStatusHistory;
 14: use App\Models\ProductVariant;
 15: use App\Models\Quotation;
 16: use App\Models\User;
 17: use Illuminate\Support\Facades\DB;
 18: 
 19: /**
 20:  * عروض أسعار الجملة (المرحلة 12.1): يبني التاجر مسودة بأسعار محسوبة من
 21:  * PricingService، يرسلها، تسعّرها الإدارة (أو تعتمد الأسعار المحسوبة)،
 22:  * ثم يقبلها التاجر أو يرفضها قبل انتهاء صلاحيتها. لا أثر مخزني هنا —
 23:  * التحويل لطلب خطوة لاحقة تنفّذ عبر OrderService.
 24:  */
 25: class QuotationService
 26: {
 27:     public function __construct(
 28:         private readonly SettingService $settings,
 29:         private readonly PricingService $pricing,
 30:         private readonly OrderService $orders,
 31:         private readonly OrderAllocationService $allocation,
 32:     ) {}
 33: 
 34:     public function create(Customer $customer, array $data): Quotation
 35:     {
 36:         return DB::transaction(function () use ($customer, $data): Quotation {
 37:             $quotation = Quotation::create([
 38:                 'quotation_number' => $this->settings->generateNextNumber('quotation'),
 39:                 'customer_id' => $customer->id,
 40:                 'status' => QuotationStatus::Draft,
 41:                 'customer_notes' => $data['customer_notes'] ?? null,
 42:             ]);
 43: 
 44:             $this->syncItems($quotation, $customer, $data['items']);
 45:             $this->recalculate($quotation);
 46: 
 47:             return $quotation->load('items.variant.product');
 48:         });
 49:     }
 50: 
 51:     public function update(Quotation $quotation, array $data): Quotation
 52:     {
 53:         if ($quotation->status !== QuotationStatus::Draft) {
 54:             throw new BusinessException('لا يمكن تعديل عرض السعر إلا وهو مسودة.');
 55:         }
 56: 
 57:         return DB::transaction(function () use ($quotation, $data): Quotation {
 58:             $quotation->update([
 59:                 'customer_notes' => $data['customer_notes'] ?? $quotation->customer_notes,
 60:             ]);
 61: 
 62:             if (isset($data['items'])) {
 63:                 $quotation->items()->delete();
 64:                 $this->syncItems($quotation, $quotation->customer, $data['items']);
 65:             }
 66: 
 67:             $this->recalculate($quotation);
 68: 
 69:             return $quotation->load('items.variant.product');
 70:         });
 71:     }
 72: 
 73:     public function submit(Quotation $quotation): Quotation
 74:     {
 75:         if ($quotation->status !== QuotationStatus::Draft) {
 76:             throw new BusinessException('لا يمكن إرسال عرض السعر إلا من حالة المسودة.');
 77:         }
 78: 
 79:         if ($quotation->items()->count() === 0) {
 80:             throw new BusinessException('لا يمكن إرسال عرض سعر بلا بنود.');
 81:         }
 82: 
 83:         $quotation->update(['status' => QuotationStatus::Requested]);
 84: 
 85:         return $quotation->load('items.variant.product');
 86:     }
 87: 
 88:     /**
 89:      * تسعير الإدارة: تحديث الأسعار المعروضة لبنود محددة (أو اعتماد المحسوبة
 90:      * كما هي) مع الخصم والضريبة وصلاحية العرض.
 91:      */
 92:     public function price(Quotation $quotation, array $data): Quotation
 93:     {
 94:         if ($quotation->status !== QuotationStatus::Requested) {
 95:             throw new BusinessException('لا يمكن تسعير عرض السعر إلا بعد إرساله من التاجر.');
 96:         }
 97: 
 98:         return DB::transaction(function () use ($quotation, $data): Quotation {
 99:             foreach ($data['items'] ?? [] as $row) {
100:                 $item = $quotation->items()->whereKey($row['id'])->first();
101: 
102:                 if ($item === null) {
103:                     throw new BusinessException('أحد بنود التسعير لا ينتمي لعرض السعر هذا.');
104:                 }
105: 
106:                 $item->update([
107:                     'offered_unit_price' => $row['offered_unit_price'],
108:                     'line_total' => round((float) $row['offered_unit_price'] * (float) $item->qty, 2),
109:                 ]);
110:             }
111: 
112:             $quotation->update([
113:                 'status' => QuotationStatus::PricedByAdmin,
114:                 'valid_until' => $data['valid_until'] ?? $quotation->valid_until,
115:                 'admin_notes' => $data['admin_notes'] ?? $quotation->admin_notes,
116:                 'discount_amount' => $data['discount_amount'] ?? $quotation->discount_amount,
117:                 'tax_amount' => $data['tax_amount'] ?? $quotation->tax_amount,
118:             ]);
119: 
120:             $this->recalculate($quotation);
121: 
122:             return $quotation->load('items.variant.product');
123:         });
124:     }
125: 
126:     /**
127:      * قبول التاجر للعرض المسعّر يحوّله تلقائيًا إلى طلب مؤكد (المرحلة 12.2)
128:      * بنفس الأسعار المتفق عليها: إنشاء الطلب آجلًا (credit) بأسعار العرض
129:      * الثابتة، حجز مخزونه عبر خدمة التوزيع، ثم تأكيده عبر بوابة الحالات —
130:      * وأي نقص مخزون يُسقط التحويل كله ويبقى العرض مسعّرًا كما هو.
131:      */
132:     public function accept(Quotation $quotation): Quotation
133:     {
134:         if ($quotation->status !== QuotationStatus::PricedByAdmin) {
135:             throw new BusinessException('لا يمكن قبول عرض السعر إلا بعد تسعير الإدارة له.');
136:         }
137: 
138:         if ($quotation->valid_until !== null && $quotation->valid_until->lt(now()->startOfDay())) {
139:             $quotation->update(['status' => QuotationStatus::Expired]);
140: 
141:             throw new BusinessException('انتهت صلاحية عرض السعر هذا.');
142:         }
143: 
144:         return DB::transaction(function () use ($quotation): Quotation {
145:             $quotation->loadMissing(['customer', 'items.variant.product']);
146:             $customer = $quotation->customer;
147: 
148:             $order = Order::create([
149:                 'order_number' => $this->settings->generateNextNumber('order'),
150:                 'channel' => 'wholesale',
151:                 'customer_id' => $customer->id,
152:                 'guest_name' => $customer->name,
153:                 'guest_phone' => $customer->phone,
154:                 'guest_phone_normalized' => Customer::normalizePhone((string) $customer->phone),
155:                 'guest_email' => $customer->email,
156:                 'status' => OrderStatus::Pending,
157:                 'payment_method' => 'credit',
158:                 'payment_status' => 'unpaid',
159:                 'subtotal' => $quotation->subtotal,
160:                 'discount_amount' => $quotation->discount_amount,
161:                 'shipping_cost' => 0,
162:                 'cod_fee' => 0,
163:                 'tax_amount' => $quotation->tax_amount,
164:                 'grand_total' => $quotation->grand_total,
165:             ]);
166: 
167:             // خصم وضريبة الترويسة يوزَّعان على البنود بأكبر باقٍ حتى تطابق
168:             // حسابات الاسترداد لاحقًا مجموع الترويسة بالقرش.
169:             $weights = $quotation->items->map(fn ($item) => (float) $item->line_total)->all();
170:             $discountShares = $this->distributeLargestRemainder((float) $quotation->discount_amount, $weights);
171:             $taxShares = $this->distributeLargestRemainder((float) $quotation->tax_amount, $weights);
172: 
173:             foreach ($quotation->items->values() as $i => $item) {
174:                 $order->items()->create([
175:                     'product_variant_id' => $item->product_variant_id,
176:                     'product_name_snapshot' => $item->variant->product?->name_ar ?? '',
177:                     'sku_snapshot' => $item->variant->sku,
178:                     'qty' => $item->qty,
179:                     'unit_price' => $item->offered_unit_price,
180:                     'discount_amount' => $discountShares[$i],
181:                     'tax_amount' => $taxShares[$i],
182:                     'line_total' => $item->line_total,
183:                 ]);
184:             }
185: 
186:             OrderStatusHistory::create([
187:                 'order_id' => $order->id,
188:                 'from_status' => null,
189:                 'to_status' => OrderStatus::Pending,
190:                 'changed_by_type' => Customer::class,
191:                 'changed_by_id' => $customer->id,
192:                 'notes' => "أُنشئ من عرض السعر {$quotation->quotation_number}",
193:             ]);
194: 
195:             $order->load('items');
196:             $this->allocation->allocate($order, performedBy: $this->systemActorId());
197: 
198:             $this->orders->changeStatus($order, OrderStatus::Confirmed, $customer, "قبول عرض السعر {$quotation->quotation_number}");
199: 
200:             $quotation->update([
201:                 'status' => QuotationStatus::ConvertedToOrder,
202:                 'converted_order_id' => $order->id,
203:             ]);
204: 
205:             OrderCreated::dispatch($order->fresh());
206: 
207:             return $quotation->load(['items.variant.product', 'convertedOrder']);
208:         });
209:     }
210: 
211:     /** معرّف مستخدم النظام منفّذًا لحركات مخزون العميل (نفس اصطلاح OrderService). */
212:     private function systemActorId(): ?int
213:     {
214:         $id = User::query()
215:             ->where('email', (string) config('orders.system_user_email', 'system@alfarid.local'))
216:             ->value('id');
217: 
218:         return $id !== null ? (int) $id : null;
219:     }
220: 
221:     /**
222:      * توزيع مبلغ على بنود بأوزان مالية بطريقة أكبر باقٍ (بالقروش) — مجموع
223:      * الحصص يساوي المبلغ بالضبط ولا تقع حصة سالبة.
224:      *
225:      * @param  list<float>  $weights
226:      * @return list<float>
227:      */
228:     private function distributeLargestRemainder(float $amount, array $weights): array
229:     {
230:         $count = count($weights);
231:         $totalCents = (int) round($amount * 100);
232:         $totalWeight = array_sum($weights);
233: 
234:         if ($count === 0 || $totalCents === 0 || $totalWeight <= 0) {
235:             return array_fill(0, $count, 0.0);
236:         }
237: 
238:         $shares = [];
239:         $remainders = [];
240:         $allocated = 0;
241:         foreach ($weights as $i => $weight) {
242:             $exact = $totalCents * $weight / $totalWeight;
243:             $floor = (int) floor($exact);
244:             $shares[$i] = $floor;
245:             $remainders[$i] = $exact - $floor;
246:             $allocated += $floor;
247:         }
248: 
249:         $order = array_keys($remainders);
250:         usort($order, fn (int $a, int $b): int => $remainders[$b] <=> $remainders[$a]);
251:         for ($k = 0; $k < $totalCents - $allocated; $k++) {
252:             $shares[$order[$k % $count]]++;
253:         }
254: 
255:         return array_map(fn (int $cents): float => $cents / 100, $shares);
256:     }
257: 
258:     public function reject(Quotation $quotation): Quotation
259:     {
260:         if (! in_array($quotation->status, [QuotationStatus::Requested, QuotationStatus::PricedByAdmin], true)) {
261:             throw new BusinessException('لا يمكن رفض عرض السعر في حالته الحالية.');
262:         }
263: 
264:         $quotation->update(['status' => QuotationStatus::Rejected]);
265: 
266:         return $quotation->load('items.variant.product');
267:     }
268: 
269:     public function expire(Quotation $quotation): Quotation
270:     {
271:         if (! in_array($quotation->status, [QuotationStatus::Requested, QuotationStatus::PricedByAdmin], true)) {
272:             throw new BusinessException('لا يمكن إنهاء صلاحية عرض السعر في حالته الحالية.');
273:         }
274: 
275:         $quotation->update(['status' => QuotationStatus::Expired]);
276: 
277:         return $quotation->load('items.variant.product');
278:     }
279: 
280:     public function deleteDraft(Quotation $quotation): void
281:     {
282:         if ($quotation->status !== QuotationStatus::Draft) {
283:             throw new BusinessException('لا يمكن حذف عرض السعر إلا وهو مسودة.');
284:         }
285: 
286:         $quotation->delete();
287:     }
288: 
289:     /**
290:      * @param  list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>  $items
291:      */
292:     private function syncItems(Quotation $quotation, Customer $customer, array $items): void
293:     {
294:         $variantIds = collect($items)->pluck('product_variant_id')->unique()->all();
295:         $variants = ProductVariant::query()->whereIn('id', $variantIds)->get()->keyBy('id');
296: 
297:         foreach ($items as $row) {
298:             $variant = $variants->get($row['product_variant_id']);
299: 
300:             if ($variant === null || ! $variant->is_active) {
301:                 throw new BusinessException('أحد المتغيرات المطلوبة غير موجود أو غير نشط.');
302:             }
303: 
304:             $offered = $this->pricing->resolve($variant, $customer, (float) $row['qty'])['unit_price'];
305: 
306:             $quotation->items()->create([
307:                 'product_variant_id' => $variant->id,
308:                 'qty' => $row['qty'],
309:                 'requested_target_price' => $row['requested_target_price'] ?? null,
310:                 'offered_unit_price' => $offered,
311:                 'line_total' => round($offered * (float) $row['qty'], 2),
312:             ]);
313:         }
314:     }
315: 
316:     private function recalculate(Quotation $quotation): void
317:     {
318:         $subtotal = (float) $quotation->items()->sum('line_total');
319:         $grandTotal = round($subtotal - (float) $quotation->discount_amount + (float) $quotation->tax_amount, 2);
320: 
321:         if ($grandTotal < 0) {
322:             throw new BusinessException('إجمالي عرض السعر لا يمكن أن يكون سالبًا — راجع الخصم.');
323:         }
324: 
325:         $quotation->update([
326:             'subtotal' => $subtotal,
327:             'grand_total' => $grandTotal,
328:         ]);
329:     }
330: }

