 2: 
 3: declare(strict_types=1);
 4: 
 5: namespace App\Services;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Models\Supplier;
 9: use Illuminate\Support\Facades\DB;
10: 
11: /**
12:  * إدارة الموردين: قاعدة الرصيد الوحيدة هنا أن current_balance يبدأ من
13:  * opening_balance لحظة الإنشاء؛ بعدها لا يتحرك إلا عبر SupplierFinanceService
14:  * (اعتماد فواتير ودفعات) — تعديل بيانات المورد لا يمس رصيده الجاري.
15:  */
16: class SupplierService
17: {
18:     /**
19:      * @param  array<string, mixed>  $data
20:      */
21:     public function create(array $data): Supplier
22:     {
23:         return DB::transaction(function () use ($data): Supplier {
24:             $data['current_balance'] = $data['opening_balance'] ?? 0;
25: 
26:             return Supplier::create($data);
27:         });
28:     }
29: 
30:     /**
31:      * @param  array<string, mixed>  $data
32:      */
33:     public function update(Supplier $supplier, array $data): Supplier
34:     {
35:         // الرصيد الجاري نتيجة دفترية — لا يُعدَّل يدويًا من شاشة المورد
36:         return DB::transaction(function () use ($supplier, $data): Supplier {
37:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($supplier->id);
38:             unset($data['current_balance']);
39:             if (array_key_exists('opening_balance', $data)
40:                 && (float) $data['opening_balance'] !== (float) $supplier->opening_balance) {
41:                 if ($supplier->invoices()->exists() || $supplier->payments()->exists()) {
42:                     throw new BusinessException('لا يمكن تعديل الرصيد الافتتاحي بعد تسجيل فواتير أو دفعات.');
43:                 }
44:                 $data['current_balance'] = round((float) $supplier->current_balance
45:                     + (float) $data['opening_balance'] - (float) $supplier->opening_balance, 2);
46:             }
47:             $supplier->update($data);
48: 
49:             return $supplier->fresh();
50:         });
51:     }
52: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Enums\TransferStatus;
 10: use App\Events\TransferPendingApproval;
 11: use App\Exceptions\BusinessException;
 12: use App\Models\Location;
 13: use App\Models\StockMovement;
 14: use App\Models\StockTransfer;
 15: use App\Models\StockTransferItem;
 16: use App\Services\Concerns\HandlesIdempotentCreation;
 17: use Carbon\Carbon;
 18: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
 19: use Illuminate\Support\Collection;
 20: use Illuminate\Support\Facades\DB;
 21: 
 22: /**
 23:  * دورة حياة التحويلات بين الفروع. كل أثر مخزني بيمر من InventoryService فقط.
 24:  *
 25:  * draft: لا أثر مخزني. approve: حجز في المرسل. ship: فك الحجز + إخراج فعلي +
 26:  * in_transit عند المستلم. receive: تسوية in_transit + إضافة الفعلي المستلم.
 27:  */
 28: class TransferService
 29: {
 30:     use HandlesIdempotentCreation;
 31: 
 32:     public function __construct(
 33:         private readonly InventoryService $inventory,
 34:         private readonly SettingService $settings,
 35:     ) {}
 36: 
 37:     public function paginate(array $filters): LengthAwarePaginator
 38:     {
 39:         return StockTransfer::query()
 40:             ->when($filters['staff_branch_id'] ?? null, fn ($q, $branch) => $q->where(fn ($scope) => $scope->where('from_branch_id', $branch)->orWhere('to_branch_id', $branch)))
 41:             ->with(['fromBranch', 'toBranch', 'creator'])
 42:             ->when($filters['from_branch_id'] ?? null, fn ($q, $v) => $q->where('from_branch_id', $v))
 43:             ->when($filters['to_branch_id'] ?? null, fn ($q, $v) => $q->where('to_branch_id', $v))
 44:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 45:             ->orderByDesc('id')
 46:             ->paginate($filters['per_page'] ?? 15);
 47:     }
 48: 
 49:     public function find(int $id): StockTransfer
 50:     {
 51:         return StockTransfer::query()
 52:             ->with(['items.variant', 'items.fromLocation', 'items.toLocation', 'fromBranch', 'toBranch', 'creator', 'approver'])
 53:             ->findOrFail($id);
 54:     }
 55: 
 56:     public function create(array $data, int $userId, ?string $idempotencyKey = null): StockTransfer
 57:     {
 58:         app(BranchAccess::class)->assertBranch($userId, (int) $data['from_branch_id']);
 59: 
 60:         /** @var StockTransfer */
 61:         return $this->createIdempotently(
 62:             'transfer_store',
 63:             $data,
 64:             $userId,
 65:             $idempotencyKey,
 66:             StockTransfer::class,
 67:             ['items.variant', 'fromBranch', 'toBranch', 'creator'],
 68:             fn (): StockTransfer => $this->doCreate($data, $userId),
 69:         );
 70:     }
 71: 
 72:     private function doCreate(array $data, int $userId): StockTransfer
 73:     {
 74:         return DB::transaction(function () use ($data, $userId): StockTransfer {
 75:             app(BranchAccess::class)->assertBranch($userId, (int) $data['from_branch_id']);
 76:             $transfer = StockTransfer::query()->create([
 77:                 'transfer_number' => $this->settings->generateNextNumber('transfer'),
 78:                 'from_branch_id' => $data['from_branch_id'],
 79:                 'to_branch_id' => $data['to_branch_id'],
 80:                 'status' => TransferStatus::Draft,
 81:                 'created_by' => $userId,
 82:                 'notes' => $data['notes'] ?? null,
 83:             ]);
 84: 
 85:             $this->syncItems($transfer, $data['items']);
 86: 
 87:             $created = $transfer->load(['items.variant', 'fromBranch', 'toBranch', 'creator']);
 88:             TransferPendingApproval::dispatch($created);
 89: 
 90:             return $created;
 91:         });
 92:     }
 93: 
 94:     public function update(StockTransfer $transfer, array $data, int $userId): StockTransfer
 95:     {
 96:         return DB::transaction(function () use ($transfer, $data, $userId): StockTransfer {
 97:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
 98:             $this->assertStatus($transfer, TransferStatus::Draft, 'التعديل');
 99:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
100:             app(BranchAccess::class)->assertBranch($userId, (int) ($data['from_branch_id'] ?? $transfer->from_branch_id));
101: 
102:             $fromBranch = $data['from_branch_id'] ?? $transfer->from_branch_id;
103:             $toBranch = $data['to_branch_id'] ?? $transfer->to_branch_id;
104:             if ((int) $fromBranch === (int) $toBranch) {
105:                 throw new BusinessException('يجب اختلاف الفرع المرسل عن الفرع المستلم.');
106:             }
107:             $items = $data['items'] ?? $transfer->items->toArray();
108:             foreach ($items as $item) {
109:                 foreach (['from_location_id' => $fromBranch, 'to_location_id' => $toBranch] as $field => $branchId) {
110:                     if (isset($item[$field]) && ! Location::query()->whereKey($item[$field])->where('branch_id', $branchId)->exists()) {
111:                         throw new BusinessException('موقع التحويل لا يتبع الفرع المحدد.');
112:                     }
113:                 }
114:             }
115: 
116:             $transfer->update([
117:                 'from_branch_id' => $data['from_branch_id'] ?? $transfer->from_branch_id,
118:                 'to_branch_id' => $data['to_branch_id'] ?? $transfer->to_branch_id,
119:                 'notes' => array_key_exists('notes', $data) ? $data['notes'] : $transfer->notes,
120:             ]);
121: 
122:             if (isset($data['items'])) {
123:                 $transfer->items()->delete();
124:                 $this->syncItems($transfer, $data['items']);
125:             }
126: 
127:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch', 'creator']);
128:         });
129:     }
130: 
131:     /** الاعتماد: حجز الكميات المعتمدة في الفرع المرسل حتى لا تُباع قبل الشحن. */
132:     public function approve(StockTransfer $transfer, array $itemsPayload, int $userId, ?string $expectedUpdatedAt = null, ?int $expectedVersion = null): StockTransfer
133:     {
134:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId, $expectedUpdatedAt, $expectedVersion): StockTransfer {
135:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
136:             $transfer->load('items.variant');
137:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
138:             $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, $expectedUpdatedAt, $expectedVersion);
139:             $this->assertStatus($transfer, TransferStatus::Draft, 'الاعتماد');
140:             if ($transfer->items->sum(fn ($item) => (float) ($itemsPayload[$item->id] ?? $item->requested_qty)) <= 0) {
141:                 throw new BusinessException('يجب اعتماد كمية موجبة واحدة على الأقل؛ يمكن إلغاء التحويل بدلًا من اعتماده بصفر.');
142:             }
143:             $levels = $this->lockTransferLevels($transfer, true, false);
144:             $qtyUpdates = [];
145: 
146:             foreach ($transfer->items as $item) {
147:                 $approvedQty = (float) ($itemsPayload[$item->id] ?? $item->requested_qty);
148: 
149:                 if ($approvedQty < 0 || $approvedQty > (float) $item->requested_qty) {
150:                     throw new BusinessException('الكمية المعتمدة يجب أن تكون بين صفر والكمية المطلوبة.');
151:                 }
152: 
153:                 // تحديثات البنود تتجمع في UPDATE واحد بعد الحلقة (M-6) — الأقفال
154:                 // مأخوذة طوال العملية، فتقليل الاستعلامات يقلل زمن احتجازها.
155:                 // الصف يُمرَّر كاملًا بحالته الحالية: PostgreSQL يتحقق من قيود
156:                 // NOT NULL وCHECK على الصف المقترح في upsert قبل حل التعارض.
157:                 $qtyUpdates[] = [...$item->only(['id', 'stock_transfer_id', 'product_variant_id', 'from_location_id', 'to_location_id', 'requested_qty', 'approved_qty', 'shipped_qty', 'received_qty', 'created_at']), 'approved_qty' => $approvedQty, 'updated_at' => now()];
158: 
159:                 if ($approvedQty > 0) {
160:                     $this->move([
161:                         'product_variant_id' => $item->product_variant_id,
162:                         'branch_id' => $transfer->from_branch_id,
163:                         'location_id' => $item->from_location_id,
164:                         'type' => StockMovementType::Reserve,
165:                         'affected_bucket' => StockBucket::Reserved,
166:                         'quantity' => $approvedQty,
167:                         'unit_cost' => $item->variant?->cost_price,
168:                         'reference_type' => StockTransfer::class,
169:                         'reference_id' => $transfer->id,
170:                         'created_by' => $userId,
171:                         'notes' => 'حجز لصالح تحويل '.$transfer->transfer_number,
172:                     ], $levels);
173:                 }
174:             }
175: 
176:             if ($qtyUpdates !== []) {
177:                 StockTransferItem::query()->upsert($qtyUpdates, ['id'], ['approved_qty', 'updated_at']);
178:             }
179: 
180:             $transfer->update(['status' => TransferStatus::Approved, 'approved_by' => $userId]);
181: 
182:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
183:         });
184:     }
185: 
186:     /** الشحن: فك الحجز وإخراج البضاعة من المرسل، وتسجيلها "في الطريق" عند المستلم. */
187:     public function ship(StockTransfer $transfer, array $itemsPayload, int $userId, ?string $expectedUpdatedAt = null, ?int $expectedVersion = null): StockTransfer
188:     {
189:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId, $expectedUpdatedAt, $expectedVersion): StockTransfer {
190:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
191:             $transfer->load('items.variant');
192:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
193:             if (in_array($transfer->status, [TransferStatus::Shipped, TransferStatus::Received], true)) {
194:                 return $this->replayCompletedStage($transfer, $itemsPayload, 'shipped_qty');
195:             }
196:             $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, $expectedUpdatedAt, $expectedVersion);
197:             $this->assertStatus($transfer, TransferStatus::Approved, 'الشحن');
198:             if ($transfer->items->sum(fn ($item) => (float) ($itemsPayload[$item->id] ?? $item->approved_qty)) <= 0) {
199:                 throw new BusinessException('يجب شحن كمية موجبة واحدة على الأقل؛ يمكن إلغاء التحويل لفك الحجز.');
200:             }
201:             $levels = $this->lockTransferLevels($transfer, true, true);
202:             $qtyUpdates = [];
203: 
204:             foreach ($transfer->items as $item) {
205:                 $shippedQty = (float) ($itemsPayload[$item->id] ?? $item->approved_qty);
206: 
207:                 if ($shippedQty < 0 || $shippedQty > (float) $item->approved_qty) {
208:                     throw new BusinessException('الكمية المشحونة يجب أن تكون بين صفر والكمية المعتمدة.');
209:                 }
210: 
211:                 $qtyUpdates[] = [...$item->only(['id', 'stock_transfer_id', 'product_variant_id', 'from_location_id', 'to_location_id', 'requested_qty', 'approved_qty', 'shipped_qty', 'received_qty', 'created_at']), 'shipped_qty' => $shippedQty, 'updated_at' => now()];
212: 
213:                 if ($shippedQty <= 0) {
214:                     if ((float) $item->approved_qty > 0) {
215:                         $this->move([
216:                             'product_variant_id' => $item->product_variant_id,
217:                             'branch_id' => $transfer->from_branch_id,
218:                             'location_id' => $item->from_location_id,
219:                             'type' => StockMovementType::ReleaseReserve,
220:                             'affected_bucket' => StockBucket::Reserved,
221:                             'quantity' => -(float) $item->approved_qty,
222:                             'reference_type' => StockTransfer::class,
223:                             'reference_id' => $transfer->id,
224:                             'created_by' => $userId,
225:                             'notes' => 'فك حجز صنف غير مشحون من تحويل '.$transfer->transfer_number,
226:                         ], $levels);
227:                     }
228: 
229:                     continue;
230:                 }
231: 
232:                 $base = [
233:                     'product_variant_id' => $item->product_variant_id,
234:                     'unit_cost' => $item->variant?->cost_price,
235:                     'reference_type' => StockTransfer::class,
236:                     'reference_id' => $transfer->id,
237:                     'created_by' => $userId,
238:                 ];
239: 
240:                 // المرسل: فك الحجز ثم إخراج فعلي
241:                 $this->move([...$base,
242:                     'branch_id' => $transfer->from_branch_id,
243:                     'location_id' => $item->from_location_id,
244:                     'type' => StockMovementType::ReleaseReserve,
245:                     'affected_bucket' => StockBucket::Reserved,
246:                     'quantity' => -$shippedQty,
247:                     'notes' => 'فك حجز عند شحن تحويل '.$transfer->transfer_number,
248:                 ], $levels);
249:                 $this->move([...$base,
250:                     'branch_id' => $transfer->from_branch_id,
251:                     'location_id' => $item->from_location_id,
252:                     'type' => StockMovementType::TransferOut,
253:                     'affected_bucket' => StockBucket::OnHand,
254:                     'quantity' => -$shippedQty,
255:                     'notes' => 'شحن تحويل '.$transfer->transfer_number,
256:                 ], $levels);
257: 
258:                 // الباقي المحجوز (معتمد ولم يُشحن) يرجع متاحًا للبيع
259:                 $unshipped = round((float) $item->approved_qty - $shippedQty, 4);
260:                 if ($unshipped > 0) {
261:                     $this->move([...$base,
262:                         'branch_id' => $transfer->from_branch_id,
263:                         'location_id' => $item->from_location_id,
264:                         'type' => StockMovementType::ReleaseReserve,
265:                         'affected_bucket' => StockBucket::Reserved,
266:                         'quantity' => -$unshipped,
267:                         'notes' => 'فك حجز الكمية المعتمدة غير المشحونة من تحويل '.$transfer->transfer_number,
268:                     ], $levels);
269:                 }
270: 
271:                 // المستلم: بضاعة في الطريق
272:                 $this->move([...$base,
273:                     'branch_id' => $transfer->to_branch_id,
274:                     'location_id' => $item->to_location_id,
275:                     'type' => StockMovementType::TransferInTransit,
276:                     'affected_bucket' => StockBucket::InTransit,
277:                     'quantity' => $shippedQty,
278:                     'notes' => 'بضاعة في الطريق من تحويل '.$transfer->transfer_number,
279:                 ], $levels);
280:             }
281: 
282:             if ($qtyUpdates !== []) {
283:                 StockTransferItem::query()->upsert($qtyUpdates, ['id'], ['shipped_qty', 'updated_at']);
284:             }
285: 
286:             $transfer->update(['status' => TransferStatus::Shipped, 'shipped_at' => now()]);
287: 
288:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
289:         });
290:     }
291: 
292:     /** الاستلام: تسوية in_transit بالكامل، وإضافة المستلم فعليًا، وتسوية أي عجز كحركة مستقلة. */
293:     public function receive(StockTransfer $transfer, array $itemsPayload, int $userId, ?string $expectedUpdatedAt = null, ?int $expectedVersion = null): StockTransfer
294:     {
295:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId, $expectedUpdatedAt, $expectedVersion): StockTransfer {
296:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
297:             $transfer->load('items.variant');
298:             app(BranchAccess::class)->assertBranch($userId, $transfer->to_branch_id);
299:             if ($transfer->status === TransferStatus::Received) {
300:                 return $this->replayCompletedStage($transfer, $itemsPayload, 'received_qty');
301:             }
302:             $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, $expectedUpdatedAt, $expectedVersion);
303:             $this->assertStatus($transfer, TransferStatus::Shipped, 'الاستلام');
304:             $levels = $this->lockTransferLevels($transfer, false, true);
305: 
306:             $shortageNotes = [];
307:             $qtyUpdates = [];
308: 
309:             foreach ($transfer->items as $item) {
310:                 $receivedQty = (float) ($itemsPayload[$item->id] ?? $item->shipped_qty);
311:                 $shippedQty = (float) $item->shipped_qty;
312: 
313:                 if ($receivedQty < 0 || $receivedQty > $shippedQty) {
314:                     throw new BusinessException('الكمية المستلمة يجب أن تكون بين صفر والكمية المشحونة.');
315:                 }
316: 
317:                 $qtyUpdates[] = [...$item->only(['id', 'stock_transfer_id', 'product_variant_id', 'from_location_id', 'to_location_id', 'requested_qty', 'approved_qty', 'shipped_qty', 'received_qty', 'created_at']), 'received_qty' => $receivedQty, 'updated_at' => now()];
318: 
319:                 if ($shippedQty <= 0) {
320:                     continue;
321:                 }
322: 
323:                 $base = [
324:                     'product_variant_id' => $item->product_variant_id,
325:                     'branch_id' => $transfer->to_branch_id,
326:                     'location_id' => $item->to_location_id,
327:                     'unit_cost' => $item->variant?->cost_price,
328:                     'reference_type' => StockTransfer::class,
329:                     'reference_id' => $transfer->id,
330:                     'created_by' => $userId,
331:                 ];
332: 
333:                 // خروج الجزء المستلم من "في الطريق" ودخوله الرصيد الفعلي
334:                 if ($receivedQty > 0) {
335:                     $this->move([...$base,
336:                         'type' => StockMovementType::TransferTransitRelease,
337:                         'affected_bucket' => StockBucket::InTransit,
338:                         'quantity' => -$receivedQty,
339:                         'notes' => 'استلام تحويل '.$transfer->transfer_number,
340:                     ], $levels);
341:                     $this->move([...$base,
342:                         'type' => StockMovementType::TransferIn,
343:                         'affected_bucket' => StockBucket::OnHand,
344:                         'quantity' => $receivedQty,
345:                         'notes' => 'استلام تحويل '.$transfer->transfer_number,
346:                     ], $levels);
347:                 }
348: 
349:                 // العجز بين المشحون والمستلم: تسوية مستقلة موثقة من رصيد "في الطريق"
350:                 $shortage = round($shippedQty - $receivedQty, 4);
351:                 if ($shortage > 0) {
352:                     $this->move([...$base,
353:                         'type' => StockMovementType::TransferShortage,
354:                         'affected_bucket' => StockBucket::InTransit,
355:                         'quantity' => -$shortage,
356:                         'notes' => 'عجز عند استلام تحويل '.$transfer->transfer_number,
357:                     ], $levels);
358:                     $shortageNotes[] = "عجز {$shortage} وحدة في المتغير #{$item->product_variant_id}";
359:                 }
360:             }
361: 
362:             if ($qtyUpdates !== []) {
363:                 StockTransferItem::query()->upsert($qtyUpdates, ['id'], ['received_qty', 'updated_at']);
364:             }
365: 
366:             $notes = $transfer->notes;
367:             if ($shortageNotes !== []) {
368:                 $notes = trim(($notes ? $notes.' | ' : '').implode('؛ ', $shortageNotes));
369:             }
370: 
371:             $transfer->update(['status' => TransferStatus::Received, 'received_at' => now(), 'notes' => $notes]);
372: 
373:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
374:         });
375:     }
376: 
377:     /** الإلغاء: من المسودة مباشرة، ومن المعتمد بعد فك الحجز. المشحون لا يُلغى (يُستلم). */
378:     public function cancel(StockTransfer $transfer, int $userId): StockTransfer
379:     {
380:         return DB::transaction(function () use ($transfer, $userId): StockTransfer {
381:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
382:             $transfer->load('items.variant');
383:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
384: 
385:             if ($transfer->status === TransferStatus::Approved) {
386:                 $levels = $this->lockTransferLevels($transfer, true, false);
387:                 foreach ($transfer->items as $item) {
388:                     if ((float) $item->approved_qty <= 0) {
389:                         continue;
390:                     }
391: 
392:                     $this->move([
393:                         'product_variant_id' => $item->product_variant_id,
394:                         'branch_id' => $transfer->from_branch_id,
395:                         'location_id' => $item->from_location_id,
396:                         'type' => StockMovementType::ReleaseReserve,
397:                         'affected_bucket' => StockBucket::Reserved,
398:                         'quantity' => -(float) $item->approved_qty,
399:                         'reference_type' => StockTransfer::class,
400:                         'reference_id' => $transfer->id,
401:                         'created_by' => $userId,
402:                         'notes' => 'فك حجز عند إلغاء تحويل '.$transfer->transfer_number,
403:                     ], $levels);
404:                 }
405:             } elseif ($transfer->status !== TransferStatus::Draft) {
406:                 throw new BusinessException('لا يمكن إلغاء تحويل بحالة '.$transfer->status->value.'.');
407:             }
408: 
409:             $transfer->update(['status' => TransferStatus::Cancelled]);
410: 
411:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
412:         });
413:     }
414: 
415:     public function delete(StockTransfer $transfer, int $userId): void
416:     {
417:         DB::transaction(function () use ($transfer, $userId): void {
418:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
419:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
420: 
421:             if (! in_array($transfer->status, [TransferStatus::Draft, TransferStatus::Cancelled], true)) {
422:                 throw new BusinessException('لا يمكن حذف تحويل إلا في حالة المسودة أو الملغي.');
423:             }
424: 
425:             // تحويل اعتُمد ثم أُلغي له حركات دفتر (حجز/فك حجز) تشير إليه بلا FK؛
426:             // حذفه يترك مراجع يتيمة ويقطع أثر التدقيق — الإلغاء نفسه هو الحفظ الصحيح.
427:             if (StockMovement::query()->whereIn('reference_type', [StockTransfer::class, 'stock_transfer'])->where('reference_id', $transfer->id)->exists()) {
428:                 throw new BusinessException('لا يمكن حذف تحويل له حركات مخزون مسجلة في الدفتر؛ إلغاؤه يحفظ أثر التدقيق.');
429:             }
430: 
431:             $transfer->delete();
432:         });
433:     }
434: 
435:     /**
436:      * حماية من الحمولات القديمة: أي معرّف عنصر لا يتبع التحويل المقفول يُرفض بدل
437:      * تجاهله بصمت (التعديل بين تحقق الطلب والقفل كان يبدّل المعرّفات)، وطابع
438:      * expected_updated_at الاختياري يمنع اعتماد نسخة لم يراجعها المعتمد.
439:      */
440:     private function assertPayloadMatchesLockedItems(StockTransfer $transfer, array $itemsPayload, ?string $expectedUpdatedAt, ?int $expectedVersion = null): void
441:     {
442:         if ($expectedVersion !== null && $expectedVersion !== $transfer->version) {
443:             throw new BusinessException('تم تعديل التحويل؛ أعد تحميله وراجع الكميات.', ['current_version' => $transfer->version], 409);
444:         }
445: 
446:         $unknownIds = array_diff(array_map('intval', array_keys($itemsPayload)), $transfer->items->pluck('id')->map(fn ($id) => (int) $id)->all());
447: 
448:         if ($unknownIds !== []) {
449:             throw new BusinessException(
450:                 'توجد عناصر في الطلب لا تتبع هذا التحويل (المعرّفات: '.implode(', ', $unknownIds).'). أعد تحميل التحويل وراجع الكميات.',
451:                 ['unknown_item_ids' => array_values($unknownIds)],
452:                 409,
453:             );
454:         }
455: 
456:         if ($expectedUpdatedAt !== null
457:             && ! Carbon::parse($expectedUpdatedAt)->equalTo($transfer->updated_at)) {
458:             throw new BusinessException(
459:                 'تم تعديل هذا التحويل بعد تحميله. أعد تحميله وراجع الكميات قبل التنفيذ.',
460:                 ['current_updated_at' => $transfer->updated_at->toIso8601String()],
461:                 409,
462:             );
463:         }
464:     }
465: 
466:     private function replayCompletedStage(StockTransfer $transfer, array $itemsPayload, string $quantityField): StockTransfer
467:     {
468:         $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, null);
469:         foreach ($transfer->items as $item) {
470:             if (array_key_exists($item->id, $itemsPayload)
471:                 && (int) round((float) $itemsPayload[$item->id] * 10000) !== (int) round((float) $item->{$quantityField} * 10000)) {
472:                 throw new BusinessException('تم تنفيذ المرحلة بكميات مختلفة؛ أعد تحميل التحويل.', [], 409);
473:             }
474:         }
475: 
476:         return $transfer->load(['fromBranch', 'toBranch']);
477:     }
478: 
479:     private function assertStatus(StockTransfer $transfer, TransferStatus $expected, string $action): void
480:     {
481:         if ($transfer->status !== $expected) {
482:             throw new BusinessException("لا يمكن تنفيذ {$action} على تحويل بحالة {$transfer->status->value}.");
483:         }
484:     }
485: 
486:     /**
487:      * @param  list<array{product_variant_id: int, from_location_id?: int|null, to_location_id?: int|null, requested_qty: float|int|string}>  $items
488:      */
489:     private function syncItems(StockTransfer $transfer, array $items): void
490:     {
491:         $this->assertDistinctItems($items);
492:         foreach ($items as $item) {
493:             $transfer->items()->create([
494:                 'product_variant_id' => $item['product_variant_id'],
495:                 'from_location_id' => $item['from_location_id'] ?? null,
496:                 'to_location_id' => $item['to_location_id'] ?? null,
497:                 'requested_qty' => $item['requested_qty'],
498:             ]);
499:         }
500:     }
501: 
502:     private function assertDistinctItems(array $items): void
503:     {
504:         $keys = array_map(fn ($item) => $item['product_variant_id'].':'.($item['from_location_id'] ?? 0).':'.($item['to_location_id'] ?? 0), $items);
505:         if (count(array_unique($keys)) !== count($keys)) {
506:             throw new BusinessException('لا يجوز تكرار نفس الصنف وموقعي الإرسال والاستلام داخل التحويل.');
507:         }
508:     }
509: 
510:     /** حركة على صف مقفول مسبقًا ضمن $levels — بلا إعادة قفل أو فحص موقع. */
511:     private function move(array $data, Collection $levels): void
512:     {
513:         $level = $levels->get($this->inventory->levelKey([
514:             'product_variant_id' => $data['product_variant_id'],
515:             'branch_id' => $data['branch_id'],
516:             'location_id' => $data['location_id'] ?? null,
517:         ]));
518: 
519:         $this->inventory->recordMovement($data, $level);
520:     }
521: 
522:     private function lockTransferLevels(StockTransfer $transfer, bool $source, bool $destination): Collection
523:     {
524:         $keys = [];
525:         foreach ($transfer->items as $item) {
526:             if ($source) {
527:                 $keys[] = ['branch_id' => $transfer->from_branch_id, 'location_id' => $item->from_location_id, 'product_variant_id' => $item->product_variant_id];
528:             }
529:             if ($destination) {
530:                 $keys[] = ['branch_id' => $transfer->to_branch_id, 'location_id' => $item->to_location_id, 'product_variant_id' => $item->product_variant_id];
531:             }
532:         }
533: 
534:         return $this->inventory->lockLevels($keys);
535:     }
536: }

