 1: import { useEffect } from 'react';
 2: import { createApiClient, resolveServiceUrl } from '@alfarid/api-client';
 3: 
 4: // Only session presence crosses origins. Credentials stay in the backoffice.
 5: export default function SessionProbePage() {
 6:   useEffect(() => {
 7:     if (window.parent === window) return;
 8:     const origin = new URL(resolveServiceUrl(import.meta.env.VITE_WEB_URL ?? 'http://localhost:3000')).origin;
 9:     const nonce = new URLSearchParams(window.location.hash.slice(1)).get('nonce');
10:     if (!nonce) return;
11:     let disposed = false;
12:     let generation = 0;
13:     const check = async () => {
14:       const request = ++generation;
15:       const token = localStorage.getItem('backoffice_token');
16:       let authenticated = false;
17:       if (token) {
18:         try {
19:           await createApiClient({
20:             baseURL: resolveServiceUrl(import.meta.env.VITE_API_URL ?? 'http://localhost:8000'),
21:             getToken: () => token,
22:             onUnauthorized: () => {},
23:           }).get('/api/v1/admin/me', { timeout: 4000 });
24:           authenticated = localStorage.getItem('backoffice_token') === token;
25:         } catch { /* Expired or unavailable sessions never trigger a redirect. */ }
26:       }
27:       if (!disposed && request === generation) {
28:         window.parent.postMessage({ type: 'alfarid:staff-session', nonce, authenticated }, origin);
29:       }
30:     };
31:     const changed = (event: StorageEvent) => {
32:       if (event.storageArea === localStorage && (event.key === 'backoffice_token' || event.key === null)) void check();
33:     };
34:     window.addEventListener('storage', changed);
35:     void check();
36:     return () => { disposed = true; window.removeEventListener('storage', changed); };
37:   }, []);
38:   return null;
39: }

