  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Http\Controllers\Controller;
  9: use App\Http\Requests\Admin\Supplier\StoreSupplierUserRequest;
 10: use App\Http\Requests\Admin\Supplier\SupplierRequest;
 11: use App\Http\Requests\Admin\Supplier\UpdateSupplierUserRequest;
 12: use App\Http\Resources\Admin\SupplierResource;
 13: use App\Http\Resources\Admin\SupplierUserResource;
 14: use App\Models\Supplier;
 15: use App\Models\SupplierUser;
 16: use App\Services\SearchTerm;
 17: use App\Services\SupplierService;
 18: use Illuminate\Http\JsonResponse;
 19: use Illuminate\Http\Request;
 20: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 21: use Illuminate\Routing\Controllers\HasMiddleware;
 22: use Illuminate\Routing\Controllers\Middleware;
 23: use Illuminate\Support\Facades\DB;
 24: 
 25: /**
 26:  * إدارة الموردين وحسابات موظفيهم (بوابة المورد):
 27:  * الرصيد الجاري دفتري — يبدأ من الافتتاحي ثم يتحرك بالفواتير والدفعات فقط.
 28:  */
 29: class SupplierController extends Controller implements HasMiddleware
 30: {
 31:     public static function middleware(): array
 32:     {
 33:         return [
 34:             new Middleware('can:suppliers.view', only: ['index', 'show', 'users']),
 35:             new Middleware('can:suppliers.create', only: ['store', 'storeUser']),
 36:             new Middleware('can:suppliers.update', only: ['update', 'updateUser']),
 37:             new Middleware('can:suppliers.delete', only: ['destroy', 'destroyUser']),
 38:         ];
 39:     }
 40: 
 41:     public function __construct(protected SupplierService $suppliers) {}
 42: 
 43:     public function index(Request $request): AnonymousResourceCollection
 44:     {
 45:         $search = trim((string) $request->query('search', ''));
 46:         $suppliers = Supplier::query()
 47:             ->when($request->query('is_active') !== null, fn ($q) => $q->where('is_active', $request->boolean('is_active')))
 48:             ->when($search !== '', fn ($q) => $q->where(function ($w) use ($search): void {
 49:                 $pattern = SearchTerm::pattern($search);
 50:                 $w->where('name', 'ilike', $pattern)
 51:                     ->orWhere('code', 'ilike', $pattern)
 52:                     ->orWhere('company_name', 'ilike', $pattern);
 53:             }))
 54:             ->latest('id')
 55:             ->paginate(20);
 56: 
 57:         return SupplierResource::collection($suppliers);
 58:     }
 59: 
 60:     public function store(SupplierRequest $request): JsonResponse
 61:     {
 62:         $supplier = $this->suppliers->create($request->validated());
 63: 
 64:         return SupplierResource::make($supplier)->response()->setStatusCode(201);
 65:     }
 66: 
 67:     public function show(Supplier $supplier): SupplierResource
 68:     {
 69:         return SupplierResource::make($supplier->load('users'));
 70:     }
 71: 
 72:     public function update(SupplierRequest $request, Supplier $supplier): SupplierResource
 73:     {
 74:         return SupplierResource::make($this->suppliers->update($supplier, $request->validated()));
 75:     }
 76: 
 77:     public function destroy(Supplier $supplier): JsonResponse
 78:     {
 79:         DB::transaction(function () use ($supplier): void {
 80:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($supplier->id);
 81:             if ($supplier->purchaseOrders()->exists() || $supplier->invoices()->exists()
 82:                 || $supplier->payments()->exists() || $supplier->users()->exists()) {
 83:                 throw new BusinessException('لا يمكن حذف مورد له أوامر شراء أو فواتير أو دفعات أو حسابات مستخدمين؛ عطّله بدلًا من حذفه.');
 84:             }
 85:             $supplier->delete();
 86:         });
 87: 
 88:         return response()->json(['message' => 'تم حذف المورد.']);
 89:     }
 90: 
 91:     // ---------- حسابات موظفي المورد ----------
 92: 
 93:     public function users(Supplier $supplier): AnonymousResourceCollection
 94:     {
 95:         return SupplierUserResource::collection($supplier->users()->latest('id')->get());
 96:     }
 97: 
 98:     public function storeUser(StoreSupplierUserRequest $request, Supplier $supplier): JsonResponse
 99:     {
100:         $user = $supplier->users()->create($request->validated());
101: 
102:         return SupplierUserResource::make($user)->response()->setStatusCode(201);
103:     }
104: 
105:     public function updateUser(UpdateSupplierUserRequest $request, Supplier $supplier, SupplierUser $user): SupplierUserResource
106:     {
107:         abort_if((int) $user->supplier_id !== (int) $supplier->id, 404);
108:         $data = $request->validated();
109:         if (empty($data['password'])) {
110:             unset($data['password']);
111:         }
112:         $user = DB::transaction(function () use ($supplier, $user, $data): SupplierUser {
113:             $user = $supplier->users()->lockForUpdate()->findOrFail($user->id);
114:             $emailChanged = isset($data['email']) && $data['email'] !== $user->email;
115:             $user->update($data);
116:             if (isset($data['password']) || $emailChanged || (isset($data['is_active']) && ! $data['is_active'])) {
117:                 $user->tokens()->delete();
118:             }
119: 
120:             return $user;
121:         });
122: 
123:         return SupplierUserResource::make($user->fresh());
124:     }
125: 
126:     public function destroyUser(Supplier $supplier, SupplierUser $user): JsonResponse
127:     {
128:         abort_if((int) $user->supplier_id !== (int) $supplier->id, 404);
129:         $user->tokens()->delete();
130:         $user->delete();
131: 
132:         return response()->json(['message' => 'تم حذف حساب موظف المورد.']);
133:     }
134: }

