  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Events\StockLowDetected;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\InventoryIdempotencyKey;
 12: use App\Models\Location;
 13: use App\Models\ProductVariant;
 14: use App\Models\StockLevel;
 15: use App\Models\StockMovement;
 16: use Illuminate\Database\QueryException;
 17: use Illuminate\Database\UniqueConstraintViolationException;
 18: use Illuminate\Support\Collection;
 19: use Illuminate\Support\Facades\DB;
 20: 
 21: /**
 22:  * القلب النابض للمخزون — الطريق الوحيد لتغيير أي رصيد في النظام.
 23:  *
 24:  * قاعدة صارمة: ممنوع تعديل stock_levels من أي Controller أو Model آخر.
 25:  * كل تغيير يمر من هنا: تسجيل حركة في دفتر الأستاذ (stock_movements) أولًا،
 26:  * ثم تحديث الرصيد — داخل نفس الـ transaction ومع قفل الصف.
 27:  */
 28: class InventoryService
 29: {
 30:     public function __construct(private readonly SettingService $settings) {}
 31: 
 32:     /**
 33:      * الدالة المركزية الوحيدة لتغيير أي رصيد في النظام.
 34:      *
 35:      * @param  array{product_variant_id: int, branch_id: int, location_id?: int|null, type: StockMovementType|string, affected_bucket: StockBucket|string, quantity: float|int|string, unit_cost?: float|null, reference_type?: string|null, reference_id?: int|null, created_by?: int|null, notes?: string|null}  $data
 36:      */
 37:     public function recordMovement(array $data, ?StockLevel $prelockedLevel = null): StockMovement
 38:     {
 39:         $apply = function () use ($data, $prelockedLevel): StockMovement {
 40:             $rawQty = $data['quantity'];
 41:             if (! is_numeric($rawQty) || ! is_finite((float) $rawQty) || abs((float) $rawQty) > 99999999.9999) {
 42:                 throw new BusinessException('كمية الحركة غير صالحة.');
 43:             }
 44:             // Work in ten-thousandths to avoid floating point residues at zero.
 45:             $units = (int) round((float) $rawQty * 10000);
 46:             $qty = $units / 10000;
 47: 
 48:             if ($units === 0) {
 49:                 throw new BusinessException('كمية الحركة يجب ألا تساوي صفرًا.');
 50:             }
 51: 
 52:             $type = $data['type'] instanceof StockMovementType ? $data['type'] : StockMovementType::from($data['type']);
 53:             $bucket = $data['affected_bucket'] instanceof StockBucket ? $data['affected_bucket'] : StockBucket::from($data['affected_bucket']);
 54:             $this->assertValidMovementSemantics($type, $bucket, $units);
 55:             $locationId = $data['location_id'] ?? null;
 56: 
 57:             // صف مقفول مسبقًا من المستدعي (lockLevels): لا إعادة قفل ولا فحص موقع —
 58:             // المستدعي ضمن الصف والموقع عند القفل. خلاف ذلك نقفل هنا ونتحقق.
 59:             if ($prelockedLevel !== null) {
 60:                 if ((int) $prelockedLevel->product_variant_id !== (int) $data['product_variant_id']
 61:                     || (int) $prelockedLevel->branch_id !== (int) $data['branch_id']
 62:                     || ($prelockedLevel->location_id === null ? null : (int) $prelockedLevel->location_id) !== ($locationId === null ? null : (int) $locationId)) {
 63:                     throw new \LogicException('الصف المقفول مسبقًا لا يطابق مفتاح الحركة.');
 64:                 }
 65:                 $stock = $prelockedLevel;
 66:             } else {
 67:                 if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $data['branch_id'])->exists()) {
 68:                     throw new BusinessException('الموقع لا يتبع الفرع المحدد.');
 69:                 }
 70: 
 71:                 $stock = $this->lockLevels([[
 72:                     'product_variant_id' => $data['product_variant_id'],
 73:                     'branch_id' => $data['branch_id'],
 74:                     'location_id' => $locationId,
 75:                 ]])->first();
 76:             }
 77: 
 78:             if ($bucket === StockBucket::OnHand && $units > 0) {
 79:                 $variant = $stock->variant;
 80:                 if ($variant === null || $variant->trashed() || ! $variant->is_active
 81:                     || ($stock->location_id !== null && ! $stock->location?->is_active)) {
 82:                     throw new BusinessException('الإدخال يتطلب متغيرًا وموقعًا نشطين.');
 83:                 }
 84:             }
 85: 
 86:             $bucketKey = $bucket->value;
 87:             $before = (float) $stock->{$bucketKey};
 88:             $afterUnits = (int) round($before * 10000) + $units;
 89:             $after = $afterUnits / 10000;
 90:             if ($afterUnits > 999999999999) {
 91:                 throw new BusinessException('الرصيد يتجاوز الحد المسموح.');
 92:             }
 93: 
 94:             // 2. التحقق: الرصيد المستهدف لا ينزل تحت الصفر
 95:             if ($after < 0) {
 96:                 throw new BusinessException("الرصيد غير كافٍ في ({$bucketKey}) لإتمام العملية.");
 97:             }
 98: 
 99:             // 3. التحقق: الكمية المتاحة للبيع لا تصبح سالبة بعد الحركة
100:             //    (يغطي حجز/تالف جديد أكبر من المتاح، وسحب فعلي يبتلع محجوزًا أو تالفًا)
101:             $onHand = $bucket === StockBucket::OnHand ? $after : (float) $stock->on_hand;
102:             $reserved = $bucket === StockBucket::Reserved ? $after : (float) $stock->reserved;
103:             $damaged = $bucket === StockBucket::Damaged ? $after : (float) $stock->damaged;
104:             $availableAfter = (int) round($onHand * 10000) - (int) round($reserved * 10000) - (int) round($damaged * 10000);
105: 
106:             if ($availableAfter < 0) {
107:                 $availableNow = (float) $stock->on_hand - (float) $stock->reserved - (float) $stock->damaged;
108: 
109:                 throw new BusinessException("الكمية المتاحة للبيع ({$availableNow}) غير كافية لإتمام العملية.");
110:             }
111: 
112:             // منفّذ الحركة إلزامي: من console/queue بلا مستخدم مصادق وبلا created_by
113:             // صريح، الفشل الواضح أفضل من QueryException على قيد NOT NULL.
114:             $createdBy = $data['created_by'] ?? auth()->id();
115:             if ($createdBy === null) {
116:                 throw new \LogicException('recordMovement يتطلب created_by صريحًا عند غياب مستخدم مصادق.');
117:             }
118: 
119:             // مرجع الدفتر يُخزن بالاسم القصير من morph map إن وُجد (stock_transfer/stocktake)
120:             // حتى لا تكسر إعادة تسمية الكلاسات أثر التدقيق؛ الأسماء الكاملة القديمة تظل مقروءة.
121:             $referenceType = $data['reference_type'] ?? null;
122:             if (is_string($referenceType) && class_exists($referenceType)) {
123:                 $referenceType = (new $referenceType)->getMorphClass();
124:             }
125: 
126:             // 4. تسجيل الحركة في دفتر الأستاذ (Ledger)
127:             $movement = StockMovement::query()->create([
128:                 'reference_number' => $this->settings->generateNextNumber('movement'),
129:                 'product_variant_id' => $data['product_variant_id'],
130:                 'branch_id' => $data['branch_id'],
131:                 'location_id' => $locationId,
132:                 'type' => $type,
133:                 'affected_bucket' => $bucket,
134:                 'quantity' => $qty,
135:                 'balance_before' => $before,
136:                 'balance_after' => $after,
137:                 'unit_cost' => $data['unit_cost'] ?? null,
138:                 'reference_type' => $referenceType,
139:                 'reference_id' => $data['reference_id'] ?? null,
140:                 'created_by' => $createdBy,
141:                 'notes' => $data['notes'] ?? null,
142:             ]);
143: 
144:             // 5. تحديث جدول الأرصدة من واقع الحركة
145:             $stock->{$bucketKey} = $after;
146:             $stock->save();
147: 
148:             // 6. حدث انخفاض المخزون: فقط عند عبور حد إعادة الطلب الفعّال نزولًا
149:             //    (الحد الفعّال = حد صف الرصيد إن وُجد وإلا حد المتغير) حتى لا
150:             //    تتكرر التنبيهات مع كل حركة والرصيد تحت الحد أصلًا.
151:             // حد المتغير متاح بلا استعلام إضافي: lockLevels يحمّل العلاقة
152:             // جزئيًا بالأعمدة id/is_active/deleted_at/reorder_level.
153:             $level = (float) $stock->reorder_level;
154:             if ($level <= 0) {
155:                 $level = (float) ($stock->variant?->reorder_level ?? 0);
156:             }
157:             if ($level > 0) {
158:                 $effectOnAvailable = match ($bucket) {
159:                     StockBucket::OnHand => $units,
160:                     StockBucket::Reserved, StockBucket::Damaged => -$units,
161:                     default => 0,
162:                 };
163:                 $availableBeforeUnits = $availableAfter - $effectOnAvailable;
164:                 $availableAfterQty = $availableAfter / 10000;
165:                 if ($availableBeforeUnits / 10000 > $level && $availableAfterQty <= $level) {
166:                     StockLowDetected::dispatch(
167:                         (int) $stock->product_variant_id,
168:                         (int) $stock->branch_id,
169:                         $availableAfterQty,
170:                         $level,
171:                     );
172:                 }
173:             }
174: 
175:             return $movement;
176:         };
177: 
178:         if ($prelockedLevel !== null) {
179:             if (DB::transactionLevel() === 0) {
180:                 throw new \LogicException('Prelocked stock requires an active transaction.');
181:             }
182: 
183:             return $apply();
184:         }
185: 
186:         return DB::transaction($apply);
187:     }
188: 
189:     /**
190:      * تسوية يدوية متعددة العناصر داخل transaction واحدة (أي فشل يلغي الكل).
191:      *
192:      * مع مفتاح عدم تكرار (Idempotency-Key): يُدرج المفتاح داخل نفس الـ transaction،
193:      * فالتكرار المتزامن يصطدم بالقيد الفريد بعد commit الأول ويعيد الحركات المحفوظة،
194:      * ونفس المفتاح بحمولة مختلفة يُرفض 409، وفشل الطلب يلغي المفتاح معه.
195:      *
196:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
197:      * @return list<StockMovement>
198:      */
199:     public function applyAdjustments(array $payload, int $userId, ?string $idempotencyKey = null): array
200:     {
201:         app(BranchAccess::class)->assertBranch($userId, (int) $payload['branch_id']);
202:         if ($idempotencyKey === null) {
203:             return $this->executeAdjustments($payload, $userId);
204:         }
205: 
206:         $requestHash = IdempotencyFingerprint::hash($payload);
207: 
208:         try {
209:             return DB::transaction(function () use ($payload, $userId, $idempotencyKey, $requestHash): array {
210:                 $record = InventoryIdempotencyKey::query()->create([
211:                     'user_id' => $userId,
212:                     'key' => $idempotencyKey,
213:                     'request_hash' => $requestHash,
214:                 ]);
215: 
216:                 $movements = $this->executeAdjustments($payload, $userId);
217: 
218:                 $record->update([
219:                     'response' => array_map(fn (StockMovement $movement) => $movement->id, $movements),
220:                     'status_code' => 201,
221:                 ]);
222: 
223:                 return $movements;
224:             });
225:         } catch (UniqueConstraintViolationException $e) {
226:             // الالتقاط خاص بقيد مفتاح عدم التكرار وحده: أي انتهاك فريد آخر داخل
227:             // المعاملة خطأ حقيقي يجب أن يظهر، لا أن يُقنَّع كتعارض مفتاح (L-2).
228:             if (! str_contains($e->getMessage(), 'inventory_idempotency_keys_user_id_key_unique')) {
229:                 throw $e;
230:             }
231: 
232:             $record = InventoryIdempotencyKey::query()
233:                 ->where('user_id', $userId)->where('key', $idempotencyKey)->first();
234: 
235:             if ($record === null) {
236:                 throw new BusinessException('تعارض في مفتاح عدم التكرار؛ أعد المحاولة.', [], 409);
237:             }
238: 
239:             if (! hash_equals($record->request_hash, $requestHash)) {
240:                 throw new BusinessException('مفتاح عدم التكرار هذا مستخدم مسبقًا مع بيانات مختلفة.', [], 409);
241:             }
242: 
243:             $ids = $record->response ?? [];
244:             $byId = StockMovement::query()->whereIn('id', $ids)->get()->keyBy('id');
245: 
246:             return array_values(array_filter(array_map(fn ($id) => $byId->get($id), $ids)));
247:         }
248:     }
249: 
250:     /**
251:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
252:      * @return list<StockMovement>
253:      */
254:     private function executeAdjustments(array $payload, int $userId): array
255:     {
256:         return DB::transaction(function () use ($payload, $userId): array {
257:             app(BranchAccess::class)->assertBranch($userId, (int) $payload['branch_id']);
258: 
259:             // M5: التعطيل لا يحبس الرصيد — عمليات الإخراج (decrease/تالف/شطب) مسموحة على
260:             // متغير/موقع معطّل لتصفية رصيده، والإدخال (increase) وحده يتطلب النشاط.
261:             if (collect($payload['items'])->contains('adjustment_type', 'increase')) {
262:                 $variants = ProductVariant::query()->withTrashed()
263:                     ->whereIn('id', array_column($payload['items'], 'product_variant_id'))
264:                     ->get()->keyBy('id');
265:                 $location = ($payload['location_id'] ?? null) !== null ? Location::query()->find($payload['location_id']) : null;
266: 
267:                 foreach ($payload['items'] as $item) {
268:                     if ($item['adjustment_type'] !== 'increase') {
269:                         continue;
270:                     }
271:                     // المحذوف ناعمًا يعامل كمعطّل للإدخال، لكن إخراجه يظل مسموحًا
272:                     // حتى لا يُحبس رصيده للأبد (M-9).
273:                     $variant = $variants->get($item['product_variant_id']);
274:                     if ($variant === null || $variant->trashed() || ! $variant->is_active) {
275:                         throw new BusinessException('لا يمكن الإدخال على متغير معطّل؛ فعّله أولًا أو استخدم عمليات الإخراج لتصفية رصيده.');
276:                     }
277:                     if ($location !== null && ! $location->is_active) {
278:                         throw new BusinessException('لا يمكن الإدخال إلى موقع معطّل؛ فعّله أولًا.');
279:                     }
280:                 }
281:             }
282:             $levels = $this->lockLevels(array_map(fn ($item) => [
283:                 'product_variant_id' => $item['product_variant_id'],
284:                 'branch_id' => $payload['branch_id'],
285:                 'location_id' => $payload['location_id'] ?? null,
286:             ], $payload['items']));
287:             $movements = [];
288: 
289:             foreach ($payload['items'] as $item) {
290:                 // الصف مقفول مسبقًا أعلاه — تُمرَّر حركتا العنصر عليه مباشرة.
291:                 $level = $levels->get($this->levelKey([
292:                     'product_variant_id' => $item['product_variant_id'],
293:                     'branch_id' => $payload['branch_id'],
294:                     'location_id' => $payload['location_id'] ?? null,
295:                 ]));
296:                 if (in_array($item['adjustment_type'], ['write_off_damaged', 'restore_damaged'], true)) {
297:                     $base = [
298:                         'product_variant_id' => $item['product_variant_id'],
299:                         'branch_id' => $payload['branch_id'], 'location_id' => $payload['location_id'] ?? null,
300:                         'created_by' => $userId, 'notes' => $item['reason'] ?? null,
301:                         'quantity' => -abs((float) $item['quantity']),
302:                     ];
303:                     $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageRelease, 'affected_bucket' => StockBucket::Damaged], $level);
304:                     if ($item['adjustment_type'] === 'write_off_damaged') {
305:                         $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageWriteOff, 'affected_bucket' => StockBucket::OnHand], $level);
306:                     }
307: 
308:                     continue;
309:                 }
310:                 [$type, $bucket, $sign] = match ($item['adjustment_type']) {
311:                     'increase' => [StockMovementType::AdjustmentIn, StockBucket::OnHand, 1],
312:                     'decrease' => [StockMovementType::AdjustmentOut, StockBucket::OnHand, -1],
313:                     'mark_damaged' => [StockMovementType::Damage, StockBucket::Damaged, 1],
314:                     default => throw new BusinessException('نوع تسوية غير معروف: '.$item['adjustment_type']),
315:                 };
316: 
317:                 $movements[] = $this->recordMovement([
318:                     'product_variant_id' => $item['product_variant_id'],
319:                     'branch_id' => $payload['branch_id'],
320:                     'location_id' => $payload['location_id'] ?? null,
321:                     'type' => $type,
322:                     'affected_bucket' => $bucket,
323:                     'quantity' => $sign * abs((float) $item['quantity']),
324:                     'created_by' => $userId,
325:                     'notes' => $item['reason'] ?? null,
326:                 ], $level);
327:             }
328: 
329:             return $movements;
330:         });
331:     }
332: 
333:     /** الرصيد الحالي لمتغير في فرع/موقع (للقطات الجرد ونحوها) — قراءة فقط. */
334:     public function levelFor(int $variantId, int $branchId, ?int $locationId): ?StockLevel
335:     {
336:         return StockLevel::query()
337:             ->where('product_variant_id', $variantId)
338:             ->where('branch_id', $branchId)
339:             ->where('location_id', $locationId)
340:             ->first();
341:     }
342: 
343:     /** Acquire every stock key before a multi-item operation, in one global order. */
344:     public function lockLevels(array $keys): Collection
345:     {
346:         if (DB::transactionLevel() === 0) {
347:             throw new \LogicException('Stock locks require an active transaction.');
348:         }
349:         // انتظار محدود للأقفال داخل هذه المعاملة فقط؛ التنافس الطويل يتحول لرفض
350:         // واضح (409) بدل تعليق الطلب حتى مهلة PHP-FPM.
351:         DB::statement("SET LOCAL lock_timeout = '5s'");
352:         $keys = collect($keys)->unique(fn ($key) => $this->levelKey($key))
353:             ->sortBy(fn ($key) => [(int) $key['branch_id'], (int) ($key['location_id'] ?? 0), (int) $key['product_variant_id']]);
354:         if ($keys->isEmpty()) {
355:             return collect();
356:         }
357:         $now = now();
358: 
359:         try {
360:             // Lock variants before stock rows in every path, including callers
361:             // that prelock a batch of balances before recording movements.
362:             $variantIds = $keys->pluck('product_variant_id')->unique()->sort()->values();
363:             $variants = ProductVariant::withTrashed()->whereIn('id', $variantIds)->orderBy('id')->lockForUpdate()->get();
364:             if ($variants->count() !== $variantIds->count()) {
365:                 throw new BusinessException('أحد المتغيرات لم يعد متاحًا.');
366:             }
367: 
368:             // الإدخال نفسه قد ينتظر قفلًا: ON CONFLICT ينتظر معاملة أخرى أدخلت
369:             // نفس المفتاح ولم تعتمد بعد، فيخضع لنفس lock_timeout — لازم يكون
370:             // جوه الـ try حتى يتحول الانتظار الطويل لـ 409 لا 500 (M-2).
371:             DB::table('stock_levels')->insertOrIgnore($keys->map(fn ($key) => [
372:                 'product_variant_id' => $key['product_variant_id'], 'branch_id' => $key['branch_id'],
373:                 'location_id' => $key['location_id'] ?? null, 'created_at' => $now, 'updated_at' => $now,
374:             ])->values()->all());
375: 
376:             $levels = StockLevel::query()->with(['variant:id,is_active,deleted_at,reorder_level', 'location:id,is_active'])->where(function ($query) use ($keys): void {
377:                 foreach ($keys->groupBy(fn ($key) => $key['branch_id'].':'.($key['location_id'] ?? 0)) as $group) {
378:                     $identity = $group->first();
379:                     $query->orWhere(fn ($scope) => $scope->where('branch_id', $identity['branch_id'])
380:                         ->where('location_id', $identity['location_id'] ?? null)
381:                         ->whereIn('product_variant_id', $group->pluck('product_variant_id')->all()));
382:                 }
383:             })->orderBy('branch_id')->orderByRaw('location_id ASC NULLS FIRST')->orderBy('product_variant_id')
384:                 ->lockForUpdate()->get()->keyBy(fn ($stock) => $this->levelKey($stock->getAttributes()));
385:         } catch (QueryException $e) {
386:             // 55P03 = lock_timeout، و40P01 = deadlock — كلاهما ازدحام مؤقت
387:             // على الأقفال، فيُرجع 409 قابلًا لإعادة المحاولة لا 500 (M-2).
388:             if (in_array($e->errorInfo[0] ?? $e->getCode(), ['55P03', '40P01'], true)) {
389:                 throw new BusinessException('المخزون مشغول بعملية أخرى الآن؛ أعد المحاولة بعد لحظات.', [], 409);
390:             }
391: 
392:             throw $e;
393:         }
394: 
395:         return $levels;
396:     }
397: 
398:     public function levelKey(array $key): string
399:     {
400:         return $key['branch_id'].':'.($key['location_id'] ?? 0).':'.$key['product_variant_id'];
401:     }
402: 
403:     private function assertValidMovementSemantics(StockMovementType $type, StockBucket $bucket, int $units): void
404:     {
405:         [$allowed, $positive] = match ($type) {
406:             StockMovementType::ProductionReceipt, StockMovementType::PurchaseReceipt, StockMovementType::SaleReturn,
407:             StockMovementType::AdjustmentIn, StockMovementType::StocktakeGain, StockMovementType::TransferIn => [[StockBucket::OnHand], true],
408:             StockMovementType::Sale, StockMovementType::AdjustmentOut,
409:             StockMovementType::StocktakeLoss, StockMovementType::TransferOut,
410:             StockMovementType::DamageWriteOff => [[StockBucket::OnHand], false],
411:             StockMovementType::Damage => [[StockBucket::Damaged], true],
412:             StockMovementType::DamageRelease => [[StockBucket::Damaged], false],
413:             StockMovementType::Reserve => [[StockBucket::Reserved], true],
414:             StockMovementType::ReleaseReserve => [[StockBucket::Reserved], false],
415:             StockMovementType::TransferInTransit => [[StockBucket::InTransit], true],
416:             StockMovementType::TransferTransitRelease, StockMovementType::TransferShortage => [[StockBucket::InTransit], false],
417:         };
418:         if (! in_array($bucket, $allowed, true) || ($units > 0) !== $positive) {
419:             throw new BusinessException('نوع الحركة لا يطابق وعاء المخزون أو اتجاه الكمية.');
420:         }
421:     }
422: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\PurchaseOrderStatus;
  8: use App\Enums\SupplierInvoiceStatus;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\PurchaseOrder;
 11: use App\Models\Supplier;
 12: use App\Models\SupplierInvoice;
 13: use App\Models\SupplierPayment;
 14: use App\Models\User;
 15: use Carbon\Carbon;
 16: use Illuminate\Http\UploadedFile;
 17: use Illuminate\Support\Facades\DB;
 18: use Illuminate\Support\Facades\Storage;
 19: 
 20: /**
 21:  * مالية الموردين — دفتر المورد الدائن:
 22:  * - اعتماد فاتورة (post) يزيد suppliers.current_balance بقيمة total_amount.
 23:  * - دفعة تنقص الرصيد وتحدّث paid_amount وحالة فاتورتها المرتبطة.
 24:  * - حذف دفعة/إلغاء فاتورة معتمدة يعكس الأثر بالكامل.
 25:  * كل حركة تحت قفل صف المورد حتى لا تتسابق فاتورة ودفعة على نفس الرصيد.
 26:  */
 27: class SupplierFinanceService
 28: {
 29:     public function __construct(protected SettingService $settings) {}
 30: 
 31:     /**
 32:      * @param  array{supplier_id: int, purchase_order_id?: int|null, supplier_invoice_no: string, issue_date: string, due_date?: string|null, subtotal: float|int|string, tax_amount?: float|int|string|null}  $data
 33:      */
 34:     public function createInvoice(array $data, ?UploadedFile $attachment = null): SupplierInvoice
 35:     {
 36:         $invoice = PrivateAttachments::transaction(function (PrivateAttachments $files) use ($data, $attachment): SupplierInvoice {
 37:             $supplier = Supplier::query()->lockForUpdate()->findOrFail((int) $data['supplier_id']);
 38:             if (! $supplier->is_active) {
 39:                 throw new BusinessException('المورد غير نشط.');
 40:             }
 41:             $this->assertInvoiceNumberAvailable($supplier->id, $data['supplier_invoice_no']);
 42:             $poId = $this->assertOrderBelongsToSupplier($data['purchase_order_id'] ?? null, $supplier);
 43:             $subtotal = round((float) $data['subtotal'], 2);
 44:             $tax = round((float) ($data['tax_amount'] ?? 0), 2);
 45:             $this->assertInvoiceDoesNotExceedOrder($poId, round($subtotal + $tax, 2));
 46:             $issueDate = Carbon::parse($data['issue_date']);
 47:             // الاستحقاق الافتراضي: تاريخ الإصدار + أجل سداد المورد
 48:             $dueDate = ! empty($data['due_date'])
 49:                 ? Carbon::parse($data['due_date'])
 50:                 : $issueDate->copy()->addDays((int) $supplier->payment_terms_days);
 51: 
 52:             if ($dueDate->lt($issueDate)) {
 53:                 throw new BusinessException('تاريخ الاستحقاق يجب ألا يسبق تاريخ الإصدار.');
 54:             }
 55:             $invoice = SupplierInvoice::create([
 56:                 'invoice_number' => $this->settings->generateNextNumber('supplier_invoice'),
 57:                 'supplier_invoice_no' => $data['supplier_invoice_no'],
 58:                 'supplier_id' => $supplier->id,
 59:                 'purchase_order_id' => $poId,
 60:                 'issue_date' => $issueDate->toDateString(),
 61:                 'due_date' => $dueDate->toDateString(),
 62:                 'subtotal' => $subtotal,
 63:                 'tax_amount' => $tax,
 64:                 'total_amount' => round($subtotal + $tax, 2),
 65:                 'paid_amount' => 0,
 66:                 'status' => SupplierInvoiceStatus::Draft,
 67:             ]);
 68:             if ($attachment !== null) {
 69:                 $invoice->update(['attachment_path' => $files->store($attachment, "supplier_invoices/{$invoice->id}")]);
 70:             }
 71: 
 72:             return $invoice;
 73:         });
 74: 
 75:         return $invoice->fresh();
 76:     }
 77: 
 78:     /**
 79:      * @param  array{supplier_invoice_no?: string, purchase_order_id?: int|null, issue_date?: string, due_date?: string|null, subtotal?: float|int|string, tax_amount?: float|int|string|null}  $data
 80:      */
 81:     public function updateInvoice(SupplierInvoice $invoice, array $data, ?UploadedFile $attachment = null): SupplierInvoice
 82:     {
 83:         $invoice = PrivateAttachments::transaction(function (PrivateAttachments $files) use ($invoice, $data, $attachment): SupplierInvoice {
 84:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($invoice->supplier_id);
 85:             $invoice = SupplierInvoice::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($invoice->id);
 86:             if ($invoice->status !== SupplierInvoiceStatus::Draft) {
 87:                 throw new BusinessException('لا يمكن تعديل فاتورة مورد إلا وهي مسودة.');
 88:             }
 89:             if (array_key_exists('purchase_order_id', $data)) {
 90:                 $data['purchase_order_id'] = $this->assertOrderBelongsToSupplier(
 91:                     $data['purchase_order_id'],
 92:                     $invoice->supplier()->firstOrFail(),
 93:                 );
 94:             }
 95:             $this->assertInvoiceNumberAvailable($supplier->id, $data['supplier_invoice_no'] ?? $invoice->supplier_invoice_no, $invoice->id);
 96:             $issue = Carbon::parse($data['issue_date'] ?? $invoice->issue_date);
 97:             if (array_key_exists('due_date', $data) && $data['due_date'] === null) {
 98:                 $data['due_date'] = $issue->copy()->addDays((int) $supplier->payment_terms_days)->toDateString();
 99:             }
100:             if (Carbon::parse($data['due_date'] ?? $invoice->due_date)->lt($issue)) {
101:                 throw new BusinessException('تاريخ الاستحقاق يجب ألا يسبق تاريخ الإصدار.');
102:             }
103:             $updates = array_intersect_key($data, array_flip([
104:                 'supplier_invoice_no', 'purchase_order_id', 'issue_date', 'due_date', 'subtotal', 'tax_amount',
105:             ]));
106:             $subtotal = round((float) ($updates['subtotal'] ?? $invoice->subtotal), 2);
107:             $tax = round((float) ($updates['tax_amount'] ?? $invoice->tax_amount), 2);
108:             $updates['subtotal'] = $subtotal;
109:             $updates['tax_amount'] = $tax;
110:             $updates['total_amount'] = round($subtotal + $tax, 2);
111:             $poId = array_key_exists('purchase_order_id', $updates) ? $updates['purchase_order_id'] : $invoice->purchase_order_id;
112:             $this->assertInvoiceDoesNotExceedOrder($poId, $updates['total_amount'], $invoice->id);
113:             $invoice->update($updates);
114: 
115:             if ($attachment !== null) {
116:                 $oldPath = $invoice->attachment_path;
117:                 $invoice->update(['attachment_path' => $files->store($attachment, "supplier_invoices/{$invoice->id}")]);
118:                 if ($oldPath) {
119:                     DB::afterCommit(fn () => Storage::disk('r2')->delete($oldPath));
120:                 }
121:             }
122: 
123:             return $invoice;
124:         });
125: 
126:         return $invoice->fresh();
127:     }
