129:     /** اعتماد الفاتورة: تُثبت الاستحقاق في رصيد المورد الدائن. */
130:     public function postInvoice(SupplierInvoice $invoice): SupplierInvoice
131:     {
132:         return DB::transaction(function () use ($invoice): SupplierInvoice {
133:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($invoice->supplier_id);
134:             $invoice = SupplierInvoice::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($invoice->id);
135:             if ($invoice->status !== SupplierInvoiceStatus::Draft) {
136:                 throw new BusinessException('لا يمكن اعتماد فاتورة إلا وهي مسودة.');
137:             }
138:             $supplier->increment('current_balance', (float) $invoice->total_amount);
139:             $invoice->update(['status' => SupplierInvoiceStatus::Posted]);
140: 
141:             return $invoice->fresh();
142:         });
143:     }
144: 
145:     /** إلغاء فاتورة: المسودة بلا أثر؛ والمعتمدة غير المسددة تعكس رصيدها. */
146:     public function cancelInvoice(SupplierInvoice $invoice): SupplierInvoice
147:     {
148:         return DB::transaction(function () use ($invoice): SupplierInvoice {
149:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($invoice->supplier_id);
150:             $invoice = SupplierInvoice::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($invoice->id);
151:             if ($invoice->status === SupplierInvoiceStatus::Draft) {
152:                 $invoice->update(['status' => SupplierInvoiceStatus::Cancelled]);
153: 
154:                 return $invoice->fresh();
155:             }
156:             if ($invoice->status === SupplierInvoiceStatus::Posted && (float) $invoice->paid_amount <= 0) {
157:                 $supplier->decrement('current_balance', (float) $invoice->total_amount);
158:                 $invoice->update(['status' => SupplierInvoiceStatus::Cancelled]);
159: 
160:                 return $invoice->fresh();
161:             }
162: 
163:             throw new BusinessException('لا يمكن إلغاء فاتورة بدأ سدادها؛ عالِج دفعاتها أولًا.');
164:         });
165:     }
