167:     public function deleteInvoice(SupplierInvoice $invoice): void
168:     {
169:         DB::transaction(function () use ($invoice): void {
170:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($invoice->supplier_id);
171:             $invoice = SupplierInvoice::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($invoice->id);
172:             if ($invoice->status !== SupplierInvoiceStatus::Draft) {
173:                 throw new BusinessException('يمكن حذف الفواتير المسودة فقط؛ يحتفظ بالسجلات الأخرى للتدقيق.');
