183:     /**
184:      * تسجيل دفعة لمورد: تخفض رصيده، وتُسند لفاتورة معتمدة عند ربطها
185:      * (بسقف المتبقي منها) فتتحدث paid_amount وحالتها.
186:      *
187:      * @param  array{supplier_id: int, supplier_invoice_id?: int|null, amount: float|int|string, payment_method: string, reference_no?: string|null, payment_date: string, notes?: string|null}  $data
188:      */
189:     public function createPayment(array $data, User $creator, ?string $idempotencyKey = null): SupplierPayment
190:     {
191:         return app(OperationIdempotencyService::class)->run('supplier_payment', $creator, $idempotencyKey, $data,
192:             fn () => $this->executePayment($data, $creator, hash('sha256', $creator->id.':'.$idempotencyKey)));
193:     }
194: 
195:     private function executePayment(array $data, User $creator, string $idempotencyKey): SupplierPayment
196:     {
197:         return DB::transaction(function () use ($data, $creator, $idempotencyKey): SupplierPayment {
198:             $supplier = Supplier::query()->lockForUpdate()->findOrFail((int) $data['supplier_id']);
199:             $amount = round((float) $data['amount'], 2);
200:             if ($amount <= 0 || $amount > 9999999999.99) {
201:                 throw new BusinessException('مبلغ الدفعة يجب أن يكون أكبر من صفر.');
202:             }
203: 
204:             $invoice = null;
205:             if (! empty($data['supplier_invoice_id'])) {
206:                 $invoice = SupplierInvoice::query()->lockForUpdate()
207:                     ->where('supplier_id', $supplier->id)
208:                     ->find((int) $data['supplier_invoice_id']);
209:                 if ($invoice === null) {
210:                     throw new BusinessException('الفاتورة المرتبطة غير موجودة لهذا المورد.');
211:                 }
212:                 if (! in_array($invoice->status, [SupplierInvoiceStatus::Posted, SupplierInvoiceStatus::PartiallyPaid], true)) {
213:                     throw new BusinessException('لا يمكن سداد فاتورة إلا وهي معتمدة أو مسددة جزئيًا.');
214:                 }
215:                 $remaining = round((float) $invoice->total_amount - (float) $invoice->paid_amount, 2);
216:                 if ($amount > $remaining) {
217:                     throw new BusinessException("مبلغ الدفعة ({$amount}) أكبر من المتبقي على الفاتورة ({$remaining}).");
218:                 }
219:             }
220: 
221:             $reference = $this->paymentReference($supplier->id, $data['payment_method'], $data['reference_no'] ?? null);
222:             $payment = SupplierPayment::create([
223:                 'payment_number' => $this->settings->generateNextNumber('supplier_payment'),
224:                 'idempotency_key' => $idempotencyKey,
225:                 'supplier_id' => $supplier->id,
226:                 'supplier_invoice_id' => $invoice?->id,
227:                 'amount' => $amount,
228:                 'payment_method' => $data['payment_method'],
229:                 'reference_no' => $reference,
230:                 'payment_date' => $data['payment_date'],
231:                 'notes' => $data['notes'] ?? null,
232:                 'created_by' => $creator->id,
233:             ]);
234: 
235:             $supplier->decrement('current_balance', $amount);
236:             if ($invoice !== null) {
237:                 $invoice->increment('paid_amount', $amount);
238:                 $this->syncInvoicePaidStatus($invoice->fresh());
239:             }
240: 
241:             return $payment->fresh();
242:         });
243:     }
244: 
245:     public function updatePayment(SupplierPayment $payment, array $data): SupplierPayment
246:     {
247:         return DB::transaction(function () use ($payment, $data): SupplierPayment {
248:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($payment->supplier_id);
249:             $payment = SupplierPayment::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($payment->id);
250:             if ($payment->voided_at !== null) {
251:                 throw new BusinessException('لا يمكن تعديل دفعة ملغاة.');
252:             }
253:             $method = $data['payment_method'] ?? $payment->payment_method->value;
254:             $reference = array_key_exists('reference_no', $data) ? $data['reference_no'] : $payment->reference_no;
255:             $data['reference_no'] = $this->paymentReference($supplier->id, $method, $reference, $payment->id);
256:             $payment->update(array_intersect_key($data, array_flip(['payment_method', 'reference_no', 'notes'])));
257: 
258:             return $payment->fresh();
259:         });
260:     }
261: 
262:     private function paymentReference(int $supplierId, string $method, ?string $reference, ?int $exceptId = null): ?string
263:     {
264:         $reference = $reference !== null ? trim($reference) : null;
265:         if ($method !== 'cash' && ($reference === null || $reference === '')) {
266:             throw new BusinessException('مرجع الدفع مطلوب للدفعات غير النقدية.');
267:         }
268:         if ($method !== 'cash' && SupplierPayment::query()->where('supplier_id', $supplierId)
269:             ->whereNull('voided_at')
270:             ->where('payment_method', '!=', 'cash')->when($exceptId, fn ($q) => $q->where('id', '!=', $exceptId))
271:             ->whereRaw('lower(btrim(reference_no)) = ?', [mb_strtolower($reference)])->exists()) {
272:             throw new BusinessException('مرجع الدفع مسجل سابقًا لهذا المورد.', [], 409);
273:         }
274: 
275:         return $reference;
276:     }
277: 
278:     /** إلغاء دفعة يعكس أثرها كاملًا: رصيد المورد ومدفوعات فاتورتها، ويبقى السجل للتدقيق. */
279:     public function deletePayment(SupplierPayment $payment, ?User $actor = null, ?string $reason = null): void
280:     {
281:         $this->voidPayment($payment, $actor, $reason);
282:     }
283: 
284:     public function voidPayment(SupplierPayment $payment, ?User $actor = null, ?string $reason = null): SupplierPayment
285:     {
286:         return DB::transaction(function () use ($payment, $actor, $reason): SupplierPayment {
287:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($payment->supplier_id);
288:             $payment = SupplierPayment::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($payment->id);
289:             if ($payment->voided_at !== null) {
290:                 throw new BusinessException('هذه الدفعة ملغاة سابقًا.');
291:             }
292:             $supplier->increment('current_balance', (float) $payment->amount);
293: 
294:             if ($payment->supplier_invoice_id !== null) {
295:                 $invoice = SupplierInvoice::query()->lockForUpdate()->find($payment->supplier_invoice_id);
296:                 if ($invoice !== null && $invoice->status !== SupplierInvoiceStatus::Cancelled) {
297:                     $invoice->decrement('paid_amount', (float) $payment->amount);
298:                     $this->syncInvoicePaidStatus($invoice->fresh());
299:                 }
300:             }
301:             $payment->update([
302:                 'voided_at' => now(),
303:                 'voided_by' => $actor?->id,
304:                 'void_reason' => $reason,
305:             ]);
306: 
307:             return $payment->fresh();
308:         });
309:     }
