311:     public function allocatePayment(SupplierPayment $payment, int $invoiceId): SupplierPayment
312:     {
313:         return DB::transaction(function () use ($payment, $invoiceId): SupplierPayment {
314:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($payment->supplier_id);
315:             $payment = SupplierPayment::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($payment->id);
316:             if ($payment->voided_at !== null) {
317:                 throw new BusinessException('لا يمكن تخصيص دفعة ملغاة.');
318:             }
319:             if ($payment->supplier_invoice_id !== null) {
320:                 throw new BusinessException('هذه الدفعة مخصصة لفاتورة بالفعل.');
321:             }
322:             $invoice = SupplierInvoice::query()->lockForUpdate()
323:                 ->where('supplier_id', $supplier->id)
324:                 ->find($invoiceId);
325:             if ($invoice === null) {
326:                 throw new BusinessException('الفاتورة المرتبطة غير موجودة لهذا المورد.');
327:             }
328:             if (! in_array($invoice->status, [SupplierInvoiceStatus::Posted, SupplierInvoiceStatus::PartiallyPaid], true)) {
329:                 throw new BusinessException('لا يمكن تخصيص دفعة إلا لفاتورة معتمدة أو مسددة جزئيًا.');
330:             }
331:             $remaining = round((float) $invoice->total_amount - (float) $invoice->paid_amount, 2);
332:             if ((float) $payment->amount > $remaining) {
333:                 throw new BusinessException("مبلغ الدفعة ({$payment->amount}) أكبر من المتبقي على الفاتورة ({$remaining}).");
334:             }
335:             $payment->update(['supplier_invoice_id' => $invoice->id]);
336:             $invoice->increment('paid_amount', (float) $payment->amount);
337:             $this->syncInvoicePaidStatus($invoice->fresh());
338: 
339:             return $payment->fresh();
340:         });
341:     }
342: 
343:     /** حالة الفاتورة من مدفوعاتها: صفر ← posted، جزئي ← partially_paid، كامل ← paid. */
344:     private function syncInvoicePaidStatus(SupplierInvoice $invoice): void
345:     {
346:         if ($invoice->status === SupplierInvoiceStatus::Draft
347:             || $invoice->status === SupplierInvoiceStatus::Cancelled) {
348:             return;
349:         }
350:         $paid = round((float) $invoice->paid_amount, 2);
351:         $total = round((float) $invoice->total_amount, 2);
352:         $invoice->update(['status' => match (true) {
353:             $paid >= $total => SupplierInvoiceStatus::Paid,
354:             $paid > 0 => SupplierInvoiceStatus::PartiallyPaid,
355:             default => SupplierInvoiceStatus::Posted,
356:         }]);
357:     }
358: 
359:     private function assertInvoiceNumberAvailable(int $supplierId, string $number, ?int $exceptId = null): void
360:     {
361:         if (SupplierInvoice::query()->where('supplier_id', $supplierId)->where('status', '!=', SupplierInvoiceStatus::Cancelled)
362:             ->when($exceptId, fn ($q) => $q->where('id', '!=', $exceptId))
363:             ->whereRaw('lower(btrim(supplier_invoice_no)) = ?', [mb_strtolower(trim($number))])->exists()) {
364:             throw new BusinessException('رقم فاتورة المورد مسجل سابقًا.', [], 409);
365:         }
366:     }
367: 
368:     private function assertOrderBelongsToSupplier(mixed $poId, Supplier $supplier): ?int
369:     {
370:         if ($poId === null || $poId === '') {
371:             return null;
372:         }
373:         $po = PurchaseOrder::query()->find((int) $poId);
374:         if ($po === null || (int) $po->supplier_id !== (int) $supplier->id) {
375:             throw new BusinessException('أمر الشراء المرتبط لا يخص هذا المورد.');
376:         }
377:         if ($po->status === PurchaseOrderStatus::Cancelled) {
378:             throw new BusinessException('لا يمكن ربط فاتورة بأمر شراء ملغى.');
379:         }
380: 
381:         return $po->id;
382:     }
383: 
384:     private function assertInvoiceDoesNotExceedOrder(?int $poId, float $thisTotal, ?int $exceptInvoiceId = null): void
385:     {
386:         if ($poId === null) {
387:             return;
388:         }
389:         $po = PurchaseOrder::query()->find($poId);
390:         if ($po === null) {
391:             return;
392:         }
393:         $existing = (float) SupplierInvoice::query()
394:             ->where('purchase_order_id', $poId)
395:             ->where('status', '!=', SupplierInvoiceStatus::Cancelled)
396:             ->when($exceptInvoiceId, fn ($q) => $q->where('id', '!=', $exceptInvoiceId))
397:             ->sum('total_amount');
398:         if (round($existing + $thisTotal, 2) > round((float) $po->grand_total, 2)) {
399:             throw new BusinessException('مجموع فواتير أمر الشراء يتجاوز إجمالي الأمر.');
400:         }
401:     }
402: 
403:     /**
404:      * كشف حساب المورد (Ledger) لفترة: رصيد افتتاحي محسوب من كل الحركات
405:      * قبل الفترة، ثم حركات الفترة بترتيب زمني مع رصيد تراكمي متحرك:
406:      * الفواتير المعتمدة Credit (+) والدفعات Debit (−).
407:      *
408:      * @return array<string, mixed>
409:      */
410:     public function statement(Supplier $supplier, ?string $fromDate = null, ?string $toDate = null): array
411:     {
412:         $to = $toDate !== null ? Carbon::parse($toDate)->toDateString() : now()->toDateString();
413:         $from = $fromDate !== null ? Carbon::parse($fromDate)->toDateString() : Carbon::parse($to)->subDays(365)->toDateString();
414:         if (Carbon::parse($from)->gt(Carbon::parse($to)) || Carbon::parse($from)->diffInDays(Carbon::parse($to)) > 366) {
415:             throw new BusinessException('فترة كشف الحساب يجب ألا تتجاوز 366 يومًا وبترتيب زمني صحيح.');
416:         }
417:         $countedStatuses = [
418:             SupplierInvoiceStatus::Posted->value,
419:             SupplierInvoiceStatus::PartiallyPaid->value,
420:             SupplierInvoiceStatus::Paid->value,
421:         ];
422: 
423:         $creditBefore = (float) SupplierInvoice::query()
424:             ->where('supplier_id', $supplier->id)
425:             ->whereIn('status', $countedStatuses)
426:             ->where('issue_date', '<', $from)
427:             ->sum('total_amount');
428:         $debitBefore = (float) SupplierPayment::query()
429:             ->where('supplier_id', $supplier->id)
430:             ->where('payment_date', '<', $from)
431:             ->sum('amount');
432:         $voidCreditBefore = (float) SupplierPayment::query()
433:             ->where('supplier_id', $supplier->id)
434:             ->whereNotNull('voided_at')
435:             ->whereDate('voided_at', '<', $from)
436:             ->sum('amount');
437:         $running = round((float) $supplier->opening_balance + $creditBefore - $debitBefore + $voidCreditBefore, 2);
438:         $periodOpening = $running;
439: 
440:         $invoices = SupplierInvoice::query()
441:             ->with('purchaseOrder:id,po_number')
442:             ->where('supplier_id', $supplier->id)
443:             ->whereIn('status', $countedStatuses)
444:             ->whereBetween('issue_date', [$from, $to])
445:             ->get()
446:             ->map(fn (SupplierInvoice $inv): array => [
447:                 'date' => $inv->issue_date->toDateString(),
448:                 'type' => 'invoice',
449:                 'reference' => $inv->invoice_number,
450:                 'description' => 'فاتورة مورد '.$inv->supplier_invoice_no.($inv->purchaseOrder !== null ? ' — أمر شراء '.$inv->purchaseOrder->po_number : ''),
451:                 'credit' => round((float) $inv->total_amount, 2),
452:                 'debit' => 0.0,
453:                 'sort' => [$inv->issue_date->toDateString(), 0, $inv->id],
454:             ]);
455:         $payments = SupplierPayment::query()
456:             ->with('invoice:id,invoice_number')
457:             ->where('supplier_id', $supplier->id)
458:             ->whereBetween('payment_date', [$from, $to])
459:             ->get()
460:             ->map(fn (SupplierPayment $pay): array => [
461:                 'date' => $pay->payment_date->toDateString(),
462:                 'type' => 'payment',
463:                 'reference' => $pay->payment_number,
464:                 'description' => 'دفعة للمورد'.($pay->invoice !== null ? ' — سداد فاتورة '.$pay->invoice->invoice_number : ''),
465:                 'credit' => 0.0,
466:                 'debit' => round((float) $pay->amount, 2),
467:                 'sort' => [$pay->payment_date->toDateString(), 1, $pay->id],
468:             ]);
469:         $voids = SupplierPayment::query()
470:             ->where('supplier_id', $supplier->id)
471:             ->whereNotNull('voided_at')
472:             ->whereDate('voided_at', '>=', $from)
473:             ->whereDate('voided_at', '<=', $to)
474:             ->get()
475:             ->map(fn (SupplierPayment $pay): array => [
476:                 'date' => $pay->voided_at->toDateString(),
477:                 'type' => 'payment_void',
478:                 'reference' => $pay->payment_number,
479:                 'description' => 'إلغاء دفعة '.$pay->payment_number.($pay->void_reason ? ' — '.$pay->void_reason : ''),
480:                 'credit' => round((float) $pay->amount, 2),
481:                 'debit' => 0.0,
482:                 'sort' => [$pay->voided_at->toDateString(), 2, $pay->id],
483:             ]);
484: 
485:         $entries = [];
486:         $totalCredit = 0.0;
487:         $totalDebit = 0.0;
488:         foreach ($invoices->concat($payments)->concat($voids)->sortBy(fn (array $e): array => $e['sort'])->values() as $entry) {
489:             $running = round($running + $entry['credit'] - $entry['debit'], 2);
490:             $totalCredit += $entry['credit'];
491:             $totalDebit += $entry['debit'];
492:             unset($entry['sort']);
493:             $entry['running_balance'] = $running;
494:             $entries[] = $entry;
495:         }
496: 
497:         return [
498:             'supplier' => [
499:                 'id' => $supplier->id,
500:                 'code' => $supplier->code,
501:                 'name' => $supplier->name,
502:                 'current_balance' => $supplier->current_balance,
503:             ],
504:             'from_date' => $from,
505:             'to_date' => $to,
506:             'opening_balance' => $periodOpening,
507:             'entries' => $entries,
508:             'total_credit' => round($totalCredit, 2),
509:             'total_debit' => round($totalDebit, 2),
510:             'closing_balance' => $running,
511:         ];
512:     }
513: }

