  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\PurchaseOrderStatus;
  8: use App\Enums\PurchaseRequestStatus;
  9: use App\Enums\StockBucket;
 10: use App\Enums\StockMovementType;
 11: use App\Enums\SupplierDeliveryStatus;
 12: use App\Events\PurchaseOrderSentToSupplier;
 13: use App\Exceptions\BusinessException;
 14: use App\Models\Branch;
 15: use App\Models\ProductVariant;
 16: use App\Models\PurchaseOrder;
 17: use App\Models\PurchaseOrderItem;
 18: use App\Models\PurchaseRequest;
 19: use App\Models\StockLevel;
 20: use App\Models\Supplier;
 21: use App\Models\SupplierDelivery;
 22: use App\Models\SupplierDeliveryItem;
 23: use App\Models\SupplierUser;
 24: use App\Models\User;
 25: use Illuminate\Http\UploadedFile;
 26: use Illuminate\Support\Facades\DB;
 27: 
 28: /**
 29:  * خدمة المشتريات — دورة الشراء كاملة:
 30:  * طلب شراء داخلي (فرع) ← اعتماد ← أمر شراء لمورد ← إرسال ← قبول/طلب تعديل
 31:  * من بوابة المورد ← إشعارات توريد (ASN) ← استلام مخزني.
 32:  *
 33:  * قلب المرحلة المحاسبي: الاستلام يحدّث متوسط التكلفة المرجح (WAC) للمتغير
 34:  * قبل تغذية المخزون، والحركات كلها عبر InventoryService::recordMovement:
 35:  *   NewAvg = (CurrentTotalOnHand × OldCost + ReceivedQty × PurchaseCost)
 36:  *            ÷ (CurrentTotalOnHand + ReceivedQty)
 37:  * حيث CurrentTotalOnHand = مجموع on_hand للمتغير في كل الفروع.
 38:  */
 39: class ProcurementService
 40: {
 41:     public function __construct(
 42:         protected InventoryService $inventory,
 43:         protected SettingService $settings,
 44:     ) {}
 45: 
 46:     // ================= طلبات الشراء الداخلية =================
 47: 
 48:     /**
 49:      * @param  array{branch_id: int, notes?: string|null, items: list<array{product_variant_id: int, requested_qty: float|int|string, notes?: string|null}>}  $data
 50:      */
 51:     public function createPurchaseRequest(array $data, User $requester): PurchaseRequest
 52:     {
 53:         return DB::transaction(function () use ($data, $requester): PurchaseRequest {
 54:             $pr = PurchaseRequest::create([
 55:                 'request_number' => $this->settings->generateNextNumber('purchase_request'),
 56:                 'branch_id' => (int) $data['branch_id'],
 57:                 'requested_by' => $requester->id,
 58:                 'status' => PurchaseRequestStatus::Draft,
 59:                 'notes' => $data['notes'] ?? null,
 60:             ]);
 61:             $this->syncRequestItems($pr, $data['items']);
 62: 
 63:             return $pr->fresh(['items']);
 64:         });
 65:     }
 66: 
 67:     /**
 68:      * @param  array{branch_id?: int, notes?: string|null, items?: list<array{product_variant_id: int, requested_qty: float|int|string, notes?: string|null}>}  $data
 69:      */
 70:     public function updatePurchaseRequest(PurchaseRequest $pr, array $data): PurchaseRequest
 71:     {
 72:         return DB::transaction(function () use ($pr, $data): PurchaseRequest {
 73:             $pr = PurchaseRequest::query()->lockForUpdate()->findOrFail($pr->id);
 74:             if ($pr->status !== PurchaseRequestStatus::Draft) {
 75:                 throw new BusinessException('لا يمكن تعديل طلب شراء إلا وهو مسودة.');
 76:             }
 77:             $pr->update(array_intersect_key($data, array_flip(['branch_id', 'notes'])));
 78:             if (isset($data['items'])) {
 79:                 $pr->items()->delete();
 80:                 $this->syncRequestItems($pr, $data['items']);
 81:             }
 82: 
 83:             return $pr->fresh(['items']);
 84:         });
 85:     }
 86: 
 87:     public function submitPurchaseRequest(PurchaseRequest $pr): PurchaseRequest
 88:     {
 89:         return $this->transitionRequest($pr, PurchaseRequestStatus::Draft, PurchaseRequestStatus::Pending, 'الإرسال');
 90:     }
 91: 
 92:     public function approvePurchaseRequest(PurchaseRequest $pr): PurchaseRequest
 93:     {
 94:         return $this->transitionRequest($pr, PurchaseRequestStatus::Pending, PurchaseRequestStatus::Approved, 'الاعتماد');
 95:     }
 96: 
 97:     public function rejectPurchaseRequest(PurchaseRequest $pr): PurchaseRequest
 98:     {
 99:         return $this->transitionRequest($pr, PurchaseRequestStatus::Pending, PurchaseRequestStatus::Rejected, 'الرفض');
100:     }
101: 
102:     private function transitionRequest(PurchaseRequest $pr, PurchaseRequestStatus $from, PurchaseRequestStatus $to, string $action): PurchaseRequest
103:     {
104:         return DB::transaction(function () use ($pr, $from, $to, $action): PurchaseRequest {
105:             $pr = PurchaseRequest::query()->lockForUpdate()->findOrFail($pr->id);
106:             if ($pr->status !== $from) {
107:                 throw new BusinessException("لا يمكن {$action} طلب شراء في حالة ({$pr->status->value}).");
108:             }
109:             $pr->update(['status' => $to]);
110: 
111:             return $pr->fresh(['items']);
112:         });
113:     }
114: 
115:     /** @param list<array{product_variant_id: int, requested_qty: float|int|string, notes?: string|null}> $items */
116:     private function syncRequestItems(PurchaseRequest $pr, array $items): void
117:     {
118:         foreach ($items as $item) {
119:             DiscreteQuantity::assert($item['requested_qty']);
120:             $pr->items()->create([
121:                 'product_variant_id' => (int) $item['product_variant_id'],
122:                 'requested_qty' => (float) $item['requested_qty'],
123:                 'notes' => $item['notes'] ?? null,
124:             ]);
125:         }
126:     }
127: 
128:     // ================= أوامر الشراء =================
129: 
130:     /**
131:      * إنشاء أمر شراء (مسودة). عند ربطه بطلب داخلي معتمد تُنسخ بنوده
132:      * افتراضيًا (بسعر تكلفة المتغير الحالية وضريبة صفر قابلة للتعديل)،
133:      * ويتحول الطلب إلى converted_to_po.
134:      *
135:      * @param  array{supplier_id: int, branch_id?: int|null, purchase_request_id?: int|null, expected_delivery_date?: string|null, discount_amount?: float|int|string|null, items?: list<array{product_variant_id: int, ordered_qty: float|int|string, unit_cost: float|int|string, tax_rate?: float|int|string|null}>}  $data
136:      */
137:     public function createPurchaseOrder(array $data, User $creator): PurchaseOrder
138:     {
139:         return DB::transaction(function () use ($data, $creator): PurchaseOrder {
140:             $pr = null;
141:             if (! empty($data['purchase_request_id'])) {
142:                 $pr = PurchaseRequest::query()->lockForUpdate()->find((int) $data['purchase_request_id']);
143:                 if ($pr === null) {
144:                     throw new BusinessException('طلب الشراء الداخلي المرتبط غير موجود.');
145:                 }
146:                 if ($pr->status !== PurchaseRequestStatus::Approved) {
147:                     throw new BusinessException('لا يمكن إنشاء أمر شراء إلا من طلب داخلي معتمد.');
148:                 }
149:                 $pr->load('items.variant');
150:             }
151: 
152:             $items = $data['items'] ?? [];
153:             if ($items === [] && $pr !== null) {
154:                 $items = $pr->items->map(fn ($item): array => [
155:                     'product_variant_id' => (int) $item->product_variant_id,
156:                     'ordered_qty' => (float) $item->requested_qty,
157:                     'unit_cost' => (float) ($item->variant?->cost_price ?? 0),
158:                     'tax_rate' => 0,
159:                 ])->all();
160:             }
161:             if ($items === []) {
162:                 throw new BusinessException('أمر الشراء يحتاج بندًا واحدًا على الأقل.');
163:             }
164: 
165:             $branchId = (int) ($data['branch_id'] ?? $pr?->branch_id ?? 0);
166:             if ($branchId <= 0) {
167:                 throw new BusinessException('حدد فرع/مخزن استلام أمر الشراء.');
168:             }
169: 
170:             if (! Supplier::query()->whereKey($data['supplier_id'])->where('is_active', true)->exists()
171:                 || ! Branch::query()->whereKey($branchId)->where('is_active', true)->exists()) {
172:                 throw new BusinessException('المورد وفرع الاستلام يجب أن يكونا نشطين.');
173:             }
174:             $po = PurchaseOrder::create([
175:                 'po_number' => $this->settings->generateNextNumber('purchase_order'),
176:                 'supplier_id' => (int) $data['supplier_id'],
177:                 'branch_id' => $branchId,
178:                 'purchase_request_id' => $pr?->id,
179:                 'status' => PurchaseOrderStatus::Draft,
180:                 'expected_delivery_date' => $data['expected_delivery_date'] ?? null,
181:                 'discount_amount' => (float) ($data['discount_amount'] ?? 0),
182:                 'created_by' => $creator->id,
183:             ]);
184:             $this->syncOrderItems($po, $items);
185:             $this->recalculateTotals($po);
186: 
187:             $pr?->update(['status' => PurchaseRequestStatus::ConvertedToPo]);
188: 
189:             return $po->fresh(['items']);
190:         });
191:     }
192: 
193:     /**
194:      * @param  array{supplier_id?: int, branch_id?: int, expected_delivery_date?: string|null, discount_amount?: float|int|string|null, items?: list<array{product_variant_id: int, ordered_qty: float|int|string, unit_cost: float|int|string, tax_rate?: float|int|string|null}>}  $data
195:      */
196:     public function updatePurchaseOrder(PurchaseOrder $po, array $data): PurchaseOrder
197:     {
198:         return DB::transaction(function () use ($po, $data): PurchaseOrder {
199:             $po = $this->lockOrder($po);
200:             if (! in_array($po->status, [PurchaseOrderStatus::Draft, PurchaseOrderStatus::ChangeRequested], true)) {
201:                 throw new BusinessException('لا يمكن تعديل أمر شراء إلا وهو مسودة أو بانتظار معالجة تعديلات المورد.');
202:             }
203:             if ($po->items()->where('received_qty', '>', 0)->exists()) {
204:                 throw new BusinessException('أمر شراء بدأ استلامه لا تُعدَّل بنوده.');
205:             }
206:             if ($po->deliveries()->exists()
207:                 && (isset($data['items'])
208:                     || (isset($data['supplier_id']) && (int) $data['supplier_id'] !== (int) $po->supplier_id)
209:                     || (isset($data['branch_id']) && (int) $data['branch_id'] !== (int) $po->branch_id))) {
210:                 throw new BusinessException('لا يمكن تغيير المورد أو الفرع أو البنود بعد تسجيل إشعار توريد.');
211:             }
212:             if (array_intersect(['supplier_id', 'branch_id', 'items', 'discount_amount', 'expected_delivery_date'], array_keys($data))) {
213:                 $data['approved_by'] = null;
214:             }
215:             if (isset($data['supplier_id']) && ! Supplier::query()->whereKey($data['supplier_id'])->where('is_active', true)->exists()) {
216:                 throw new BusinessException('المورد غير نشط.');
217:             }
218:             if (isset($data['branch_id']) && ! Branch::query()->whereKey($data['branch_id'])->where('is_active', true)->exists()) {
219:                 throw new BusinessException('فرع الاستلام غير نشط.');
220:             }
221:             $po->update(array_intersect_key($data, array_flip([
222:                 'supplier_id', 'branch_id', 'expected_delivery_date', 'discount_amount', 'approved_by',
223:             ])));
224:             if (isset($data['items'])) {
225:                 $po->items()->delete();
226:                 $this->syncOrderItems($po, $data['items']);
227:             }
228:             $this->recalculateTotals($po);
229: 
230:             return $po->fresh(['items']);
231:         });
232:     }
