234:     /** ختم الاعتماد الداخلي (approved_by) على مسودة — الإرسال خطوة مستقلة. */
235:     public function approvePurchaseOrder(PurchaseOrder $po, User $admin): PurchaseOrder
236:     {
237:         return DB::transaction(function () use ($po, $admin): PurchaseOrder {
238:             $po = $this->lockOrder($po);
239:             if (! in_array($po->status, [PurchaseOrderStatus::Draft, PurchaseOrderStatus::ChangeRequested], true)) {
240:                 throw new BusinessException('لا يمكن اعتماد أمر شراء إلا وهو مسودة أو بانتظار معالجة التعديلات.');
241:             }
242:             if ((int) $po->created_by === (int) $admin->id
243:                 && ! (bool) $this->settings->get('allow_self_approve_purchases', false)) {
244:                 throw new BusinessException('لا يجوز لمن أنشأ أمر الشراء اعتماده بنفسه.');
245:             }
246:             $po->update(['approved_by' => $admin->id]);
247: 
248:             return $po->fresh(['items']);
249:         });
250:     }
251: 
252:     public function sendPurchaseOrder(PurchaseOrder $po): PurchaseOrder
253:     {
254:         return DB::transaction(function () use ($po): PurchaseOrder {
255:             $po = $this->lockOrder($po);
256:             if (! in_array($po->status, [PurchaseOrderStatus::Draft, PurchaseOrderStatus::ChangeRequested], true)) {
257:                 throw new BusinessException("لا يمكن إرسال أمر شراء في حالة ({$po->status->value}).");
258:             }
259:             if ($po->approved_by === null) {
260:                 throw new BusinessException('يجب اعتماد أمر الشراء قبل إرساله إلى المورد.');
261:             }
262:             if ($po->items()->count() === 0) {
263:                 throw new BusinessException('لا يمكن إرسال أمر شراء بلا بنود.');
264:             }
265:             if (! Supplier::query()->whereKey($po->supplier_id)->where('is_active', true)->exists()) {
266:                 throw new BusinessException('المورد غير نشط.');
267:             }
268:             $po->update(['status' => PurchaseOrderStatus::SentToSupplier, 'supplier_change_notes' => null]);
269: 
270:             $sent = $po->fresh(['items']);
271:             PurchaseOrderSentToSupplier::dispatch($sent);
272: 
273:             return $sent;
274:         });
275:     }
