277:     public function cancelPurchaseOrder(PurchaseOrder $po): PurchaseOrder
278:     {
279:         return DB::transaction(function () use ($po): PurchaseOrder {
280:             $po = $this->lockOrder($po);
281:             if ($po->items()->where('received_qty', '>', 0)->exists()) {
282:                 throw new BusinessException('لا يمكن إلغاء أمر شراء بدأ استلام بضاعته.');
283:             }
284:             if (! in_array($po->status, [
285:                 PurchaseOrderStatus::Draft, PurchaseOrderStatus::SentToSupplier,
286:                 PurchaseOrderStatus::SupplierAccepted, PurchaseOrderStatus::ChangeRequested,
287:             ], true)) {
288:                 throw new BusinessException("لا يمكن إلغاء أمر شراء في حالة ({$po->status->value}).");
289:             }
290:             $po->update(['status' => PurchaseOrderStatus::Cancelled]);
291:             $po->deliveries()->where('status', SupplierDeliveryStatus::PendingReceipt)->update(['status' => SupplierDeliveryStatus::Rejected]);
292:             if ($po->purchase_request_id !== null) {
293:                 PurchaseRequest::query()->whereKey($po->purchase_request_id)->where('status', PurchaseRequestStatus::ConvertedToPo)->update(['status' => PurchaseRequestStatus::Approved]);
294:             }
295: 
296:             return $po->fresh(['items']);
297:         });
298:     }
299: 
300:     /** @param list<array{product_variant_id: int, ordered_qty: float|int|string, unit_cost: float|int|string, tax_rate?: float|int|string|null}> $items */
301:     private function syncOrderItems(PurchaseOrder $po, array $items): void
302:     {
303:         foreach ($items as $item) {
304:             DiscreteQuantity::assert($item['ordered_qty']);
305:             $qty = (float) $item['ordered_qty'];
306:             $cost = (float) $item['unit_cost'];
307:             if (round($qty * $cost, 4) > 99999999.9999) {
308:                 throw new BusinessException('قيمة بند أمر الشراء تتجاوز السعة المسموحة.');
309:             }
310:             $po->items()->create([
311:                 'product_variant_id' => (int) $item['product_variant_id'],
312:                 'ordered_qty' => $qty,
313:                 'unit_cost' => $cost,
314:                 'tax_rate' => (float) ($item['tax_rate'] ?? 0),
315:                 'line_total' => round($qty * $cost, 4),
316:             ]);
317:         }
318:     }
319: 
320:     /** إجماليات الرأس من البنود: subtotal وضرائب البنود والخصم والنهائي. */
321:     private function recalculateTotals(PurchaseOrder $po): void
322:     {
323:         $items = $po->items()->get();
324:         $subtotal = round((float) $items->sum(fn (PurchaseOrderItem $i): float => (float) $i->line_total), 2);
325:         $tax = round((float) $items->sum(fn (PurchaseOrderItem $i): float => (float) $i->line_total * (float) $i->tax_rate / 100), 2);
326:         if ((float) $po->discount_amount > $subtotal) {
327:             throw new BusinessException('خصم أمر الشراء لا يمكن أن يتجاوز مجموع البنود.');
328:         }
329:         $po->update([
330:             'subtotal' => $subtotal,
331:             'tax_amount' => $tax,
332:             'grand_total' => round($subtotal - (float) $po->discount_amount + $tax, 2),
333:         ]);
334:     }
