336:     public function deletePurchaseOrder(PurchaseOrder $po): void
337:     {
338:         DB::transaction(function () use ($po): void {
339:             $po = $this->lockOrder($po);
340:             if (! in_array($po->status, [PurchaseOrderStatus::Draft, PurchaseOrderStatus::Cancelled], true)
341:                 || $po->deliveries()->exists() || $po->items()->where('received_qty', '>', 0)->exists()
342:                 || $po->invoices()->exists()) {
343:                 throw new BusinessException('لا يمكن حذف أمر شراء له استلام أو توريدات أو فواتير؛ احتفظ بالمستند للتدقيق.');
344:             }
345:             if ($po->purchase_request_id !== null) {
346:                 PurchaseRequest::query()->whereKey($po->purchase_request_id)
347:                     ->where('status', PurchaseRequestStatus::ConvertedToPo)
348:                     ->update(['status' => PurchaseRequestStatus::Approved]);
349:             }
350:             $po->delete();
351:         });
352:     }
