354:     public function closeShort(PurchaseOrder $po): PurchaseOrder
355:     {
356:         return DB::transaction(function () use ($po): PurchaseOrder {
357:             $po = $this->lockOrder($po);
358:             if ($po->status !== PurchaseOrderStatus::PartiallyReceived) {
359:                 throw new BusinessException('إغلاق النقص متاح لأمر مستلم جزئيًا فقط.');
360:             }
361:             $po->deliveries()->where('status', SupplierDeliveryStatus::PendingReceipt)->update(['status' => SupplierDeliveryStatus::Rejected]);
362:             $po->update(['status' => PurchaseOrderStatus::Completed]);
363: 
364:             return $po->fresh(['items']);
365:         });
366:     }
367: 
368:     private function lockOrder(PurchaseOrder $po): PurchaseOrder
369:     {
370:         return PurchaseOrder::query()->lockForUpdate()->findOrFail($po->id);
371:     }
372: 
373:     // ================= الاستلام ومتوسط التكلفة =================
374: 
375:     /**
376:      * استلام بضاعة أمر شراء (كلي أو جزئي) + تحديث متوسط التكلفة المرجح
377:      * + تغذية المخزون — قلب المرحلة 10.
378:      *
379:      * عند ربط الاستلام بإشعار توريد (supplierDeliveryId) تُطابَق الكميات
380:      * مع بنوده وتُحدَّث حالته إلى received عند اكتمال استلام مشحوناته.
381:      *
382:      * @param  list<array{purchase_order_item_id: int, qty: float|int|string}>  $receivedItems
383:      */
384:     public function receivePurchaseOrder(PurchaseOrder $po, array $receivedItems, ?int $locationId = null, ?int $supplierDeliveryId = null, ?int $performedBy = null, ?string $idempotencyKey = null): PurchaseOrder
385:     {
386:         $actor = User::query()->findOrFail($performedBy ?? auth()->id());
387: 
388:         return app(OperationIdempotencyService::class)->run('purchase_receipt', $actor, $idempotencyKey,
389:             ['purchase_order_id' => $po->id, 'items' => $receivedItems, 'location_id' => $locationId, 'supplier_delivery_id' => $supplierDeliveryId],
390:             fn () => $this->executePurchaseReceipt($po, $receivedItems, $locationId, $supplierDeliveryId, $actor->id));
391:     }
392: 
393:     private function executePurchaseReceipt(PurchaseOrder $po, array $receivedItems, ?int $locationId, ?int $supplierDeliveryId, int $performedBy): PurchaseOrder
394:     {
395:         return DB::transaction(function () use ($po, $receivedItems, $locationId, $supplierDeliveryId, $performedBy): PurchaseOrder {
396:             $po = $this->lockOrder($po);
397:             if (! in_array($po->status, [
398:                 PurchaseOrderStatus::SentToSupplier,
399:                 PurchaseOrderStatus::SupplierAccepted,
400:                 PurchaseOrderStatus::PartiallyReceived,
401:             ], true)) {
402:                 throw new BusinessException("لا يمكن استلام بضاعة لأمر شراء في حالة ({$po->status->value}).");
403:             }
404:             // إعادة فحص نشاط فرع الاستلام لحظة الاستلام الفعلي (L4): قد يكون
405:             // الفرع عُطّل بعد إرسال الأمر، فلا يصح تغذية مخزون فرع ميت.
406:             if (! Branch::query()->whereKey($po->branch_id)->where('is_active', true)->exists()) {
407:                 throw new BusinessException('فرع استلام أمر الشراء غير نشط.');
408:             }
409: 
410:             if ($supplierDeliveryId === null && $po->deliveries()->where('status', SupplierDeliveryStatus::PendingReceipt)->exists()) {
411:                 throw new BusinessException('حدد إشعار التوريد المعلق عند الاستلام لمنع احتساب كمياته مرتين.');
412:             }
413:             $poItems = $po->items()->orderBy('product_variant_id')->orderBy('id')->lockForUpdate()->get()->keyBy('id');
414:             usort($receivedItems, fn (array $a, array $b): int => [($poItems->get((int) $a['purchase_order_item_id'])?->product_variant_id ?? 0), (int) $a['purchase_order_item_id']]
415:                 <=> [($poItems->get((int) $b['purchase_order_item_id'])?->product_variant_id ?? 0), (int) $b['purchase_order_item_id']]);
416:             $variants = ProductVariant::query()->whereIn('id', $poItems->pluck('product_variant_id'))->orderBy('id')->lockForUpdate()->get()->keyBy('id');
417:             $costFactor = (float) $po->subtotal > 0 ? max(0.0, 1 - (float) $po->discount_amount / (float) $po->subtotal) : 1.0;
418:             $delivery = null;
419:             $deliveryItems = collect();
420:             if ($supplierDeliveryId !== null) {
421:                 $delivery = SupplierDelivery::query()->lockForUpdate()
422:                     ->where('purchase_order_id', $po->id)
423:                     ->findOrFail($supplierDeliveryId);
424:                 if ($delivery->status !== SupplierDeliveryStatus::PendingReceipt) {
425:                     throw new BusinessException('إشعار التوريد هذا تمت معالجته من قبل.');
426:                 }
427:                 $deliveryItems = $delivery->items()->get()->keyBy('purchase_order_item_id');
428:             }
429: 
430:             foreach ($receivedItems as $itemData) {
431:                 $poItem = $poItems->get((int) $itemData['purchase_order_item_id']);
432:                 if ($poItem === null) {
433:                     throw new BusinessException('أحد بنود الاستلام لا يتبع أمر الشراء هذا.');
434:                 }
435:                 DiscreteQuantity::assert($itemData['qty']);
436:                 $qtyToReceive = (float) $itemData['qty'];
437:                 if ($qtyToReceive <= 0) {
438:                     continue;
439:                 }
440: 
441:                 $remainingQty = (float) $poItem->ordered_qty - (float) $poItem->received_qty;
442:                 if (round($qtyToReceive, 4) > round($remainingQty, 4)) {
443:                     throw new BusinessException("الكمية المستلمة ({$qtyToReceive}) أكبر من الكمية المتبقية في أمر الشراء ({$remainingQty}).");
444:                 }
445: 
446:                 $deliveryItem = null;
447:                 if ($delivery !== null) {
448:                     $deliveryItem = $deliveryItems->get($poItem->id);
449:                     if ($deliveryItem === null) {
450:                         throw new BusinessException('أحد بنود الاستلام غير موجود في إشعار التوريد المحدد.');
451:                     }
452:                     $shippedRemaining = (float) $deliveryItem->shipped_qty - (float) $deliveryItem->received_qty;
453:                     if (round($qtyToReceive, 4) > round($shippedRemaining, 4)) {
454:                         throw new BusinessException('الكمية المستلمة أكبر من المشحونة المتبقية في إشعار التوريد.');
455:                     }
456:                 }
457: 
458:                 // 1. المتغير مقفولًا لتحديث متوسط التكلفة بأمان
459:                 $variant = $variants->get($poItem->product_variant_id);
460:                 if ($variant === null) {
461:                     throw new BusinessException('متغير الصنف غير متاح للاستلام.');
462:                 }
463: 
464:                 // Includes damaged stock: it remains part of physical on_hand across all branches.
465:                 $currentTotalOnHand = (float) StockLevel::query()
466:                     ->where('product_variant_id', $variant->id)
467:                     ->sum('on_hand');
468:                 $oldCost = (float) $variant->cost_price;
469:                 $newUnitCost = round((float) $poItem->unit_cost * $costFactor, 4);
470: 
471:                 // معادلة المتوسط المرجح للتكلفة (WAC)
472:                 $safeCurrentStock = max(0.0, $currentTotalOnHand);
473:                 $newAverageCost = ($safeCurrentStock + $qtyToReceive) > 0
474:                     ? (($safeCurrentStock * $oldCost) + ($qtyToReceive * $newUnitCost)) / ($safeCurrentStock + $qtyToReceive)
475:                     : $newUnitCost;
476: 
477:                 $variant->update([
478:                     'cost_price' => round($newAverageCost, 4),
479:                     'last_cost_price' => $newUnitCost,
480:                 ]);
481: 
482:                 // 2. حركة إضافة للمخزون عبر InventoryService حصرًا
483:                 $this->inventory->recordMovement([
484:                     'product_variant_id' => $variant->id,
485:                     'branch_id' => (int) $po->branch_id,
486:                     'location_id' => $locationId,
487:                     'type' => StockMovementType::PurchaseReceipt,
488:                     'affected_bucket' => StockBucket::OnHand,
489:                     'quantity' => $qtyToReceive,
490:                     'unit_cost' => $newUnitCost,
491:                     'reference_type' => PurchaseOrder::class,
492:                     'reference_id' => $po->id,
493:                     'created_by' => $performedBy ?? auth()->id(),
494:                     'notes' => "استلام من أمر شراء رقم {$po->po_number}",
495:                 ]);
496: 
497:                 // 3. تحديث المستلم في بند الأمر (وبند إشعار التوريد عند الربط)
498:                 $poItem->increment('received_qty', $qtyToReceive);
499:                 $deliveryItem?->increment('received_qty', $qtyToReceive);
500:             }
501: 
502:             if ($delivery !== null) {
503:                 $allDeliveryReceived = $delivery->items()->get()
504:                     ->every(fn (SupplierDeliveryItem $i): bool => (float) $i->received_qty >= (float) $i->shipped_qty);
505:                 if ($allDeliveryReceived) {
506:                     $delivery->update(['status' => SupplierDeliveryStatus::Received]);
507:                 }
508:             }
509: 
510:             // 4. حالة الأمر: مكتمل عند استلام كل بنوده، وإلا جزئي
511:             $po->load('items');
512:             $allCompleted = $po->items->every(fn (PurchaseOrderItem $i): bool => (float) $i->received_qty >= (float) $i->ordered_qty);
513:             $po->update(['status' => $allCompleted ? PurchaseOrderStatus::Completed : PurchaseOrderStatus::PartiallyReceived]);
514: 
515:             return $po->fresh(['items.variant']);
516:         });
517:     }
518: 
519:     // ================= بوابة المورد =================
520: 
521:     /** قبول المورد لأمر شراء مُرسل إليه (نطاق المورد يُفرض هنا أيضًا). */
522:     public function supplierAccept(PurchaseOrder $po, SupplierUser $user): PurchaseOrder
523:     {
524:         $this->assertOwnsOrder($po, $user);
525: 
526:         return DB::transaction(function () use ($po, $user): PurchaseOrder {
527:             $po = $this->lockOrder($po);
528:             $this->assertOwnsOrder($po, $user);
529:             if ($po->status !== PurchaseOrderStatus::SentToSupplier) {
530:                 throw new BusinessException("لا يمكن قبول أمر شراء في حالة ({$po->status->value}).");
531:             }
532:             $po->update(['status' => PurchaseOrderStatus::SupplierAccepted]);
533: 
534:             return $po->fresh(['items']);
535:         });
536:     }
537: 
538:     /** طلب المورد تعديل الأسعار/الكميات/الموعد مع ملاحظاته للإدارة. */
539:     public function supplierRequestChange(PurchaseOrder $po, SupplierUser $user, string $notes): PurchaseOrder
540:     {
541:         $this->assertOwnsOrder($po, $user);
542: 
543:         return DB::transaction(function () use ($po, $user, $notes): PurchaseOrder {
544:             $po = $this->lockOrder($po);
545:             $this->assertOwnsOrder($po, $user);
546:             if (! in_array($po->status, [PurchaseOrderStatus::SentToSupplier, PurchaseOrderStatus::SupplierAccepted], true)) {
547:                 throw new BusinessException("لا يمكن طلب تعديل على أمر شراء في حالة ({$po->status->value}).");
548:             }
549:             if ($po->deliveries()->where('status', SupplierDeliveryStatus::PendingReceipt)->exists()) {
550:                 throw new BusinessException('لا يمكن طلب تعديل وأمر الشراء له توريد بانتظار الاستلام.');
551:             }
552:             $po->update([
553:                 'status' => PurchaseOrderStatus::ChangeRequested,
554:                 'supplier_change_notes' => $notes,
555:             ]);
556: 
557:             return $po->fresh(['items']);
558:         });
559:     }
560: 
561:     /**
562:      * إشعار توريد (ASN) من المورد: كميات مشحونة فعليًا في هذه الدفعة +
563:      * فاتورة مبدئية مرفوعة. سقف الشحن التراكمي لكل بند = الكمية المطلوبة.
564:      *
565:      * @param  array{delivery_date: string, supplier_invoice_no?: string|null, notes?: string|null, items: list<array{purchase_order_item_id: int, shipped_qty: float|int|string}>}  $data
566:      */
567:     public function createSupplierDelivery(PurchaseOrder $po, SupplierUser $user, array $data, ?UploadedFile $invoiceFile = null, ?string $idempotencyKey = null): SupplierDelivery
568:     {
569:         $fresh = $po->fresh();
570:         if ($fresh === null) {
571:             throw new BusinessException('أمر الشراء غير موجود.', [], 404);
572:         }
573:         $this->assertOwnsOrder($fresh, $user);
574: 
575:         return PrivateAttachments::transaction(fn (PrivateAttachments $files) => app(OperationIdempotencyService::class)->run('supplier_delivery', $user, $idempotencyKey,
576:             ['purchase_order_id' => $po->id, ...$data, 'invoice_hash' => $invoiceFile ? hash_file('sha256', $invoiceFile->getRealPath()) : null],
577:             fn () => $this->executeSupplierDelivery($po, $user, $data, $invoiceFile, $files)));
578:     }
579: 
580:     private function executeSupplierDelivery(PurchaseOrder $po, SupplierUser $user, array $data, ?UploadedFile $invoiceFile, PrivateAttachments $files): SupplierDelivery
581:     {
582:         $this->assertOwnsOrder($po, $user);
583: 
584:         $delivery = DB::transaction(function () use ($po, $user, $data, $invoiceFile, $files): SupplierDelivery {
585:             $po = $this->lockOrder($po);
586:             $this->assertOwnsOrder($po, $user);
587:             if (! in_array($po->status, [
588:                 PurchaseOrderStatus::SentToSupplier,
589:                 PurchaseOrderStatus::SupplierAccepted,
590:                 PurchaseOrderStatus::PartiallyReceived,
591:             ], true)) {
592:                 throw new BusinessException("لا يمكن إرسال توريد لأمر شراء في حالة ({$po->status->value}).");
593:             }
594: 
595:             // تجميع البنود المكررة قبل فحص سقف الشحن التراكمي
596:             $lines = [];
597:             foreach ($data['items'] as $line) {
598:                 DiscreteQuantity::assert($line['shipped_qty']);
599:                 $itemId = (int) $line['purchase_order_item_id'];
600:                 $lines[$itemId] = ($lines[$itemId] ?? 0.0) + (float) $line['shipped_qty'];
601:             }
602: 
603:             $poItems = $po->items()->whereIn('id', array_keys($lines))->get()->keyBy('id');
604:             if ($poItems->count() !== count($lines)) {
605:                 throw new BusinessException('أحد بنود التوريد لا يتبع أمر الشراء هذا.');
606:             }
607:             foreach ($lines as $itemId => $shippedQty) {
608:                 $poItem = $poItems->get($itemId);
609:                 $pendingShipment = (float) SupplierDeliveryItem::query()
610:                     ->where('purchase_order_item_id', $itemId)
611:                     ->whereHas('delivery', fn ($q) => $q->where('status', SupplierDeliveryStatus::PendingReceipt->value))
612:                     ->selectRaw('COALESCE(SUM(shipped_qty - received_qty), 0) as total')->value('total');
613:                 if (round((float) $poItem->received_qty + $pendingShipment + $shippedQty, 4) > round((float) $poItem->ordered_qty, 4)) {
614:                     throw new BusinessException("إجمالي المشحون للصنف ({$poItem->variant?->sku}) يتجاوز الكمية المطلوبة في أمر الشراء.");
615:                 }
616:             }
617: 
618:             $delivery = SupplierDelivery::create([
619:                 'delivery_number' => $this->settings->generateNextNumber('delivery'),
620:                 'purchase_order_id' => $po->id,
621:                 'supplier_id' => (int) $user->supplier_id,
622:                 'status' => SupplierDeliveryStatus::PendingReceipt,
623:                 'delivery_date' => $data['delivery_date'],
624:                 'supplier_invoice_no' => $data['supplier_invoice_no'] ?? null,
625:                 'notes' => $data['notes'] ?? null,
626:             ]);
627:             foreach ($lines as $itemId => $shippedQty) {
628:                 $delivery->items()->create([
629:                     'purchase_order_item_id' => $itemId,
630:                     'product_variant_id' => $poItems->get($itemId)->product_variant_id,
631:                     'shipped_qty' => $shippedQty,
632:                 ]);
633:             }
634: 
635:             // الشحن دون قبول صريح = قبول ضمني بالالتزام
636:             if ($po->status === PurchaseOrderStatus::SentToSupplier) {
637:                 $po->update(['status' => PurchaseOrderStatus::SupplierAccepted]);
638:             }
639: 
640:             if ($invoiceFile !== null) {
641:                 $delivery->update(['invoice_file_path' => $files->store($invoiceFile, "supplier_deliveries/{$delivery->id}")]);
642:             }
643: 
644:             return $delivery;
645:         });
646: 
647:         return $delivery->fresh(['items']);
648:     }
649: 
650:     /** حارس نطاق بوابة المورد: أمر شراء مورد آخر غير موجود أصلًا في عالم هذا المستخدم. */
651:     private function assertOwnsOrder(PurchaseOrder $po, SupplierUser $user): void
652:     {
653:         if ((int) $po->supplier_id !== (int) $user->supplier_id) {
654:             throw new BusinessException('أمر الشراء غير موجود.', [], 404);
655:         }
656:     }
657: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Enums\RefundMethod;
  9: use App\Enums\ReturnStatus;
 10: use App\Enums\StockBucket;
 11: use App\Enums\StockMovementType;
 12: use App\Exceptions\BusinessException;
 13: use App\Models\Branch;
 14: use App\Models\Customer;
 15: use App\Models\Order;
 16: use App\Models\OrderItem;
 17: use App\Models\Product;
 18: use App\Models\ReturnRequest;
 19: use App\Models\ReturnRequestItem;
 20: use App\Models\User;
 21: use Illuminate\Http\UploadedFile;
 22: use Illuminate\Support\Facades\DB;
 23: use Illuminate\Support\Facades\Storage;
 24: 
 25: /**
 26:  * خدمة المرتجعات (RMA) — دورة حياة طلب الإرجاع في أربع خطوات:
 27:  * create ← تقديم الطلب (تحقق من التسليم ونافذة الاسترجاع وسقف الكميات)،
 28:  * approve ← موافقة مبدئية (فرع مستلم وكميات معتمدة)،
 29:  * receive ← استلام وفحص فعلي، refund ← رد مالي للعميل.
 30:  *
 31:  * القاعدة الذهبية: الإنشاء والاعتماد لا يضيفان أي رصيد للمخزون. الإضافة
 32:  * الفعلية تتم حصريًا في receive عبر InventoryService::recordMovement:
 33:  * السليم يعود إلى on_hand بحركة sale_return، والتالف يُسجل في وعاء
 34:  * damaged بحركة damage (بعد عودته فيزيائيًا إلى on_hand بنفس الكمية،
 35:  * لأن وعاء التالف شريحة من الرصيد الفعلي لا رصيد مستقل).
 36:  */
 37: class ReturnService
 38: {
 39:     public function __construct(
 40:         protected SettingService $settings,
 41:         protected InventoryService $inventory,
 42:         protected OrderService $orders,
 43:     ) {}
 44: 
 45:     /**
 46:      * تقديم طلب إرجاع لطلب مُسلَّم داخل نافذة الاسترجاع.
 47:      * $customer عند الإنشاء من المتجر (يفرض ملكية الطلب)؛ null عند إنشاء
 48:      * الأدمن اليدوي لطلب أي عميل/زائر.
 49:      *
 50:      * @param  array{reason: string, refund_method?: string|null, items: list<array{order_item_id: int, requested_qty: float|int|string, item_reason?: string|null, attachments?: list<UploadedFile>}>}  $data
 51:      */
 52:     public function createReturnRequest(Order $order, array $data, ?Customer $customer = null): ReturnRequest
 53:     {
 54:         $return = PrivateAttachments::transaction(function (PrivateAttachments $files) use ($order, $data, $customer): ReturnRequest {
 55:             // قفل صف الطلب: طلبا إرجاع متزامنان لنفس البند لا يتجاوزا سقفه معًا
 56:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 57: 
 58:             if ($customer !== null && (int) $order->customer_id !== (int) $customer->id) {
 59:                 throw new BusinessException('هذا الطلب لا يخص حسابك.', [], 403);
 60:             }
 61: 
 62:             if ($order->status !== OrderStatus::Delivered) {
 63:                 throw new BusinessException('لا يمكن إنشاء طلب إرجاع إلا لطلب تم تسليمه فعليًا.');
 64:             }
 65: 
 66:             $this->assertWithinReturnWindow($order);
 67: 
 68:             // تجميع البنود المكررة لنفس سطر الطلب قبل فحص السقف
 69:             $lines = [];
 70:             foreach ($data['items'] as $line) {
 71:                 DiscreteQuantity::assert($line['requested_qty']);
 72:                 $orderItemId = (int) $line['order_item_id'];
 73:                 $lines[$orderItemId] ??= ['qty' => 0.0, 'reason' => null, 'files' => []];
 74:                 $lines[$orderItemId]['qty'] += (float) $line['requested_qty'];
 75:                 $lines[$orderItemId]['reason'] = $line['item_reason'] ?? $lines[$orderItemId]['reason'];
 76:                 $lines[$orderItemId]['files'] = array_merge($lines[$orderItemId]['files'], $line['attachments'] ?? []);
 77:             }
 78: 
 79:             $orderItems = $order->items()->whereIn('id', array_keys($lines))->get()->keyBy('id');
 80:             if ($orderItems->count() !== count($lines)) {
 81:                 throw new BusinessException('أحد البنود المطلوب إرجاعها لا يتبع هذا الطلب.');
 82:             }
 83: 
 84:             foreach ($lines as $orderItemId => $line) {
 85:                 $orderItem = $orderItems->get($orderItemId);
 86:                 // ما سبق طلبه للإرجاع في طلبات قائمة (غير المرفوض/الملغي)
 87:                 // يحجز من سقف البند حتى لا يُرجع أكثر مما اشتراه العميل
 88:                 $previouslyRequested = (float) ReturnRequestItem::query()
 89:                     ->where('order_item_id', $orderItemId)
 90:                     ->join('return_requests', 'return_requests.id', '=', 'return_request_items.return_request_id')
 91:                     ->whereNotIn('return_requests.status', [ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value])
 92:                     ->selectRaw("COALESCE(SUM(CASE WHEN return_requests.status IN ('received', 'refunded') THEN received_good_qty + received_damaged_qty WHEN return_requests.status = 'approved' THEN approved_qty ELSE requested_qty END), 0) as total")
 93:                     ->value('total');
 94:                 if (round($previouslyRequested + $line['qty'], 4) > round((float) $orderItem->qty, 4)) {
 95:                     throw new BusinessException("كمية الإرجاع للصنف ({$orderItem->sku_snapshot}) تتجاوز الكمية المشتراة بعد احتساب مرتجعات سابقة.");
 96:                 }
 97:             }
 98: 
 99:             $return = ReturnRequest::create([
100:                 'return_number' => $this->settings->generateNextNumber('return'),
101:                 'order_id' => $order->id,
102:                 'customer_id' => $order->customer_id,
103:                 'status' => ReturnStatus::Pending,
104:                 'refund_method' => $data['refund_method'] ?? null,
105:                 'total_refund_amount' => 0,
106:                 'reason' => $data['reason'],
107:             ]);
108: 
109:             foreach ($lines as $orderItemId => $line) {
110:                 $orderItem = $orderItems->get($orderItemId);
111:                 $return->items()->create([
112:                     'order_item_id' => $orderItem->id,
113:                     'product_variant_id' => $orderItem->product_variant_id,
114:                     'requested_qty' => $line['qty'],
115:                     'unit_refund_price' => $this->netUnitRefundPrice($orderItem),
116:                     'item_reason' => $line['reason'],
117:                 ]);
118:             }
119: 
120:             $this->storeAttachments($return, $data['items'], $files);
121: 
122:             return $return;
123:         });
124: 
125:         return $return->fresh(['items']);
126:     }
127: 
128:     /**
129:      * الموافقة المبدئية: تحديد الفرع المستلم والكميات المعتمدة لكل بند.
130:      * لا تلمس المخزون بأي شكل — الاستلام الفعلي لاحقًا هو ما يحرّكه.
131:      *
132:      * @param  array{branch_id: int, admin_notes?: string|null, items?: list<array{id: int, approved_qty: float|int|string}>}  $data
133:      */
134:     public function approve(ReturnRequest $return, User $admin, array $data): ReturnRequest
135:     {
136:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
137:             Order::query()->lockForUpdate()->findOrFail($return->order_id);
138:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
139:             if ($return->status !== ReturnStatus::Pending) {
140:                 throw new BusinessException('لا يمكن اعتماد طلب مرتجع إلا وهو قيد المراجعة.');
141:             }
142: 
143:             if (! Branch::query()->whereKey($data['branch_id'])->where('is_active', true)->exists()) {
144:                 throw new BusinessException('فرع الاستلام غير نشط.');
145:             }
146:             $return->load(['items.orderItem', 'items.variant.product']);
147:             $approved = collect($data['items'] ?? [])->keyBy(fn (array $line): int => (int) $line['id']);
148:             foreach ($approved->keys() as $itemId) {
149:                 if (! $return->items->contains('id', $itemId)) {
150:                     throw new BusinessException('أحد البنود المعتمدة لا يتبع طلب المرتجع هذا.');
151:                 }
152:             }
153: 
154:             $totalApproved = 0.0;
155:             foreach ($return->items as $item) {
156:                 // بند غير مذكور في الحمولة يُعتمد بكامل كميته المطلوبة
157:                 $qty = $approved->has($item->id)
158:                     ? (float) $approved->get($item->id)['approved_qty']
159:                     : (float) $item->requested_qty;
160:                 DiscreteQuantity::assert($qty, true);
161:                 if ($qty < 0 || round($qty, 4) > round((float) $item->requested_qty, 4)) {
162:                     throw new BusinessException("الكمية المعتمدة للصنف ({$item->orderItem?->sku_snapshot}) يجب أن تكون بين صفر والمطلوب.");
163:                 }
164:                 $item->update(['approved_qty' => $qty]);
165:                 $totalApproved += $qty;
166:             }
167:             if ($totalApproved <= 0) {
168:                 throw new BusinessException('لا توجد كميات معتمدة؛ ارفض الطلب بدلًا من اعتماده إن لم يُقبل أي بند.');
169:             }
170: 
171:             $return->update([
172:                 'branch_id' => (int) $data['branch_id'],
173:                 'status' => ReturnStatus::Approved,
174:                 'approved_by' => $admin->id,
175:                 'approved_at' => now(),
176:                 'admin_notes' => $data['admin_notes'] ?? $return->admin_notes,
177:             ]);
178: 
179:             return $return->fresh(['items']);
180:         });
181:     }
182: 
183:     /**
184:      * الاستلام والفحص المخزني — الخطوة الوحيدة التي تحرّك المخزون:
185:      * السليم sale_return إلى on_hand، والتالف damage إلى وعاء damaged،
186:      * داخل معاملة واحدة عبر InventoryService حصرًا.
187:      *
188:      * @param  array{items: list<array{id: int, received_good_qty: float|int|string, received_damaged_qty: float|int|string}>}  $data
189:      */
190:     public function receive(ReturnRequest $return, User $admin, array $data): ReturnRequest
191:     {
192:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
193:             Order::query()->lockForUpdate()->findOrFail($return->order_id);
194:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
195:             if ($return->status !== ReturnStatus::Approved) {
196:                 throw new BusinessException('لا يمكن استلام مرتجع إلا بعد الموافقة المبدئية عليه.');
197:             }
198:             if ($return->branch_id === null) {
199:                 throw new BusinessException('لم يُحدد فرع الاستلام عند اعتماد هذا المرتجع.');
200:             }
201:             if (! Branch::query()->whereKey($return->branch_id)->where('is_active', true)->exists()) {
202:                 throw new BusinessException('فرع الاستلام غير نشط.');
203:             }
204: 
205:             $return->load(['items.orderItem', 'items.variant.product']);
206:             $lines = collect($data['items'])->keyBy(fn (array $line): int => (int) $line['id']);
207:             foreach ($lines->keys() as $itemId) {
208:                 if (! $return->items->contains('id', $itemId)) {
209:                     throw new BusinessException('أحد البنود المستلمة لا يتبع طلب المرتجع هذا.');
210:                 }
211:             }
212:             foreach ($return->items as $item) {
213:                 if (! $lines->has($item->id)) {
214:                     throw new BusinessException('بيانات الاستلام يجب أن تغطي كل بنود المرتجع (بند بلا استلام فعلي يُرسل بصفر).');
215:                 }
216:             }
217: 
218:             // تجميعات المرتجعات السابقة (مستلمة/مردودة) لكل بنود الطلب في
219:             // استعلام واحد مجمّع بدل استعلام لكل بند داخل الحلقة (L5). بنود
220:             // هذا المرتجع نفسه مستبعدة ضمنيًا لأن حالته ما زالت Approved.
221:             $previousByOrderItem = ReturnRequestItem::query()
222:                 ->whereIn('order_item_id', $return->items->pluck('order_item_id')->all())
223:                 ->whereHas('returnRequest', fn ($q) => $q->whereIn('status', [ReturnStatus::Received, ReturnStatus::Refunded]))
224:                 ->selectRaw('order_item_id, COALESCE(SUM(received_good_qty + received_damaged_qty), 0) as qty, COALESCE(SUM(refund_amount), 0) as refunded')
225:                 ->groupBy('order_item_id')
226:                 ->get()
227:                 ->keyBy('order_item_id');
228: 
229:             $refundTotal = 0.0;
230:             foreach ($return->items as $item) {
231:                 $line = $lines->get($item->id);
232:                 DiscreteQuantity::assert($line['received_good_qty'], true);
233:                 DiscreteQuantity::assert($line['received_damaged_qty'], true);
234:                 $good = (float) $line['received_good_qty'];
235:                 $damaged = (float) $line['received_damaged_qty'];
236:                 if (round($good + $damaged, 4) > round((float) $item->approved_qty, 4)) {
237:                     throw new BusinessException("المستلم للصنف ({$item->orderItem?->sku_snapshot}) يتجاوز الكمية المعتمدة.");
238:                 }
239: 
240:                 $base = [
241:                     'product_variant_id' => $item->product_variant_id,
242:                     'branch_id' => (int) $return->branch_id,
243:                     'location_id' => null,
244:                     'reference_type' => ReturnRequest::class,
245:                     'reference_id' => $return->id,
246:                     'created_by' => $admin->id,
247:                 ];
248:                 if ($good > 0) {
249:                     $this->inventory->recordMovement([...$base,
250:                         'type' => StockMovementType::SaleReturn,
251:                         'affected_bucket' => StockBucket::OnHand,
252:                         'quantity' => $good,
253:                         'notes' => "مرتجع سليم — طلب {$return->return_number}",
254:                     ]);
255:                 }
256:                 if ($damaged > 0) {
257:                     // القطعة التالفة عادت فيزيائيًا للمخزن فتدخل on_hand أولًا،
258:                     // ثم تُحجز في وعاء التالف — المتاح للبيع لا يزيد بها
259:                     $this->inventory->recordMovement([...$base,
260:                         'type' => StockMovementType::SaleReturn,
261:                         'affected_bucket' => StockBucket::OnHand,
262:                         'quantity' => $damaged,
263:                         'notes' => "مرتجع تالف (عودة فيزيائية) — طلب {$return->return_number}",
264:                     ]);
265:                     $this->inventory->recordMovement([...$base,
266:                         'type' => StockMovementType::Damage,
267:                         'affected_bucket' => StockBucket::Damaged,
268:                         'quantity' => $damaged,
269:                         'notes' => "مرتجع تالف بعد الفحص — طلب {$return->return_number}",
270:                     ]);
271:                 }
272: 
273:                 $receivedTotal = $good + $damaged;
274:                 if ($receivedTotal > 0 && $item->variant?->product_id) {
275:                     Product::query()->whereKey($item->variant->product_id)
276:                         ->update(['sales_count' => DB::raw('GREATEST(sales_count - '.(int) round($receivedTotal).', 0)')]);
277:                 }
278: 
279:                 $previous = $previousByOrderItem->get($item->order_item_id);
280:                 $previousQty = (float) ($previous->qty ?? 0);
281:                 $previousRefunded = (float) ($previous->refunded ?? 0);
282:                 $orderItem = $item->orderItem;
283:                 $netCents = $this->netLineRefundCents($orderItem);
284:                 $cumulativeQty = $previousQty + $receivedTotal;
285:                 $targetCents = $cumulativeQty >= (float) $orderItem->qty
286:                     ? $netCents
287:                     : min($netCents, (int) round($cumulativeQty * (float) $item->unit_refund_price * 100));
288:                 $refundAmount = max(0, $targetCents - (int) round($previousRefunded * 100)) / 100;
289:                 $item->update([
290:                     'refund_amount' => $refundAmount,
291:                     'received_good_qty' => $good,
292:                     'received_damaged_qty' => $damaged,
293:                 ]);
294:                 $refundTotal += $refundAmount;
295:             }
296: 
297:             $return->update([
298:                 'total_refund_amount' => round($refundTotal, 2),
299:                 'status' => ReturnStatus::Received,
300:                 'received_by' => $admin->id,
301:                 'received_at' => now(),
302:             ]);
303: 
304:             return $return->fresh(['items']);
305:         });
306:     }
307: 
308:     /**
309:      * رد المبلغ للعميل بعد الاستلام: محفظة (تُضاف لرصيد العميل) أو تسجيل
310:      * مرجع تحويل/بوابة. اكتمال إرجاع كل بنود الطلب ينقل الطلب نفسه إلى
311:      * Returned عبر بوابة الحالة بلا آثار مخزون/استرداد مكررة.
312:      *
313:      * @param  array{refund_method?: string|null, refund_reference?: string|null}  $data
314:      */
315:     public function refund(ReturnRequest $return, User $admin, array $data): ReturnRequest
316:     {
317:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
318:             $order = Order::query()->lockForUpdate()->findOrFail($return->order_id);
319:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
320:             if ($return->status !== ReturnStatus::Received) {
321:                 throw new BusinessException('لا يمكن رد مبلغ مرتجع إلا بعد استلامه وفحصه.');
322:             }
323: 
324:             $method = $data['refund_method'] ?? $return->refund_method?->value;
325:             if ($method === null) {
326:                 throw new BusinessException('حدد طريقة رد المبلغ قبل إتمام الاسترداد.');
327:             }
328:             $reference = $data['refund_reference'] ?? $return->refund_reference;
329:             if (in_array($method, [RefundMethod::OriginalPayment->value, RefundMethod::BankTransfer->value], true)
330:                 && trim((string) $reference) === '') {
331:                 throw new BusinessException('مرجع التحويل أو بوابة الدفع مطلوب لإتمام الاسترداد.');
332:             }
333: 
334:             if (! in_array($order->payment_status, ['paid', 'partially_refunded', 'refunded'], true)) {
335:                 throw new BusinessException('لا يمكن رد مبلغ نقدي أو إلى المحفظة لطلب غير مدفوع. يُقيَّد المرتجع كتخفيض للمستحق حتى يُبنى مسار إشعار دائن.');
336:             }
337:             if ($order->payment_method === 'wallet' && $method !== RefundMethod::Wallet->value) {
338:                 throw new BusinessException('طلب مدفوع بالمحفظة يُرد إلى المحفظة فقط.');
339:             }
340:             $reference = $reference !== null ? trim((string) $reference) : $reference;
341:             if ($reference !== null && $reference !== '' && ReturnRequest::query()
342:                 ->where('id', '!=', $return->id)
343:                 ->whereNotIn('status', [ReturnStatus::Rejected, ReturnStatus::Cancelled])
344:                 ->whereRaw('lower(btrim(refund_reference)) = ?', [mb_strtolower($reference)])
345:                 ->exists()) {
346:                 throw new BusinessException('مرجع الرد مسجّل سابقًا.', [], 409);
347:             }
348: 
349:             if ($method === RefundMethod::Wallet->value) {
350:                 if ($return->customer_id === null) {
351:                     throw new BusinessException('الاسترداد إلى المحفظة يتطلب حساب عميل مسجل؛ اختر طريقة أخرى لطلبات الزوار.');
352:                 }
353:                 app(WalletService::class)->record($return->customer_id, (float) $return->total_refund_amount,
354:                     'return_refund', 'return_request', $return->id, $admin->id);
355:             }
356: 
357:             $return->update([
358:                 'refund_method' => $method,
359:                 'refund_reference' => $reference,
360:                 'status' => ReturnStatus::Refunded,
361:                 'refunded_by' => $admin->id,
362:                 'refunded_at' => now(),
363:             ]);
364: 
365:             $this->syncOrderPaymentStatusAfterRefund($order);
366:             if ($this->isOrderFullyReturned($order)) {
367:                 $this->orders->changeStatus(
368:                     $order,
369:                     OrderStatus::Returned,
370:                     $admin,
371:                     "إرجاع كامل لبنود الطلب عبر طلب المرتجع {$return->return_number}",
372:                     null,
373:                     false,
374:                 );
375:             }
376: 
377:             return $return->fresh(['items']);
378:         });
379:     }
380: 
381:     public function delete(ReturnRequest $return): void
382:     {
383:         DB::transaction(function () use ($return): void {
384:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
385:             if ($return->status !== ReturnStatus::Pending) {
386:                 throw new BusinessException('يمكن حذف المرتجعات قيد المراجعة فقط؛ استخدم الإلغاء للحالات الأخرى.');
387:             }
388:             $paths = $return->items()->get()->flatMap(fn ($item) => $item->attachments ?? [])->all();
389:             $return->delete();
390:             DB::afterCommit(function () use ($paths): void {
391:                 Storage::disk('r2')->delete($paths);
392:             });
393:         });
394:     }
395: 
396:     /** رفض طلب قيد المراجعة — بلا أي أثر (لم يتحرك مخزون ولا مال). */
397:     public function reject(ReturnRequest $return, User $admin, ?string $notes = null): ReturnRequest
398:     {
399:         return DB::transaction(function () use ($return, $notes): ReturnRequest {
400:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
401:             if ($return->status !== ReturnStatus::Pending) {
402:                 throw new BusinessException('لا يمكن رفض طلب مرتجع إلا وهو قيد المراجعة.');
403:             }
404:             $return->update([
405:                 'status' => ReturnStatus::Rejected,
406:                 'admin_notes' => $notes ?? $return->admin_notes,
407:             ]);
408: 
409:             return $return->fresh(['items']);
410:         });
411:     }
412: 
413:     /** إلغاء طلب لم يُستلم بعد (قيد المراجعة/معتمد) — بلا أي أثر مخزني. */
414:     public function cancel(ReturnRequest $return, ?string $notes = null): ReturnRequest
415:     {
416:         return DB::transaction(function () use ($return, $notes): ReturnRequest {
417:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
418:             if (! in_array($return->status, [ReturnStatus::Pending, ReturnStatus::Approved], true)) {
419:                 throw new BusinessException('لا يمكن إلغاء مرتجع بعد استلامه.');
420:             }
421:             $return->update([
422:                 'status' => ReturnStatus::Cancelled,
423:                 'admin_notes' => $notes ?? $return->admin_notes,
424:             ]);
425: 
426:             return $return->fresh(['items']);
427:         });
428:     }
429: 
430:     /**
431:      * تعديلات إدارية بلا آثار جانبية: ملاحظات وطريقة رد (قبل اكتمال الرد)،
432:      * وتوجيه حالتي rejected/cancelled لمساريهما في الخدمة.
433:      *
434:      * @param  array{admin_notes?: string|null, refund_method?: string|null, status?: string|null}  $data
435:      */
436:     public function updateDetails(ReturnRequest $return, User $admin, array $data): ReturnRequest
437:     {
438:         if (($data['status'] ?? null) === ReturnStatus::Rejected->value) {
439:             return $this->reject($return, $admin, $data['admin_notes'] ?? null);
440:         }
441:         if (($data['status'] ?? null) === ReturnStatus::Cancelled->value) {
442:             return $this->cancel($return, $data['admin_notes'] ?? null);
443:         }
444: 
445:         return DB::transaction(function () use ($return, $data): ReturnRequest {
446:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
447:             if (! in_array($return->status, [ReturnStatus::Pending, ReturnStatus::Approved, ReturnStatus::Received], true)
448:                 && array_key_exists('refund_method', $data)) {
449:                 throw new BusinessException('لا يمكن تغيير طريقة الرد بعد اكتمال الاسترداد.');
450:             }
451: 
452:             $updates = [];
453:             if (array_key_exists('admin_notes', $data)) {
454:                 $updates['admin_notes'] = $data['admin_notes'];
455:             }
456:             if (array_key_exists('refund_method', $data)) {
457:                 $updates['refund_method'] = $data['refund_method'];
458:             }
459:             if ($updates !== []) {
460:                 $return->update($updates);
461:             }
462: 
463:             return $return->fresh(['items']);
464:         });
465:     }
466: 
467:     /**
468:      * نافذة الاسترجاع من الإعدادات (أيام من لحظة انتقال الطلب إلى delivered).
469:      * 0 = الإرجاع متوقف، قيمة سالبة (مثل -1) = بلا حد زمني.
470:      */
471:     private function assertWithinReturnWindow(Order $order): void
472:     {
473:         $windowDays = (int) $this->settings->get('return_window_days', 14);
474:         if ($windowDays === 0) {
475:             throw new BusinessException('الإرجاع متوقف من إعدادات المتجر.');
476:         }
477:         if ($windowDays < 0) {
478:             return;
479:         }
480: 
481:         $deliveredAt = $order->statusHistories()
482:             ->where('to_status', OrderStatus::Delivered->value)
483:             ->latest('id')
484:             ->value('created_at');
485: 
486:         if ($deliveredAt === null) {
487:             throw new BusinessException('لا يوجد سجل تسليم موثوق لحساب فترة الاسترجاع.');
488:         }
489: 
490:         if ($deliveredAt !== null && $deliveredAt->copy()->addDays($windowDays)->isPast()) {
491:             throw new BusinessException("انتهت فترة الاسترجاع المسموحة ({$windowDays} يومًا من التسليم) لهذا الطلب.");
492:         }
493:     }
494: 
495:     /** سعر وحدة الرد الصافي: ما دفعه العميل فعليًا للبند ÷ كميته (بعد خصومات الأسعار وحصة الكوبون والضريبة غير المشمولة). */
496:     private function netUnitRefundPrice(OrderItem $orderItem): float
497:     {
498:         $qty = (float) $orderItem->qty;
499:         if ($qty <= 0) {
500:             return (float) $orderItem->unit_price;
501:         }
502: 
503:         return round($this->netLineRefundCents($orderItem) / 100 / $qty, 4);
504:     }
505: 
506:     /** صافي البند بالسنت: السعر × الكمية − الخصم + ضريبة البند (صفر عندما تكون الأسعار شاملة الضريبة). */
507:     private function netLineRefundCents(OrderItem $orderItem): int
508:     {
509:         $net = (float) $orderItem->unit_price * (float) $orderItem->qty
510:             - (float) $orderItem->discount_amount
511:             + (float) $orderItem->tax_amount;
512: 
513:         return (int) round(max(0.0, $net) * 100);
514:     }
515: 
516:     private function syncOrderPaymentStatusAfterRefund(Order $order): void
517:     {
518:         if (! in_array($order->payment_status, ['paid', 'partially_refunded', 'refunded'], true)) {
519:             return;
520:         }
521:         $refundedCents = (int) round((float) $order->returnRequests()->where('status', ReturnStatus::Refunded)->sum('total_refund_amount') * 100);
522:         $refundableCents = (int) $order->items()->get()->sum(fn (OrderItem $item): int => $this->netLineRefundCents($item));
523:         if ($refundableCents > 0 && $refundedCents >= $refundableCents) {
524:             $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
525:         } elseif ($refundedCents > 0) {
526:             $order->update(['payment_status' => 'partially_refunded']);
527:         }
528:     }
529: 
530:     /**
531:      * حفظ صور العيوب على القرص الخاص داخل معاملة إنشاء المرتجع،
532:      * وتسجيل مساراتها في attachments البند.
533:      *
534:      * @param  list<array{order_item_id: int, attachments?: list<UploadedFile>}>  $rawItems
535:      */
536:     private function storeAttachments(ReturnRequest $return, array $rawItems, PrivateAttachments $files): void
537:     {
538:         $filesByOrderItem = [];
539:         foreach ($rawItems as $line) {
540:             foreach ($line['attachments'] ?? [] as $file) {
541:                 if ($file instanceof UploadedFile) {
542:                     $filesByOrderItem[(int) $line['order_item_id']][] = $file;
543:                 }
544:             }
545:         }
546:         if ($filesByOrderItem === []) {
547:             return;
548:         }
549: 
550:         $return->load('items');
551:         foreach ($return->items as $item) {
552:             $itemFiles = $filesByOrderItem[(int) $item->order_item_id] ?? [];
553:             if ($itemFiles === []) {
554:                 continue;
555:             }
556:             $paths = [];
557:             foreach ($itemFiles as $file) {
558:                 $paths[] = $files->store($file, "return_requests/{$return->id}");
559:             }
560:             $item->update(['attachments' => array_merge($item->attachments ?? [], $paths)]);
561:         }
562:     }
563: 
564:     /** هل اكتمل استلام ورد قيمة كل بنود الطلب عبر المرتجعات؟ */
565:     private function isOrderFullyReturned(Order $order): bool
566:     {
567:         $items = $order->items()->get();
568:         if ($items->isEmpty()) {
569:             return false;
570:         }
571: 
572:         $receivedByItem = ReturnRequestItem::query()
573:             ->whereIn('order_item_id', $items->pluck('id'))
574:             ->whereHas('returnRequest', fn ($q) => $q->where('status', ReturnStatus::Refunded->value))
575:             ->selectRaw('order_item_id, COALESCE(SUM(received_good_qty + received_damaged_qty), 0) as total')
576:             ->groupBy('order_item_id')
577:             ->pluck('total', 'order_item_id');
578:         foreach ($items as $orderItem) {
579:             $received = (float) ($receivedByItem[$orderItem->id] ?? 0);
580:             if (round($received, 4) < round((float) $orderItem->qty, 4)) {
581:                 return false;
582:             }
583:         }
584: 
585:         return true;
586:     }
587: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Enums\ShipmentStatus;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Order;
 11: use App\Models\Shipment;
 12: use App\Models\ShippingCompany;
 13: use App\Models\ShippingRate;
 14: use App\Models\User;
 15: use Illuminate\Support\Facades\DB;
 16: use Illuminate\Support\Str;
 17: 
 18: /**
 19:  * إنشاء بوالص الشحن للطلبات.
 20:  * لا توجد بوابة شركة شحن مربوطة بعد: رقم البوليصة يُولّد داخليًا
 21:  * (أو يُمرّر جاهزًا من الأدمن)، وتكلفة البوليصة من جدول أسعار الشحن
 22:  * (شركة × منطقة مدينة الطلب) مع احترام حد الشحن المجاني.
 23:  */
 24: class ShipmentService
 25: {
 26:     public function __construct(protected OrderService $orders) {}
 27: 
 28:     public function createForOrder(Order $order, int $companyId, ?string $awbNumber, User $actor): Shipment
 29:     {
 30:         return DB::transaction(function () use ($order, $companyId, $awbNumber, $actor): Shipment {
 31:             // قفل الطلب والتحقق من حالته ومن عدم وجود بوليصة نشطة —
 32:             // نقرة مزدوجة لا تنتج بوليصتين ولا بيعًا مكررًا (H1)
 33:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 34:             $hasActiveShipmentEarly = $order->shipments()
 35:                 ->whereNotIn('status', [ShipmentStatus::Failed->value, ShipmentStatus::Returned->value])
 36:                 ->exists();
 37:             // بوليصة بديلة (F-16): طلب مشحون كل بوالصه فاشلة/مرتجعة يمكن
 38:             // إعادة إصدار بوليصة له — بلا changeStatus (حالته Shipped أصلًا
 39:             // ومخزونه خرج مع الشحنة الأولى)
 40:             $isReplacement = $order->status === OrderStatus::Shipped
 41:                 && ! $hasActiveShipmentEarly
 42:                 && $order->shipments()->exists();
 43:             if (! in_array($order->status, [OrderStatus::Confirmed, OrderStatus::Processing], true) && ! $isReplacement) {
 44:                 throw new BusinessException('لا يمكن إنشاء بوليصة إلا لطلب مؤكد أو قيد التجهيز.');
 45:             }
 46:             // الدفع المسبق (غير COD) لا يُشحن إلا وحالته paid (F-05): طلب
 47:             // مسترد أو غير مدفوع لا يخرج من المستودع فيُشحن مجانًا. ضبط
 48:             // paid يدويًا (تحويل بنكي) قبل الشحن مقصود هنا
 49:             if ($order->payment_method !== 'cod' && $order->payment_status !== 'paid') {
 50:                 throw new BusinessException('لا يمكن شحن طلب دفع مسبق لم يُدفع بعد (الحالة الحالية: '.$order->payment_status.').');
 51:             }
 52:             if ($hasActiveShipmentEarly) {
 53:                 throw new BusinessException('توجد بوليصة نشطة لهذا الطلب بالفعل.');
 54:             }
 55: 
 56:             $company = ShippingCompany::query()->where('is_active', true)->find($companyId);
 57:             if ($company === null) {
 58:                 throw new BusinessException('شركة الشحن غير موجودة أو غير نشطة.');
 59:             }
 60: 
 61:             $rate = $this->rateFor($order, $company->id);
 62:             $shippingCost = $rate !== null ? (float) $rate->base_cost : (float) $order->shipping_cost;
 63:             if ($rate !== null && $rate->free_shipping_threshold !== null
 64:                 && ((float) $order->subtotal - (float) $order->discount_amount) >= (float) $rate->free_shipping_threshold) {
 65:                 $shippingCost = 0.0;
 66:             }
 67: 
 68:             $shipment = Shipment::create([
 69:                 'order_id' => $order->id,
 70:                 'shipping_company_id' => $company->id,
 71:                 'awb_number' => $awbNumber ?? $this->generateAwb($company),
 72:                 'status' => ShipmentStatus::Created,
 73:                 'label_url' => null,
 74:                 'shipping_cost' => $shippingCost,
 75:                 'cod_amount' => $order->payment_method === 'cod' ? (float) $order->grand_total : 0,
 76:                 'raw_response' => ['source' => 'internal'],
 77:             ]);
 78: 
 79:             // الشحن الفعلي للطلب (يفك الحجز ويخصم البيع) عبر بوابة الحالة —
 80:             // البديلة لا تستدعيه: الطلب مشحون ومخزونه خرج من الشحنة الأولى
 81:             if (! $isReplacement) {
 82:                 $this->orders->changeStatus($order, OrderStatus::Shipped, $actor, "تم إنشاء بوليصة الشحن {$shipment->awb_number}");
 83:             }
 84: 
 85:             return $shipment->fresh(['company', 'order']);
 86:         });
 87:     }
 88: 
 89:     /** سعر الشركة لمنطقة مدينة الطلب إن وُجد. */
 90:     /**
 91:      * سعر الشركة لمدينة الطلب: join مباشر rates × zone_cities مفلتر بالشركة
 92:      * والمدينة معًا — مدينة في أكثر من منطقة لا تختار منطقة بلا سعر (M12).
 93:      */
 94:     private function rateFor(Order $order, int $companyId): ?ShippingRate
 95:     {
 96:         if ($order->city_id === null) {
 97:             return null;
 98:         }
 99: 
100:         return ShippingRate::query()
101:             ->join('shipping_zones', 'shipping_zones.id', '=', 'shipping_rates.shipping_zone_id')
102:             ->join('shipping_zone_cities', 'shipping_zone_cities.shipping_zone_id', '=', 'shipping_zones.id')
103:             ->where('shipping_rates.shipping_company_id', $companyId)
104:             ->where('shipping_zone_cities.city_id', $order->city_id)
105:             ->where('shipping_zones.is_active', true)
106:             ->orderBy('shipping_rates.id')
107:             ->select('shipping_rates.*')
108:             ->first();
109:     }
110: 
111:     // تسعيرة العميل الموحدة في ShippingQuoteService (بلا تبعية دائرية)
112: 
113:     private function generateAwb(ShippingCompany $company): string
114:     {
115:         do {
116:             $awb = Str::upper($company->code).'-'.Str::upper(Str::random(10));
117:         } while (Shipment::query()->where('awb_number', $awb)->exists());
118: 
119:         return $awb;
120:     }
121: }

