149:   function changeTheme(targetDark, origin) {
150:     const isDark = targetDark === state.darkMode ? !state.darkMode : targetDark;
151:     cancelAnimationFrame(timers.current.wipe);
152:     const viewport = viewportRef.current;
153:     const underlay = underlayRef.current;
154:     const rect = origin.getBoundingClientRect();
155:     const cx = Math.round(rect.left + rect.width / 2);
156:     const cy = Math.round(rect.top + rect.height / 2);
157:     const scrollY = window.scrollY || 0;
158:     const maxRadius = Math.ceil(Math.hypot(Math.max(cx, window.innerWidth - cx), Math.max(cy, window.innerHeight - cy))) + 30;
159:     const snapshot = viewport.cloneNode(true);
160:     const liveInputs = viewport.querySelectorAll('input');
161:     snapshot.querySelectorAll('input').forEach((input, index) => {
162:       input.value = liveInputs[index].value;
163:       input.checked = liveInputs[index].checked;
164:     });
165:     const liveHosts = viewport.querySelectorAll('[data-catalog-mock], [data-categories-mock]');
166:     snapshot.querySelectorAll('[data-catalog-mock], [data-categories-mock]').forEach((hostClone, index) => {
167:       const liveHost = liveHosts[index];
168:       if (liveHost?.shadowRoot) {
169:         const cloneRoot = hostClone.attachShadow({ mode: 'open' });
170:         cloneRoot.innerHTML = liveHost.shadowRoot.innerHTML;
171:       }
172:     });
173:     snapshot.removeAttribute('id');
174:     snapshot.style.clipPath = 'none';
175:     snapshot.style.width = viewport.offsetWidth + 'px';
176:     snapshot.style.transform = `translateY(-${scrollY}px)`;
177:     snapshot.querySelectorAll('[id]').forEach(element => element.removeAttribute('id'));
178:     underlay.replaceChildren(snapshot);
179:     underlay.classList.remove('hidden');
180:     try {
181:       localStorage.setItem('vortix_theme', isDark ? 'dark' : 'light');
182:     } catch {}
183:     window.dispatchEvent(new CustomEvent('vortix:theme-change', { detail: { darkMode: isDark } }));
184:     document.documentElement.setAttribute('data-theme', isDark ? 'dark' : 'light');
185:     flushSync(() => update(next => { next.darkMode = isDark; }));
186:     hostRef.current.setAttribute('data-theme', isDark ? 'dark' : 'light');
187:     viewport.classList.add('no-theme-transitions');
188:     const clipY = cy + scrollY;
189:     viewport.style.clipPath = `circle(0px at ${cx}px ${clipY}px)`;
190:     const started = performance.now();
191:     function step(now) {
192:       const progress = Math.min((now - started) / 660, 1);
193:       const eased = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
194:       viewport.style.clipPath = `circle(${(eased * maxRadius).toFixed(1)}px at ${cx}px ${clipY}px)`;
195:       if (progress < 1) timers.current.wipe = requestAnimationFrame(step);
196:       else {
197:         viewport.style.clipPath = 'none';
198:         viewport.classList.remove('no-theme-transitions');
199:         underlay.classList.add('hidden');
200:         underlay.replaceChildren();
201:       }
202:     }
203:     timers.current.wipe = requestAnimationFrame(step);
204:   }
