453:                     "color": "var(--text-muted)"
454:                   }} onClick={() => showToast('Select an invoice or receipt to attach')}>{" "}<svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">{" "}<path strokeLinecap="round" strokeLinejoin="round" d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />{" "}</svg>{" "}</button>{" "}<input id="chat-composer-input" type="text" className="bg-transparent text-[12.5px] outline-none flex-1" style={{
455:                     "color": "var(--text-primary)"
