462:     if (event.target === event.currentTarget) setModal(null);
463:   }}>{" "}<div className="v-card max-w-md w-full p-6 shadow-2xl">{" "}<div className="flex items-center justify-between mb-4">{" "}<h3 id="v-modal-title" className="font-display text-[18px] font-semibold" style={{
464:           "color": "var(--text-primary)"
465:         }}>{modalTitle}</h3>{" "}<button type="button" id="v-modal-close" className="w-8 h-8 rounded-full v-subcard flex items-center justify-center text-sm" style={{
466:           "color": "var(--text-secondary)"
467:         }} onClick={() => setModal(null)}>✕</button>{" "}</div>{" "}<div id="v-modal-body" className="space-y-3 text-[13px]">{renderModal()}</div>{" "}</div>{" "}</div>{" "}</></>, shadowRoot)}
468:   </div>;
469: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Branch;
 11: use App\Models\Order;
 12: use App\Models\OrderItem;
 13: use App\Models\StockLevel;
 14: use App\Models\StockMovement;
 15: use Illuminate\Database\Eloquent\Builder;
 16: use Illuminate\Support\Facades\DB;
 17: 
 18: /**
 19:  * توزيع الطلب على الفروع وحجز مخزونه (reserved) عبر InventoryService حصرًا.
 20:  *
 21:  * الخوارزمية:
 22:  * 1. فرع مُجبر من الأدمن: يُتحقق من تغطيته ويُحجز منه.
 23:  * 2. أول فرع نشط واحد يغطي الطلب كاملًا — أولوية لفرع نفس مدينة العميل.
 24:  * 3. وإلا: كل صنف من الفرع الأعلى رصيدًا متاحًا له (الصنف كاملًا من فرع واحد).
 25:  *
 26:  * داخل الفرع الواحد قد يتوزع الصنف على أكثر من موقع (الأعلى متاحًا أولًا).
 27:  * أي نقص في أي صنف يُلغي العملية كلها (transaction واحدة — لا حجز جزئي يتسرب).
 28:  */
 29: class OrderAllocationService
 30: {
 31:     public function __construct(protected InventoryService $inventoryService) {}
 32: 
 33:     public function allocate(Order $order, ?int $forcedBranchId = null, ?int $performedBy = null): Order
 34:     {
 35:         return DB::transaction(function () use ($order, $forcedBranchId, $performedBy): Order {
 36:             // إعادة قراءة الطلب بقفل صف قبل فحص التوزيع السابق (C1)
 37:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 38:             $order->load('items');
 39:             // ترتيب قفل عام ثابت (F-02): البنود بترتيب product_variant_id
 40:             // في كل المسارات حتى لا ينتظر طلبان بعضهما دائريًا (40P01)
 41:             $order->setRelation('items', $order->items
 42:                 ->sortBy(fn (OrderItem $item): int => (int) $item->product_variant_id)
 43:                 ->values());
 44:             $performedBy ??= auth()->id();
 45: 
 46:             if ($order->allocated_branch_id !== null
 47:                 || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null)) {
 48:                 throw new BusinessException('الطلب مُوزّع على الفروع من قبل؛ ألغِ التوزيع الحالي أولًا قبل إعادة التوزيع.');
 49:             }
 50: 
 51:             // قفل صفوف الأرصدة المرشّحة بترتيب ثابت قبل حساب التغطية (F8):
 52:             // متزامنان لا يقرآن «متاح» نفسه ثم يحجزان أكثر من الرصيد. القفل
 53:             // المجمّع على (branch_id, product_variant_id) غير ممكن، فتُقفل
 54:             // الصفوف الخام كلها بترتيب المنتج ثم المعرّف لمنع الجمود
 55:             $this->lockStockRows($order);
 56: 
 57:             // 1. فرع مُجبر يدويًا
 58:             if ($forcedBranchId !== null) {
 59:                 $branch = Branch::query()->where('is_active', true)->find($forcedBranchId);
 60:                 if ($branch === null) {
 61:                     throw new BusinessException('الفرع المحدد غير موجود أو غير نشط.');
 62:                 }
 63:                 $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
 64:                 $order->update(['allocated_branch_id' => $branch->id]);
 65: 
 66:                 return $order->fresh(['items']);
 67:             }
 68: 
 69:             // خريطة تغطية واحدة مجمّعة لكل الفروع والأصناف (M15) بدل
 70:             // استعلام لكل فرع × صنف — القرارات التالية كلها في الذاكرة
 71:             $coverage = $this->branchAvailabilityMap($order);
 72: 
 73:             // 2. فرع واحد يغطي الطلب كاملًا (أولوية لنفس مدينة العميل:
 74:             // بالمعرّف أولًا ثم بمطابقة الاسم كرجوع — L5)
 75:             $cityName = $order->city?->name_ar;
 76:             $branches = Branch::query()
 77:                 ->where('is_active', true)
 78:                 ->when($order->city_id !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city_id = ? THEN 0 ELSE 1 END', [$order->city_id]))
 79:                 // CASE لا «city = ? DESC» (F17): في Postgres ترتيب DESC يضع
 80:                 // NULL أولًا فتتقدّم فروع بلا مدينة معلنة على فرع مدينة العميل
 81:                 ->when($cityName !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city = ? THEN 0 ELSE 1 END', [$cityName]))
 82:                 ->orderBy('id')
 83:                 ->get();
 84: 
 85:             foreach ($branches as $branch) {
 86:                 if ($this->canBranchFulfillFullOrder($order, $branch->id, $coverage)) {
 87:                     $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
 88:                     $order->update(['allocated_branch_id' => $branch->id]);
 89: 
 90:                     return $order->fresh(['items']);
 91:                 }
 92:             }
 93: 
 94:             // 3. كل صنف من الفرع الأعلى رصيدًا متاحًا له
 95:             foreach ($order->items as $item) {
 96:                 $branchId = $this->bestBranchForItem($item, $coverage);
 97:                 if ($branchId === null) {
 98:                     throw new BusinessException("الرصيد المتاح غير كافٍ للصنف ({$item->sku_snapshot}) في أي فرع.");
 99:                 }
100:                 $this->reserveItemFromBranch($order, $item, $branchId, $performedBy);
101:                 $item->update(['allocated_branch_id' => $branchId]);
102:             }
103: 
104:             return $order->fresh(['items']);
105:         });
106:     }
107: 
108:     /**
109:      * فك توزيع الطلب (M5): يُحرّر كل حجوزات الطلب من وعاء reserved ويعيده
110:      * إلى «غير موزّع» — كان endpoint التوزيع يشير لهذه العملية في رسالته
111:      * بينما لا سبيل لتنفيذها. الحجوزات تُقرأ من دفتر الحركات نفسه، فلا يعتمد
112:      * الفك على حالة مشتقة قابلة للانحراف.
113:      */
114:     public function deallocate(Order $order, ?int $performedBy = null): Order
115:     {
116:         return DB::transaction(function () use ($order, $performedBy): Order {
117:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
118:             $order->load('items');
119:             // ترتيب قفل عام ثابت كالتوزيع (F-02) لتفادي الجمود
120:             $order->setRelation('items', $order->items
121:                 ->sortBy(fn (OrderItem $item): int => (int) $item->product_variant_id)
122:                 ->values());
123:             $performedBy ??= auth()->id();
124: 
125:             if (! $this->isAllocated($order)) {
126:                 throw new BusinessException('الطلب غير موزّع على أي فرع؛ لا شيء لفكه.');
127:             }
128: 
129:             // حركات الحجز تُقفل بترتيب ثابت ثم يُعكس كل منها بإفراج مقابل
130:             $reservations = StockMovement::query()
131:                 ->where('reference_type', $order->getMorphClass())
132:                 ->where('reference_id', $order->id)
133:                 ->where('type', StockMovementType::Reserve->value)
134:                 ->orderBy('product_variant_id')
135:                 ->orderBy('id')
136:                 ->lockForUpdate()
137:                 ->get();
138: 
139:             foreach ($reservations as $movement) {
140:                 $this->inventoryService->recordMovement([
141:                     'product_variant_id' => (int) $movement->product_variant_id,
142:                     'branch_id' => (int) $movement->branch_id,
143:                     'location_id' => $movement->location_id,
144:                     'type' => StockMovementType::ReleaseReserve,
145:                     'affected_bucket' => StockBucket::Reserved,
146:                     'quantity' => -1 * (float) $movement->quantity,
147:                     'reference_type' => Order::class,
148:                     'reference_id' => $order->id,
149:                     'created_by' => $performedBy,
150:                     'notes' => "فك يدوي لتوزيع الطلب رقم {$order->order_number}",
151:                 ]);
152:             }
153: 
154:             $order->items()->update(['allocated_branch_id' => null]);
155:             $order->update(['allocated_branch_id' => null]);
156: 
157:             return $order->fresh(['items']);
158:         });
159:     }
160: 
161:     /** هل الطلب موزّع على أي فرع (على مستوى الطلب أو أي بند)؟ */
162:     public function isAllocated(Order $order): bool
163:     {
164:         return $order->allocated_branch_id !== null
165:             || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null);
166:     }
167: 
168:     /** قفل صفوف أرصدة أصناف الطلب بترتيب ثابت (منتج ثم معرّف) — F8. */
169:     private function lockStockRows(Order $order): void
170:     {
171:         $variantIds = $order->items
172:             ->map(fn (OrderItem $item): int => (int) $item->product_variant_id)
173:             ->unique()->sort()->values()->all();
174:         if ($variantIds === []) {
175:             return;
176:         }
177: 
178:         StockLevel::query()
179:             ->whereIn('product_variant_id', $variantIds)
180:             ->orderBy('product_variant_id')
181:             ->orderBy('id')
182:             ->lockForUpdate()
183:             ->get();
184:     }
185: 
186:     /**
187:      * تغطية الفروع لأصناف الطلب باستعلام واحد مجمّع (M15):
188:      * ‏[branch_id][variant_id] => مجموع المتاح في المواقع النشطة.
189:      *
190:      * @return array<int, array<int, float>>
191:      */
192:     private function branchAvailabilityMap(Order $order): array
193:     {
194:         $variantIds = $order->items
195:             ->map(fn (OrderItem $item): int => (int) $item->product_variant_id)
196:             ->unique()->values()->all();
197: 
198:         $rows = StockLevel::query()
199:             ->whereIn('product_variant_id', $variantIds)
200:             ->whereHas('branch', fn (Builder $q): Builder => $q->where('is_active', true))
201:             ->where(fn (Builder $q): Builder => $q
202:                 ->whereNull('location_id')
203:                 ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)))
204:             ->groupBy('branch_id', 'product_variant_id')
205:             ->selectRaw('branch_id, product_variant_id, SUM(available) as total_available')
206:             ->get();
207: 
208:         $map = [];
209:         foreach ($rows as $row) {
210:             $map[(int) $row->branch_id][(int) $row->product_variant_id] = (float) $row->total_available;
211:         }
212: 
213:         return $map;
214:     }
215: 
216:     /** @param array<int, array<int, float>> $coverage */
217:     private function canBranchFulfillFullOrder(Order $order, int $branchId, array $coverage): bool
218:     {
219:         foreach ($order->items as $item) {
220:             if (($coverage[$branchId][(int) $item->product_variant_id] ?? 0) < (float) $item->qty) {
221:                 return false;
222:             }
223:         }
224: 
225:         return true;
226:     }
227: 
228:     /** @param array<int, array<int, float>> $coverage */
229:     private function bestBranchForItem(OrderItem $item, array $coverage): ?int
230:     {
231:         $best = null;
232:         $bestAvailable = 0.0;
233:         foreach ($coverage as $branchId => $variants) {
234:             $available = $variants[(int) $item->product_variant_id] ?? 0;
235:             if ($available >= (float) $item->qty && $available > $bestAvailable) {
236:                 $best = $branchId;
237:                 $bestAvailable = $available;
238:             }
239:         }
240: 
241:         return $best;
242:     }
243: 
244:     private function reserveItemsFromBranch(Order $order, int $branchId, ?int $performedBy): void
245:     {
246:         foreach ($order->items as $item) {
247:             $this->reserveItemFromBranch($order, $item, $branchId, $performedBy);
248:             $item->update(['allocated_branch_id' => $branchId]);
249:         }
250:     }
251: 
252:     /**
253:      * حجز كمية الصنف من فرع واحد، موزعة على مواقعه الأعلى متاحًا عند الحاجة.
254:      */
255:     private function reserveItemFromBranch(Order $order, OrderItem $item, int $branchId, ?int $performedBy): void
256:     {
257:         $remaining = (float) $item->qty;
258:         // قفل صفوف الأرصدة بترتيب ثابت (id) حتى لا يُحجز نفس الرصيد مرتين (H10)
259:         $levels = $this->usableLevels((int) $item->product_variant_id, $branchId)
260:             ->where('available', '>', 0)
261:             ->orderBy('id')
262:             ->lockForUpdate()
263:             ->get();
264: 
265:         foreach ($levels as $level) {
266:             if ($remaining <= 0) {
267:                 break;
268:             }
269:             $take = min((float) $level->available, $remaining);
270:             $this->inventoryService->recordMovement([
271:                 'product_variant_id' => (int) $item->product_variant_id,
272:                 'branch_id' => $branchId,
273:                 'location_id' => $level->location_id,
274:                 'type' => StockMovementType::Reserve,
275:                 'affected_bucket' => StockBucket::Reserved,
276:                 'quantity' => $take,
277:                 'reference_type' => Order::class,
278:                 'reference_id' => $order->id,
279:                 'created_by' => $performedBy,
280:                 'notes' => "حجز للطلب رقم {$order->order_number}",
281:             ]);
282:             $remaining -= $take;
283:         }
284: 
285:         if ($remaining > 0) {
286:             throw new BusinessException("الفرع المحدد لا يمتلك كمية كافية من الصنف ({$item->sku_snapshot}).");
287:         }
288:     }
289: 
290:     /**
291:      * صفوف رصيد قابلة للاستخدام: رصيد الفرع/المتغير في مواقع نشطة
292:      * (أو بلا موقع) — الحجز لا يخرج من موقع معطّل.
293:      *
294:      * @return Builder<StockLevel>
295:      */
296:     private function usableLevels(int $variantId, ?int $branchId = null): Builder
297:     {
298:         return StockLevel::query()
299:             ->where('product_variant_id', $variantId)
300:             ->when($branchId !== null, fn (Builder $q): Builder => $q->where('branch_id', $branchId))
301:             ->where(fn (Builder $q): Builder => $q
302:                 ->whereNull('location_id')
303:                 ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)));
304:     }
305: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\Setting;
  9: use Illuminate\Support\Facades\Cache;
 10: use Illuminate\Support\Facades\DB;
 11: use InvalidArgumentException;
 12: use JsonException;
 13: 
 14: class SettingService
 15: {
 16:     /** @var array<string, array{0: string, 1: int}> بادئة وحشو الترقيم لكل نوع — يُقرآن مرة واحدة لكل طلب (M11). */
 17:     private array $numberingConfig = [];
 18: 
 19:     private const CACHE_KEY = 'app_settings_static';
 20: 
 21:     private const CACHE_TTL_SECONDS = 3600;
 22: 
 23:     /** @var list<string> */
 24:     private const NUMBERING_COUNTER_KEYS = [
 25:         'invoice_next_number',
 26:         'order_next_number',
 27:         'purchase_order_next_number',
 28:         'quotation_next_number',
 29:         'movement_next_number',
 30:         'transfer_next_number',
 31:         'stocktake_next_number',
 32:         'return_next_number',
 33:         'purchase_request_next_number',
 34:         'delivery_next_number',
 35:         'supplier_invoice_next_number',
 36:         'supplier_payment_next_number',
 37:     ];
 38: 
 39:     /** مستندات داخلية تُرقَّم بتسلسل PostgreSQL (فجوات مقبولة) حتى لا يُحتجز قفل العداد داخل معاملات طويلة. */
 40:     private const SEQUENCE_TYPES = [
 41:         'order' => 'order_next_number',
 42:         'purchase_order' => 'purchase_order_next_number',
 43:         'quotation' => 'quotation_next_number',
 44:         'transfer' => 'transfer_next_number',
 45:         'stocktake' => 'stocktake_next_number',
 46:         'return' => 'return_next_number',
 47:         'purchase_request' => 'purchase_request_next_number',
 48:         'delivery' => 'delivery_next_number',
 49:         'supplier_invoice' => 'supplier_invoice_next_number',
 50:         'supplier_payment' => 'supplier_payment_next_number',
 51:     ];
 52: 
 53:     /**
 54:      * Return all settings grouped by their group name, with values cast to their declared types.
 55:      * Numbering counters are read fresh because they change for every generated document number.
 56:      *
 57:      * @return array<string, array<string, mixed>>
 58:      */
 59:     public function getAllGrouped(): array
 60:     {
 61:         $grouped = Cache::remember(self::CACHE_KEY, self::CACHE_TTL_SECONDS, function (): array {
 62:             return Setting::query()
 63:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
 64:                 ->orderBy('group')
 65:                 ->orderBy('key')
 66:                 ->get()
 67:                 ->groupBy('group')
 68:                 ->map(fn ($settings): array => $settings
 69:                     ->mapWithKeys(fn (Setting $setting): array => [
 70:                         $setting->key => $this->castValue($setting->value, $setting->type),
 71:                     ])
 72:                     ->all())
 73:                 ->all();
 74:         });
 75: 
 76:         $counters = Setting::query()
 77:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 78:             ->orderBy('key')
 79:             ->get()
 80:             ->mapWithKeys(fn (Setting $setting): array => [
 81:                 $setting->key => $this->castValue($setting->value, $setting->type),
 82:             ])
 83:             ->all();
 84: 
 85:         if (isset($counters['movement_next_number'])) {
 86:             $counters['movement_next_number'] = $this->nextMovementNumber();
 87:         }
 88:         foreach (self::SEQUENCE_TYPES as $type => $key) {
 89:             if (isset($counters[$key])) {
 90:                 $counters[$key] = $this->nextDocumentNumber($type);
 91:             }
 92:         }
 93: 
 94:         if ($counters !== []) {
 95:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
 96:             ksort($grouped['numbering']);
 97:         }
 98: 
 99:         return $grouped;
100:     }
101: 
102:     public function get(string $key, mixed $default = null): mixed
103:     {
104:         foreach ($this->getAllGrouped() as $settings) {
105:             if (array_key_exists($key, $settings)) {
106:                 return $settings[$key];
107:             }
108:         }
109: 
110:         return $default;
111:     }
112: 
113:     /**
114:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
115:      *
116:      * @param  array<string, mixed>  $settings
117:      *
118:      * @throws JsonException
119:      */
120:     public function updateBatch(array $settings): void
121:     {
122:         DB::transaction(function () use ($settings): void {
123:             $movementSequenceTarget = null;
124:             /** @var array<string, int> $documentSequenceTargets */
125:             $documentSequenceTargets = [];
126:             $lockedSettings = Setting::query()
127:                 ->whereIn('key', array_keys($settings))
128:                 ->orderBy('key')
129:                 ->lockForUpdate()
130:                 ->get()
131:                 ->keyBy('key');
132: 
133:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
134: 
135:             if ($missingKeys !== []) {
136:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
137:             }
138: 
139:             foreach ($settings as $key => $value) {
140:                 /** @var Setting $setting */
141:                 $setting = $lockedSettings->get($key);
142: 
143:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
144:                     $value = max($this->counterValue($setting->value), $this->counterValue($value));
145:                     if ($key === 'movement_next_number') {
146:                         $value = max($value, $this->nextMovementNumber());
147:                         $movementSequenceTarget = $value;
148:                     }
149:                     $sequenceType = array_search($key, self::SEQUENCE_TYPES, true);
150:                     if (is_string($sequenceType)) {
151:                         $value = max($value, $this->nextDocumentNumber($sequenceType));
152:                         $documentSequenceTargets[$sequenceType] = $value;
153:                     }
154:                 }
155: 
156:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
157:                     ? ''
158:                     : $this->serializeValue($value, $setting->type);
159:                 $setting->save();
160:             }
161: 
162:             DB::afterCommit(fn () => $this->clearCache());
163: 
164:             if ($movementSequenceTarget !== null) {
165:                 // مزامنة التسلسل بعد الاعتماد لا داخله: ALTER SEQUENCE داخل
166:                 // المعاملة كان يحجب كل nextval (أي كل حركات المخزون) حتى نهاية
167:                 // معاملة الإعدادات (L-9). الدالة تقفل الترقيم لمدة الاستعلام
168:                 // نفسه وتنسّق رفع الحد الأدنى مع كل تخصيص جديد لمنع إعادة رقم.
169:                 DB::afterCommit(function () use ($movementSequenceTarget): void {
170:                     DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]);
171:                 });
172:             }
173:             if ($documentSequenceTargets !== []) {
174:                 DB::afterCommit(function () use ($documentSequenceTargets): void {
175:                     foreach ($documentSequenceTargets as $type => $minimum) {
176:                         DB::selectOne('SELECT document_next_number(?, ?) AS number', [$type, $minimum]);
177:                     }
178:                 });
179:             }
180:         }, attempts: 3);
181:     }
182: 
183:     /**
184:      * Atomically return and increment the next document number for the requested type.
185:      *
186:      * @throws JsonException
187:      */
188:     public function generateNextNumber(string $type): string
189:     {
190:         if ($type === 'movement') {
191:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
192:             $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;
193: 
194:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
195:         }
196:         if (isset(self::SEQUENCE_TYPES[$type])) {
197:             $definitions = $this->numberingDefinitions();
198:             $definition = $definitions[$type];
199:             [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
200:             $number = DB::selectOne('SELECT document_next_number(?) AS number', [$type])->number;
201: 
202:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
203:         }
204:         $definitions = $this->numberingDefinitions();
205: 
206:         if (! isset($definitions[$type])) {
207:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
208:         }
209: 
210:         $definition = $definitions[$type];
211:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
212: 
213:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
214:             // العداد وحده يُقفل ويُقرأ طازجًا كل مرة؛ البادئة والحشو من ذاكرة الطلب.
215:             $nextSetting = Setting::query()
216:                 ->where('key', $definition['next'])
217:                 ->lockForUpdate()
218:                 ->first();
219: 
220:             if ($nextSetting === null) {
221:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
222:             }
223: 
224:             $nextValue = $this->counterValue($nextSetting->value);
225: 
226:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
227:             $nextSetting->value = (string) ($nextValue + 1);
228:             $nextSetting->save();
229: 
230:             return $formatted;
231:         }, attempts: 3);
232:     }
233: 
234:     /**
235:      * بادئة وحشو نوع ترقيم — قراءة واحدة لكل طلب بدل استعلام مع كل حركة/مستند.
236:      *
237:      * @return array{0: string, 1: int}
238:      */
239:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
240:     {
241:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
242:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
243: 
244:             foreach ([$prefixKey, $paddingKey] as $key) {
245:                 if (! $settings->has($key)) {
246:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
247:                 }
248:             }
249: 
250:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
251:         })();
252:     }
253: 
254:     public function clearCache(): void
255:     {
256:         Cache::forget(self::CACHE_KEY);
257:         $this->numberingConfig = [];
258:     }
259: 
260:     /**
261:      * @return array<string, array{prefix: string, next: string, padding: string}>
262:      */
263:     private function numberingDefinitions(): array
264:     {
265:         return [
266:             'invoice' => ['prefix' => 'invoice_prefix', 'next' => 'invoice_next_number', 'padding' => 'invoice_padding'],
267:             'order' => ['prefix' => 'order_prefix', 'next' => 'order_next_number', 'padding' => 'order_padding'],
268:             'purchase_order' => ['prefix' => 'purchase_order_prefix', 'next' => 'purchase_order_next_number', 'padding' => 'purchase_order_padding'],
269:             'quotation' => ['prefix' => 'quotation_prefix', 'next' => 'quotation_next_number', 'padding' => 'quotation_padding'],
270:             'transfer' => ['prefix' => 'transfer_prefix', 'next' => 'transfer_next_number', 'padding' => 'transfer_padding'],
271:             'stocktake' => ['prefix' => 'stocktake_prefix', 'next' => 'stocktake_next_number', 'padding' => 'stocktake_padding'],
272:             'return' => ['prefix' => 'return_prefix', 'next' => 'return_next_number', 'padding' => 'return_padding'],
273:             'purchase_request' => ['prefix' => 'purchase_request_prefix', 'next' => 'purchase_request_next_number', 'padding' => 'purchase_request_padding'],
274:             'delivery' => ['prefix' => 'delivery_prefix', 'next' => 'delivery_next_number', 'padding' => 'delivery_padding'],
275:             'supplier_invoice' => ['prefix' => 'supplier_invoice_prefix', 'next' => 'supplier_invoice_next_number', 'padding' => 'supplier_invoice_padding'],
276:             'supplier_payment' => ['prefix' => 'supplier_payment_prefix',    'next' => 'supplier_payment_next_number',    'padding' => 'supplier_payment_padding'],
277:             'shift' => ['prefix' => 'shift_prefix',               'next' => 'shift_next_number',               'padding' => 'shift_padding'],
278:             'expense' => ['prefix' => 'expense_prefix',             'next' => 'expense_next_number',             'padding' => 'expense_padding'],
279:             'treasury_transfer' => ['prefix' => 'treasury_transfer_prefix',   'next' => 'treasury_transfer_next_number',   'padding' => 'treasury_transfer_padding'],
280:             'payment_notice' => ['prefix' => 'payment_notice_prefix',      'next' => 'payment_notice_next_number',      'padding' => 'payment_notice_padding'],
281:         ];
282:     }
283: 
284:     private function nextMovementNumber(): int
285:     {
286:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
287: 
288:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
289:     }
290: 
291:     private function nextDocumentNumber(string $type): int
292:     {
293:         if (! isset(self::SEQUENCE_TYPES[$type])) {
294:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
295:         }
296:         $sequence = DB::selectOne("SELECT last_value, is_called FROM document_{$type}_number_seq");
297: 
298:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
299:     }
300: 
301:     private function counterValue(mixed $value): int
302:     {
303:         $number = (is_int($value) || is_string($value))
304:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
305:             : false;
306:         if ($number === false) {
307:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
308:         }
309: 
310:         return $number;
311:     }
312: 
313:     private function castValue(?string $value, string $type): mixed
314:     {
315:         if ($value === null) {
316:             return null;
317:         }
318: 
319:         return match ($type) {
320:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
321:             'integer' => (int) $value,
322:             'float' => (float) $value,
323:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
324:             default => $value,
325:         };
326:     }
327: 
328:     /** @throws JsonException */
329:     private function serializeValue(mixed $value, string $type): ?string
330:     {
331:         if ($value === null) {
332:             return null;
333:         }
334: 
335:         if ($type === 'json') {
336:             return json_encode($value, JSON_THROW_ON_ERROR);
337:         }
338: 
339:         if ($type === 'boolean') {
340:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
341:         }
342: 
343:         return (string) $value;
344:     }
345: }

  1: <?php
  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Http\Controllers\Controller;
 10: use App\Http\Requests\Admin\Order\AllocateOrderRequest;
 11: use App\Http\Requests\Admin\Order\CreateShipmentRequest;
 12: use App\Http\Requests\Admin\Order\UpdateOrderPaymentRequest;
 13: use App\Http\Requests\Admin\Order\UpdateOrderStatusRequest;
 14: use App\Http\Resources\Admin\AdminOrderResource;
 15: use App\Http\Resources\Admin\ShipmentResource;
 16: use App\Models\Order;
 17: use App\Services\OrderAllocationService;
 18: use App\Services\OrderService;
 19: use App\Services\ShipmentService;
 20: use Illuminate\Http\Request;
 21: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 22: use Illuminate\Routing\Controllers\HasMiddleware;
 23: use Illuminate\Routing\Controllers\Middleware;
 24: use Illuminate\Support\Carbon;
 25: use Illuminate\Support\Facades\DB;
 26: use Illuminate\Validation\Rule;
 27: 
 28: /** إدارة الطلبات: عرض وفلترة، تغيير الحالة عبر OrderService، وتوزيع يدوي/مُجبر. */
 29: class OrderController extends Controller implements HasMiddleware
 30: {
 31:     /**
 32:      * آلة انتقالات حالة الدفع (H4): تمنع الحالات المستحيلة مثل refunded→unpaid
 33:      * وpaid→failed ووضع paid على طلب ملغى بلا التزام استرداد.
 34:      */
 35:     private const PAYMENT_TRANSITIONS = [
 36:         'unpaid' => ['paid', 'failed'],
 37:         'failed' => ['paid', 'unpaid'],
 38:         'paid' => ['refunded'],
 39:         'refunded' => [],
 40:     ];
 41: 
 42:     public function __construct(
 43:         private readonly OrderService $orders,
 44:         private readonly OrderAllocationService $allocation,
 45:         private readonly ShipmentService $shipments,
 46:     ) {}
 47: 
 48:     public static function middleware(): array
 49:     {
 50:         return [
 51:             new Middleware('can:orders.view', only: ['index', 'show']),
 52:             new Middleware('can:orders.update', only: ['updateStatus', 'createShipment']),
 53:             // صلاحية مالية منفصلة (H4): تغيير الحالة التشغيلية لا يمنح تعديل الدفع
 54:             new Middleware('can:orders.payment', only: ['updatePayment']),
 55:             new Middleware('can:orders.allocate', only: ['allocate', 'deallocate']),
 56:         ];
 57:     }
 58: 
 59:     public function index(Request $request): AnonymousResourceCollection
 60:     {
 61:         $filters = $request->validate([
 62:             'status' => ['nullable', Rule::in(array_column(OrderStatus::cases(), 'value'))],
 63:             'allocated_branch_id' => ['nullable', 'integer', 'min:1'],
 64:             'payment_method' => ['nullable', Rule::in(['cod', 'card', 'wallet', 'bank_transfer', 'credit'])],
 65:             'date_from' => ['nullable', 'date'],
 66:             'date_to' => ['nullable', 'date'],
 67:             'search' => ['nullable', 'string', 'max:100'],
 68:             // تظهر العلامتان في المورد بلا شاشة تصفية (F-29): تُتاح الآن كفلتر
 69:             'needs_attention' => ['nullable', 'boolean'],
 70:             'requires_refund' => ['nullable', 'boolean'],
 71:         ]);
 72: 
 73:         $orders = Order::query()
 74:             ->with(['customer', 'allocatedBranch'])
 75:             ->withCount('items')
 76:             ->when($filters['status'] ?? null, fn ($q, $status) => $q->where('status', $status))
 77:             ->when($filters['allocated_branch_id'] ?? null, fn ($q, $branchId) => $q->where('allocated_branch_id', $branchId))
 78:             ->when($filters['payment_method'] ?? null, fn ($q, $method) => $q->where('payment_method', $method))
 79:             ->when(array_key_exists('needs_attention', $filters) && $filters['needs_attention'] !== null,
 80:                 fn ($q) => $q->where('needs_attention', (bool) $filters['needs_attention']))
 81:             ->when(array_key_exists('requires_refund', $filters) && $filters['requires_refund'] !== null,
 82:                 fn ($q) => $q->where('requires_refund', (bool) $filters['requires_refund']))
 83:             // نطاق زمني بدل whereDate حتى يعمل فهرس created_at (M16)،
 84:             // بمنطقة العمل ثم يُخزّن/يُقارن بـ UTC
 85:             ->when($filters['date_from'] ?? null, fn ($q, $date) => $q->where('created_at', '>=',
 86:                 Carbon::parse($date, (string) config('app.business_timezone'))->startOfDay()->utc()))
 87:             ->when($filters['date_to'] ?? null, fn ($q, $date) => $q->where('created_at', '<',
 88:                 Carbon::parse($date, (string) config('app.business_timezone'))->startOfDay()->addDay()->utc()))
 89:             // بحث مُقسَّم حسب شكل المدخل (F11): الرقمي على رقم الطلب/الهاتف
 90:             // بالبادئة (فهرسي text_pattern_ops)، والنصي يضيف الاسم بالاحتواء
 91:             // عبر فهرس pg_trgm — فلا يُشغَّل فحص الاسم على مدخل رقمي،
 92:             // وتهريب محارف LIKE يمنع حقن الأنماط (M16)
 93:             ->when($filters['search'] ?? null, fn ($q, $term) => $q->where(function ($inner) use ($term): void {
 94:                 $escaped = str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], (string) $term);
 95:                 $numeric = preg_match('/^\s*[0-9+\-\s()]+\s*$/', (string) $term) === 1;
 96:                 $inner->where('order_number', 'like', $escaped.'%')
 97:                     ->orWhere('guest_phone', 'like', $escaped.'%')
 98:                     ->orWhere('guest_phone_normalized', 'like', $escaped.'%');
 99:                 if (! $numeric) {
100:                     $inner->orWhere('guest_name', 'ilike', '%'.$escaped.'%');
101:                 }
102:             }))
103:             ->latest('id')
104:             ->paginate(20);
105: 
106:         return AdminOrderResource::collection($orders);
107:     }
108: 
109:     public function show(Order $order): AdminOrderResource
110:     {
111:         return $this->orderResource($order);
112:     }
113: 
114:     public function updateStatus(UpdateOrderStatusRequest $request, Order $order): AdminOrderResource
115:     {
116:         // الشحن له بوليصة ومسار مخزون: من إنشاء البوليصة فقط (L3) —
117:         // وضع Shipped يدويًا يترك الطلب بلا بوليصة فلا يصله ويب هوك تسليم
118:         if (($request->validated()['status'] ?? null) === OrderStatus::Shipped->value) {
119:             throw new BusinessException('حالة الشحن تتم فقط عبر إنشاء بوليصة شحن للطلب.');
120:         }
121: 
122:         $order = $this->orders->changeStatus(
123:             $order,
124:             (string) $request->validated()['status'],
125:             $request->user(),
126:             $request->validated()['notes'] ?? null,
127:         );
128: 
129:         return $this->orderResource($order);
130:     }
131: 
132:     /**
133:      * تحديث حالة الدفع يدويًا (F6): مسار إداري صريح بدل الترقيع عبر تغيير
134:      * الحالة. يُسجّل التغيير في سجل الطلب بالمنفّذ والملاحظة للتدقيق.
135:      */
136:     public function updatePayment(UpdateOrderPaymentRequest $request, Order $order): AdminOrderResource
137:     {
138:         $data = $request->validated();
139:         $to = (string) $data['payment_status'];
140: 
141:         // قفل صف + transaction (H4): سباق مع ويب هوك الدفع كان يضيّع تحديث
142:         // أحدهما (lost update)، وآلة انتقالات تمنع الحالات المستحيلة.
143:         $order = DB::transaction(function () use ($order, $to, $data, $request): Order {
144:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
145:             $from = $order->payment_status;
146: 
147:             if ($from === $to) {
148:                 return $order;
149:             }
150:             if (! in_array($to, self::PAYMENT_TRANSITIONS[$from] ?? [], true)) {
151:                 throw new BusinessException("انتقال حالة دفع غير مسموح: من ({$from}) إلى ({$to}).");
152:             }
153: 
154:             // حالة الاسترداد تتبع حالة الطلب لا القيمة القادمة (H4): دفع على
155:             // طلب ملغى/مرتجع يستلزم استردادًا، والاسترداد يُسقط الالتزام.
156:             // ضبط requires_refund مباشرة من $to كان يمحو الالتزام بصمت.
157:             $requiresRefund = $to === 'paid'
158:                 && in_array($order->status, [OrderStatus::Cancelled, OrderStatus::Returned], true);
159:             if ($to === 'refunded') {
160:                 $requiresRefund = false;
161:             }
162: 
163:             $order->update([
164:                 'payment_status' => $to,
165:                 'requires_refund' => $requiresRefund,
166:             ]);
167: 
168:             $actor = $request->user();
169:             $notes = trim("تحديث يدوي لحالة الدفع: {$from} ← {$to}. ".($data['notes'] ?? ''));
170:             $order->statusHistories()->create([
171:                 'from_status' => $order->status,
172:                 'to_status' => $order->status,
173:                 'changed_by_type' => $actor?->getMorphClass(),
174:                 'changed_by_id' => $actor?->getKey(),
175:                 'notes' => mb_substr($notes, 0, 500),
176:             ]);
177: 
178:             return $order;
179:         });
180: 
181:         return $this->orderResource($order);
182:     }
183: 
184:     /** إنشاء بوليصة شحن للطلب وتحويله إلى SHIPPED عبر OrderService. */
185:     public function createShipment(CreateShipmentRequest $request, Order $order): ShipmentResource
186:     {
187:         $shipment = $this->shipments->createForOrder(
188:             $order,
189:             (int) $request->validated()['shipping_company_id'],
190:             $request->validated()['awb_number'] ?? null,
191:             $request->user(),
192:         );
193: 
194:         return ShipmentResource::make($shipment);
195:     }
196: 
197:     public function allocate(AllocateOrderRequest $request, Order $order): AdminOrderResource
198:     {
199:         if (! in_array($order->status, [OrderStatus::Confirmed, OrderStatus::Processing], true)) {
200:             throw new BusinessException('التوزيع متاح فقط لطلب مؤكد أو قيد التجهيز.');
201:         }
202: 
203:         $order = $this->allocation->allocate(
204:             $order,
205:             $request->validated()['branch_id'] ?? null,
206:             (int) $request->user()->id,
207:         );
208: 
209:         return $this->orderResource($order);
210:     }
211: 
212:     /** فك توزيع الطلب (M5) — عكس allocate، يُحرّر الحجوزات ويعيد الطلب غير موزّع. */
213:     public function deallocate(Request $request, Order $order): AdminOrderResource
214:     {
215:         if (! in_array($order->status, [OrderStatus::Confirmed, OrderStatus::Processing], true)) {
216:             throw new BusinessException('فك التوزيع متاح فقط لطلب مؤكد أو قيد التجهيز.');
217:         }
218: 
219:         $order = $this->allocation->deallocate($order, (int) $request->user()->id);
220: 
221:         return $this->orderResource($order);
222:     }
223: 
224:     private function orderResource(Order $order): AdminOrderResource
225:     {
226:         return AdminOrderResource::make(
227:             $order->load(['items', 'statusHistories', 'customer', 'city', 'allocatedBranch'])
228:         );
229:     }
230: }

