 1: import { hasPermission } from '@alfarid/utils';
 2: import { defaultApiClient, resolveServiceUrl } from '@alfarid/api-client';
 3: import { ProtectedRoute } from './components/auth/ProtectedRoute';
 4: import AuthCallbackPage from './pages/auth/AuthCallbackPage';
 5: import LoginPage from './pages/auth/LoginPage';
 6: import SessionProbePage from './pages/auth/SessionProbePage';
 7: import { FinancialDashboard } from '@alfarid/ui';
 8: import { lazy, Suspense, useCallback, useEffect, useState } from 'react';
 9: import { useAuthStore } from './stores/auth.store';
10: import CategoriesMockPage from './pages/admin/categories-mock/CategoriesMockPage';
11: import PosPage from './pages/pos/PosPage';
12: import CatalogMockPage from './pages/admin/catalog-mock/CatalogMockPage';
13: const InventoryPage = lazy(() => import('./pages/admin/inventory-mock/InventoryPage'));
14: 
15: defaultApiClient.defaults.baseURL = resolveServiceUrl(import.meta.env.VITE_API_URL ?? 'http://localhost:8000');
16: 
17: export function App() {
18:   if (window.location.pathname === '/auth/session') return <SessionProbePage />;
19:   if (window.location.pathname === '/auth/callback') return <AuthCallbackPage />;
20:   if (window.location.pathname === '/login') return <LoginPage />;
21:   return <ProtectedRoute><AuthenticatedApp /></ProtectedRoute>;
22: }
23: 
24: function AuthenticatedApp() {
25:   const user = useAuthStore((state) => state.user);
26:   const logoutRemote = useAuthStore((state) => state.logoutRemote);
27:   const readRoute = () => window.location.hash.replace(/^#/, '').split('?')[0]
28:     || window.location.pathname;
29:   const [route, setRoute] = useState(readRoute);
30:   const can = useCallback((permission: string) =>
31:     hasPermission(user?.permissions, permission), [user]);
32:   const cashierOnly = user?.roles.length === 1 && user.roles[0] === 'cashier';
33:   useEffect(() => {
34:     // Stocktake navigation guards may synchronously restore the accepted hash.
35:     const changed = () => queueMicrotask(() => setRoute(readRoute()));
36:     window.addEventListener('hashchange', changed);
37:     window.addEventListener('popstate', changed);
38:     return () => {
39:       window.removeEventListener('hashchange', changed);
40:       window.removeEventListener('popstate', changed);
41:     };
42:   }, []);
43:   useEffect(() => {
44:     if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) window.location.replace('/dashboard');
45:     else if (!['/', '/dashboard', '/categories', '/dealers', '/production', '/pos'].includes(route) && !/^\/products(?:\/(?:new|[0-9]+))?$/.test(route) && !/^\/inventory(?:\/[a-z-]+)?$/.test(route)) window.location.replace('/dashboard');
46:   }, [cashierOnly, route]);
47:   if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) return null;
48:   if (route === '/pos') return <PosPage />;
49:   const categoriesActive = route === '/categories';
50:   const inventoryActive = route === '/inventory' || route.startsWith('/inventory/');
51:   const catalogActive = inventoryActive ? 'inventory' : route.startsWith('/products') ? 'products' : route === '/dealers' ? 'dealers' : route === '/production' ? 'production' : null;
52:   return <FinancialDashboard
53:     onLogout={logoutRemote}
54:     catalogActive={catalogActive}
55:     catalogPage={inventoryActive ? (can('inventory.view') ? <Suspense fallback={<div dir="rtl" className="p-6">جارٍ تحميل المخزون…</div>}><InventoryPage can={can}/></Suspense> : <div dir="rtl" className="p-6">ليس لديك صلاحية عرض المخزون.</div>) : catalogActive && <CatalogMockPage key={catalogActive} can={can} page={catalogActive} />}
56:     catalogNav={!cashierOnly ? [
57:       ...(can('inventory.view') ? [{ id: 'inventory', label: 'المخزون', onOpen: () => { window.location.hash = '/inventory/stock'; } }] : []),
58:       ...(can('products.view') ? [{ id: 'products', label: 'المنتجات', onOpen: () => { window.location.hash = '/products'; } }] : []),
59:       ...(can('customers.view') ? [{ id: 'dealers', label: 'التجار والموزعون', onOpen: () => { window.location.hash = '/dealers'; } }] : []),
60:       ...(can('inventory.view') ? [{ id: 'production', label: 'استلام الإنتاج', onOpen: () => { window.location.hash = '/production'; } }] : []),
61:     ] : []}
62:     onCloseCatalog={() => { window.location.hash = '/dashboard'; }}
63:     categoriesActive={categoriesActive}
64:     categoriesPage={<CategoriesMockPage can={can} embedded />}
65:     onOpenCategories={!cashierOnly && can('categories.view')
66:       ? () => { window.location.hash = '/categories'; }
67:       : undefined}
68:     onCloseCategories={() => { window.location.hash = '/dashboard'; }}
69:   />;
70: }
71: 
72: export default App;

