  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Enums\OrderStatus;
 10: use App\Enums\ReturnStatus;
 11: use App\Enums\StockBucket;
 12: use App\Enums\StockMovementType;
 13: use App\Events\OrderCreated;
 14: use App\Exceptions\BusinessException;
 15: use App\Models\Cart;
 16: use App\Models\City;
 17: use App\Models\Coupon;
 18: use App\Models\CouponUsage;
 19: use App\Models\Customer;
 20: use App\Models\CustomerWalletTransaction;
 21: use App\Models\Order;
 22: use App\Models\Product;
 23: use App\Models\ReturnRequest;
 24: use App\Models\StockMovement;
 25: use App\Models\User;
 26: use Illuminate\Database\Eloquent\Model;
 27: use Illuminate\Support\Collection;
 28: use Illuminate\Support\Facades\DB;
 29: 
 30: /**
 31:  * خدمات الطلب.
 32:  * - createFromCart: تحويل سلة إلى طلب بلقطات أسعار من PricingService،
 33:  *   وخصم الكوبون، وشحن المدينة، وضريبة الإعدادات، ثم إفراغ السلة.
 34:  * - changeStatus: بوابة تغيير الحالة الوحيدة — تتحقق من آلة الحالات،
 35:  *   وتسجل التغيير في order_status_histories، وتدير آثار المخزون:
 36:  *   confirmed ← حجز وتوزيع، shipped ← فك حجز + بيع فعلي،
 37:  *   cancelled (من confirmed/processing) ← فك حجز.
 38:  */
 39: class OrderService
 40: {
 41:     /** الانتقالات المسموحة بين حالات الطلب. */
 42:     private const TRANSITIONS = [
 43:         'pending' => ['confirmed', 'cancelled'],
 44:         'confirmed' => ['processing', 'shipped', 'cancelled'],
 45:         'processing' => ['shipped', 'cancelled'],
 46:         'shipped' => ['delivered', 'returned'],
 47:         'delivered' => ['returned'],
 48:         'cancelled' => [],
 49:         'returned' => [],
 50:     ];
 51: 
 52:     public function __construct(
 53:         protected OrderAllocationService $allocationService,
 54:         protected CartService $cartService,
 55:         protected CouponService $couponService,
 56:         protected SettingService $settings,
 57:         protected InventoryService $inventoryService,
 58:         protected ShippingQuoteService $shippingQuote,
 59:     ) {}
 60: 
 61:     /**
 62:      * تحويل سلة إلى طلب جديد بحالة pending.
 63:      *
 64:      * @param  array{recipient_name?: string|null, recipient_phone?: string|null, recipient_email?: string|null, city_id?: int|null, shipping_address_line?: string|null, shipping_notes?: string|null, payment_method?: string|null, channel?: string}  $data
 65:      */
 66:     public function createFromCart(Cart $cart, array $data, ?Customer $customer = null): Order
 67:     {
 68:         // إعادة إرسال بنفس مفتاح منع التكرار ترجع الطلب نفسه (F-13):
 69:         // انقطاع الشبكة بعد إنشاء الطلب لا يعني «سلة فارغة» ولا طلبًا مكررًا.
 70:         // المفتاح مقيّد بهوية المُرسِل (F2): زائر لا يستطيع سرقة طلب غيره أو
 71:         // تعطيله بمعرفة/تخمين مفتاحه، فالمفتاح وحده ملك مشترك للفضاء كله.
 72:         $idempotencyKey = isset($data['idempotency_key']) && is_string($data['idempotency_key']) && $data['idempotency_key'] !== ''
 73:             ? mb_substr($data['idempotency_key'], 0, 191)
 74:             : null;
 75: 
 76:         $guestPhone = $data['recipient_phone'] ?? $customer?->phone;
 77:         $guestPhoneNormalized = is_string($guestPhone) && trim($guestPhone) !== ''
 78:             ? Customer::normalizePhone($guestPhone)
 79:             : null;
 80:         // هاتف زائر لا يحمل أرقامًا بعد التوحيد = هوية مشتركة بين كل من أرسل
 81:         // مدخلًا عشوائيًا (M3): نطاق idempotency يصير 'guest:' عامًا ويتطابق
 82:         // التتبع مع أي هاتف. يُرفض بدل أن يفسد Discounts/التتبع.
 83:         if ($customer === null && $guestPhoneNormalized !== null
 84:             && preg_match('/\d/', $guestPhoneNormalized) !== 1) {
 85:             throw new BusinessException('رقم هاتف صالح مطلوب لإتمام الشراء كزائر.');
 86:         }
 87:         $idempotencyScope = $customer !== null
 88:             ? 'customer:'.$customer->id
 89:             : ($guestPhoneNormalized !== null ? 'guest:'.$guestPhoneNormalized : null);
 90: 
 91:         if ($idempotencyKey !== null && $idempotencyScope !== null) {
 92:             $existing = Order::query()
 93:                 ->where('idempotency_key', $idempotencyKey)
 94:                 ->where('idempotency_scope', $idempotencyScope)
 95:                 ->first();
 96:             if ($existing !== null) {
 97:                 return $existing->load('items');
 98:             }
 99:         }
100: 
101:         return DB::transaction(function () use ($cart, $data, $customer, $idempotencyKey, $idempotencyScope, $guestPhoneNormalized): Order {
102:             // قفل استشاري على (النطاق + المفتاح): طلبان متزامنان بنفس المفتاح
103:             // يتسلسلان، فيجد الثاني الطلب الأول ويعيده بدل إنشاء ثانٍ (F2/F-13)
104:             if ($idempotencyKey !== null && $idempotencyScope !== null) {
105:                 DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', ['order-idem:'.$idempotencyScope.':'.$idempotencyKey]);
106:                 $existing = Order::query()
107:                     ->where('idempotency_key', $idempotencyKey)
108:                     ->where('idempotency_scope', $idempotencyScope)
109:                     ->first();
110:                 if ($existing !== null) {
111:                     return $existing->load('items');
112:                 }
113:             }
114: 
115:             // قفل صف السلة وقراءة بنودها طازجة: طلب متزامن ثانٍ ينتظر
116:             // ثم يجد السلة فارغة بدل إنشاء طلب مكرر (H2)
117:             $cart = Cart::query()->whereKey($cart->id)->lockForUpdate()->firstOrFail();
118:             $cart->load('items');
119:             if ($cart->items->isEmpty()) {
120:                 throw new BusinessException('السلة فارغة؛ لا يمكن إنشاء طلب.');
121:             }
122: 
123:             $lines = $this->cartService->pricedLines($cart, $customer);
124:             foreach ($lines as $line) {
125:                 if ($line['unit_price'] === null) {
126:                     throw new BusinessException("الصنف ({$line['variant']->sku}) غير مُسعَّر؛ لا يمكن إتمام الطلب.");
127:                 }
128:                 // سطر بقيمة صفر (كمية شبه صفرية × سعر صغير) لا يمر (F-03)
129:                 if ($line['line_total'] <= 0) {
130:                     throw new BusinessException("قيمة الصنف ({$line['variant']->sku}) صفر؛ راجع الكمية أو السعر.");
131:                 }
132:             }
133: 
134:             // سقوف المخزون (F5/H2): الزائر بلا تحقق من الهاتف، والعميل المسجّل
135:             // بلا سقف كانا يحبسان المخزون بكميات ضخمة وطلبات معلّقة. عملاء
136:             // الجملة/التوزيع المعتمدون مستثنون (مسار الجملة للكميات الكبيرة).
137:             $isWholesale = $this->isWholesaleApproved($customer);
138:             if (! $isWholesale) {
139:                 $lineCap = $customer === null
140:                     ? (float) config('store.guest_max_line_qty', 10)
141:                     : (float) config('store.retail_max_line_qty', 50);
142:                 if ($lineCap > 0) {
143:                     foreach ($lines as $line) {
144:                         if ((float) $line['qty'] > $lineCap) {
145:                             throw new BusinessException($customer === null
146:                                 ? "سقف كمية البند الواحد للزوار ({$lineCap}) — سجّل الدخول للكميات الأكبر."
147:                                 : "سقف كمية البند الواحد ({$lineCap}) — للكميات الأكبر تواصل مع مسار الجملة.");
148:                         }
149:                     }
150:                 }
151:             }
152: 
153:             if ($customer === null) {
154:                 $pendingCap = (int) config('store.guest_pending_orders_cap', 3);
155:                 if ($pendingCap > 0 && $guestPhoneNormalized !== null) {
156:                     $pendingForPhone = Order::query()
157:                         ->whereNull('customer_id')
158:                         ->where('status', OrderStatus::Pending)
159:                         ->where('guest_phone_normalized', $guestPhoneNormalized)
160:                         ->count();
161:                     if ($pendingForPhone >= $pendingCap) {
162:                         throw new BusinessException('لديك طلبات معلّقة كثيرة على هذا الرقم؛ أكملها أو ألغِها قبل طلب جديد.');
163:                     }
164:                 }
165:             } elseif (! $isWholesale) {
166:                 $pendingCap = (int) config('store.customer_pending_orders_cap', 5);
167:                 if ($pendingCap > 0) {
168:                     $pendingForCustomer = Order::query()
169:                         ->where('customer_id', $customer->id)
170:                         ->where('status', OrderStatus::Pending)
171:                         ->count();
172:                     if ($pendingForCustomer >= $pendingCap) {
173:                         throw new BusinessException('لديك طلبات معلّقة كثيرة؛ أكملها أو ألغِها قبل طلب جديد.');
174:                     }
175:                 }
176:             }
177: 
178:             // إعادة التحقق من التوفر وقابلية البيع لحظة الشراء (M14):
179:             // صنف عُطّل أو منتج أُلغي نشره/حُذف بعد الإضافة لا يُشترى
180:             $this->cartService->assertLinesAvailable($lines);
181:             $this->cartService->assertLinesPurchasable($lines);
182:             $totals = $this->cartService->totals($cart, $customer, $lines);
183:             $subtotal = $totals['subtotal'];
184:             $pricingDiscount = $totals['pricing_discount'];
185: 
186:             // الكوبون: إعادة تحقق صارمة عند الشراء (يشمل حد العميل الواحد)
187:             $couponDiscount = 0.0;
188:             $couponId = null;
189:             $couponCode = null;
190:             $coupon = null;
191:             if ($cart->coupon_id !== null) {
192:                 // لا قفل صف كوبون مسبق (F4): ترتيب الأقفال صار مخزون←كوبون،
193:                 // والذرّية تُضمن عند تسجيل الاستخدام (قفل استشاري + زيادة
194:                 // شرطية) فلا جمود بين الشراء والإلغاء
195:                 try {
196:                     $coupon = $this->couponService->redeemableById(
197:                         (int) $cart->coupon_id,
198:                         $totals['items_total'],
199:                         $customer,
200:                         $customer === null ? ($data['recipient_phone'] ?? null) : null,
201:                     );
202:                 } catch (BusinessException $e) {
203:                     // رمز مميز حتى تعرض الواجهة زر إزالة الكوبون (H8)
204:                     throw new BusinessException($e->getMessage(), $e->errors, $e->status, 'coupon_invalid');
205:                 }
206:                 // حد معدّل لكل (كوبون + IP) عند إتمام الشراء (H3)
207:                 $this->couponService->enforceRateLimit($coupon, 'redeem');
208:                 $couponDiscount = $this->couponService->discountFor($coupon, $totals['items_total']);
209:                 $couponId = $coupon->id;
210:                 $couponCode = $coupon->code;
211:             }
212:             $discountAmount = round($pricingDiscount + $couponDiscount, 2);
213: 
214:             // الشحن من تسعيرة المناطق الموحدة (M12): سعر المنطقة/الشركة
215:             // وحدها المجاني ورسوم COD — ورجوع لسعر المدينة عند غياب سعر.
216:             // كوبون الشحن المجاني يعفي من تكلفة الشحن (لا من رسوم COD)
217:             $city = null;
218:             $shippingCost = 0.0;
219:             $codFee = 0.0;
220:             if (! empty($data['city_id'])) {
221:                 $city = City::query()->where('is_active', true)->find((int) $data['city_id']);
222:                 if ($city === null) {
223:                     throw new BusinessException('مدينة التوصيل غير متاحة.');
224:                 }
225:                 $quote = $this->shippingQuote->quoteForCity(
226:                     $city->id,
227:                     $totals['items_total'] - $couponDiscount,
228:                     ($data['payment_method'] ?? 'cod') === 'cod',
229:                 );
230:                 $shippingCost = $quote['cost'];
231:                 $codFee = $quote['cod_fee'];
232:             }
233:             $waivedShipping = 0.0;
234:             if ($coupon !== null && $coupon->type === 'free_shipping' && $shippingCost > 0) {
235:                 $waivedShipping = $shippingCost;
236:                 $shippingCost = 0.0;
237:             }
238: 
239:             // الضريبة من الإعدادات (مفعّلة وغير مشمولة في الأسعار فقط)
240:             $taxAmount = 0.0;
241:             $taxRate = 0.0;
242:             if (filter_var($this->settings->get('tax_enabled', false), FILTER_VALIDATE_BOOLEAN)
243:                 && ! filter_var($this->settings->get('prices_include_tax', false), FILTER_VALIDATE_BOOLEAN)) {
244:                 $taxRate = (float) $this->settings->get('default_tax_rate', 0);
245:                 $taxAmount = round(($subtotal - $discountAmount) * $taxRate / 100, 2);
246:             }
247: 
248:             $grandTotal = round(($subtotal - $discountAmount) + $shippingCost + $codFee + $taxAmount, 2);
249: 
250:             // حماية من تغيّر السعر بين عرض السلة والشراء (M6): إن أرسل العميل
251:             // الإجمالي الذي رآه واختلف عمّا حُسب فعليًا نرفض بدل تحصيل زائد صامت
252:             if (isset($data['expected_total']) && is_numeric($data['expected_total'])
253:                 && abs((float) $data['expected_total'] - $grandTotal) > 0.01) {
254:                 throw new BusinessException(
255:                     'تغيّر إجمالي الطلب منذ عرضه. راجع السلة ثم أعد المحاولة.',
256:                     [], 422, 'price_changed',
257:                 );
258:             }
259: 
260:             $order = Order::create([
261:                 'order_number' => $this->settings->generateNextNumber('order'),
262:                 'idempotency_key' => $idempotencyKey,
263:                 'idempotency_scope' => $idempotencyScope,
264:                 'channel' => $data['channel'] ?? 'store',
265:                 'customer_id' => $customer?->id,
266:                 'guest_name' => $data['recipient_name'] ?? $customer?->name,
267:                 'guest_phone' => $data['recipient_phone'] ?? $customer?->phone,
268:                 'guest_phone_normalized' => $guestPhoneNormalized,
269:                 'guest_email' => $data['recipient_email'] ?? $customer?->email,
270:                 'city_id' => $city?->id,
271:                 'shipping_address_line' => $data['shipping_address_line'] ?? null,
272:                 'shipping_notes' => $data['shipping_notes'] ?? null,
273:                 'status' => OrderStatus::Pending,
274:                 'payment_method' => $data['payment_method'] ?? 'cod',
275:                 'payment_status' => 'unpaid',
276:                 'subtotal' => $subtotal,
277:                 'discount_amount' => $discountAmount,
278:                 'coupon_id' => $couponId,
279:                 'coupon_code' => $couponCode,
280:                 'shipping_cost' => $shippingCost,
281:                 'cod_fee' => $codFee,
282:                 'tax_amount' => $taxAmount,
283:                 'grand_total' => $grandTotal,
284:             ]);
285: 
286:             // بنود الطلب بلقطات الاسم والـ SKU والسعر + توزيع الضريبة وحصة
287:             // الكوبون على البنود بطريقة «أكبر باقٍ» (L5/M17): الحصة تُحسب
288:             // بالقروش فتكون الأعداد صحيحة ومجموعها يساوي الإجمالي بالضبط،
289:             // ولا يقع بند بحصة سالبة بسبب التقريب
290:             $weights = array_map(fn (array $line): float => (float) $line['line_total'], $lines);
291:             $taxShares = $this->distributeLargestRemainder($taxAmount, $weights);
292:             $couponShares = $this->distributeLargestRemainder($couponDiscount, $weights);
293:             foreach ($lines as $i => $line) {
294:                 $order->items()->create([
295:                     'product_variant_id' => $line['variant']->id,
296:                     'product_name_snapshot' => $line['variant']->product?->name_ar ?? '',
297:                     'sku_snapshot' => $line['variant']->sku,
298:                     'qty' => $line['qty'],
299:                     'unit_price' => $line['unit_price'],
300:                     'discount_amount' => round($line['line_discount'] + $couponShares[$i], 2),
301:                     'tax_amount' => $taxShares[$i],
302:                     'line_total' => $line['line_total'],
303:                 ]);
304:             }
305: 
306:             // الحجز الفوري داخل نفس معاملة الشراء (F-01): التوفر يتحول
307:             // لحجز ذرّي تحت أقفال صفوف الأرصدة بدل انتظار التأكيد، فآخر
308:             // وحدة لا تُباع مرتين. نقص الرصيد يُسقط الشراء كله هنا.
309:             $order->load('items');
310:             $this->allocationService->allocate($order, performedBy: $this->inventoryActorId($customer));
311:             $order->refresh();
312: 
313:             // تسجيل استخدام الكوبون فعليًا (خصم البضاعة أو الشحن المُعفى).
314:             // كوبون شحن مجاني وشحن الطلب صفر أصلًا لا يستهلك حدًا بلا فائدة (L4)
315:             if ($coupon !== null
316:                 && ! ($coupon->type === 'free_shipping' && $waivedShipping <= 0)) {
317:                 $this->couponService->recordUsage(
318:                     $coupon,
319:                     $order,
320:                     $customer,
321:                     $coupon->type === 'free_shipping' ? $waivedShipping : $couponDiscount,
322:                 );
323:             }
324: 
325:             if (($data['payment_method'] ?? 'cod') === 'wallet') {
326:                 if ($customer === null || $customer->fresh()->status !== CustomerStatus::Approved) {
327:                     throw new BusinessException('الدفع بالمحفظة يتطلب حساب عميل نشطًا.');
328:                 }
329:                 app(WalletService::class)->record($customer->id, -$grandTotal, 'checkout_payment', 'order', $order->id);
330:                 $order->update(['payment_status' => 'paid']);
331:             }
332: 
333:             // أول سجل حالة: إنشاء الطلب
334:             $order->statusHistories()->create([
335:                 'from_status' => null,
336:                 'to_status' => OrderStatus::Pending,
337:                 'changed_by_type' => $customer?->getMorphClass(),
338:                 'changed_by_id' => $customer?->getKey(),
339:                 'notes' => 'تم إنشاء الطلب من السلة',
340:             ]);
341: 
342:             // إفراغ السلة من البنود التي تحولت لطلب فقط (F-23): بند أُضيف
343:             // والتزم أثناء المعاملة لا يجب أن يمسحه مسحٌ كامل للسلة
344:             $orderedItemIds = array_values(array_unique(array_map(
345:                 fn (array $line): int => (int) $line['item_id'],
346:                 $lines,
347:             )));
348:             if ($orderedItemIds !== []) {
349:                 $cart->items()->whereIn('id', $orderedItemIds)->delete();
350:             }
351:             $cart->update(['coupon_id' => null]);
352: 
353:             $created = $order->fresh(['items', 'statusHistories']);
354:             OrderCreated::dispatch($created);
355: 
356:             return $created;
357:         });
358:     }
359: 
360:     /**
361:      * بوابة الحالة الوحيدة. $expectedFrom (F-11): حالات مصدر يفترضها
362:      * المستدعي على نسخته غير المقفولة — تُفحص بعد إعادة القراءة بالقفل،
363:      * فسباق (عميل يلغي × أدمن يجهّز) لا يمر من فحص قديم.
364:      * $returnEffects (المرحلة 9): عند false ينتقل الطلب إلى Returned بلا
365:      * إعادة مخزون وبلا علم استرداد — مسار RMA سوّى المخزون عند الاستلام
366:      * الفعلي والمال عند رد المبلغ، فتكرار الأثر هنا ازدواج.
367:      *
368:      * @param  array<int, OrderStatus>|null  $expectedFrom
369:      */
370:     public function changeStatus(Order $order, OrderStatus|string $toStatus, ?Model $actor = null, ?string $notes = null, ?array $expectedFrom = null, bool $returnEffects = true): Order
371:     {
372:         $to = $toStatus instanceof OrderStatus ? $toStatus : OrderStatus::from($toStatus);
373: 
374:         return DB::transaction(function () use ($order, $to, $actor, $notes, $expectedFrom, $returnEffects): Order {
375:             // إعادة قراءة الطلب بقفل صف: النسخة الممرَّرة قد تكون قديمة،
376:             // وكل الانتقالات على نفس الطلب يجب أن تتسلسل (C1)
377:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
378:             $from = $order->status;
379: 
380:             if ($expectedFrom !== null && ! in_array($from, $expectedFrom, true)) {
381:                 throw new BusinessException("تغيّرت حالة الطلب أثناء العملية (أصبحت {$from->value})؛ أعد المحاولة.");
382:             }
383: 
384:             if ($from === $to) {
385:                 return $order;
386:             }
387: 
388:             if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
389:                 throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
390:             }
391: 
392:             $actorId = $this->inventoryActorId($actor);
393: 
394:             if ($to === OrderStatus::Returned && $returnEffects
395:                 && ReturnRequest::query()->where('order_id', $order->id)->whereNotIn('status', [
396:                     ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value,
397:                 ])->exists()) {
398:                 throw new BusinessException('للطلب مرتجعات قائمة؛ أكمل الاستلام والاسترداد من إدارة المرتجعات لمنع تكرار المخزون.');
399:             }
400: 
401:             // آثار المخزون بحسب الانتقال
402:             $extraNote = null;
403:             if ($to === OrderStatus::Shipped) {
404:                 $this->shipOrder($order, $actorId);
405:             } elseif ($to === OrderStatus::Cancelled
406:                 && in_array($from, [OrderStatus::Pending, OrderStatus::Confirmed, OrderStatus::Processing], true)) {
407:                 // الحجز صار من لحظة الإنشاء (F-01) فيُفك من Pending أيضًا
408:                 $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
409:             } elseif ($to === OrderStatus::Returned
410:                 && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)
411:                 && $returnEffects) {
412:                 // إعادة البضاعة المشحونة للمخزون بحركات sale_return (M13) —
413:                 // تُتخطى في مسار RMA لأن الاستلام الفعلي سوّاها بالفعل (مرحلة 9)
414:                 if (! $this->returnSalesToStock($order, $actorId)) {
415:                     $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
416:                 }
417:             }
418: 
419:             if ($to === OrderStatus::Cancelled) {
420:                 // عكس استخدام الكوبون حتى لا يُحرم العميل منه بإلغاء (M13)
421:                 $this->reverseCouponUsage($order);
422:                 if ($order->payment_status === 'paid') {
423:                     $order->update(['requires_refund' => true]);
424:                 }
425:             }
426: 
427:             // مرتجع لطلب مدفوع يحتاج استردادًا أيضًا، لا الإلغاء فقط (F-14) —
428:             // في مسار RMA الاسترداد اكتمل داخل طلب المرتجع نفسه فلا علم هنا
429:             if ($to === OrderStatus::Returned && $order->payment_status === 'paid' && $returnEffects) {
430:                 $order->update(['requires_refund' => true]);
431:             }
432: 
433:             if ($order->payment_method === 'wallet' && $order->payment_status === 'paid'
434:                 && ($to === OrderStatus::Cancelled || ($to === OrderStatus::Returned && $returnEffects))) {
435:                 $payment = CustomerWalletTransaction::query()->where('reference_type', 'order')->where('reference_id', $order->id)
436:                     ->where('type', 'checkout_payment')->first();
437:                 if ($payment !== null) {
438:                     app(WalletService::class)->record($payment->customer_id, -(float) $payment->amount,
439:                         'order_reversal', 'order', $order->id, $actorId);
440:                     $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
441:                 }
442:             }
443: 
444:             $order->update(['status' => $to]);
445: 
446:             // تسوية COD عند التسليم من أي مسار (أدمن يدوي أو ويب هوك) —
447:             // الأثر هنا في بوابة الحالة لا في ويب هوك الشحن فقط (F-14)
448:             if ($to === OrderStatus::Delivered
449:                 && $order->payment_method === 'cod'
450:                 && $order->payment_status !== 'paid') {
451:                 $order->update(['payment_status' => 'paid']);
452:             }
453: 
454:             // notes عمود varchar(500): ملاحظة الأدمن (حتى 500) مع الملحق قد
455:             // تتجاوزه فتنفجر بحركة إرجاع بلا حركات بيع — تُقصّ على 500 (F-28)
456:             $historyNotes = trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes;
457: 
458:             $order->statusHistories()->create([
459:                 'from_status' => $from,
460:                 'to_status' => $to,
461:                 'changed_by_type' => $actor?->getMorphClass(),
462:                 'changed_by_id' => $actor?->getKey(),
463:                 'notes' => $historyNotes !== null ? mb_substr($historyNotes, 0, 500) : null,
464:             ]);
465: 
466:             // التوزيع ناقص إن غاب فرع الطلب أو بقي بند بلا فرع: الاعتماد على
467:             // allocated_branch_id وحده يفشل عندما تُوزَّع البنود في فروع
468:             // مختلفة فيبقى حقل الطلب فارغًا (F1)
469:             if ($to === OrderStatus::Confirmed && ! $this->isAllocated($order)) {
470:                 $this->allocationService->allocate($order, performedBy: $actorId);
471:             }
472: 
473:             return $order->fresh(['items', 'statusHistories']);
474:         });
475:     }
476: 
477:     /**
478:      * كفاية التوزيع: يكفي أن يكون لفرع الطلب قيمة أو أن يكون كل بند موزّعًا
479:      * فعليًا في فرع ما (F1) — التوزيع الجزئي (بند بلا فرع) يُعيد الاستدعاء.
480:      */
481:     private function isAllocated(Order $order): bool
482:     {
483:         if ($order->allocated_branch_id !== null) {
484:             return true;
485:         }
486: 
487:         $distribution = $order->items()
488:             ->selectRaw('COUNT(*) AS total, COUNT(allocated_branch_id) AS allocated')
489:             ->first();
490: 
491:         if ($distribution === null || (int) $distribution->total === 0) {
492:             return false;
493:         }
494: 
495:         return (int) $distribution->total === (int) $distribution->allocated;
496:     }
497: 
498:     /** عميل جملة/توزيع معتمد — يُستثنى من سقوف التجزئة (H2). */
499:     private function isWholesaleApproved(?Customer $customer): bool
500:     {
501:         return $customer !== null
502:             && $customer->status === CustomerStatus::Approved
503:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true);
504:     }
505: 
506:     /**
507:      * توزيع مبلغ على أوزان بطريقة «أكبر باقٍ» بعدد صحيح من القروش (L5):
508:      * مجموع الحصص يساوي المبلغ بالضبط، ولا حصة سالبة بسبب التقريب.
509:      *
510:      * @param  array<int, float>  $weights
511:      * @return array<int, float>
512:      */
513:     private function distributeLargestRemainder(float $total, array $weights): array
514:     {
515:         $count = count($weights);
516:         if ($count === 0) {
517:             return [];
518:         }
519:         $totalCents = (int) round($total * 100);
520:         $weightSum = array_sum($weights);
521:         if ($totalCents <= 0 || $weightSum <= 0) {
522:             return array_fill(0, $count, 0.0);
523:         }
524: 
525:         $floorCents = [];
526:         $remainders = [];
527:         $assigned = 0;
528:         foreach ($weights as $i => $weight) {
529:             $exact = $totalCents * ((float) $weight / $weightSum);
530:             $floor = (int) floor($exact);
531:             $floorCents[$i] = $floor;
532:             $remainders[$i] = $exact - $floor;
533:             $assigned += $floor;
534:         }
535: 
536:         $left = $totalCents - $assigned;
537:         arsort($remainders);
538:         foreach (array_keys($remainders) as $i) {
539:             if ($left <= 0) {
540:                 break;
541:             }
542:             $floorCents[$i]++;
543:             $left--;
544:         }
545: 
546:         ksort($floorCents);
547: 
548:         return array_map(fn (int $cents): float => $cents / 100, $floorCents);
549:     }
550: 
551:     /**
552:      * الشحن: لكل حركة حجز — فك الحجز من reserved وخصم فعلي sale من on_hand
553:      * على نفس صف الرصيد، وزيادة عدّاد مبيعات المنتج.
554:      */
555:     private function shipOrder(Order $order, ?int $actorId): void
556:     {
557:         $reservations = $this->reserveMovements($order);
558:         if ($reservations->isEmpty()) {
559:             throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
560:         }
561: 
562:         foreach ($reservations as $movement) {
563:             $base = [
564:                 'product_variant_id' => $movement->product_variant_id,
565:                 'branch_id' => $movement->branch_id,
566:                 'location_id' => $movement->location_id,
567:                 'reference_type' => Order::class,
568:                 'reference_id' => $order->id,
569:                 'created_by' => $actorId,
570:             ];
571:             $this->inventoryService->recordMovement([...$base,
572:                 'type' => StockMovementType::ReleaseReserve,
573:                 'affected_bucket' => StockBucket::Reserved,
574:                 'quantity' => -1 * (float) $movement->quantity,
575:                 'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
576:             ]);
577:             $this->inventoryService->recordMovement([...$base,
578:                 'type' => StockMovementType::Sale,
579:                 'affected_bucket' => StockBucket::OnHand,
580:                 'quantity' => -1 * (float) $movement->quantity,
581:                 'notes' => "بيع عند شحن الطلب {$order->order_number}",
582:             ]);
583:         }
584: 
585:         foreach ($order->items as $item) {
586:             $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
587:         }
588:     }
589: 
590:     /** إلغاء طلب مُحجوز: فك كل حجوزاته فتعود الكميات متاحة للبيع. */
591:     private function releaseReservations(Order $order, ?int $actorId, string $reason): void
592:     {
593:         foreach ($this->reserveMovements($order) as $movement) {
594:             $this->inventoryService->recordMovement([
595:                 'product_variant_id' => $movement->product_variant_id,
596:                 'branch_id' => $movement->branch_id,
597:                 'location_id' => $movement->location_id,
598:                 'type' => StockMovementType::ReleaseReserve,
599:                 'affected_bucket' => StockBucket::Reserved,
600:                 'quantity' => -1 * (float) $movement->quantity,
601:                 'reference_type' => Order::class,
602:                 'reference_id' => $order->id,
603:                 'created_by' => $actorId,
604:                 'notes' => "{$reason} {$order->order_number}",
605:             ]);
606:         }
607:     }
608: 
609:     /**
610:      * إعادة بضاعة طلب مشحون/مُسلَّم إلى المخزون: لكل حركة بيع حركة
611:      * sale_return معاكسة على نفس الرصيد، وتنقيص عدّاد المبيعات (M13).
612:      * ترجع false إذا لم توجد حركات بيع (يحتاج استلامًا يدويًا).
613:      */
614:     private function returnSalesToStock(Order $order, ?int $actorId): bool
615:     {
616:         $sales = StockMovement::query()
617:             ->where('reference_type', $order->getMorphClass())
618:             ->where('reference_id', $order->id)
619:             ->where('type', StockMovementType::Sale)
620:             ->orderBy('id')
621:             ->get();
622:         if ($sales->isEmpty()) {
623:             return false;
624:         }
625: 
626:         foreach ($sales as $movement) {
627:             $this->inventoryService->recordMovement([
628:                 'product_variant_id' => $movement->product_variant_id,
629:                 'branch_id' => $movement->branch_id,
630:                 'location_id' => $movement->location_id,
631:                 'type' => StockMovementType::SaleReturn,
632:                 'affected_bucket' => StockBucket::OnHand,
633:                 'quantity' => -1 * (float) $movement->quantity,
634:                 'reference_type' => Order::class,
635:                 'reference_id' => $order->id,
636:                 'created_by' => $actorId,
637:                 'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
638:             ]);
639:         }
640: 
641:         foreach ($order->items as $item) {
642:             if ($item->variant?->product_id) {
643:                 Product::query()->whereKey($item->variant->product_id)
644:                     ->update(['sales_count' => DB::raw('GREATEST(sales_count - '.(int) round((float) $item->qty).', 0)')]);
645:             }
646:         }
647: 
648:         return true;
649:     }
650: 
651:     /** عكس تسجيل استخدام الكوبون عند إلغاء الطلب: حذف السجل وإنقاص العدّاد (M13). */
652:     private function reverseCouponUsage(Order $order): void
653:     {
654:         foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
655:             Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
656:             $usage->delete();
657:         }
658:     }
659: 
660:     /** حركات الحجز الأصلية للطلب من الدفتر (مصدر الحقيقة لمواضع الحجز ومواقعه). */
661:     private function reserveMovements(Order $order): Collection
662:     {
663:         return StockMovement::query()
664:             ->where('reference_type', $order->getMorphClass())
665:             ->where('reference_id', $order->id)
666:             ->where('type', StockMovementType::Reserve)
667:             ->orderBy('id')
668:             ->get();
669:     }
670: 
671:     // التخزين على مستوى الـ instance لا static (F-27): في Octane/العمال
672:     // طويلة العمر كانت قيمة static تبقى عالقة بين الطلبات وبين الاختبارات
673:     private ?int $systemActorId = null;
674: 
675:     private bool $systemActorResolved = false;
676: 
677:     /**
678:      * منفّذ حركات المخزون: الموظف الفاعل نفسه؛ وعند غيابه (عميل/ويب هوك)
679:      * يُنسب التنفيذ لمستخدم النظام المخصص (M19) — لا لأول Super Admin،
680:      * حتى يبقى سجل التدقيق صادقًا. يُحسم مرة واحدة لكل نسخة خدمة.
681:      */
682:     private function inventoryActorId(?Model $actor): ?int
683:     {
684:         if ($actor instanceof User) {
685:             return (int) $actor->getKey();
686:         }
687: 
688:         if (! $this->systemActorResolved) {
689:             $this->systemActorResolved = true;
690:             $systemId = User::query()
691:                 ->where('email', (string) config('orders.system_user_email', 'system@alfarid.local'))
692:                 ->value('id');
693:             $this->systemActorId = $systemId !== null ? (int) $systemId : null;
694:         }
695:         if ($this->systemActorId !== null) {
696:             return $this->systemActorId;
697:         }
698: 
699:         // رجوع احتياطي إن لم تُزرع هجرة مستخدم النظام بعد
700:         $adminId = User::query()
701:             ->whereHas('roles', fn ($q) => $q->where('name', 'Super Admin'))
702:             ->orderBy('id')
703:             ->value('id');
704: 
705:         return $adminId !== null ? (int) $adminId : (auth()->user() instanceof User ? (int) auth()->id() : null);
706:     }
707: }

